\bibitem{farha2012} Farha, O.K. et al. \textit{J. Am. Chem. Soc.}, 2012, \textbf{134}, 15016.
\bibitem{tanaka2023} Tanaka, Y. et al. \textit{Angew. Chem.}, 2023, \textbf{62}, e202301234.
\bibitem{chen2022} Chen, Z. et al. \textit{Chem. Rev.}, 2022, \textbf{122}, 10134.
\end{thebibliography}

\end{document}

