// Calculate the Julian Date for a given Gregorian date.
function gregorianToJulianDate(year, month, day, hour = 0, minute = 0, second = 0) {
  const JD = 367 * year - Math.floor(7 * (year + Math.floor((month + 9) / 12)) / 4) + Math.floor(275 * month / 9) + day + 1721013.5;
  const fractionalDay = (hour + minute / 60 + second / 3600) / 24;
  return JD + fractionalDay;
}

// Calculate the sidereal time in hours for a given Julian Date and longitude.
function calculateSiderealTime(julianDate, longitudeDegrees) {
  const T = (julianDate - 2451545.0) / 36525;
  let GMST = 280.46061837 + 360.98564736629 * (julianDate - 2451545.0) + 0.000387933 * T * T - T * T * T / 38710000;
  GMST = GMST % 360;
  if (GMST < 0) GMST += 360;
  const LMST = GMST + longitudeDegrees;
  return LMST / 15; // Convert degrees to hours
}

// Calculate the approximate position of the Sun in ecliptic coordinates (longitude in degrees).
function getSunEclipticLongitude(julianDate) {
  const n = julianDate - 2451545.0;
  let L = 280.460 + 0.9856474 * n;
  L = L % 360;
  if (L < 0) L += 360;
  const g = 357.528 + 0.9856003 * n;
  const lambda = L + 1.915 * Math.sin(degreesToRadians(g)) + 0.020 * Math.sin(degreesToRadians(2 * g));
  return lambda % 360;
}

// Calculate the approximate right ascension of the Sun in hours.
function getSunRightAscension(julianDate) {
  const eclipticLongitude = getSunEclipticLongitude(julianDate);
  const obliquityOfEcliptic = 23.439 - 0.0000004 * (julianDate - 2451545.0);
  const sinRA = Math.sin(degreesToRadians(eclipticLongitude)) * Math.cos(degreesToRadians(obliquityOfEcliptic));
  const cosRA = Math.cos(degreesToRadians(eclipticLongitude));
  let RA = radiansToDegrees(Math.atan2(sinRA, cosRA));
  if (RA < 0) RA += 360;
  return RA / 15; // Convert degrees to hours
}

// Calculate the approximate declination of the Sun in degrees.
function getSunDeclination(julianDate) {
  const eclipticLongitude = getSunEclipticLongitude(julianDate);
  const obliquityOfEcliptic = 23.439 - 0.0000004 * (julianDate - 2451545.0);
  const sinDec = Math.sin(degreesToRadians(eclipticLongitude)) * Math.sin(degreesToRadians(obliquityOfEcliptic));
  return radiansToDegrees(Math.asin(sinDec));
}

// Determine if a given year is a leap year.
function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
}

// Calculate the number of days in a given month of a given year.
function daysInMonth(year, month) {
  const days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month === 2 && isLeapYear(year)) {
    return 29;
  }
  return days[month - 1];
}

// Convert an angle to be within the range [0, 360).
const normalizeAngle360 = (angle) => {
  let normalized = angle % 360;
  if (normalized < 0) normalized += 360;
  return normalized;
};

// Cell Division Calculator Module
const CellDivision = (() => {
  const validateCellCount = (count) => {
    if (typeof count !== 'number' || count <= 0) {
      throw new Error('Cell count must be a positive number');
    }
    if (!Number.isInteger(count)) {
      throw new Error('Cell count must be an integer');
    }
  };

  const mitosisCycles = (initialCells, cycles) => {
    try {
      validateCellCount(initialCells);
      if (cycles < 0) throw new Error('Cycles cannot be negative');
      return initialCells * Math.pow(2, cycles);
    } catch (err) {
      console.error(`Mitosis calculation error: ${err.message}`);
      return null;
    }
  };

  const meiosisCycles = (initialCells) => {
    try {
      validateCellCount(initialCells);
      return initialCells * 4;
    } catch (err) {
      console.error(`Meiosis calculation error: ${err.message}`);
      return null;
    }
  };

  const doublingTime = (rate) => {
    if (rate <= 0) throw new Error('Growth rate must be positive');
    return Math.log(2) / rate;
  };

  return { mitosisCycles, meiosisCycles, doublingTime };
})();

module.exports = CellDivision;

// DNA Sequence Analyzer Module
const DNAAnalyzer = {
  validBases: new Set(['A', 'T', 'C', 'G']),

  validateSequence(sequence) {
    if (typeof sequence !== 'string' || sequence.length === 0) {
      throw new TypeError('Sequence must be a non-empty string');
    }
    const upper = sequence.toUpperCase();
    for (const base of upper) {
      if (!this.validBases.has(base)) {
        throw new Error(`Invalid base found: ${base}`);
      }
    }
    return upper;
  },

  getComplement(sequence) {
    try {
      const validated = this.validateSequence(sequence);
      const map = { A: 'T', T: 'A', C: 'G', G: 'C' };
      return validated.split('').map(b => map[b]).join('');
    } catch (err) {
      console.error(`Complement error: ${err.message}`);
      return null;
    }
  },

  gcContent(sequence) {
    try {
      const validated = this.validateSequence(sequence);
      const gcCount = validated.split('').filter(b => b === 'G' || b === 'C').length;
      return (gcCount / validated.length) * 100;
    } catch (err) {
      console.error(`GC content error: ${err.message}`);
      return null;
    }
  },

  transcribe(sequence) {
    try {
      const validated = this.validateSequence(sequence);
      return validated.replace(/T/g, 'U');
    } catch (err) {
      console.error(`Transcription error: ${err.message}`);
      return null;
    }
  }
};

module.exports = DNAAnalyzer;

// Ecosystem Population Model
class PopulationModel {
  constructor(species, initialPop, carryingCapacity) {
    if (!species || typeof species !== 'string') {
      throw new TypeError('Species name must be a valid string');
    }
    if (initialPop <= 0 || carryingCapacity <= 0) {
      throw new RangeError('Population values must be positive');
    }
    this.species = species;
    this.population = initialPop;
    this.carryingCapacity = carryingCapacity;
  }

  logisticGrowth(growthRate, timeSteps) {
    if (growthRate <= 0 || growthRate > 1) {
      throw new RangeError('Growth rate must be between 0 and 1');
    }
    const history = [this.population];
    let current = this.population;
    for (let i = 0; i < timeSteps; i++) {
      current = current + growthRate * current * (1 - current / this.carryingCapacity);
      if (current < 0) current = 0;
      history.push(Math.round(current));
    }
    return history;
  }

  isExtinct() {
    return this.population <= 0;
  }

  getStatus() {
    const ratio = this.population / this.carryingCapacity;
    if (ratio < 0.1) return 'Critical';
    if (ratio < 0.3) return 'Endangered';
    if (ratio < 0.7) return 'Stable';
    return 'Thriving';
  }
}

module.exports = PopulationModel;

// Protein Synthesis Module
const ProteinSynthesis = (() => {
  const codonTable = {
    'AUG': 'Met', 'UUU': 'Phe', 'UUC': 'Phe', 'UUA': 'Leu',
    'UUG': 'Leu', 'UCU': 'Ser', 'UCC': 'Ser', 'UAU': 'Tyr',
    'UAC': 'Tyr', 'UGU': 'Cys', 'UGC': 'Cys', 'UGG': 'Trp',
    'UAA': 'Stop', 'UAG': 'Stop', 'UGA': 'Stop'
  };

  const validateRNA = (rna) => {
    if (typeof rna !== 'string') throw new TypeError('RNA must be a string');
    if (rna.length % 3 !== 0) throw new Error('RNA length must be divisible by 3');
    const validBases = /^[AUGC]+$/;
    if (!validBases.test(rna)) throw new Error('Invalid RNA bases detected');
  };

  const translate = (mrna) => {
    try {
      validateRNA(mrna);
      const protein = [];
      for (let i = 0; i < mrna.length; i += 3) {
        const codon = mrna.slice(i, i + 3);
        const aminoAcid = codonTable[codon] || 'Unknown';
        if (aminoAcid === 'Stop') break;
        protein.push(aminoAcid);
      }
      return protein;
    } catch (err) {
      console.error(`Translation error: ${err.message}`);
      return [];
    }
  };

  const getProteinLength = (mrna) => {
    const protein = translate(mrna);
    return protein.length;
  };

  return { translate, getProteinLength, codonTable };
})();

module.exports = ProteinSynthesis;

// Photosynthesis Rate Calculator
class PhotosynthesisCalculator {
  constructor() {
    this.lightCompensationPoint = 50;
    this.maxRate = 100;
  }

  validateEnvironment(light, co2, temp) {
    const errors = [];
    if (light < 0 || light > 2000) errors.push('Light intensity out of range (0-2000 lux)');
    if (co2 < 0 || co2 > 2000) errors.push('CO2 concentration out of range (0-2000 ppm)');
    if (temp < 0 || temp > 50) errors.push('Temperature out of range (0-50°C)');
    if (errors.length > 0) throw new Error(errors.join('; '));
  }

  calculateRate(light, co2, temp) {
    try {
      this.validateEnvironment(light, co2, temp);
      const lightFactor = Math.min(light / 500, 1);
      const co2Factor = Math.min(co2 / 400, 1);
      const tempFactor = temp >= 20 && temp <= 35 ? 1 : Math.max(0, 1 - Math.abs(temp - 27.5) / 27.5);
      return this.maxRate * lightFactor * co2Factor * tempFactor;
    } catch (err) {
      console.error(`Photosynthesis calculation failed: ${err.message}`);
      return null;
    }
  }

  isNetPositive(light, co2, temp) {
    const rate = this.calculateRate(light, co2, temp);
    return rate !== null ? rate > this.lightCompensationPoint : false;
  }

  getOptimalConditions() {
    return { light: 500, co2: 400, temp: 27.5 };
  }
}

module.exports = PhotosynthesisCalculator;

// Genetics Inheritance Module
const GeneticsModule = {
  alleleTypes: ['dominant', 'recessive'],

  validateAllele(allele) {
    if (typeof allele !== 'string' || allele.length !== 1) {
      throw new TypeError('Allele must be a single character string');
    }
    if (!/[A-Za-z]/.test(allele)) {
      throw new Error('Allele must be an alphabetical character');
    }
  },

  punnettSquare(parent1, parent2) {
    try {
      if (parent1.length !== 2 || parent2.length !== 2) {
        throw new Error('Each parent must have exactly 2 alleles');
      }
      parent1.split('').forEach(a => this.validateAllele(a));
      parent2.split('').forEach(a => this.validateAllele(a));
      const offspring = [];
      for (const a1 of parent1) {
        for (const a2 of parent2) {
          offspring.push([a1, a2].sort((a, b) => a < b ? 1 : -1).join(''));
        }
      }
      return offspring;
    } catch (err) {
      console.error(`Punnett square error: ${err.message}`);
      return [];
    }
  },

  phenotypeRatio(offspring) {
    if (!Array.isArray(offspring) || offspring.length === 0) {
      throw new Error('Offspring must be a non-empty array');
    }
    const dominant = offspring.filter(o => o[0] === o[0].toUpperCase()).length;
    return { dominant, recessive: offspring.length - dominant };
  }
};

module.exports = GeneticsModule;

// Enzyme Kinetics Module
class EnzymeKinetics {
  constructor(name, vmax, km) {
    if (!name) throw new TypeError('Enzyme name is required');
    if (vmax <= 0) throw new RangeError('Vmax must be positive');
    if (km <= 0) throw new RangeError('Km must be positive');
    this.name = name;
    this.vmax = vmax;
    this.km = km;
  }

  michaelisRate(substrateConc) {
    try {
      if (substrateConc < 0) throw new RangeError('Substrate concentration cannot be negative');
      return (this.vmax * substrateConc) / (this.km + substrateConc);
    } catch (err) {
      console.error(`Rate calculation error: ${err.message}`);
      return null;
    }
  }

  inhibitedRate(substrateConc, inhibitorConc, ki) {
    try {
      if (inhibitorConc < 0 || ki <= 0) throw new RangeError('Invalid inhibitor parameters');
      const apparentKm = this.km * (1 + inhibitorConc / ki);
      return (this.vmax * substrateConc) / (apparentKm + substrateConc);
    } catch (err) {
      console.error(`Inhibition calculation error: ${err.message}`);
      return null;
    }
  }

  halfMaxConcentration() {
    return this.km;
  }

  efficiency() {
    return this.vmax / this.km;
  }

  toString() {
    return `Enzyme: ${this.name}, Vmax: ${this.vmax}, Km: ${this.km}`;
  }
}

module.exports = EnzymeKinetics;

