const BiomeClassifier = (() => {
  const biomes = [
    { name: 'Tropical Rainforest', minTemp: 20, maxTemp: 35, minPrecip: 2000, maxPrecip: 10000 },
    { name: 'Desert', minTemp: -10, maxTemp: 50, minPrecip: 0, maxPrecip: 250 },
    { name: 'Temperate Forest', minTemp: -10, maxTemp: 20, minPrecip: 750, maxPrecip: 2000 },
    { name: 'Tundra', minTemp: -40, maxTemp: 5, minPrecip: 150, maxPrecip: 500 },
    { name: 'Grassland', minTemp: -5, maxTemp: 25, minPrecip: 250, maxPrecip: 750 }
  ];

  const validateInput = (temp, precipitation) => {
    if (typeof temp !== 'number' || typeof precipitation !== 'number') {
      throw new TypeError('Temperature and precipitation must be numbers');
    }
    if (precipitation < 0) throw new RangeError('Precipitation cannot be negative');
  };

  const classify = (avgTemp, annualPrecip) => {
    try {
      validateInput(avgTemp, annualPrecip);
      const match = biomes.find(b =>
        avgTemp >= b.minTemp && avgTemp <= b.maxTemp &&
        annualPrecip >= b.minPrecip && annualPrecip <= b.maxPrecip
      );
