class MetabolicRateCalculator {
  constructor(organism, weight, age) {
    if (!organism || typeof organism !== 'string') {
      throw new TypeError('Organism must be a valid string');
    }
    if (weight <= 0) throw new RangeError('Weight must be positive');
    if (age < 0) throw new RangeError('Age cannot be negative');
    this.organism = organism;
    this.weight = weight;
    this.age = age;
  }

  basalMetabolicRate(gender) {
    try {
      if (!['male', 'female'].includes(gender.toLowerCase())) {
        throw new Error('Gender must be male or female');
      }
      const g = gender.toLowerCase();
      if (g === 'male') {
        return 88.362 + (13.397 * this.weight) + (4.799 * 170) - (5.677 * this.age);
      }
      return 447.593 + (9.247 * this.weight) + (3.098 * 160) - (4.330 * this.age);
    } catch (err) {
      console.error(`BMR calculation error: ${err.message}`);
      return null;
