// Example 1: Chemistry utilities module demonstrating unit handling,
// validation, stoichiometry helpers, and safe scientific computation.

/**
 * @typedef {Object} Element
 * @property {string} symbol
 * @property {string} name
 * @property {number} atomicMass
 */

/**
 * A tiny periodic table subset for demonstration.
 * In production, prefer a complete and vetted data source.
 */
export const PERIODIC_TABLE = Object.freeze({
  H: Object.freeze({ symbol: 'H', name: 'Hydrogen', atomicMass: 1.008 }),
  C: Object.freeze({ symbol: 'C', name: 'Carbon', atomicMass: 12.011 }),
  N: Object.freeze({ symbol: 'N', name: 'Nitrogen', atomicMass: 14.007 }),
  O: Object.freeze({ symbol: 'O', name: 'Oxygen', atomicMass: 15.999 }),
  Na: Object.freeze({ symbol: 'Na', name: 'Sodium', atomicMass: 22.990 }),
  Cl: Object.freeze({ symbol: 'Cl', name: 'Chlorine', atomicMass: 35.45 }),
  Ca: Object.freeze({ symbol: 'Ca', name: 'Calcium', atomicMass: 40.078 })
});

/**
 * Assert a condition with a chemistry-specific error message.
 * @param {boolean} condition
 * @param {string} message
 */
function invariant(condition, message) {
  if (!condition) {
    throw new Error(`Chemistry invariant failed: ${message}`);
  }
}

/**
 * Ensure an input is a finite positive number.
 * @param {number} value
 * @param {string} name
 */
function assertPositiveFinite(value, name) {
  invariant(typeof value === 'number' && Number.isFinite(value), `${name} must be finite`);
  invariant(value > 0, `${name} must be > 0`);
}

/**
 * Parse a simple chemical formula without nested parentheses.
 * Supported examples: H2O, CO2, C6H12O6, NaCl, CaCl2
 * @param {string} formula
 * @returns {Map<string, number>}
 */
export function parseFormula(formula) {
  invariant(typeof formula === 'string' && formula.trim().length > 0, 'formula must be non-empty');
  const clean = formula.trim();
  const tokenPattern = /([A-Z][a-z]?)(\d*)/g;
  const counts = new Map();

  let match;
  let consumed = '';
  while ((match = tokenPattern.exec(clean)) !== null) {
    const [, symbol, countText] = match;
    invariant(PERIODIC_TABLE[symbol], `unknown element symbol: ${symbol}`);
    const count = countText ? Number.parseInt(countText, 10) : 1;
    invariant(Number.isInteger(count) && count > 0, `invalid count for ${symbol}`);
    counts.set(symbol, (counts.get(symbol) || 0) + count);
    consumed += match[0];
  }

  invariant(consumed === clean, `unable to fully parse formula: ${formula}`);
  return counts;
}

/**
 * Compute molar mass from a formula string.
 * @param {string} formula
 * @returns {number}
 */
export function molarMass(formula) {
  const composition = parseFormula(formula);
  let total = 0;
  for (const [symbol, count] of composition.entries()) {
    total += PERIODIC_TABLE[symbol].atomicMass * count;
  }
  return total;
}

/**
 * Convert grams to moles.
 * @param {number} grams
 * @param {string} formula
 * @returns {number}
 */
export function gramsToMoles(grams, formula) {
  assertPositiveFinite(grams, 'grams');
  return grams / molarMass(formula);
}

/**
 * Convert moles to grams.
 * @param {number} moles
 * @param {string} formula
 * @returns {number}
 */
export function molesToGrams(moles, formula) {
  assertPositiveFinite(moles, 'moles');
  return moles * molarMass(formula);
}

/**
 * Round with explicit precision for display only.
 * Avoid using rounded values for chained scientific calculations.
 * @param {number} value
 * @param {number} digits
 * @returns {number}
 */
export function roundForReport(value, digits = 4) {
  invariant(Number.isInteger(digits) && digits >= 0 && digits <= 12, 'digits out of range');
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
}

/**
 * Produce a descriptive report for a compound sample.
 * @param {string} formula
 * @param {number} grams
 * @returns {object}
 */
export function analyzeSample(formula, grams) {
  assertPositiveFinite(grams, 'grams');
  const composition = parseFormula(formula);
  const mm = molarMass(formula);
  const moles = gramsToMoles(grams, formula);

  const elementalMasses = [...composition.entries()].map(([symbol, count]) => {
    const element = PERIODIC_TABLE[symbol];
    const contribution = element.atomicMass * count;
    return {
      symbol,
      count,
      atomicMass: element.atomicMass,
      massContribution: contribution,
      massPercent: (contribution / mm) * 100
    };
  });

  return {
    formula,
    grams,
    molarMass: mm,
    moles,
    elementalMasses
  };
}

/**
 * Example execution function.
 * Keep side effects isolated for testability.
 */
export function demo() {
  const water = analyzeSample('H2O', 18.015);
  const carbonDioxide = analyzeSample('CO2', 44.01);

  return {
    water: {
      molarMass: roundForReport(water.molarMass, 3),
      moles: roundForReport(water.moles, 3)
    },
    carbonDioxide: {
      molarMass: roundForReport(carbonDioxide.molarMass, 3),
      moles: roundForReport(carbonDioxide.moles, 3)
    }
  };
}

// Example self-checks using simple assertions.
function runSelfChecks() {
  invariant(roundForReport(molarMass('H2O'), 3) === 18.015, 'H2O molar mass mismatch');
  invariant(roundForReport(molarMass('CO2'), 3) === 44.009, 'CO2 molar mass mismatch');
  invariant(parseFormula('CaCl2').get('Cl') === 2, 'CaCl2 parse mismatch');

  const sodiumChlorideMoles = gramsToMoles(58.44, 'NaCl');
  invariant(Math.abs(sodiumChlorideMoles - 1) < 0.01, 'NaCl conversion mismatch');
}

runSelfChecks();

// Example 2: Solution chemistry module focused on concentration,
// dilution, and transparent assumptions.

/**
 * Scientific constants used in aqueous chemistry.
 */
export const CONSTANTS = Object.freeze({
  WATER_DENSITY_G_PER_ML: 1.0,
  ROOM_TEMPERATURE_C: 25,
  LITERS_PER_ML: 1e-3
});

/**
 * Validate numeric inputs before calculations.
 * @param {number} value
 * @param {string} label
 * @param {object} [options]
 */
function validateNumber(value, label, options = {}) {
  const { minExclusive = -Infinity, minInclusive = -Infinity } = options;
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${label} must be a finite number`);
  }
  if (!(value > minExclusive) && minExclusive !== -Infinity) {
    throw new RangeError(`${label} must be > ${minExclusive}`);
  }
  if (!(value >= minInclusive) && minInclusive !== -Infinity) {
    throw new RangeError(`${label} must be >= ${minInclusive}`);
  }
}

/**
 * Convert milliliters to liters.
 * @param {number} mL
 * @returns {number}
 */
export function millilitersToLiters(mL) {
  validateNumber(mL, 'mL', { minExclusive: 0 });
  return mL * CONSTANTS.LITERS_PER_ML;
}

/**
 * Compute molarity from moles and liters.
 * @param {number} moles
 * @param {number} liters
 * @returns {number}
 */
export function molarityFromMoles(moles, liters) {
  validateNumber(moles, 'moles', { minInclusive: 0 });
  validateNumber(liters, 'liters', { minExclusive: 0 });
  return moles / liters;
}

/**
 * Compute moles from molarity and liters.
 * @param {number} molarity
 * @param {number} liters
 * @returns {number}
 */
export function molesFromMolarity(molarity, liters) {
  validateNumber(molarity, 'molarity', { minInclusive: 0 });
  validateNumber(liters, 'liters', { minExclusive: 0 });
  return molarity * liters;
}

/**
 * Use the dilution equation M1V1 = M2V2.
 * @param {number} initialMolarity
 * @param {number} targetMolarity
 * @param {number} finalVolumeL
 * @returns {{stockVolumeL: number, diluentVolumeL: number}}
 */
export function dilutionPlan(initialMolarity, targetMolarity, finalVolumeL) {
  validateNumber(initialMolarity, 'initialMolarity', { minExclusive: 0 });
  validateNumber(targetMolarity, 'targetMolarity', { minExclusive: 0 });
  validateNumber(finalVolumeL, 'finalVolumeL', { minExclusive: 0 });

  if (targetMolarity > initialMolarity) {
    throw new RangeError('targetMolarity cannot exceed initialMolarity in a dilution');
  }

  const stockVolumeL = (targetMolarity * finalVolumeL) / initialMolarity;
  const diluentVolumeL = finalVolumeL - stockVolumeL;

  return { stockVolumeL, diluentVolumeL };
}

/**
 * Calculate mass concentration in g/L.
 * @param {number} grams
 * @param {number} liters
 * @returns {number}
 */
export function gramsPerLiter(grams, liters) {
  validateNumber(grams, 'grams', { minInclusive: 0 });
  validateNumber(liters, 'liters', { minExclusive: 0 });
  return grams / liters;
}

/**
 * Express a concentration as parts per million for dilute aqueous systems.
 * Assumes density ~ 1.0 g/mL unless a different solution mass is provided.
 * @param {number} soluteMg
 * @param {number} solutionLiters
 * @returns {number}
 */
export function ppmFromMgPerLiter(soluteMg, solutionLiters) {
  validateNumber(soluteMg, 'soluteMg', { minInclusive: 0 });
  validateNumber(solutionLiters, 'solutionLiters', { minExclusive: 0 });
  return soluteMg / solutionLiters;
}

/**
 * A structured report function that records assumptions.
 * @param {object} input
 * @returns {object}
 */
export function prepareSolutionReport(input) {
  const { stockMolarity, targetMolarity, finalVolumeML } = input;
  validateNumber(finalVolumeML, 'finalVolumeML', { minExclusive: 0 });

  const finalVolumeL = millilitersToLiters(finalVolumeML);
  const plan = dilutionPlan(stockMolarity, targetMolarity, finalVolumeL);

  return {
    conditions: {
      temperatureC: CONSTANTS.ROOM_TEMPERATURE_C,
      densityAssumption: 'aqueous solution approximated as 1.0 g/mL where relevant'
    },
    input: {
      stockMolarity,
      targetMolarity,
      finalVolumeML,
      finalVolumeL
    },
    output: {
      stockVolumeL: plan.stockVolumeL,
      stockVolumeML: plan.stockVolumeL * 1000,
      diluentVolumeL: plan.diluentVolumeL,
      diluentVolumeML: plan.diluentVolumeL * 1000
    }
  };
}

/**
 * Format a report for downstream display layers.
 * @param {object} report
 * @returns {string}
 */
export function formatReport(report) {
  const { input, output, conditions } = report;
  return [
    `Prepare ${input.finalVolumeML.toFixed(1)} mL of ${input.targetMolarity.toFixed(3)} M solution`,
    `from ${input.stockMolarity.toFixed(3)} M stock.`,
    `Use ${output.stockVolumeML.toFixed(2)} mL stock and ${output.diluentVolumeML.toFixed(2)} mL diluent.`,
    `Assumption: ${conditions.densityAssumption}.`
  ].join(' ');
}

/**
 * Deterministic demo function.
 */
export function demo() {
  const report = prepareSolutionReport({
    stockMolarity: 2.0,
    targetMolarity: 0.5,
    finalVolumeML: 250
  });

  return {
    report,
    text: formatReport(report),
    examples: {
      sodiumChloride: gramsPerLiter(5.84, 1),
      traceLeadApproxPpm: ppmFromMgPerLiter(0.015, 1)
    }
  };
}

// Minimal self-tests.
(function selfTest() {
  const liters = millilitersToLiters(500);
  if (liters !== 0.5) throw new Error('mL to L conversion failed');

  const molarity = molarityFromMoles(0.25, 0.5);
  if (Math.abs(molarity - 0.5) > 1e-12) throw new Error('molarity calculation failed');

  const plan = dilutionPlan(1, 0.1, 1);
  if (Math.abs(plan.stockVolumeL - 0.1) > 1e-12) throw new Error('dilution plan failed');
})();

// Example 3: Acid-base chemistry module emphasizing explicit assumptions,
// pH relationships, and robust edge-case handling.

const EPSILON = 1e-14;

/**
 * Validate concentration-like values.
 * @param {number} value
 * @param {string} label
 */
function assertNonNegativeFinite(value, label) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${label} must be finite`);
  }
  if (value < 0) {
    throw new RangeError(`${label} must be non-negative`);
  }
}

/**
 * Safe base-10 logarithm for chemistry quantities.
 * @param {number} value
 * @returns {number}
 */
function log10(value) {
  if (!(value > 0)) {
    throw new RangeError('log10 input must be > 0');
  }
  return Math.log(value) / Math.LN10;
}

/**
 * Compute pH from hydrogen ion concentration.
 * @param {number} hPlus
 * @returns {number}
 */
export function pHFromHPlus(hPlus) {
  assertNonNegativeFinite(hPlus, 'hPlus');
  if (hPlus < EPSILON) {
    throw new RangeError('hPlus too small for stable calculation');
  }
  return -log10(hPlus);
}

/**
 * Compute pOH from hydroxide ion concentration.
 * @param {number} ohMinus
 * @returns {number}
 */
export function pOHFromOHMinus(ohMinus) {
  assertNonNegativeFinite(ohMinus, 'ohMinus');
  if (ohMinus < EPSILON) {
    throw new RangeError('ohMinus too small for stable calculation');
  }
  return -log10(ohMinus);
}

/**
 * Convert pH to [H+].
 * @param {number} pH
 * @returns {number}
 */
export function hPlusFromPH(pH) {
  if (typeof pH !== 'number' || !Number.isFinite(pH)) {
    throw new TypeError('pH must be finite');
  }
  return 10 ** (-pH);
}

/**
 * Convert pOH to [OH-].
 * @param {number} pOH
 * @returns {number}
 */
export function ohMinusFromPOH(pOH) {
  if (typeof pOH !== 'number' || !Number.isFinite(pOH)) {
    throw new TypeError('pOH must be finite');
  }
  return 10 ** (-pOH);
}

/**
 * At 25 C, pH + pOH = 14 for dilute aqueous solutions.
 * @param {number} pH
 * @returns {number}
 */
export function pOHFromPH(pH) {
  if (typeof pH !== 'number' || !Number.isFinite(pH)) {
    throw new TypeError('pH must be finite');
  }
  return 14 - pH;
}

/**
 * Henderson-Hasselbalch equation for buffer estimate.
 * Best used when both acid and conjugate base are present.
 * @param {number} pKa
 * @param {number} acidMoles
 * @param {number} baseMoles
 * @returns {number}
 */
export function bufferPH(pKa, acidMoles, baseMoles) {
  if (typeof pKa !== 'number' || !Number.isFinite(pKa)) {
    throw new TypeError('pKa must be finite');
  }
  assertNonNegativeFinite(acidMoles, 'acidMoles');
  assertNonNegativeFinite(baseMoles, 'baseMoles');

  if (acidMoles <= 0 || baseMoles <= 0) {
    throw new RangeError('acidMoles and baseMoles must both be > 0 for Henderson-Hasselbalch');
  }

  return pKa + log10(baseMoles / acidMoles);
}

/**
 * Simulate strong acid dilution assuming complete dissociation.
 * @param {number} stockConcentration
 * @param {number} stockVolumeL
 * @param {number} finalVolumeL
 * @returns {object}
 */
export function diluteStrongAcid(stockConcentration, stockVolumeL, finalVolumeL) {
  assertNonNegativeFinite(stockConcentration, 'stockConcentration');
  assertNonNegativeFinite(stockVolumeL, 'stockVolumeL');
  assertNonNegativeFinite(finalVolumeL, 'finalVolumeL');

  if (stockConcentration <= 0 || stockVolumeL <= 0 || finalVolumeL <= 0) {
    throw new RangeError('all inputs must be > 0');
  }
  if (finalVolumeL < stockVolumeL) {
    throw new RangeError('finalVolumeL should be >= stockVolumeL in dilution scenarios');
  }

  const molesHPlus = stockConcentration * stockVolumeL;
  const finalHPlus = molesHPlus / finalVolumeL;

  return {
    molesHPlus,
    finalHPlus,
    pH: pHFromHPlus(finalHPlus),
    assumptions: ['strong monoprotic acid', 'complete dissociation', '25 C aqueous approximation']
  };
}

/**
 * Create a concise chemistry summary object.
 * @param {object} options
 * @returns {object}
 */
export function summarizeAcidBase(options) {
  const { pKa, acidMoles, baseMoles, stockConcentration, stockVolumeL, finalVolumeL } = options;
  const bufferEstimate = bufferPH(pKa, acidMoles, baseMoles);
  const dilution = diluteStrongAcid(stockConcentration, stockVolumeL, finalVolumeL);

  return {
    buffer: {
      estimatedPH: bufferEstimate,
      pOH: pOHFromPH(bufferEstimate)
    },
    dilution
  };
}

/**
 * Demonstration entry point.
 */
export function demo() {
  return summarizeAcidBase({
    pKa: 4.76,
    acidMoles: 0.2,
    baseMoles: 0.1,
    stockConcentration: 0.01,
    stockVolumeL: 0.05,
    finalVolumeL: 0.5
  });
}

// Self-test block.
(function verify() {
  const neutralPH = pHFromHPlus(1e-7);
  if (Math.abs(neutralPH - 7) > 1e-12) throw new Error('neutral pH failed');

  const neutralPOH = pOHFromPH(7);
  if (neutralPOH !== 7) throw new Error('pOH relation failed');

  const estimate = bufferPH(4.76, 1, 1);
  if (Math.abs(estimate - 4.76) > 1e-12) throw new Error('buffer equation failed');
})();

// Example 4: Gas law chemistry module with clear units and assumptions.
// Demonstrates ideal gas calculations and composable API design.

export const GAS_CONSTANTS = Object.freeze({
  R_L_ATM_PER_MOL_K: 0.082057,
  STANDARD_TEMPERATURE_K: 273.15,
  STANDARD_PRESSURE_ATM: 1
});

function assertFinitePositive(value, name) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be finite`);
  }
  if (value <= 0) {
    throw new RangeError(`${name} must be > 0`);
  }
}

/**
 * Convert Celsius to Kelvin.
 * @param {number} celsius
 * @returns {number}
 */
export function celsiusToKelvin(celsius) {
  if (typeof celsius !== 'number' || !Number.isFinite(celsius)) {
    throw new TypeError('celsius must be finite');
  }
  const kelvin = celsius + 273.15;
  if (kelvin <= 0) {
    throw new RangeError('temperature below absolute zero');
  }
  return kelvin;
}

/**
 * Ideal gas law: PV = nRT, solving for pressure.
 * @param {number} moles
 * @param {number} temperatureK
 * @param {number} volumeL
 * @returns {number}
 */
export function pressureFromIdealGas(moles, temperatureK, volumeL) {
  assertFinitePositive(moles, 'moles');
  assertFinitePositive(temperatureK, 'temperatureK');
  assertFinitePositive(volumeL, 'volumeL');
  return (moles * GAS_CONSTANTS.R_L_ATM_PER_MOL_K * temperatureK) / volumeL;
}

/**
 * Solve the ideal gas law for volume.
 * @param {number} moles
 * @param {number} temperatureK
 * @param {number} pressureAtm
 * @returns {number}
 */
export function volumeFromIdealGas(moles, temperatureK, pressureAtm) {
  assertFinitePositive(moles, 'moles');
  assertFinitePositive(temperatureK, 'temperatureK');
  assertFinitePositive(pressureAtm, 'pressureAtm');
  return (moles * GAS_CONSTANTS.R_L_ATM_PER_MOL_K * temperatureK) / pressureAtm;
}

/**
 * Combined gas law for fixed amount of gas.
 * P1V1/T1 = P2V2/T2
 * @param {object} state
 * @returns {number}
 */
export function finalVolumeCombinedGasLaw(state) {
  const { p1, v1, t1, p2, t2 } = state;
  assertFinitePositive(p1, 'p1');
  assertFinitePositive(v1, 'v1');
  assertFinitePositive(t1, 't1');
  assertFinitePositive(p2, 'p2');
  assertFinitePositive(t2, 't2');
  return (p1 * v1 * t2) / (t1 * p2);
}

/**
 * Dalton's law of partial pressures.
 * @param {number[]} partialPressures
 * @returns {number}
 */
export function totalPressure(partialPressures) {
  if (!Array.isArray(partialPressures) || partialPressures.length === 0) {
    throw new TypeError('partialPressures must be a non-empty array');
  }
  return partialPressures.reduce((sum, value, index) => {
    assertFinitePositive(value, `partialPressures[${index}]`);
    return sum + value;
  }, 0);
}

/**
 * Mole fraction from a component partial pressure.
 * @param {number} componentPressure
 * @param {number} totalPressureAtm
 * @returns {number}
 */
export function moleFraction(componentPressure, totalPressureAtm) {
  assertFinitePositive(componentPressure, 'componentPressure');
  assertFinitePositive(totalPressureAtm, 'totalPressureAtm');
  if (componentPressure > totalPressureAtm) {
    throw new RangeError('componentPressure cannot exceed totalPressureAtm');
  }
  return componentPressure / totalPressureAtm;
}

/**
 * Standard molar volume estimate for an ideal gas at STP.
 * @param {number} moles
 * @returns {number}
 */
export function stpVolume(moles) {
  assertFinitePositive(moles, 'moles');
  return volumeFromIdealGas(
    moles,
    GAS_CONSTANTS.STANDARD_TEMPERATURE_K,
    GAS_CONSTANTS.STANDARD_PRESSURE_ATM
  );
}

/**
 * Generate a report for a gas sample.
 * @param {object} input
 * @returns {object}
 */
export function gasSampleReport(input) {
  const { moles, temperatureC, volumeL, partials } = input;
  assertFinitePositive(moles, 'moles');
  assertFinitePositive(volumeL, 'volumeL');

  const temperatureK = celsiusToKelvin(temperatureC);
  const pressureAtm = pressureFromIdealGas(moles, temperatureK, volumeL);
  const totalPartialPressure = totalPressure(partials);

  return {
    assumptions: ['ideal gas behavior', 'uniform temperature', 'pressure in atm, volume in L'],
    state: { moles, temperatureC, temperatureK, volumeL },
    calculated: {
      pressureAtm,
      totalPartialPressure,
      methaneFractionIfFirst: moleFraction(partials[0], totalPartialPressure)
    }
  };
}

/**
 * Demo function.
 */
export function demo() {
  return gasSampleReport({
    moles: 1,
    temperatureC: 25,
    volumeL: 24.5,
    partials: [0.5, 0.3, 0.2]
  });
}

// Self-checks.
(function selfCheck() {
  const stp = stpVolume(1);
  if (Math.abs(stp - 22.414) > 0.1) throw new Error('STP volume check failed');

  const tp = totalPressure([0.2, 0.3, 0.5]);
  if (Math.abs(tp - 1.0) > 1e-12) throw new Error('Dalton law check failed');

  const fraction = moleFraction(0.25, 1.0);
  if (Math.abs(fraction - 0.25) > 1e-12) throw new Error('mole fraction check failed');
})();

// Example 5: Thermochemistry module with careful sign conventions,
// state documentation, and immutable result objects.

export const ENERGY_UNITS = Object.freeze({
  JOULES_PER_KILOJOULE: 1000
});

/**
 * Enforce finite numeric values.
 * @param {number} value
 * @param {string} name
 */
function requireFinite(value, name) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be finite`);
  }
}

/**
 * Convert kilojoules to joules.
 * @param {number} kJ
 * @returns {number}
 */
export function kJToJ(kJ) {
  requireFinite(kJ, 'kJ');
  return kJ * ENERGY_UNITS.JOULES_PER_KILOJOULE;
}

/**
 * Convert joules to kilojoules.
 * @param {number} j
 * @returns {number}
 */
export function jToKJ(j) {
  requireFinite(j, 'j');
  return j / ENERGY_UNITS.JOULES_PER_KILOJOULE;
}

/**
 * Heat transfer estimate from q = m c ΔT.
 * Sign convention: q > 0 means system absorbs heat.
 * @param {number} massG
 * @param {number} specificHeatJPerG_C
 * @param {number} deltaT_C
 * @returns {number}
 */
export function heatTransfer(massG, specificHeatJPerG_C, deltaT_C) {
  requireFinite(massG, 'massG');
  requireFinite(specificHeatJPerG_C, 'specificHeatJPerG_C');
  requireFinite(deltaT_C, 'deltaT_C');
  if (massG <= 0 || specificHeatJPerG_C <= 0) {
    throw new RangeError('massG and specificHeatJPerG_C must be > 0');
  }
  return massG * specificHeatJPerG_C * deltaT_C;
}

/**
 * Estimate ΔH from bond energies.
 * ΔH ≈ Σ(bonds broken) - Σ(bonds formed)
 * @param {number[]} broken
 * @param {number[]} formed
 * @returns {number}
 */
export function enthalpyFromBondEnergies(broken, formed) {
  if (!Array.isArray(broken) || !Array.isArray(formed)) {
    throw new TypeError('broken and formed must be arrays');
  }
  const sum = (values, name) => values.reduce((acc, value, i) => {
    requireFinite(value, `${name}[${i}]`);
    if (value < 0) throw new RangeError(`${name}[${i}] cannot be negative`);
    return acc + value;
  }, 0);

  return sum(broken, 'broken') - sum(formed, 'formed');
}

/**
 * Hess's law helper for summing reaction enthalpies.
 * @param {number[]} stepsKJ
 * @returns {number}
 */
export function hessLaw(stepsKJ) {
  if (!Array.isArray(stepsKJ) || stepsKJ.length === 0) {
    throw new TypeError('stepsKJ must be a non-empty array');
  }
  return stepsKJ.reduce((total, value, i) => {
    requireFinite(value, `stepsKJ[${i}]`);
    return total + value;
  }, 0);
}

/**
 * Determine whether a process is endothermic or exothermic.
 * @param {number} deltaH_kJ
 * @returns {'endothermic'|'exothermic'|'thermoneutral'}
 */
export function classifyThermalProcess(deltaH_kJ) {
  requireFinite(deltaH_kJ, 'deltaH_kJ');
  if (deltaH_kJ > 0) return 'endothermic';
  if (deltaH_kJ < 0) return 'exothermic';
  return 'thermoneutral';
}

/**
 * Build an immutable experiment result.
 * @param {object} options
 * @returns {Readonly<object>}
 */
export function calorimetryReport(options) {
  const { massG, specificHeatJPerG_C, initialTempC, finalTempC } = options;
  requireFinite(initialTempC, 'initialTempC');
  requireFinite(finalTempC, 'finalTempC');

  const deltaT_C = finalTempC - initialTempC;
  const qJ = heatTransfer(massG, specificHeatJPerG_C, deltaT_C);
  const result = {
    data: { massG, specificHeatJPerG_C, initialTempC, finalTempC, deltaT_C },
    heat: {
      qJ,
      qKJ: jToKJ(qJ),
      classification: classifyThermalProcess(jToKJ(qJ))
    },
    note: 'Positive q indicates heat absorbed by the system as defined here.'
  };

  return Object.freeze(result);
}

/**
 * Demo function using water heat capacity.
 */
export function demo() {
  const report = calorimetryReport({
    massG: 100,
    specificHeatJPerG_C: 4.184,
    initialTempC: 22,
    finalTempC: 30
  });

  return {
    report,
    bondEstimateKJ: enthalpyFromBondEnergies([413, 436], [467, 391]),
    hessLawKJ: hessLaw([-100, 25, -10])
  };
}

// Lightweight validation.
(function validate() {
  const q = heatTransfer(10, 4, 5);
  if (q !== 200) throw new Error('heat transfer mismatch');

  const h = hessLaw([1, 2, 3]);
  if (h !== 6) throw new Error('Hess law mismatch');

  const type = classifyThermalProcess(-5);
  if (type !== 'exothermic') throw new Error('classification mismatch');
})();

// Example 6: Equilibrium chemistry module demonstrating ICE-style reasoning,
// reaction quotient checks, and stable utility functions.

/**
 * Ensure numeric chemistry inputs are suitable for calculation.
 * @param {number} value
 * @param {string} name
 */
function requireNonNegative(value, name) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be finite`);
  }
  if (value < 0) {
    throw new RangeError(`${name} must be >= 0`);
  }
}

/**
 * Raise a value to a stoichiometric power.
 * @param {number} concentration
 * @param {number} coefficient
 * @returns {number}
 */
function term(concentration, coefficient) {
  requireNonNegative(concentration, 'concentration');
  if (coefficient === 0) return 1;
  if (concentration === 0 && coefficient > 0) return 0;
  return concentration ** coefficient;
}

/**
 * Compute reaction quotient or equilibrium constant form:
 * products over reactants, omitting pure solids/liquids externally.
 * @param {object} products
 * @param {object} reactants
 * @returns {number}
 */
export function equilibriumExpression(products, reactants) {
  const multiplyTerms = (side, label) => Object.entries(side).reduce((acc, [name, spec]) => {
    const { concentration, coefficient } = spec;
    requireNonNegative(concentration, `${label}.${name}.concentration`);
    if (!Number.isInteger(coefficient) || coefficient < 0) {
      throw new RangeError(`${label}.${name}.coefficient must be a non-negative integer`);
    }
    return acc * term(concentration, coefficient);
  }, 1);

  const numerator = multiplyTerms(products, 'products');
  const denominator = multiplyTerms(reactants, 'reactants');
  if (denominator === 0) throw new RangeError('reactant term evaluates to zero');
  return numerator / denominator;
}

/**
 * Compare Q and K to infer net direction.
 * @param {number} q
 * @param {number} k
 * @returns {'forward'|'reverse'|'equilibrium'}
 */
export function compareQToK(q, k) {
  requireNonNegative(q, 'q');
  requireNonNegative(k, 'k');
  const tolerance = 1e-9;
  if (Math.abs(q - k) <= tolerance) return 'equilibrium';
  return q < k ? 'forward' : 'reverse';
}

/**
 * Solve a simple A <=> B equilibrium where K = [B]/[A].
 * Initial concentrations must be non-negative.
 * @param {number} initialA
 * @param {number} initialB
 * @param {number} k
 * @returns {object}
 */
export function solveSimpleABEquilibrium(initialA, initialB, k) {
  requireNonNegative(initialA, 'initialA');
  requireNonNegative(initialB, 'initialB');
  requireNonNegative(k, 'k');
  if (k === 0) {
    return { A: initialA + initialB, B: 0, shift: 'reverse' };
  }

  const total = initialA + initialB;
  const equilibriumA = total / (1 + k);
  const equilibriumB = total - equilibriumA;
  const shift = compareQToK(initialB / Math.max(initialA, 1e-15), k);

  return { A: equilibriumA, B: equilibriumB, shift };
}

/**
 * Estimate percent dissociation for HA <=> H+ + A-
 * with x equilibrium approximation provided directly.
 * @param {number} initialAcid
 * @param {number} x
 * @returns {number}
 */
export function percentDissociation(initialAcid, x) {
  requireNonNegative(initialAcid, 'initialAcid');
  requireNonNegative(x, 'x');
  if (initialAcid === 0) throw new RangeError('initialAcid must be > 0');
  if (x > initialAcid) throw new RangeError('x cannot exceed initialAcid');
  return (x / initialAcid) * 100;
}

/**
 * Generate a human-readable equilibrium summary.
 * @param {object} options
 * @returns {object}
 */
export function equilibriumSummary(options) {
  const { qDefinition, kValue, initialA, initialB } = options;
  const qValue = equilibriumExpression(qDefinition.products, qDefinition.reactants);
  const direction = compareQToK(qValue, kValue);
  const solved = solveSimpleABEquilibrium(initialA, initialB, kValue);

  return {
    qValue,
    kValue,
    direction,
    solved,
    notes: [
      'Activities are approximated as concentrations.',
      'Pure solids and liquids should be omitted from the expression.',
      'Simple A <=> B solver is a teaching model, not a universal equilibrium engine.'
    ]
  };
}

/**
 * Demonstration.
 */
export function demo() {
  return equilibriumSummary({
    qDefinition: {
      products: { B: { concentration: 0.2, coefficient: 1 } },
