// Example 7: Kinetics chemistry module focused on reaction rates,
// rate laws, and reproducible regression-free calculations.

/**
 * Validate finite values.
 * @param {number} value
 * @param {string} label
 */
function assertFinite(value, label) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${label} must be finite`);
  }
}

/**
 * Validate non-negative concentration/time values.
 * @param {number} value
 * @param {string} label
 */
function assertNonNegative(value, label) {
  assertFinite(value, label);
  if (value < 0) {
    throw new RangeError(`${label} must be non-negative`);
  }
}

/**
 * Average reaction rate based on concentration change over time.
 * @param {number} deltaConcentration
 * @param {number} deltaTime
 * @returns {number}
 */
export function averageRate(deltaConcentration, deltaTime) {
  assertFinite(deltaConcentration, 'deltaConcentration');
  assertFinite(deltaTime, 'deltaTime');
  if (deltaTime === 0) throw new RangeError('deltaTime cannot be zero');
  return deltaConcentration / deltaTime;
}

/**
 * Generic rate law: rate = k[A]^m[B]^n...
 * @param {number} k
 * @param {Array<{concentration:number, order:number}>} terms
 * @returns {number}
 */
export function rateLaw(k, terms) {
  assertNonNegative(k, 'k');
  if (!Array.isArray(terms) || terms.length === 0) {
    throw new TypeError('terms must be a non-empty array');
  }

  return terms.reduce((rate, term, index) => {
    assertNonNegative(term.concentration, `terms[${index}].concentration`);
    assertFinite(term.order, `terms[${index}].order`);
    return rate * (term.concentration ** term.order);
  }, k);
}

/**
 * First-order integrated rate law.
 * [A]t = [A]0 * e^(-kt)
 * @param {number} initialConcentration
 * @param {number} k
 * @param {number} time
 * @returns {number}
 */
export function firstOrderConcentration(initialConcentration, k, time) {
  assertNonNegative(initialConcentration, 'initialConcentration');
  assertNonNegative(k, 'k');
  assertNonNegative(time, 'time');
  return initialConcentration * Math.exp(-k * time);
}

/**
 * First-order half-life.
 * t1/2 = ln(2)/k
 * @param {number} k
 * @returns {number}
 */
export function firstOrderHalfLife(k) {
  assertNonNegative(k, 'k');
  if (k === 0) throw new RangeError('k must be > 0');
  return Math.LN2 / k;
}

/**
 * Determine reaction order using simple ratio method for one reactant.
 * order = log(rate2/rate1) / log(conc2/conc1)
 * @param {number} rate1
 * @param {number} rate2
 * @param {number} conc1
 * @param {number} conc2
 * @returns {number}
 */
export function inferOrder(rate1, rate2, conc1, conc2) {
  assertNonNegative(rate1, 'rate1');
  assertNonNegative(rate2, 'rate2');
  assertNonNegative(conc1, 'conc1');
  assertNonNegative(conc2, 'conc2');
  if (rate1 === 0 || conc1 === 0 || conc2 === 0) {
    throw new RangeError('rate1, conc1, and conc2 must be > 0');
  }
  return Math.log(rate2 / rate1) / Math.log(conc2 / conc1);
}

/**
 * Build a kinetics experiment summary.
 * @param {object} input
 * @returns {object}
 */
export function kineticsSummary(input) {
  const { k, a, b, orderA, orderB, initialA, time } = input;
  const instantaneousModelRate = rateLaw(k, [
    { concentration: a, order: orderA },
    { concentration: b, order: orderB }
  ]);

  const firstOrderAtTime = firstOrderConcentration(initialA, k, time);
  const halfLife = firstOrderHalfLife(k);

  return {
    model: {
      rate: instantaneousModelRate,
      overallOrder: orderA + orderB
    },
    firstOrderDecay: {
      initialA,
      time,
      concentrationAtTime: firstOrderAtTime,
      halfLife
    },
    notes: [
      'Instantaneous rate law model and first-order decay model are shown separately.',
      'Do not combine these blindly unless the reaction mechanism supports it.'
    ]
  };
}

/**
 * Demonstration entry point.
 */
export function demo() {
  return kineticsSummary({
    k: 0.2,
    a: 0.5,
    b: 0.25,
    orderA: 1,
    orderB: 2,
    initialA: 1,
    time: 10
  });
}

// Self-checks.
(function verify() {
  const hl = firstOrderHalfLife(0.6931471805599453);
  if (Math.abs(hl - 1) > 1e-9) throw new Error('half-life check failed');

  const order = inferOrder(4, 16, 1, 2);
  if (Math.abs(order - 2) > 1e-12) throw new Error('order inference failed');
})();

// Example 8: Electrochemistry module illustrating redox calculations,
// Nernst-style helpers, and clear separation of concerns.

export const PHYSICAL_CONSTANTS = Object.freeze({
  FARADAY_C_PER_MOL: 96485,
  R_J_PER_MOL_K: 8.314462618,
  T_STANDARD_K: 298.15
});

function ensureFinite(value, name) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be finite`);
  }
}

function ensurePositive(value, name) {
  ensureFinite(value, name);
  if (value <= 0) {
    throw new RangeError(`${name} must be > 0`);
  }
}

/**
 * Compute standard cell potential.
 * Ecell = Ecathode - Eanode
 * @param {number} cathodeReductionPotential
 * @param {number} anodeReductionPotential
 * @returns {number}
 */
export function standardCellPotential(cathodeReductionPotential, anodeReductionPotential) {
  ensureFinite(cathodeReductionPotential, 'cathodeReductionPotential');
  ensureFinite(anodeReductionPotential, 'anodeReductionPotential');
  return cathodeReductionPotential - anodeReductionPotential;
}

/**
 * Gibbs free energy from cell potential.
 * ΔG = -nFE
 * @param {number} electrons
 * @param {number} cellPotentialV
 * @returns {number}
 */
export function gibbsFromCellPotential(electrons, cellPotentialV) {
  ensurePositive(electrons, 'electrons');
  ensureFinite(cellPotentialV, 'cellPotentialV');
  return -electrons * PHYSICAL_CONSTANTS.FARADAY_C_PER_MOL * cellPotentialV;
}

/**
 * Equilibrium constant from standard cell potential.
 * ln K = nFE° / RT
 * @param {number} electrons
 * @param {number} standardPotentialV
 * @param {number} temperatureK
 * @returns {number}
 */
export function equilibriumConstantFromE(electrons, standardPotentialV, temperatureK = PHYSICAL_CONSTANTS.T_STANDARD_K) {
  ensurePositive(electrons, 'electrons');
  ensureFinite(standardPotentialV, 'standardPotentialV');
  ensurePositive(temperatureK, 'temperatureK');

  const exponent = (electrons * PHYSICAL_CONSTANTS.FARADAY_C_PER_MOL * standardPotentialV) /
    (PHYSICAL_CONSTANTS.R_J_PER_MOL_K * temperatureK);
  return Math.exp(exponent);
}

/**
 * Nernst equation using natural log form.
 * E = E° - (RT/nF) ln Q
 * @param {number} standardPotentialV
 * @param {number} electrons
 * @param {number} reactionQuotient
 * @param {number} temperatureK
 * @returns {number}
 */
export function nernstPotential(standardPotentialV, electrons, reactionQuotient, temperatureK = PHYSICAL_CONSTANTS.T_STANDARD_K) {
  ensureFinite(standardPotentialV, 'standardPotentialV');
  ensurePositive(electrons, 'electrons');
  ensurePositive(reactionQuotient, 'reactionQuotient');
  ensurePositive(temperatureK, 'temperatureK');

  return standardPotentialV - (
    (PHYSICAL_CONSTANTS.R_J_PER_MOL_K * temperatureK) /
    (electrons * PHYSICAL_CONSTANTS.FARADAY_C_PER_MOL)
  ) * Math.log(reactionQuotient);
}

/**
 * Electroplating mass estimate from charge passed.
 * mass = (I t / F) * (molarMass / electrons)
 * @param {number} currentA
 * @param {number} timeS
 * @param {number} molarMassGPerMol
 * @param {number} electrons
 * @returns {number}
 */
export function electroplatedMass(currentA, timeS, molarMassGPerMol, electrons) {
  ensurePositive(currentA, 'currentA');
  ensurePositive(timeS, 'timeS');
  ensurePositive(molarMassGPerMol, 'molarMassGPerMol');
  ensurePositive(electrons, 'electrons');

  const molesElectrons = (currentA * timeS) / PHYSICAL_CONSTANTS.FARADAY_C_PER_MOL;
  const molesMetal = molesElectrons / electrons;
  return molesMetal * molarMassGPerMol;
}

/**
 * Generate an electrochemistry report.
 * @param {object} input
 * @returns {object}
 */
export function electrochemistryReport(input) {
  const { cathodeE, anodeE, electrons, q, currentA, timeS, molarMass } = input;
  const eStandard = standardCellPotential(cathodeE, anodeE);
  const eNonStandard = nernstPotential(eStandard, electrons, q);
  const deltaG = gibbsFromCellPotential(electrons, eStandard);
  const equilibriumK = equilibriumConstantFromE(electrons, eStandard);
  const platedMass = electroplatedMass(currentA, timeS, molarMass, electrons);

  return {
    cell: { eStandard, eNonStandard, electrons },
    thermodynamics: { deltaG, equilibriumK },
    electrolysis: { currentA, timeS, platedMass },
    notes: ['Reduction potentials are provided in volts.', 'Reaction quotient Q must be dimensionless.']
  };
}

/**
 * Demonstration.
 */
export function demo() {
  return electrochemistryReport({
    cathodeE: 0.34,
    anodeE: -0.76,
    electrons: 2,
    q: 0.1,
    currentA: 2,
    timeS: 1800,
    molarMass: 63.546
  });
}

// Self-test.
(function selfTest() {
  const e = standardCellPotential(0.34, -0.76);
  if (Math.abs(e - 1.1) > 1e-12) throw new Error('cell potential failed');

  const mass = electroplatedMass(1, 96485, 107.8682, 1);
  if (Math.abs(mass - 107.8682) > 0.1) throw new Error('electroplating failed');
