// Example 9: Organic chemistry teaching utilities with functional-group
// detection heuristics, nomenclature helpers, and safety reminders.

/**
 * Functional group patterns are simple heuristics for demonstration.
 * They are not full cheminformatics replacements.
 */
const FUNCTIONAL_GROUPS = Object.freeze([
  Object.freeze({ name: 'alcohol', pattern: /OH/ }),
  Object.freeze({ name: 'carboxylic acid', pattern: /COOH/ }),
  Object.freeze({ name: 'amine', pattern: /NH2|N\(/ }),
  Object.freeze({ name: 'aldehyde', pattern: /CHO/ }),
  Object.freeze({ name: 'ketone', pattern: /CO/ }),
  Object.freeze({ name: 'alkene', pattern: /C=C/ }),
  Object.freeze({ name: 'alkyne', pattern: /C#C/ })
]);

function validateString(value, name) {
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new TypeError(`${name} must be a non-empty string`);
  }
}

/**
 * Normalize an input structural shorthand.
 * @param {string} structure
 * @returns {string}
 */
export function normalizeStructure(structure) {
  validateString(structure, 'structure');
  return structure.replace(/\s+/g, '').toUpperCase();
}

/**
 * Detect likely functional groups from shorthand text.
 * @param {string} structure
 * @returns {string[]}
 */
export function detectFunctionalGroups(structure) {
  const normalized = normalizeStructure(structure);
  return FUNCTIONAL_GROUPS
    .filter(group => group.pattern.test(normalized))
    .map(group => group.name);
}

/**
 * Estimate degree of unsaturation from molecular formula counts.
 * DBE = C - H/2 - X/2 + N/2 + 1
 * Oxygen is ignored in DBE.
 * @param {object} counts
 * @returns {number}
 */
export function degreeOfUnsaturation(counts) {
  const { C = 0, H = 0, N = 0, X = 0 } = counts;
  for (const [key, value] of Object.entries({ C, H, N, X })) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new TypeError(`${key} count must be a non-negative finite number`);
    }
  }
  return C - H / 2 - X / 2 + N / 2 + 1;
}

/**
 * Classify a hydrocarbon family from simple shorthand.
 * @param {string} structure
 * @returns {string}
 */
export function classifyHydrocarbon(structure) {
  const normalized = normalizeStructure(structure);
  if (/C#C/.test(normalized)) return 'alkyne';
  if (/C=C/.test(normalized)) return 'alkene';
  return 'alkane or other saturated framework';
}

/**
 * Build a teaching-oriented organic summary.
 * @param {object} input
 * @returns {object}
 */
export function organicSummary(input) {
  const { name, structure, formulaCounts } = input;
  validateString(name, 'name');
  const normalized = normalizeStructure(structure);
  const groups = detectFunctionalGroups(normalized);
  const unsaturation = degreeOfUnsaturation(formulaCounts);
  const hydrocarbonClass = classifyHydrocarbon(normalized);

  return {
    compound: name,
    normalizedStructure: normalized,
    inferred: {
      functionalGroups: groups,
      degreeOfUnsaturation: unsaturation,
      hydrocarbonClass
    },
    notes: [
      'Pattern-based detection is approximate.',
      'Full structural determination requires proper graph-based chemistry tools.',
      'Always verify with spectroscopy and reference data where relevant.'
    ],
    safety: {
      reminder: 'Consult SDS information before handling any organic reagent or solvent.'
    }
  };
}

/**
 * Produce a simple homologous series sequence.
 * @param {number} length
 * @returns {string[]}
 */
export function alkaneSeries(length) {
  if (!Number.isInteger(length) || length <= 0) {
    throw new RangeError('length must be a positive integer');
  }
  const prefixes = ['meth', 'eth', 'prop', 'but', 'pent', 'hex', 'hept', 'oct', 'non', 'dec'];
  return Array.from({ length: Math.min(length, prefixes.length) }, (_, i) => `${prefixes[i]}ane`);
}

/**
 * Demo function.
 */
export function demo() {
  return organicSummary({
    name: 'Ethanol',
    structure: 'CH3CH2OH',
    formulaCounts: { C: 2, H: 6, O: 1 }
  });
}

// Self-checks.
(function verify() {
  const groups = detectFunctionalGroups('CH3CH2OH');
  if (!groups.includes('alcohol')) throw new Error('functional group detection failed');

  const dbe = degreeOfUnsaturation({ C: 6, H: 6 });
  if (dbe !== 4) throw new Error('DBE failed');

  const series = alkaneSeries(3);
  if (series.join(',') !== 'methane,ethane,propane') throw new Error('series failed');
})();

// Example 10: Laboratory chemistry best-practices module combining
// metadata capture, uncertainty handling, unit normalization, and auditability.

/**
 * Create immutable measurement records.
 * Good chemistry practice includes units, uncertainty, and provenance.
 */
export function createMeasurement(value, unit, uncertainty = 0, source = 'unspecified') {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError('value must be finite');
  }
  if (typeof unit !== 'string' || unit.trim().length === 0) {
    throw new TypeError('unit must be a non-empty string');
  }
  if (typeof uncertainty !== 'number' || !Number.isFinite(uncertainty) || uncertainty < 0) {
    throw new TypeError('uncertainty must be a non-negative finite number');
  }
  if (typeof source !== 'string' || source.trim().length === 0) {
    throw new TypeError('source must be a non-empty string');
  }

  return Object.freeze({
    value,
    unit,
    uncertainty,
    source,
    timestamp: new Date().toISOString()
  });
}

/**
 * Normalize common volume units to liters.
 * @param {object} measurement
 * @returns {object}
 */
export function toLiters(measurement) {
  const { value, unit, uncertainty, source } = measurement;
  switch (unit) {
    case 'L':
      return createMeasurement(value, 'L', uncertainty, source);
    case 'mL':
      return createMeasurement(value / 1000, 'L', uncertainty / 1000, source);
    default:
      throw new RangeError(`unsupported volume unit: ${unit}`);
  }
}

/**
 * Normalize common mass units to grams.
 * @param {object} measurement
 * @returns {object}
 */
export function toGrams(measurement) {
  const { value, unit, uncertainty, source } = measurement;
  switch (unit) {
    case 'g':
      return createMeasurement(value, 'g', uncertainty, source);
    case 'mg':
      return createMeasurement(value / 1000, 'g', uncertainty / 1000, source);
    case 'kg':
      return createMeasurement(value * 1000, 'g', uncertainty * 1000, source);
    default:
      throw new RangeError(`unsupported mass unit: ${unit}`);
  }
}

/**
 * Add measurements with simple absolute uncertainty propagation.
 * @param {object} a
 * @param {object} b
 * @returns {object}
 */
export function addMeasurements(a, b) {
  if (a.unit !== b.unit) {
    throw new RangeError('units must match before addition');
  }
  return createMeasurement(
    a.value + b.value,
    a.unit,
    a.uncertainty + b.uncertainty,
    `${a.source}; ${b.source}`
  );
}

/**
 * Multiply measurements with approximate relative uncertainty propagation.
 * @param {object} a
 * @param {object} b
 * @param {string} resultUnit
 * @returns {object}
 */
export function multiplyMeasurements(a, b, resultUnit) {
  const value = a.value * b.value;
  const relA = a.value === 0 ? 0 : a.uncertainty / Math.abs(a.value);
  const relB = b.value === 0 ? 0 : b.uncertainty / Math.abs(b.value);
  const uncertainty = Math.abs(value) * (relA + relB);

  return createMeasurement(value, resultUnit, uncertainty, `${a.source}; ${b.source}`);
}

/**
 * Record a lab sample with traceable metadata.
 * @param {object} options
 * @returns {object}
 */
export function createSampleRecord(options) {
  const { id, label, mass, volume, analyst } = options;
  if (typeof id !== 'string' || !id) throw new TypeError('id is required');
  if (typeof label !== 'string' || !label) throw new TypeError('label is required');
  if (typeof analyst !== 'string' || !analyst) throw new TypeError('analyst is required');

  return Object.freeze({
    id,
    label,
    analyst,
    mass,
    volume,
    createdAt: new Date().toISOString()
  });
}

/**
 * Build an audit-friendly report.
 * @param {object} sample
 * @returns {object}
 */
export function buildAuditReport(sample) {
  const normalizedMass = toGrams(sample.mass);
  const normalizedVolume = toLiters(sample.volume);
  const density = createMeasurement(
    normalizedMass.value / normalizedVolume.value,
    'g/L',
    0,
    'derived from normalized mass and volume'
  );

  return {
    sample,
    normalized: {
      mass: normalizedMass,
      volume: normalizedVolume,
      density
    },
    bestPractices: [
      'Record units explicitly.',
      'Store uncertainty alongside measurements.',
      'Keep analyst identity and timestamps for traceability.',
      'Separate raw data from derived values.'
    ]
  };
}

/**
 * Demo workflow.
 */
export function demo() {
  const mass = createMeasurement(250, 'mg', 1, 'analytical balance');
  const volume = createMeasurement(50, 'mL', 0.1, 'class A volumetric flask');
  const sample = createSampleRecord({
    id: 'S-001',
    label: 'Copper sulfate solution aliquot',
    mass,
    volume,
    analyst: 'A. Chemist'
  });
  return buildAuditReport(sample);
}

