// NewDNA creates a new DNA instance with error handling

func NewDNA(sequence string) (*DNA, error) {
    if len(sequence) == 0 {
        return nil, errors.New("empty DNA sequence")
    }

    for _, nucleotide := range sequence {
        if nucleotide != 'A' && nucleotide != 'T' && nucleotide != 'C' && nucleotide != 'G' {
            return nil, fmt.Errorf("invalid nucleotide: %c", nucleotide)
        }
    }

    return &DNA{Sequence: sequence}, nil
}

// Complement returns the complement of the DNA sequence

func (d *DNA) Complement() (string, error) {
    if d == nil {
        return "", errors.New("nil DNA instance")
    }

    complement := make([]byte, len(d.Sequence))

    for i, nucleotide := range d.Sequence {
        switch nucleotide {
        case 'A':
            complement[i] = 'T'
        case 'T':
            complement[i] = 'A'
        case 'C':
            complement[i] = 'G'
        case 'G':
            complement[i] = 'C'
        }
    }

    return string(complement), nil
}

func main() {
    dna, err := NewDNA("ATCG")
    if err != nil {
        fmt.Println("Error creating DNA instance:", err)
        return
    }

    complement, err := dna.Complement()
    if err != nil {
        fmt.Println("Error getting DNA complement:", err)
        return
    }

    fmt.Println("DNA sequence:", dna.Sequence)
    fmt.Println("DNA complement:", complement)
}

