import (
    "fmt"
    "math"
)

// Molecule represents a chemical compound with atoms and bonds.
type Molecule struct {
    Name  string
    Atoms []Atom
    Bonds []Bond
}

// Atom represents an atom with its properties.
type Atom struct {
    Symbol   string
    AtomicNumber int
    Mass     float64
    Position [3]float64
}

// Bond represents a chemical bond between two atoms.
type Bond struct {
    Atom1Index int
    Atom2Index int
    BondType   string
}

// NewMolecule creates a new Molecule instance.
func NewMolecule(name string) *Molecule {
    return &Molecule{
        Name:  name,
        Atoms: make([]Atom, 0),
        Bonds: make([]Bond, 0),
    }
}

// AddAtom adds an atom to the molecule.
func (m *Molecule) AddAtom(symbol string, atomicNumber int, mass float64, position [3]float64) {
    m.Atoms = append(m.Atoms, Atom{
        Symbol:       symbol,
        AtomicNumber: atomicNumber,
        Mass:         mass,
        Position:     position,
    })
}

// AddBond adds a bond between two atoms in the molecule.
func (m *Molecule) AddBond(atom1Index, atom2Index int, bondType string) {
    m.Bonds = append(m.Bonds, Bond{
        Atom1Index: atom1Index,
        Atom2Index: atom2Index,
        BondType:   bondType,
    })
}

// CalculateDistance calculates the distance between two atoms.
func (m *Molecule) CalculateDistance(atom1Index, atom2Index int) float64 {
    atom1 := m.Atoms[atom1Index]
    atom2 := m.Atoms[atom2Index]

    dx := atom1.Position[0] - atom2.Position[0]
    dy := atom1.Position[1] - atom2.Position[1]
    dz := atom1.Position[2] - atom2.Position[2]

    return math.Sqrt(dx*dx + dy*dy + dz*dz)
}

// CalculateAngle calculates the angle between three atoms.
func (m *Molecule) CalculateAngle(atom1Index, atom2Index, atom3Index int) float64 {
    atom1 := m.Atoms[atom1Index]
    atom2 := m.Atoms[atom2Index]
    atom3 := m.Atoms[atom3Index]

    vector1 := [3]float64{
        atom1.Position[0] - atom2.Position[0],
        atom1.Position[1] - atom2.Position[1],
        atom1.Position[2] - atom2.Position[2],
    }

    vector2 := [3]float64{
        atom3.Position[0] - atom2.Position[0],
        atom3.Position[1] - atom2.Position[1],
        atom3.Position[2] - atom2.Position[2],
    }

    dotProduct := vector1[0]*vector2[0] + vector1[1]*vector2[1] + vector1[2]*vector2[2]
    magnitude1 := math.Sqrt(vector1[0]*vector1[0] + vector1[1]*vector1[1] + vector1[2]*vector1[2])
    magnitude2 := math.Sqrt(vector2[0]*vector2[0] + vector2[1]*vector2[1] + vector2[2]*vector2[2])

    cosAngle := dotProduct / (magnitude1 * magnitude2)
    return math.Acos(cosAngle) * 180 / math.Pi
}

// CalculateDihedral calculates the dihedral angle between four atoms.
func (m *Molecule) CalculateDihedral(atom1Index, atom2Index, atom3Index, atom4Index int) float64 {
    atom1 := m.Atoms[atom1Index]
    atom2 := m.Atoms[atom2Index]
    atom3 := m.Atoms[atom3Index]
    atom4 := m.Atoms[atom4Index]

    vector1 := [3]float64{
        atom2.Position[0] - atom1.Position[0],
        atom2.Position[1] - atom1.Position[1],
        atom2.Position[2] - atom1.Position[2],
    }

    vector2 := [3]float64{
        atom3.Position[0] - atom2.Position[0],
        atom3.Position[1] - atom2.Position[1],
        atom3.Position[2] - atom2.Position[2],
    }

    vector3 := [3]float64{
        atom4.Position[0] - atom3.Position[0],
        atom4.Position[1] - atom3.Position[1],
        atom4.Position[2] - atom3.Position[2],
    }

    cross1 := [3]float64{
        vector1[1]*vector2[2] - vector1[2]*vector2[1],
        vector1[2]*vector2[0] - vector1[0]*vector2[2],
        vector1[0]*vector2[1] - vector1[1]*vector2[0],
    }

    cross2 := [3]float64{
        vector2[1]*vector3[2] - vector2[2]*vector3[1],
        vector2[2]*vector3[0] - vector2[0]*vector3[2],
        vector2[0]*vector3[1] - vector2[1]*vector3[0],
    }

    dotProduct := cross1[0]*cross2[0] + cross1[1]*cross2[1] + cross1[2]*cross2[2]
    magnitude1 := math.Sqrt(cross1[0]*cross1[0] + cross1[1]*cross1[1] + cross1[2]*cross1[2])
    magnitude2 := math.Sqrt(cross2[0]*cross2[0] + cross2[1]*cross2[1] + cross2[2]*cross2[2])

    cosAngle := dotProduct / (magnitude1 * magnitude2)
    return math.Acos(cosAngle) * 180 / math.Pi
}

func main() {
    // Create a water molecule
    water := NewMolecule("Water")
    water.AddAtom("O", 8, 15.999, [3]float64{0.0, 0.0, 0.0})
    water.AddAtom("H", 1, 1.008, [3]float64{0.0, 1.0, 0.0})
    water.AddAtom("H", 1, 1.008, [3]float64{0.0, 0.0, 1.0})
    water.AddBond(0, 1, "single")
    water.AddBond(0, 2, "single")

    // Calculate and print distances, angles, and dihedral angles
    distance := water.CalculateDistance(1, 2)
    angle := water.CalculateAngle(1, 0, 2)
    dihedral := water.CalculateDihedral(1, 0, 2, 3)

    fmt.Printf("Distance between H1 and H2: %.2f Å\n", distance)
    fmt.Printf("Angle between H1, O, and H2: %.2f°\n", angle)
    fmt.Printf("Dihedral angle between H1, O, H2, and a hypothetical atom: %.2f°\n", dihedral)
}

