// AddReactant adds a reactant to the reaction.
func (r *Reaction) AddReactant(formula string, molarMass float64, properties map[string]float64) {
    r.Reactants = append(r.Reactants, Compound{
        Formula:    formula,
        MolarMass:  molarMass,
        Properties: properties,
    })
}

// AddProduct adds a product to the reaction.
func (r *Reaction) AddProduct(formula string, molarMass float64, properties map[string]float64) {
    r.Products = append(r.Products, Compound{
        Formula:    formula,
        MolarMass:  molarMass,
        Properties: properties,
    })
}

// CalculateMolarMass calculates the total molar mass of a list of compounds.
func CalculateMolarMass(compounds []Compound) float64 {
    totalMass := 0.0
    for _, compound := range compounds {
        totalMass += compound.MolarMass
    }
    return totalMass
}

// CalculateMolarity calculates the molarity of a solution.
func CalculateMolarity(moles float64, volume float64) float64 {
    return moles / volume
}

// CalculateDilution calculates the dilution of a solution.
func CalculateDilution(initialVolume float64, finalVolume float64) float64 {
    return finalVolume / initialVolume
}

// CalculatepH calculates the pH of a solution given its hydrogen ion concentration.
func CalculatepH(hydrogenIonConcentration float64) float64 {
    return -math.Log10(hydrogenIonConcentration)
}

// CalculatepOH calculates the pOH of a solution given its hydroxide ion concentration.
func CalculatepOH(hydroxideIonConcentration float64) float64 {
    return -math.Log10(hydroxideIonConcentration)
}

func main() {
    // Create a reaction: 2H2 + O2 -> 2H2O
    reaction := NewReaction()
    reaction.AddReactant("H2", 2.016, map[string]float64{"density": 0.0899})
    reaction.AddReactant("O2", 31.998, map[string]float64{"density": 1.429})
    reaction.AddProduct("H2O", 18.015, map[string]float64{"density": 0.997})

    // Calculate and print molar masses
    reactantsMass := CalculateMolarMass(reaction.Reactants)
    productsMass := CalculateMolarMass(reaction.Products)

    fmt.Printf("Total molar mass of reactants: %.3f g/mol\n", reactantsMass)
    fmt.Printf("Total molar mass of products: %.3f g/mol\n", productsMass)

    // Calculate and print molarity, dilution, pH, and pOH
    molarity := CalculateMolarity(2.0, 1.0)
    dilution := CalculateDilution(1.0, 2.0)
    pH := CalculatepH(1e-7)
    pOH := CalculatepOH(1e-7)

    fmt.Printf("Molarity of a solution with 2 moles in 1 L: %.2f M\n", molarity)
    fmt.Printf("Dilution of a solution from 1 L to 2 L: %.2f\n", dilution)
    fmt.Printf("pH of a solution with [H+] = 1e-7 M: %.2f\n", pH)
    fmt.Printf("pOH of a solution with [OH-] = 1e-7 M: %.2f\n", pOH)
}

