// Element represents a chemical element with its properties.
type Element struct {
    Symbol       string
    AtomicNumber int
    AtomicMass   float64
    Group        int
    Period       int
    Properties   map[string]float64
}

// NewElement creates a new Element instance.
func NewElement(symbol string, atomicNumber int, atomicMass float64, group int, period int, properties map[string]float64) *Element {
    return &Element{
        Symbol:       symbol,
        AtomicNumber: atomicNumber,
        AtomicMass:   atomicMass,
        Group:        group,
        Period:       period,
        Properties:   properties,
    }
}

// IsMetal checks if the element is a metal.
func (e *Element) IsMetal() bool {
    return e.Group != 0 && e.Group <= 12 || e.Group == 18 && e.Period >= 6
}

// IsNonMetal checks if the element is a non-metal.
func (e *Element) IsNonMetal() bool {
    return e.Group >= 13 && e.Group <= 17 || e.Group == 18 && e.Period <= 2
}

// IsMetalloid checks if the element is a metalloid.
func (e *Element) IsMetalloid() bool {
    return e.Group >= 13 && e.Group <= 16 && e.Period >= 3 && e.Period <= 5
}

// CalculateDensity calculates the density of an element given its mass and volume.
func (e *Element) CalculateDensity(mass float64, volume float64) float64 {
    return mass / volume
}

// CalculateMolarity calculates the molarity of an element given its mass and volume.
func (e *Element) CalculateMolarity(mass float64, volume float64) float64 {
    return mass / (e.AtomicMass * volume)
}

// CalculatepH calculates the pH of an element given its hydrogen ion concentration.
func (e *Element) CalculatepH(hydrogenIonConcentration float64) float64 {
    return -math.Log10(hydrogenIonConcentration)
}

// CalculatepOH calculates the pOH of an element given its hydroxide ion concentration.
func (e *Element) CalculatepOH(hydroxideIonConcentration float64) float64 {
    return -math.Log10(hydroxideIonConcentration)
}

func main() {
    // Create an element: Oxygen
    oxygen := NewElement("O", 8, 15.999, 16, 2, map[string]float64{"meltingPoint": 54.36, "boilingPoint": 90.20})

    // Check and print the type of the element
    if oxygen.IsMetal() {
        fmt.Println("Oxygen is a metal")
    } else if oxygen.IsNonMetal() {
        fmt.Println("Oxygen is a non-metal")
    } else if oxygen.IsMetalloid() {
        fmt.Println("Oxygen is a metalloid")
    } else {
        fmt.Println("Oxygen is an unknown type")
    }

    // Calculate and print density, molarity, pH, and pOH
    density := oxygen.CalculateDensity(1.0, 0.0224)
    molarity := oxygen.CalculateMolarity(1.0, 1.0)
    pH := oxygen.CalculatepH(1e-7)
    pOH := oxygen.CalculatepOH(1e-7)

    fmt.Printf("Density of Oxygen: %.2f g/cm³\n", density)
    fmt.Printf("Molarity of Oxygen: %.2f M\n", molarity)
    fmt.Printf("pH of Oxygen: %.2f\n", pH)
    fmt.Printf("pOH of Oxygen: %.2f\n", pOH)
}

