// Solution represents a chemical solution with its properties.
type Solution struct {
    Solute     Compound
    Solvent    Compound
    Concentration float64
    Volume     float64
}

// Compound represents a chemical compound with its formula and properties.
type Compound struct {
    Formula    string
    MolarMass  float64
    Properties map[string]float64
}

// NewSolution creates a new Solution instance.
func NewSolution(solute Compound, solvent Compound, concentration float64, volume float64) *Solution {
    return &Solution{
        Solute:        solute,
        Solvent:       solvent,
        Concentration: concentration,
        Volume:        volume,
    }
}

// CalculateMoles calculates the number of moles of the solute in the solution.
func (s *Solution) CalculateMoles() float64 {
    return s.Concentration * s.Volume
}

// CalculateMass calculates the mass of the solute in the solution.
func (s *Solution) CalculateMass() float64 {
    return s.CalculateMoles() * s.Solute.MolarMass
}

// CalculateMolarity calculates the molarity of the solution.
func (s *Solution) CalculateMolarity() float64 {
    return s.Concentration
}

// CalculateMolality calculates the molality of the solution.
func (s *Solution) CalculateMolality() float64 {
    solventMass := s.Volume * s.Solvent.Properties["density"]
    return s.CalculateMoles() / solventMass
}

// CalculateFreezingPoint calculates the freezing point of the solution.
func (s *Solution) CalculateFreezingPoint() float64 {
    freezingPointDepression := s.Solvent.Properties["freezingPointDepression"] * s.CalculateMoles()
    return s.Solvent.Properties["freezingPoint"] - freezingPointDepression
}

// CalculateBoilingPoint calculates the boiling point of the solution.
func (s *Solution) CalculateBoilingPoint() float64 {
    boilingPointElevation := s.Solvent.Properties["boilingPointElevation"] * s.CalculateMoles()
    return s.Solvent.Properties["boilingPoint"] + boilingPointElevation
}

func main() {
    // Create a solution: 0.5 M NaCl in water
    sodiumChloride := Compound{
        Formula:   "NaCl",
        MolarMass: 58.44,
        Properties: map[string]float64{"density": 2.165},
    }
    water := Compound{
        Formula:   "H2O",
        MolarMass: 18.015,
        Properties: map[string]float64{"density": 0.997, "freezingPoint": 0.0, "boilingPoint": 100.0, "freezingPointDepression": 1.86, "boilingPointElevation": 0.512},
    }
    solution := NewSolution(sodiumChloride, water, 0.5, 1.0)

    // Calculate and print moles, mass, molarity, molality, freezing point, and boiling point
    moles := solution.CalculateMoles()
    mass := solution.CalculateMass()
    molarity := solution.CalculateMolarity()
    molality := solution.CalculateMolality()
    freezingPoint := solution.CalculateFreezingPoint()
    boilingPoint := solution.CalculateBoilingPoint()

    fmt.Printf("Moles of NaCl in the solution: %.2f mol\n", moles)
    fmt.Printf("Mass of NaCl in the solution: %.2f g\n", mass)
    fmt.Printf("Molarity of the solution: %.2f M\n", molarity)
    fmt.Printf("Molality of the solution: %.2f m\n", molality)
    fmt.Printf("Freezing point of the solution: %.2f °C\n", freezingPoint)
    fmt.Printf("Boiling point of the solution: %.2f °C\n", boilingPoint)
}

