// AcidBaseReaction represents an acid-base reaction with its properties.
type AcidBaseReaction struct {
    Acid       Compound
    Base       Compound
    ConjugateAcid Compound
    ConjugateBase Compound
    Ka         float64
    Kb         float64
}

// Compound represents a chemical compound with its formula and properties.
type Compound struct {
    Formula    string
    MolarMass  float64
    Properties map[string]float64
}

// NewAcidBaseReaction creates a new AcidBaseReaction instance.
func NewAcidBaseReaction(acid Compound, base Compound, conjugateAcid Compound, conjugateBase Compound, ka float64, kb float64) *AcidBaseReaction {
    return &AcidBaseReaction{
        Acid:          acid,
        Base:          base,
        ConjugateAcid: conjugateAcid,
        ConjugateBase: conjugateBase,
        Ka:            ka,
        Kb:            kb,
    }
}

// CalculatepH calculates the pH of the solution after the reaction.
func (abr *AcidBaseReaction) CalculatepH(acidConcentration float64, baseConcentration float64) float64 {
    hydrogenIonConcentration := math.Sqrt(abr.Ka * acidConcentration)
    hydroxideIonConcentration := math.Sqrt(abr.Kb * baseConcentration)
    return -math.Log10(hydrogenIonConcentration + hydroxideIonConcentration)
}

// CalculatepOH calculates the pOH of the solution after the reaction.
func (abr *AcidBaseReaction) CalculatepOH(acidConcentration float64, baseConcentration float64) float64 {
    hydrogenIonConcentration := math.Sqrt(abr.Ka * acidConcentration)
    hydroxideIonConcentration := math.Sqrt(abr.Kb * baseConcentration)
    return -math.Log10(hydrogenIonConcentration + hydroxideIonConcentration)
}

// CalculateBufferCapacity calculates the buffer capacity of the solution.
func (abr *AcidBaseReaction) CalculateBufferCapacity(acidConcentration float64, baseConcentration float64) float64 {
    return acidConcentration + baseConcentration
}

// CalculateBufferRange calculates the buffer range of the solution.
func (abr *AcidBaseReaction) CalculateBufferRange(acidConcentration float64, baseConcentration float64) float64 {
    return math.Log10(acidConcentration) - math.Log10(baseConcentration)
}

func main() {
    // Create an acid-base reaction: HCl + NaOH -> H2O + NaCl
    hydrochloricAcid := Compound{
        Formula:   "HCl",
        MolarMass: 36.46,
        Properties: map[string]float64{"density": 1.19},
    }
    sodiumHydroxide := Compound{
        Formula:   "NaOH",
        MolarMass: 39.997,
        Properties: map[string]float64{"density": 2.13},
    }
    water := Compound{
        Formula:   "H2O",
        MolarMass: 18.015,
        Properties: map[string]float64{"density": 0.997},
    }
    sodiumChloride := Compound{
        Formula:   "NaCl",
        MolarMass: 58.44,
        Properties: map[string]float64{"density": 2.165},
    }
    reaction := NewAcidBaseReaction(hydrochloricAcid, sodiumHydroxide, water, sodiumChloride, 1e-7, 1e-14)

    // Calculate and print pH, pOH, buffer capacity, and buffer range
    pH := reaction.CalculatepH(0.1, 0.1)
    pOH := reaction.CalculatepOH(0.1, 0.1)
    bufferCapacity := reaction.CalculateBufferCapacity(0.1, 0.1)
    bufferRange := reaction.CalculateBufferRange(0.1, 0.1)

    fmt.Printf("pH of the solution: %.2f\n", pH)
    fmt.Printf("pOH of the solution: %.2f\n", pOH)
    fmt.Printf("Buffer capacity of the solution: %.2f\n", bufferCapacity)
    fmt.Printf("Buffer range of the solution: %.2f\n", bufferRange)
}

