// RedoxReaction represents a redox reaction with its properties.
type RedoxReaction struct {
    OxidizingAgent Compound
    ReducingAgent  Compound
    Products      []Compound
    HalfReactions []HalfReaction
}

// Compound represents a chemical compound with its formula and properties.
type Compound struct {
    Formula    string
    MolarMass  float64
    Properties map[string]float64
}

// HalfReaction represents a half-reaction in a redox reaction.
type HalfReaction struct {
    Reactants []Compound
    Products  []Compound
    Electrons float64
}

// NewRedoxReaction creates a new RedoxReaction instance.
func NewRedoxReaction(oxidizingAgent Compound, reducingAgent Compound) *RedoxReaction {
    return &RedoxReaction{
        OxidizingAgent: oxidizingAgent,
        ReducingAgent:  reducingAgent,
        Products:       make([]Compound, 0),
        HalfReactions:  make([]HalfReaction, 0),
    }
}

// AddProduct adds a product to the redox reaction.
func (rr *RedoxReaction) AddProduct(formula string, molarMass float64, properties map[string]float64) {
    rr.Products = append(rr.Products, Compound{
        Formula:    formula,
        MolarMass:  molarMass,
        Properties: properties,
    })
}

// AddHalfReaction adds a half-reaction to the redox reaction.
func (rr *RedoxReaction) AddHalfReaction(reactants []Compound, products []Compound, electrons float64) {
    rr.HalfReactions = append(rr.HalfReactions, HalfReaction{
        Reactants: reactants,
        Products:  products,
        Electrons: electrons,
    })
}

// CalculateStandardCellPotential calculates the standard cell potential of the redox reaction.
func (rr *RedoxReaction) CalculateStandardCellPotential() float64 {
    standardCellPotential := 0.0
    for _, halfReaction := range rr.HalfReactions {
        standardCellPotential += halfReaction.Electrons
    }
    return standardCellPotential
}

// CalculateCellPotential calculates the cell potential of the redox reaction.
func (rr *RedoxReaction) CalculateCellPotential(standardCellPotential float64, temperature float64) float64 {
    gasConstant := 8.314
    faradayConstant := 96485.0
    return standardCellPotential - (temperature * math.Log(0.5) * faradayConstant / (gasConstant * temperature))
}

func main() {
    // Create a redox reaction: Cu + 2AgNO3 -> Cu(NO3)2 + 2Ag
    copper := Compound{
        Formula:   "Cu",
        MolarMass: 63.55,
        Properties: map[string]float64{"density": 8.96},
    }
    silverNitrate := Compound{
        Formula:   "AgNO3",
        MolarMass: 169.87,
        Properties: map[string]float64{"density": 4.36},
    }
    copperNitrate := Compound{
        Formula:   "Cu(NO3)2",
        MolarMass: 187.55,
        Properties: map[string]float64{"density": 3.41},
    }
    silver := Compound{
        Formula:   "Ag",
        MolarMass: 107.87,
        Properties: map[string]float64{"density": 10.49},
    }
    reaction := NewRedoxReaction(silverNitrate, copper)
    reaction.AddProduct(copperNitrate.Formula, copperNitrate.MolarMass, copperNitrate.Properties)
    reaction.AddProduct(silver.Formula, silver.MolarMass, silver.Properties)
    reaction.AddHalfReaction([]Compound{copper}, []Compound{copperNitrate}, 2.0)
    reaction.AddHalfReaction([]Compound{silverNitrate}, []Compound{silver}, -1.0)

    // Calculate and print standard cell potential and cell potential
    standardCellPotential := reaction.CalculateStandardCellPotential()
    cellPotential := reaction.CalculateCellPotential(standardCellPotential, 298.15)

    fmt.Printf("Standard cell potential of the redox reaction: %.2f V\n", standardCellPotential)
    fmt.Printf("Cell potential of the redox reaction: %.2f V\n", cellPotential)
}

