// Thermodynamics represents the thermodynamic properties of a system.
type Thermodynamics struct {
    InternalEnergy float64
    Enthalpy      float64
    Entropy       float64
    GibbsEnergy   float64
}

// NewThermodynamics creates a new Thermodynamics instance.
func NewThermodynamics(internalEnergy float64, enthalpy float64, entropy float64, gibbsEnergy float64) *Thermodynamics {
    return &Thermodynamics{
        InternalEnergy: internalEnergy,
        Enthalpy:       enthalpy,
        Entropy:        entropy,
        GibbsEnergy:    gibbsEnergy,
    }
}

// CalculateInternalEnergy calculates the internal energy of the system.
func (t *Thermodynamics) CalculateInternalEnergy(temperature float64, heatCapacity float64) {
    t.InternalEnergy = heatCapacity * temperature
}

// CalculateEnthalpy calculates the enthalpy of the system.
func (t *Thermodynamics) CalculateEnthalpy(temperature float64, heatCapacity float64, pressure float64, volume float64) {
    t.Enthalpy = heatCapacity * temperature + pressure * volume
}

// CalculateEntropy calculates the entropy of the system.
func (t *Thermodynamics) CalculateEntropy(temperature float64, heatCapacity float64) {
    t.Entropy = heatCapacity * math.Log(temperature)
}

// CalculateGibbsEnergy calculates the Gibbs energy of the system.
func (t *Thermodynamics) CalculateGibbsEnergy(temperature float64, heatCapacity float64, pressure float64, volume float64) {
    t.GibbsEnergy = t.Enthalpy - temperature * t.Entropy
}

func main() {
    // Create a thermodynamic system
    thermodynamics := NewThermodynamics(0.0, 0.0, 0.0, 0.0)

    // Calculate and print internal energy, enthalpy, entropy, and Gibbs energy
    thermodynamics.CalculateInternalEnergy(298.15, 29.1)
    thermodynamics.CalculateEnthalpy(298.15, 29.1, 1.0, 0.0224)
    thermodynamics.CalculateEntropy(298.15, 29.1)
    thermodynamics.CalculateGibbsEnergy(298.15, 29.1, 1.0, 0.0224)

    fmt.Printf("Internal energy of the system: %.2f J\n", thermodynamics.InternalEnergy)
    fmt.Printf("Enthalpy of the system: %.2f J\n", thermodynamics.Enthalpy)
    fmt.Printf("Entropy of the system: %.2f J/K\n", thermodynamics.Entropy)
    fmt.Printf("Gibbs energy of the system: %.2f J\n", thermodynamics.GibbsEnergy)
}

