import (
    "fmt"
    "math"
)

// Kinetics represents the kinetics properties of a reaction.
type Kinetics struct {
    RateConstant float64
    ActivationEnergy float64
    FrequencyFactor float64
}

// NewKinetics creates a new Kinetics instance.
func NewKinetics(rateConstant float64, activationEnergy float64, frequencyFactor float64) *Kinetics {
    return &Kinetics{
        RateConstant:     rateConstant,
        ActivationEnergy: activationEnergy,
        FrequencyFactor: frequencyFactor,
    }
}

// CalculateRateConstant calculates the rate constant of the reaction.
func (k *Kinetics) CalculateRateConstant(temperature float64) {
    gasConstant := 8.314
    k.RateConstant = k.FrequencyFactor * math.Exp(-k.ActivationEnergy / (gasConstant * temperature))
}

// CalculateActivationEnergy calculates the activation energy of the reaction.
func (k *Kinetics) CalculateActivationEnergy(temperature float64) {
    gasConstant := 8.314
    k.ActivationEnergy = -gasConstant * temperature * math.Log(k.RateConstant / k.FrequencyFactor)
}

// CalculateFrequencyFactor calculates the frequency factor of the reaction.
func (k *Kinetics) CalculateFrequencyFactor(temperature float64) {
    gasConstant := 8.314
    k.FrequencyFactor = k.RateConstant * math.Exp(k.ActivationEnergy / (gasConstant * temperature))
}

func main() {
    // Create a kinetics system
    kinetics := NewKinetics(0.0, 0.0, 0.0)

    // Calculate and print rate constant, activation energy, and frequency factor
    kinetics.CalculateRateConstant(298.15)
    kinetics.CalculateActivationEnergy(298.15)
    kinetics.CalculateFrequencyFactor(298.15)

    fmt.Printf("Rate constant of the reaction: %.2e s^-1\n", kinetics.RateConstant)
    fmt.Printf("Activation energy of the reaction: %.2f J/mol\n", kinetics.ActivationEnergy)
    fmt.Printf("Frequency factor of the reaction: %.2e s^-1\n", kinetics.FrequencyFactor)
}

