// Chromatography represents the chromatographic properties of a system.
type Chromatography struct {
    RetentionFactor float64
    Selectivity     float64
    Resolution     float64
}

// NewChromatography creates a new Chromatography instance.
func NewChromatography(retentionFactor float64, selectivity float64, resolution float64) *Chromatography {
    return &Chromatography{
        RetentionFactor: retentionFactor,
        Selectivity:     selectivity,
        Resolution:     resolution,
    }
}

// CalculateRetentionFactor calculates the retention factor of the system.
func (c *Chromatography) CalculateRetentionFactor(volumeMobilePhase float64, volumeStationaryPhase float64) {
    c.RetentionFactor = volumeMobilePhase / volumeStationaryPhase
}

// CalculateSelectivity calculates the selectivity of the system.
func (c *Chromatography) CalculateSelectivity(retentionFactor1 float64, retentionFactor2 float64) {
    c.Selectivity = retentionFactor1 / retentionFactor2
}

// CalculateResolution calculates the resolution of the system.
func (c *Chromatography) CalculateResolution(retentionFactor1 float64, retentionFactor2 float64, peakWidth1 float64, peakWidth2 float64) {
    c.Resolution = 2 * (retentionFactor1 - retentionFactor2) / (peakWidth1 + peakWidth2)
}

func main() {
    // Create a chromatography system
    chromatography := NewChromatography(0.0, 0.0, 0.0)

    // Calculate and print retention factor, selectivity, and resolution
    chromatography.CalculateRetentionFactor(1.0, 0.5)
    chromatography.CalculateSelectivity(1.0, 0.5)
    chromatography.CalculateResolution(1.0, 0.5, 0.1, 0.1)

    fmt.Printf("Retention factor of the system: %.2f\n", chromatography.RetentionFactor)
    fmt.Printf("Selectivity of the system: %.2f\n", chromatography.Selectivity)
