public class CellCounter {
    private int count;

    public CellCounter(int initialCount) {
        if (initialCount < 0) {
            throw new IllegalArgumentException("Initial cell count cannot be negative");
        }
        this.count = initialCount;
    }

    public void divide(int newCells) {
        if (newCells <= 0) {
            throw new IllegalArgumentException("New cells must be positive");
        }
        count += newCells;
    }

    public void removeDeadCells(int deadCells) {
        if (deadCells < 0 || deadCells > count) {
            throw new IllegalArgumentException("Invalid dead cell count");
        }
        count -= deadCells;
    }

    public int getCount() {
        return count;
    }
}

public class DNASequence {
    private final String sequence;

    public DNASequence(String sequence) {
        if (sequence == null || sequence.isBlank()) {
            throw new IllegalArgumentException("DNA sequence cannot be empty");
        }
        if (!sequence.matches("[ATCG]+")) {
            throw new IllegalArgumentException("DNA sequence contains invalid characters");
        }
        this.sequence = sequence;
    }

    public int length() {
        return sequence.length();
    }

    public char nucleotideAt(int index) {
        try {
            return sequence.charAt(index);
        } catch (IndexOutOfBoundsException e) {
            throw new IllegalArgumentException("Index out of range: " + index, e);
        }
    }

    public String getComplement() {
        StringBuilder complement = new StringBuilder();
        for (char c : sequence.toCharArray()) {
            switch (c) {
                case 'A' -> complement.append('T');
                case 'T' -> complement.append('A');
                case 'C' -> complement.append('G');
                case 'G' -> complement.append('C');
                default -> throw new IllegalStateException("Unexpected nucleotide: " + c);
            }
        }
        return complement.toString();
    }
}

public class EnzymeReaction {
    private double substrateConcentration;
    private final double maxRate;

    public EnzymeReaction(double substrateConcentration, double maxRate) {
        if (substrateConcentration < 0 || maxRate <= 0) {
            throw new IllegalArgumentException("Concentrations and rate must be valid");
        }
        this.substrateConcentration = substrateConcentration;
        this.maxRate = maxRate;
    }

    public double calculateRate(double km) {
        if (km <= 0) {
            throw new IllegalArgumentException("Km must be positive");
        }
        try {
            return (maxRate * substrateConcentration) / (km + substrateConcentration);
        } catch (ArithmeticException e) {
            throw new IllegalStateException("Failed to calculate reaction rate", e);
        }
    }

    public void addSubstrate(double amount) {
        if (amount <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }
        substrateConcentration += amount;
    }

    public double getSubstrateConcentration() {
        return substrateConcentration;
    }
}

public class PopulationGrowth {
    private int population;
    private final double growthRate;

    public PopulationGrowth(int population, double growthRate) {
        if (population < 0 || growthRate < 0) {
            throw new IllegalArgumentException("Population and growth rate must not be negative");
        }
        this.population = population;
        this.growthRate = growthRate;
    }

    public void simulateYear() {
        long nextPopulation = Math.round(population * (1 + growthRate));
        if (nextPopulation > Integer.MAX_VALUE) {
            throw new ArithmeticException("Population overflow");
        }
        population = (int) nextPopulation;
    }

    public void reducePopulation(int loss) {
        if (loss < 0 || loss > population) {
            throw new IllegalArgumentException("Invalid population loss");
        }
        population -= loss;
    }

    public int getPopulation() {
        return population;
    }
}

public class HeartRateMonitor {
    private int heartRate;

    public HeartRateMonitor(int heartRate) {
        if (heartRate <= 0) {
            throw new IllegalArgumentException("Heart rate must be positive");
        }
        this.heartRate = heartRate;
    }

    public void updateHeartRate(int newRate) {
        if (newRate <= 0 || newRate > 250) {
            throw new IllegalArgumentException("Heart rate out of biological range");
        }
        this.heartRate = newRate;
    }

    public String getCondition() {
        if (heartRate < 60) {
            return "Bradycardia";
        } else if (heartRate <= 100) {
            return "Normal";
        } else {
            return "Tachycardia";
        }
    }

    public int getHeartRate() {
        return heartRate;
    }
}

public class PhotosynthesisCalculator {
    private double lightIntensity;
    private double carbonDioxideLevel;

    public PhotosynthesisCalculator(double lightIntensity, double carbonDioxideLevel) {
        if (lightIntensity < 0 || carbonDioxideLevel < 0) {
            throw new IllegalArgumentException("Environmental values cannot be negative");
        }
        this.lightIntensity = lightIntensity;
        this.carbonDioxideLevel = carbonDioxideLevel;
    }

    public double calculateEfficiency() {
        if (lightIntensity == 0 || carbonDioxideLevel == 0) {
            throw new IllegalStateException("Insufficient conditions for photosynthesis");
        }
        return Math.min(100.0, (lightIntensity * carbonDioxideLevel) / 100.0);
    }

    public void adjustLight(double change) {
        if (lightIntensity + change < 0) {
            throw new IllegalArgumentException("Light intensity cannot become negative");
        }
        lightIntensity += change;
    }

    public void adjustCarbonDioxide(double change) {
        if (carbonDioxideLevel + change < 0) {
            throw new IllegalArgumentException("CO2 level cannot become negative");
        }
        carbonDioxideLevel += change;
    }
}

public class ProteinAnalyzer {
    private final String proteinSequence;

    public ProteinAnalyzer(String proteinSequence) {
        if (proteinSequence == null || proteinSequence.isBlank()) {
            throw new IllegalArgumentException("Protein sequence cannot be empty");
        }
        if (!proteinSequence.matches("[ACDEFGHIKLMNPQRSTVWY]+")) {
            throw new IllegalArgumentException("Invalid amino acid sequence");
        }
        this.proteinSequence = proteinSequence;
    }

    public int countAminoAcid(char aminoAcid) {
        if ("ACDEFGHIKLMNPQRSTVWY".indexOf(aminoAcid) == -1) {
            throw new IllegalArgumentException("Unknown amino acid: " + aminoAcid);
        }
        int count = 0;
        for (char c : proteinSequence.toCharArray()) {
            if (c == aminoAcid) {
                count++;
            }
        }
        return count;
    }

    public double averageResidueMass() {
        try {
            return proteinSequence.length() * 110.0 / proteinSequence.length();
        } catch (ArithmeticException e) {
            throw new IllegalStateException("Failed to compute average residue mass", e);
        }
    }
}

public class EcosystemBalance {
    private int predators;
    private int prey;

    public EcosystemBalance(int predators, int prey) {
        if (predators < 0 || prey < 0) {
            throw new IllegalArgumentException("Population counts cannot be negative");
        }
        this.predators = predators;
        this.prey = prey;
    }

    public void simulateInteraction() {
        if (prey == 0 && predators > 0) {
            throw new IllegalStateException("Predators cannot survive without prey");
        }
        int preyLoss = predators * 2;
        if (preyLoss > prey) {
            preyLoss = prey;
        }
        prey -= preyLoss;
        predators += preyLoss / 4;
    }

    public void addPrey(int amount) {
        if (amount <= 0) {
            throw new IllegalArgumentException("Prey addition must be positive");
        }
        prey += amount;
    }

    public String getStatus() {
        return "Predators: " + predators + ", Prey: " + prey;
    }
}

public class RespirationTracker {
    private double oxygenLevel;
    private double carbonDioxideOutput;

    public RespirationTracker(double oxygenLevel, double carbonDioxideOutput) {
        if (oxygenLevel < 0 || carbonDioxideOutput < 0) {
            throw new IllegalArgumentException("Gas values must not be negative");
        }
        this.oxygenLevel = oxygenLevel;
        this.carbonDioxideOutput = carbonDioxideOutput;
    }

    public void breathe(double oxygenConsumed, double co2Produced) {
        if (oxygenConsumed < 0 || co2Produced < 0) {
            throw new IllegalArgumentException("Gas exchange values must be positive");
        }
        if (oxygenConsumed > oxygenLevel) {
            throw new IllegalStateException("Not enough oxygen available");
        }
        oxygenLevel -= oxygenConsumed;
        carbonDioxideOutput += co2Produced;
    }

    public double getRespiratoryQuotient() {
        if (oxygenLevel == 0) {
            throw new ArithmeticException("Cannot divide by zero oxygen level");
        }
        return carbonDioxideOutput / oxygenLevel;
    }
}

public class GeneExpression {
    private String geneName;
    private double expressionLevel;

    public GeneExpression(String geneName, double expressionLevel) {
        if (geneName == null || geneName.isBlank()) {
            throw new IllegalArgumentException("Gene name cannot be blank");
        }
        if (expressionLevel < 0) {
            throw new IllegalArgumentException("Expression level cannot be negative");
        }
        this.geneName = geneName;
        this.expressionLevel = expressionLevel;
    }

    public void amplify(double factor) {
        if (factor <= 0) {
            throw new IllegalArgumentException("Amplification factor must be positive");
        }
        expressionLevel *= factor;
    }

    public void suppress(double amount) {
        if (amount < 0 || amount > expressionLevel) {
            throw new IllegalArgumentException("Invalid suppression amount");
        }
        expressionLevel -= amount;
    }

    public String describe() {
        return geneName + " expression level: " + expressionLevel;
    }
}

