import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Represents a chemical compound with its empirical formula and molecular weight.
 * This class uses a map to store the count of each element in the compound.
 * It is designed for immutability to ensure consistency after creation.
 */
public final class ChemicalCompound {

    private final String name;
    private final Map<ChemicalElement, Integer> composition;
    private final double molecularWeight;

    /**
     * Constructs a new ChemicalCompound instance.
     * @param name The name of the compound. Must not be null or empty.
     * @param composition A map detailing the elements and their counts in the compound.
     *                    Must not be null or empty, and all counts must be positive.
     * @throws IllegalArgumentException if name is invalid or composition is invalid.
     */
    public ChemicalCompound(String name, Map<ChemicalElement, Integer> composition) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Compound name cannot be null or empty.");
        }
        if (composition == null || composition.isEmpty()) {
            throw new IllegalArgumentException("Composition map cannot be null or empty.");
        }

        this.name = name.trim();
        this.composition = new HashMap<>();
        double calculatedWeight = 0.0;

        for (Map.Entry<ChemicalElement, Integer> entry : composition.entrySet()) {
            ChemicalElement element = entry.getKey();
            Integer count = entry.getValue();
            if (element == null || count == null || count <= 0) {
                throw new IllegalArgumentException("Invalid element or count in composition.");
            }
            this.composition.put(element, count);
            // For simplicity, we'll assume a fixed atomic mass for elements here.
            // In a real scenario, this would come from the ChemicalElement or an external data source.
            calculatedWeight += count * getApproximateAtomicMass(element);
        }
        this.molecularWeight = calculatedWeight;
    }

    // Helper method to get approximate atomic mass (for demonstration purposes)
    private double getApproximateAtomicMass(ChemicalElement element) {
        switch (element.getSymbol()) {
            case "H": return 1.008;
            case "O": return 15.999;
            case "C": return 12.011;
            case "N": return 14.007;
            default: return element.getAtomicNumber() * 2.0; // Very rough estimate
        }
    }

    /**
     * Returns the name of the compound.
     * @return The compound name.
     */
    public String getName() {
        return name;
    }

    /**
     * Returns an unmodifiable map of the compound's elemental composition.
     * @return The composition map.
     */
    public Map<ChemicalElement, Integer> getComposition() {
        return new HashMap<>(composition); // Return a defensive copy
    }

    /**
     * Returns the calculated molecular weight of the compound.
     * @return The molecular weight.
     */
    public double getMolecularWeight() {
        return molecularWeight;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ChemicalCompound that = (ChemicalCompound) o;
        return Double.compare(that.molecularWeight, molecularWeight) == 0 &&
               name.equals(that.name) &&
               composition.equals(that.composition);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, composition, molecularWeight);
    }

    @Override
    public String toString() {
        StringBuilder formula = new StringBuilder();
        for (Map.Entry<ChemicalElement, Integer> entry : composition.entrySet()) {
            formula.append(entry.getKey().getSymbol());
            if (entry.getValue() > 1) {
                formula.append(entry.getValue());
            }
        }
        return name + " (Formula: " + formula.toString() + ", MW: " + String.format("%.3f", molecularWeight) + ")";
    }

    public static void main(String[] args) {
        ChemicalElement hydrogen = new ChemicalElement(1, "H", "Hydrogen");
        ChemicalElement oxygen = new ChemicalElement(8, "O", "Oxygen");
        ChemicalElement carbon = new ChemicalElement(6, "C", "Carbon");

        Map<ChemicalElement, Integer> waterComposition = new HashMap<>();
        waterComposition.put(hydrogen, 2);
        waterComposition.put(oxygen, 1);
        ChemicalCompound water = new ChemicalCompound("Water", waterComposition);
        System.out.println(water);

        Map<ChemicalElement, Integer> methaneComposition = new HashMap<>();
        methaneComposition.put(carbon, 1);
        methaneComposition.put(hydrogen, 4);
        ChemicalCompound methane = new ChemicalCompound("Methane", methaneComposition);
        System.out.println(methane);

        Map<ChemicalElement, Integer> glucoseComposition = new HashMap<>();
        glucoseComposition.put(carbon, 6);
        glucoseComposition.put(hydrogen, 12);
        glucoseComposition.put(oxygen, 6);
        ChemicalCompound glucose = new ChemicalCompound("Glucose", glucoseComposition);
        System.out.println(glucose);

        System.out.println("Water's composition: " + water.getComposition());
    }
}"
