    "text": "import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/**
 * Represents a chemical reaction, including reactants, products, and stoichiometry.
 * This class emphasizes immutability for the reaction itself and provides methods
 * to access its components safely.
 */
public final class ChemicalReaction {

    private final String name;
    private final Map<ChemicalCompound, Integer> reactants;
    private final Map<ChemicalCompound, Integer> products;
    private final boolean isReversible;

    /**
     * Constructs a new ChemicalReaction instance.
     * @param name An optional name for the reaction. Can be null or empty.
     * @param reactants A map of reactant compounds and their stoichiometric coefficients. Must not be null or empty, coefficients must be positive.
     * @param products A map of product compounds and their stoichiometric coefficients. Must not be null or empty, coefficients must be positive.
     * @param isReversible True if the reaction is reversible, false otherwise.
     * @throws IllegalArgumentException if reactants or products maps are invalid.
     */
    public ChemicalReaction(String name, Map<ChemicalCompound, Integer> reactants,
                            Map<ChemicalCompound, Integer> products, boolean isReversible) {
        if (reactants == null || reactants.isEmpty()) {
            throw new IllegalArgumentException("Reactants map cannot be null or empty.");
        }
        if (products == null || products.isEmpty()) {
            throw new IllegalArgumentException("Products map cannot be null or empty.");
        }

        this.name = (name != null && !name.trim().isEmpty()) ? name.trim() : "Unnamed Reaction";
        this.reactants = validateAndCopyMap(reactants, "Reactant");
        this.products = validateAndCopyMap(products, "Product");
        this.isReversible = isReversible;
    }

    private Map<ChemicalCompound, Integer> validateAndCopyMap(Map<ChemicalCompound, Integer> sourceMap, String type) {
        Map<ChemicalCompound, Integer> newMap = new HashMap<>();
        for (Map.Entry<ChemicalCompound, Integer> entry : sourceMap.entrySet()) {
            ChemicalCompound compound = entry.getKey();
            Integer coefficient = entry.getValue();
            if (compound == null || coefficient == null || coefficient <= 0) {
                throw new IllegalArgumentException(type + " compound or coefficient is invalid.");
            }
            newMap.put(compound, coefficient);
        }
        return Collections.unmodifiableMap(newMap); // Ensure immutability
    }

    /**
     * Returns the name of the reaction.
     * @return The reaction name.
     */
    public String getName() {
        return name;
    }

    /**
     * Returns an unmodifiable map of the reactants and their stoichiometric coefficients.
     * @return An unmodifiable map of reactants.
     */
    public Map<ChemicalCompound, Integer> getReactants() {
        return reactants;
    }

    /**
     * Returns an unmodifiable map of the products and their stoichiometric coefficients.
     * @return An unmodifiable map of products.
     */
    public Map<ChemicalCompound, Integer> getProducts() {
        return products;
    }

    /**
     * Checks if the reaction is reversible.
     * @return True if reversible, false otherwise.
     */
    public boolean isReversible() {
        return isReversible;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ChemicalReaction that = (ChemicalReaction) o;
        return isReversible == that.isReversible &&
               name.equals(that.name) &&
               reactants.equals(that.reactants) &&
               products.equals(that.products);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, reactants, products, isReversible);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Reaction: ").append(name).append("\n");
        sb.append("  Reactants: ");
        appendCompounds(sb, reactants);
        sb.append(isReversible ? " <--> " : " --> ");
        sb.append("Products: ");
        appendCompounds(sb, products);
        return sb.toString();
    }

    private void appendCompounds(StringBuilder sb, Map<ChemicalCompound, Integer> compoundMap) {
        boolean first = true;
        for (Map.Entry<ChemicalCompound, Integer> entry : compoundMap.entrySet()) {
            if (!first) {
                sb.append(" + ");
            }
            sb.append(entry.getValue());
            sb.append(entry.getKey().getName()); // Using name for brevity, could use formula
            first = false;
        }
    }

    public static void main(String[] args) {
        ChemicalElement H = new ChemicalElement(1, "H", "Hydrogen");
        ChemicalElement O = new ChemicalElement(8, "O", "Oxygen");
        ChemicalElement C = new ChemicalElement(6, "C", "Carbon");

        Map<ChemicalElement, Integer> waterComp = new HashMap<>();
        waterComp.put(H, 2); waterComp.put(O, 1);
        ChemicalCompound water = new ChemicalCompound("Water", waterComp);

        Map<ChemicalElement, Integer> oxygenGasComp = new HashMap<>();
        oxygenGasComp.put(O, 2);
        ChemicalCompound oxygenGas = new ChemicalCompound("Oxygen", oxygenGasComp);

        Map<ChemicalElement, Integer> hydrogenGasComp = new HashMap<>();
        hydrogenGasComp.put(H, 2);
        ChemicalCompound hydrogenGas = new ChemicalCompound("Hydrogen", hydrogenGasComp);

        Map<ChemicalElement, Integer> carbonDioxideComp = new HashMap<>();
        carbonDioxideComp.put(C, 1); carbonDioxideComp.put(O, 2);
        ChemicalCompound carbonDioxide = new ChemicalCompound("Carbon Dioxide", carbonDioxideComp);

        // Water formation reaction: 2H2 + O2 --> 2H2O
        Map<ChemicalCompound, Integer> reactants1 = new HashMap<>();
        reactants1.put(hydrogenGas, 2);
        reactants1.put(oxygenGas, 1);

        Map<ChemicalCompound, Integer> products1 = new HashMap<>();
        products1.put(water, 2);

        ChemicalReaction waterFormation = new ChemicalReaction("Water Formation", reactants1, products1, false);
        System.out.println(waterFormation);

        // Photosynthesis: 6CO2 + 6H2O <--> C6H12O6 + 6O2
        ChemicalElement N = new ChemicalElement(7, "N", "Nitrogen");
        Map<ChemicalElement, Integer> glucoseComp = new HashMap<>();
        glucoseComp.put(C, 6); glucoseComp.put(H, 12); glucoseComp.put(O, 6);
        ChemicalCompound glucose = new ChemicalCompound("Glucose", glucoseComp);

        Map<ChemicalCompound, Integer> reactants2 = new HashMap<>();
        reactants2.put(carbonDioxide, 6);
        reactants2.put(water, 6);

        Map<ChemicalCompound, Integer> products2 = new HashMap<>();
        products2.put(glucose, 1);
        products2.put(oxygenGas, 6);

        ChemicalReaction photosynthesis = new ChemicalReaction("Photosynthesis", reactants2, products2, true);
        System.out.println(photosynthesis);
    }
}"
