/**
 * Represents an atomic isotope, extending the concept of a ChemicalElement
 * by including the number of neutrons. This class is also immutable.
 */
public final class Isotope extends ChemicalElement {

    private final int neutronCount;
    private final double exactAtomicMass;

    /**
     * Constructs a new Isotope instance.
     * @param atomicNumber The atomic number (number of protons).
     * @param symbol The chemical symbol.
     * @param name The name of the element.
     * @param neutronCount The number of neutrons. Must be non-negative.
     * @param exactAtomicMass The exact atomic mass of the isotope in amu. Must be positive.
     * @throws IllegalArgumentException if any parameter is invalid.
     */
    public Isotope(int atomicNumber, String symbol, String name,
                   int neutronCount, double exactAtomicMass) {
        // Call the superclass constructor to initialize common element properties
        super(atomicNumber, symbol, name);

        if (neutronCount < 0) {
            throw new IllegalArgumentException("Neutron count cannot be negative.");
        }
        if (exactAtomicMass <= 0) {
            throw new IllegalArgumentException("Exact atomic mass must be positive.");
        }

        this.neutronCount = neutronCount;
        this.exactAtomicMass = exactAtomicMass;
    }

    /**
     * Returns the number of neutrons in this isotope.
     * @return The neutron count.
     */
    public int getNeutronCount() {
        return neutronCount;
    }

    /**
     * Returns the mass number (protons + neutrons) of this isotope.
     * @return The mass number.
     */
    public int getMassNumber() {
        return getAtomicNumber() + neutronCount;
    }

    /**
     * Returns the exact atomic mass of this isotope in atomic mass units (amu).
     * @return The exact atomic mass.
     */
    public double getExactAtomicMass() {
        return exactAtomicMass;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        if (!super.equals(o)) return false; // Check superclass equality
        Isotope isotope = (Isotope) o;
        return neutronCount == isotope.neutronCount &&
               Double.compare(isotope.exactAtomicMass, exactAtomicMass) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), neutronCount, exactAtomicMass);
    }

    @Override
    public String toString() {
        return String.format("%s-%d (Symbol: %s, Protons: %d, Neutrons: %d, Mass: %.4f amu)",
                             getName(), getMassNumber(), getSymbol(), getAtomicNumber(), neutronCount, exactAtomicMass);
    }

    public static void main(String[] args) {
        // Hydrogen-1 (Protium)
        Isotope protium = new Isotope(1, "H", "Hydrogen", 0, 1.007825);
        System.out.println(protium);

        // Hydrogen-2 (Deuterium)
        Isotope deuterium = new Isotope(1, "H", "Hydrogen", 1, 2.014102);
        System.out.println(deuterium);

        // Oxygen-16
        Isotope oxygen16 = new Isotope(8, "O", "Oxygen", 8, 15.994915);
        System.out.println(oxygen16);

        // Uranium-238
        Isotope uranium238 = new Isotope(92, "U", "Uranium", 146, 238.050788);
        System.out.println(uranium238);

        System.out.println("Are protium and deuterium the same element? " + protium.getSymbol().equals(deuterium.getSymbol()));
        System.out.println("Are protium and deuterium the same isotope? " + protium.equals(deuterium));

        // Demonstrating polymorphism
        ChemicalElement generalElement = protium;
        System.out.println("General element: " + generalElement.getName() + " (Atomic Number: " + generalElement.getAtomicNumber() + ")");
    }
}"
