    "text": "import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * Represents a collection of atoms forming a molecule, with a focus on its structure.
 * This class demonstrates a simple way to represent molecular structure using a list of atoms.
 * In a more complex system, this would involve bonds and 3D coordinates.
 */
public final class Molecule {

    private final String name;
    private final List<Atom> atoms;

    /**
     * Constructs a new Molecule instance.
     * @param name The name of the molecule. Must not be null or empty.
     * @param atoms A list of Atom objects that constitute the molecule. Must not be null or empty.
     * @throws IllegalArgumentException if name is invalid or atoms list is invalid.
     */
    public Molecule(String name, List<Atom> atoms) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Molecule name cannot be null or empty.");
        }
        if (atoms == null || atoms.isEmpty()) {
            throw new IllegalArgumentException("Atoms list cannot be null or empty for a molecule.");
        }
        for (Atom atom : atoms) {
            if (atom == null) {
                throw new IllegalArgumentException("Atoms list cannot contain null entries.");
            }
        }

        this.name = name.trim();
        this.atoms = Collections.unmodifiableList(new ArrayList<>(atoms)); // Defensive copy for immutability
    }

    /**
     * Returns the name of the molecule.
     * @return The molecule name.
     */
    public String getName() {
        return name;
    }

    /**
     * Returns an unmodifiable list of the atoms in the molecule.
     * @return An unmodifiable list of atoms.
     */
    public List<Atom> getAtoms() {
        return atoms;
    }

    /**
     * Calculates the total molecular weight based on the exact atomic masses of its constituent atoms.
     * @return The total molecular weight.
     */
    public double calculateMolecularWeight() {
        return atoms.stream()
                    .mapToDouble(atom -> atom.getIsotope().getExactAtomicMass())
                    .sum();
    }

    /**
     * Counts the occurrences of each element in the molecule.
     * @return A map where keys are ChemicalElements and values are their counts.
     */
    public Map<ChemicalElement, Integer> getElementalComposition() {
        Map<ChemicalElement, Integer> composition = new HashMap<>();
        for (Atom atom : atoms) {
            ChemicalElement element = new ChemicalElement(atom.getIsotope().getAtomicNumber(),
                                                          atom.getIsotope().getSymbol(),
                                                          atom.getIsotope().getName());
            composition.merge(element, 1, Integer::sum);
        }
        return Collections.unmodifiableMap(composition);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Molecule molecule = (Molecule) o;
        return name.equals(molecule.name) &&
               atoms.equals(molecule.atoms);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, atoms);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Molecule: ").append(name).append(" (MW: ")
          .append(String.format("%.4f", calculateMolecularWeight()))
          .append(" amu)\n");
        sb.append("  Atoms:\n");
        atoms.forEach(atom -> sb.append("    - ").append(atom).append("\n"));
        sb.append("  Elemental Composition: ").append(getElementalComposition());
        return sb.toString();
    }

    public static void main(String[] args) {
        Isotope h1 = new Isotope(1, "H", "Hydrogen", 0, 1.007825);
        Isotope o16 = new Isotope(8, "O", "Oxygen", 8, 15.994915);
        Isotope c12 = new Isotope(6, "C", "Carbon", 6, 12.000000);

        // Water (H2O)
        List<Atom> waterAtoms = new ArrayList<>();
        waterAtoms.add(new Atom(h1, 0)); // Atom ID 0
        waterAtoms.add(new Atom(h1, 1)); // Atom ID 1
        waterAtoms.add(new Atom(o16, 2)); // Atom ID 2
        Molecule water = new Molecule("Water", waterAtoms);
        System.out.println(water);

        // Methane (CH4)
        List<Atom> methaneAtoms = new ArrayList<>();
        methaneAtoms.add(new Atom(c12, 0));
        methaneAtoms.add(new Atom(h1, 1));
        methaneAtoms.add(new Atom(h1, 2));
        methaneAtoms.add(new Atom(h1, 3));
        methaneAtoms.add(new Atom(h1, 4));
        Molecule methane = new Molecule("Methane", methaneAtoms);
        System.out.println(methane);

        System.out.println("Are water's atoms the same as methane's atoms? " + water.getAtoms().equals(methane.getAtoms()));
    }
}

/**
 * Represents a single atom within a molecule, referencing an Isotope.
 * This class could be extended to include 3D coordinates, charge, etc.
 * It is immutable.
 */
final class Atom {
    private final Isotope isotope;
    private final int atomId; // Unique identifier for this atom within a system/molecule

    public Atom(Isotope isotope, int atomId) {
        if (isotope == null) {
            throw new IllegalArgumentException("Isotope cannot be null.");
        }
        if (atomId < 0) {
            throw new IllegalArgumentException("Atom ID cannot be negative.");
        }
        this.isotope = isotope;
        this.atomId = atomId;
    }

    public Isotope getIsotope() {
        return isotope;
    }

    public int getAtomId() {
        return atomId;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Atom atom = (Atom) o;
        return atomId == atom.atomId &&
               isotope.equals(atom.isotope);
    }

    @Override
    public int hashCode() {
        return Objects.hash(isotope, atomId);
    }

    @Override
    public String toString() {
        return String.format("Atom ID: %d, Isotope: %s", atomId, isotope.getName() + "-" + isotope.getMassNumber());
    }
}"
