    "text": "import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Represents a solution, containing a solvent and multiple solutes with their concentrations.
 * This class uses a generic `Unit` enum for concentrations to promote type safety and clarity.
 * It is designed to be immutable once created.
 */
public final class Solution {

    /**
     * Represents different units of concentration.
     */
    public enum ConcentrationUnit {
        MOLARITY("M"), MOLALITY("m"), PERCENT_MASS("% w/w"), PPM("ppm");

        private final String symbol;

        ConcentrationUnit(String symbol) {
            this.symbol = symbol;
        }

        public String getSymbol() {
            return symbol;
        }
    }

    private final String name;
    private final ChemicalCompound solvent;
    private final Map<ChemicalCompound, Double> soluteConcentrations;
    private final ConcentrationUnit unit;

    /**
     * Constructs a new Solution instance.
     * @param name The name of the solution (e.g., "Saline Solution"). Can be null or empty.
     * @param solvent The chemical compound acting as the solvent. Must not be null.
     * @param soluteConcentrations A map of solute compounds and their concentrations. Can be empty if no solutes.
     *                             Concentrations must be non-negative.
     * @param unit The unit of concentration for all solutes. Must not be null.
     * @throws IllegalArgumentException if solvent is null, unit is null, or any concentration is negative.
     */
    public Solution(String name, ChemicalCompound solvent,
                    Map<ChemicalCompound, Double> soluteConcentrations, ConcentrationUnit unit) {
        if (solvent == null) {
            throw new IllegalArgumentException("Solvent cannot be null.");
        }
        if (unit == null) {
            throw new IllegalArgumentException("Concentration unit cannot be null.");
        }

        this.name = (name != null && !name.trim().isEmpty()) ? name.trim() : "Unnamed Solution";
        this.solvent = solvent;
        this.unit = unit;

        this.soluteConcentrations = new HashMap<>();
        if (soluteConcentrations != null) {
            for (Map.Entry<ChemicalCompound, Double> entry : soluteConcentrations.entrySet()) {
                ChemicalCompound solute = entry.getKey();
                Double concentration = entry.getValue();
                if (solute == null || concentration == null || concentration < 0) {
                    throw new IllegalArgumentException("Invalid solute or negative concentration provided.");
                }
                this.soluteConcentrations.put(solute, concentration);
            }
        }
    }

    /**
     * Returns the name of the solution.
     * @return The solution name.
     */
    public String getName() {
        return name;
    }

    /**
     * Returns the solvent compound.
     * @return The solvent.
     */
    public ChemicalCompound getSolvent() {
        return solvent;
    }

    /**
     * Returns an unmodifiable map of solute compounds and their concentrations.
     * @return An unmodifiable map of solute concentrations.
     */
    public Map<ChemicalCompound, Double> getSoluteConcentrations() {
        return new HashMap<>(soluteConcentrations); // Defensive copy
    }

    /**
     * Returns the unit of concentration used for the solutes.
     * @return The concentration unit.
     */
    public ConcentrationUnit getUnit() {
        return unit;
    }

    /**
     * Checks if the solution contains a specific solute.
     * @param solute The compound to check for.
     * @return True if the solute is present, false otherwise.
     */
    public boolean containsSolute(ChemicalCompound solute) {
        return soluteConcentrations.containsKey(solute);
    }

    /**
     * Gets the concentration of a specific solute.
     * @param solute The compound whose concentration is requested.
     * @return An Optional containing the concentration if the solute is present, empty otherwise.
     */
    public Optional<Double> getConcentrationOf(ChemicalCompound solute) {
        return Optional.ofNullable(soluteConcentrations.get(solute));
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Solution solution = (Solution) o;
        return name.equals(solution.name) &&
               solvent.equals(solution.solvent) &&
               soluteConcentrations.equals(solution.soluteConcentrations) &&
               unit == solution.unit;
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, solvent, soluteConcentrations, unit);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Solution: ").append(name).append("\n");
        sb.append("  Solvent: ").append(solvent.getName()).append("\n");
        if (soluteConcentrations.isEmpty()) {
            sb.append("  No solutes present.");
        } else {
            sb.append("  Solutes (in ").append(unit.getSymbol()).append("):\n");
            soluteConcentrations.forEach((solute, conc) ->
                sb.append("    - ").append(solute.getName()).append(": ").append(String.format("%.4f", conc)).append(" ").append(unit.getSymbol()).append("\n"));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        ChemicalElement Na = new ChemicalElement(11, "Na", "Sodium");
        ChemicalElement Cl = new ChemicalElement(17, "Cl", "Chlorine");
        ChemicalElement H = new ChemicalElement(1, "H", "Hydrogen");
        ChemicalElement O = new ChemicalElement(8, "O", "Oxygen");
        ChemicalElement C = new ChemicalElement(6, "C", "Carbon");

        Map<ChemicalElement, Integer> saltComp = new HashMap<>();
        saltComp.put(Na, 1); saltComp.put(Cl, 1);
        ChemicalCompound salt = new ChemicalCompound("Sodium Chloride", saltComp);

        Map<ChemicalElement, Integer> waterComp = new HashMap<>();
        waterComp.put(H, 2); waterComp.put(O, 1);
        ChemicalCompound water = new ChemicalCompound("Water", waterComp);

        Map<ChemicalElement, Integer> sugarComp = new HashMap<>();
        sugarComp.put(C, 12); sugarComp.put(H, 22); sugarComp.put(O, 11);
        ChemicalCompound sugar = new ChemicalCompound("Sucrose", sugarComp);

        Map<ChemicalCompound, Double> salineSolutes = new HashMap<>();
        salineSolutes.put(salt, 0.15); // 0.15 M NaCl
        Solution salineSolution = new Solution("Saline Solution", water, salineSolutes, ConcentrationUnit.MOLARITY);
        System.out.println(salineSolution);

        Map<ChemicalCompound, Double> sugarWaterSolutes = new HashMap<>();
        sugarWaterSolutes.put(sugar, 5.0); // 5.0 % w/w Sucrose
        Solution sugarWater = new Solution("Sugar Water", water, sugarWaterSolutes, ConcentrationUnit.PERCENT_MASS);
        System.out.println(sugarWater);

        Map<ChemicalCompound, Double> pureWaterSolutes = new HashMap<>();
        Solution pureWater = new Solution("Pure Water", water, pureWaterSolutes, ConcentrationUnit.MOLARITY);
        System.out.println(pureWater);

        System.out.println("Saline contains salt? " + salineSolution.containsSolute(salt));
        salineSolution.getConcentrationOf(salt).ifPresent(conc ->
            System.out.println("Salt concentration in saline: " + conc + " " + salineSolution.getUnit().getSymbol()));
    }
}"
