import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/**
 * Represents a periodic table, a collection of unique chemical elements.
 * This class provides methods to retrieve elements by atomic number, symbol, or name.
 * It is designed to be a singleton or a static utility class to ensure a single source of truth for elements.
 * For this example, it's a simple class with a static factory method.
 */
public final class PeriodicTable {

    private static final Map<Integer, ChemicalElement> elementsByAtomicNumber = new HashMap<>();
    private static final Map<String, ChemicalElement> elementsBySymbol = new HashMap<>();
    private static final Map<String, ChemicalElement> elementsByName = new HashMap<>();

    // Static initializer block to populate the periodic table upon class loading
    static {
        // Add common elements. In a real application, this would be loaded from a data source.
        addElement(new ChemicalElement(1, "H", "Hydrogen"));
        addElement(new ChemicalElement(2, "He", "Helium"));
        addElement(new ChemicalElement(3, "Li", "Lithium"));
        addElement(new ChemicalElement(4, "Be", "Beryllium"));
        addElement(new ChemicalElement(5, "B", "Boron"));
        addElement(new ChemicalElement(6, "C", "Carbon"));
        addElement(new ChemicalElement(7, "N", "Nitrogen"));
        addElement(new ChemicalElement(8, "O", "Oxygen"));
        addElement(new ChemicalElement(9, "F", "Fluorine"));
        addElement(new ChemicalElement(10, "Ne", "Neon"));
        addElement(new ChemicalElement(11, "Na", "Sodium"));
        addElement(new ChemicalElement(12, "Mg", "Magnesium"));
        // ... add more elements as needed
    }

    private PeriodicTable() {
        // Private constructor to prevent instantiation
    }

    private static void addElement(ChemicalElement element) {
        if (element == null) {
            throw new IllegalArgumentException("Cannot add a null element to the periodic table.");
        }
        elementsByAtomicNumber.put(element.getAtomicNumber(), element);
        elementsBySymbol.put(element.getSymbol(), element);
        elementsByName.put(element.getName(), element);
    }

    /**
     * Retrieves a ChemicalElement by its atomic number.
     * @param atomicNumber The atomic number of the element.
     * @return The ChemicalElement if found, null otherwise.
     */
    public static ChemicalElement getElementByAtomicNumber(int atomicNumber) {
        return elementsByAtomicNumber.get(atomicNumber);
    }

    /**
     * Retrieves a ChemicalElement by its symbol (case-sensitive).
     * @param symbol The chemical symbol of the element.
     * @return The ChemicalElement if found, null otherwise.
     */
    public static ChemicalElement getElementBySymbol(String symbol) {
        return elementsBySymbol.get(symbol);
    }

    /**
     * Retrieves a ChemicalElement by its name (case-sensitive).
     * @param name The full name of the element.
     * @return The ChemicalElement if found, null otherwise.
     */
    public static ChemicalElement getElementByName(String name) {
        return elementsByName.get(name);
    }

    /**
     * Returns an unmodifiable map of all elements keyed by atomic number.
     * @return An unmodifiable map of all elements.
     */
    public static Map<Integer, ChemicalElement> getAllElementsByAtomicNumber() {
        return Collections.unmodifiableMap(elementsByAtomicNumber);
    }

    /**
     * Returns the total number of elements currently stored in the periodic table.
     * @return The count of elements.
     */
    public static int getNumberOfElements() {
        return elementsByAtomicNumber.size();
    }

    public static void main(String[] args) {
        System.out.println("Total elements in table: " + PeriodicTable.getNumberOfElements());

        ChemicalElement carbon = PeriodicTable.getElementByAtomicNumber(6);
        System.out.println("Element with atomic number 6: " + carbon);

        ChemicalElement oxygen = PeriodicTable.getElementBySymbol("O");
        System.out.println("Element with symbol 'O': " + oxygen);

        ChemicalElement hydrogen = PeriodicTable.getElementByName("Hydrogen");
        System.out.println("Element named 'Hydrogen': " + hydrogen);

        ChemicalElement unknown = PeriodicTable.getElementByAtomicNumber(999);
        System.out.println("Element with atomic number 999: " + (unknown != null ? unknown.getName() : "Not found"));

        System.out.println("All elements (by atomic number):");
        PeriodicTable.getAllElementsByAtomicNumber().values().forEach(System.out::println);
    }
}"
