    "text": "import java.util.Objects;

/**
 * Represents a chemical bond between two atoms, specifying the type and strength.
 * This is a simplified model for demonstration purposes.
 * Immutability is maintained for bond properties.
 */
public final class ChemicalBond {

    /**
     * Enum to define the type of chemical bond.
     */
    public enum BondType {
        SINGLE, DOUBLE, TRIPLE, AROMATIC, IONIC, METALLIC
    }

    private final Atom atom1;
    private final Atom atom2;
    private final BondType type;
    private final double bondLengthAngstroms; // Example property
    private final double bondEnergyKJmol;     // Example property

    /**
     * Constructs a new ChemicalBond instance.
     * @param atom1 The first atom in the bond. Must not be null.
     * @param atom2 The second atom in the bond. Must not be null and different from atom1.
     * @param type The type of bond. Must not be null.
     * @param bondLengthAngstroms The length of the bond in Angstroms. Must be positive.
     * @param bondEnergyKJmol The energy of the bond in kJ/mol. Must be positive.
     * @throws IllegalArgumentException if any parameter is invalid.
     */
    public ChemicalBond(Atom atom1, Atom atom2, BondType type,
                        double bondLengthAngstroms, double bondEnergyKJmol) {
        if (atom1 == null || atom2 == null) {
            throw new IllegalArgumentException("Neither atom in a bond can be null.");
        }
        if (atom1.equals(atom2)) {
            throw new IllegalArgumentException("An atom cannot bond to itself.");
        }
        if (type == null) {
            throw new IllegalArgumentException("Bond type cannot be null.");
        }
        if (bondLengthAngstroms <= 0) {
            throw new IllegalArgumentException("Bond length must be positive.");
        }
        if (bondEnergyKJmol <= 0) {
            throw new IllegalArgumentException("Bond energy must be positive.");
        }

        this.atom1 = atom1;
        this.atom2 = atom2;
        this.type = type;
        this.bondLengthAngstroms = bondLengthAngstroms;
        this.bondEnergyKJmol = bondEnergyKJmol;
    }

    /**
     * Returns the first atom involved in the bond.
     * @return The first atom.
     */
    public Atom getAtom1() {
        return atom1;
    }

    /**
     * Returns the second atom involved in the bond.
     * @return The second atom.
     */
    public Atom getAtom2() {
        return atom2;
    }

    /**
     * Returns the type of the chemical bond.
     * @return The bond type.
     */
    public BondType getType() {
        return type;
    }

    /**
     * Returns the length of the bond in Angstroms.
     * @return The bond length.
     */
    public double getBondLengthAngstroms() {
        return bondLengthAngstroms;
    }

    /**
     * Returns the energy required to break the bond in kJ/mol.
     * @return The bond energy.
     */
    public double getBondEnergyKJmol() {
        return bondEnergyKJmol;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ChemicalBond that = (ChemicalBond) o;
        // Bonds are symmetric, so (A,B) is equal to (B,A)
        return (atom1.equals(that.atom1) && atom2.equals(that.atom2) ||
                atom1.equals(that.atom2) && atom2.equals(that.atom1)) &&
               type == that.type &&
               Double.compare(that.bondLengthAngstroms, bondLengthAngstroms) == 0 &&
               Double.compare(that.bondEnergyKJmol, bondEnergyKJmol) == 0;
    }

    @Override
    public int hashCode() {
        // Hash code should also be symmetric for (A,B) and (B,A)
        return Objects.hash(type, bondLengthAngstroms, bondEnergyKJmol,
                            atom1.hashCode() + atom2.hashCode()); // Simple symmetric hash
    }

    @Override
    public String toString() {
        return String.format("Bond: %s-%s (%s, Length: %.3f Å, Energy: %.1f kJ/mol)",
                             atom1.getIsotope().getSymbol(), atom2.getIsotope().getSymbol(),
                             type, bondLengthAngstroms, bondEnergyKJmol);
    }

    public static void main(String[] args) {
        Isotope h1 = new Isotope(1, "H", "Hydrogen", 0, 1.007825);
        Isotope o16 = new Isotope(8, "O", "Oxygen", 8, 15.994915);
        Isotope c12 = new Isotope(6, "C", "Carbon", 6, 12.000000);

        Atom hAtom1 = new Atom(h1, 0);
        Atom hAtom2 = new Atom(h1, 1);
        Atom oAtom = new Atom(o16, 2);
        Atom cAtom = new Atom(c12, 3);

        // H-O bond in Water
        ChemicalBond hoBond = new ChemicalBond(hAtom1, oAtom, BondType.SINGLE, 0.958, 463.0);
        System.out.println(hoBond);

        // C=O bond (example)
        ChemicalBond coDoubleBond = new ChemicalBond(cAtom, oAtom, BondType.DOUBLE, 1.21, 745.0);
        System.out.println(coDoubleBond);

        // H-H bond (example)
        ChemicalBond hhBond = new ChemicalBond(hAtom1, hAtom2, BondType.SINGLE, 0.74, 436.0);
        System.out.println(hhBond);

        // Test equality (symmetric nature)
        ChemicalBond hoBondReversed = new ChemicalBond(oAtom, hAtom1, BondType.SINGLE, 0.958, 463.0);
        System.out.println("Is hoBond equal to hoBondReversed? " + hoBond.equals(hoBondReversed));

        // Test inequality
        ChemicalBond anotherHoBond = new ChemicalBond(hAtom1, oAtom, BondType.SINGLE, 0.960, 460.0);
        System.out.println("Is hoBond equal to anotherHoBond (different length/energy)? " + hoBond.equals(anotherHoBond));
    }
}"
