    "text": "import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;

/**
 * Represents the physical state of a chemical compound under specific conditions (temperature, pressure).
 * This class uses an EnumMap for properties that depend on state, for efficient access.
 * It's immutable, representing a snapshot of properties for a given state.
 */
public final class ChemicalState {

    /**
     * Enum to define the possible phases of matter.
     */
    public enum Phase {
        SOLID, LIQUID, GAS, AQUEOUS, PLASMA
    }

    private final ChemicalCompound compound;
    private final Phase phase;
    private final double temperatureCelsius;
    private final double pressureAtm;
    private final Map<Property, Double> stateDependentProperties;

    /**
     * Enum for various state-dependent properties.
     */
    public enum Property {
        DENSITY("g/cm³"), BOILING_POINT("°C"), MELTING_POINT("°C"), HEAT_CAPACITY("J/mol·K");

        private final String unit;

        Property(String unit) {
            this.unit = unit;
        }

        public String getUnit() {
            return unit;
        }
    }

    /**
     * Constructs a new ChemicalState instance.
     * @param compound The chemical compound in this state. Must not be null.
     * @param phase The phase of the compound. Must not be null.
     * @param temperatureCelsius The temperature in Celsius.
     * @param pressureAtm The pressure in atmospheres. Must be non-negative.
     * @param stateDependentProperties A map of properties specific to this state. Can be null or empty.
     *                                 Values must be non-negative where applicable (e.g., density).
     * @throws IllegalArgumentException if compound or phase are null, or pressure is negative.
     */
    public ChemicalState(ChemicalCompound compound, Phase phase, double temperatureCelsius,
                         double pressureAtm, Map<Property, Double> stateDependentProperties) {
        if (compound == null) {
            throw new IllegalArgumentException("Compound cannot be null.");
        }
        if (phase == null) {
            throw new IllegalArgumentException("Phase cannot be null.");
        }
        if (pressureAtm < 0) {
            throw new IllegalArgumentException("Pressure cannot be negative.");
        }

        this.compound = compound;
        this.phase = phase;
        this.temperatureCelsius = temperatureCelsius;
        this.pressureAtm = pressureAtm;

        this.stateDependentProperties = new EnumMap<>(Property.class);
        if (stateDependentProperties != null) {
            for (Map.Entry<Property, Double> entry : stateDependentProperties.entrySet()) {
                Property prop = entry.getKey();
                Double value = entry.getValue();
                if (prop == null || value == null || (value < 0 && prop != Property.MELTING_POINT && prop != Property.BOILING_POINT)) {
                    // Allow negative melting/boiling points (e.g., -100C), but not for density etc.
                    if (value < 0 && (prop == Property.DENSITY || prop == Property.HEAT_CAPACITY)) {
                        throw new IllegalArgumentException("Property value for " + prop + " cannot be negative.");
                    }
                }
                this.stateDependentProperties.put(prop, value);
            }
        }
    }

    /**
     * Returns the chemical compound associated with this state.
     * @return The compound.
     */
    public ChemicalCompound getCompound() {
        return compound;
    }

    /**
     * Returns the phase of the compound.
     * @return The phase.
     */
    public Phase getPhase() {
        return phase;
    }

    /**
     * Returns the temperature in Celsius.
     * @return The temperature.
     */
    public double getTemperatureCelsius() {
        return temperatureCelsius;
    }

    /**
     * Returns the pressure in atmospheres.
     * @return The pressure.
     */\    public double getPressureAtm() {
        return pressureAtm;
    }

    /**
     * Returns an unmodifiable map of state-dependent properties.
     * @return An unmodifiable map of properties.
     */
    public Map<Property, Double> getStateDependentProperties() {
        return Collections.unmodifiableMap(stateDependentProperties); // Defensive copy for EnumMap
    }

    /**
     * Gets a specific property value for this state.
     * @param property The property to retrieve.
     * @return An Optional containing the property value if present, empty otherwise.
     */
    public Optional<Double> getPropertyValue(Property property) {
        return Optional.ofNullable(stateDependentProperties.get(property));
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ChemicalState that = (ChemicalState) o;
        return Double.compare(that.temperatureCelsius, temperatureCelsius) == 0 &&
               Double.compare(that.pressureAtm, pressureAtm) == 0 &&
               compound.equals(that.compound) &&
               phase == that.phase &&
               stateDependentProperties.equals(that.stateDependentProperties);
    }

    @Override
    public int hashCode() {
        return Objects.hash(compound, phase, temperatureCelsius, pressureAtm, stateDependentProperties);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append(compound.getName()).append(" in ").append(phase.name()).append(" state\n");
        sb.append("  Conditions: T = ").append(String.format("%.1f", temperatureCelsius)).append(" °C, P = ").append(String.format("%.2f", pressureAtm)).append(" atm\n");
        if (!stateDependentProperties.isEmpty()) {
            sb.append("  Properties:\n");
            stateDependentProperties.forEach((prop, value) ->
                sb.append("    - ").append(prop.name()).append(": ").append(String.format("%.4f", value)).append(" ").append(prop.getUnit()).append("\n"));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        ChemicalElement H = new ChemicalElement(1, "H", "Hydrogen");
        ChemicalElement O = new ChemicalElement(8, "O", "Oxygen");
        ChemicalElement C = new ChemicalElement(6, "C", "Carbon");

        Map<ChemicalElement, Integer> waterComp = new HashMap<>();
        waterComp.put(H, 2); waterComp.put(O, 1);
        ChemicalCompound water = new ChemicalCompound("Water", waterComp);

        Map<ChemicalElement, Integer> carbonDioxideComp = new HashMap<>();
        carbonDioxideComp.put(C, 1); carbonDioxideComp.put(O, 2);
        ChemicalCompound carbonDioxide = new ChemicalCompound("Carbon Dioxide", carbonDioxideComp);

        // Liquid water at room temp
        Map<ChemicalState.Property, Double> liquidWaterProps = new EnumMap<>(ChemicalState.Property.class);
        liquidWaterProps.put(ChemicalState.Property.DENSITY, 0.998);
        liquidWaterProps.put(ChemicalState.Property.BOILING_POINT, 100.0);
        liquidWaterProps.put(ChemicalState.Property.MELTING_POINT, 0.0);
        ChemicalState liquidWater = new ChemicalState(water, Phase.LIQUID, 25.0, 1.0, liquidWaterProps);
        System.out.println(liquidWater);

        // Gaseous CO2
        Map<ChemicalState.Property, Double> gaseousCO2Props = new EnumMap<>(ChemicalState.Property.class);
        gaseousCO2Props.put(ChemicalState.Property.DENSITY, 0.001977);
        ChemicalState gaseousCO2 = new ChemicalState(carbonDioxide, Phase.GAS, 25.0, 1.0, gaseousCO2Props);
        System.out.println(gaseousCO2);

        // Solid water (ice)
        Map<ChemicalState.Property, Double> solidWaterProps = new EnumMap<>(ChemicalState.Property.class);
        solidWaterProps.put(ChemicalState.Property.DENSITY, 0.917);
        solidWaterProps.put(ChemicalState.Property.MELTING_POINT, 0.0);
        ChemicalState solidWater = new ChemicalState(water, Phase.SOLID, -5.0, 1.0, solidWaterProps);
        System.out.println(solidWater);

        solidWater.getPropertyValue(Property.DENSITY).ifPresent(d ->
            System.out.println("Density of ice: " + d + " " + Property.DENSITY.getUnit()));
    }
}"
