    "text": "import java.util.Objects;
import java.util.Optional;

/**
 * Represents a quantity of a chemical substance, defined by its compound and amount.
 * This class uses a generic `Unit` enum for amounts to promote type safety and clarity.
 * It is immutable to ensure consistent values.
 */
public final class ChemicalQuantity {

    /**
     * Enum to define different units of chemical amount.
     */
    public enum AmountUnit {
        MOLES("mol"), GRAMS("g"), MILLIGRAMS("mg");

        private final String symbol;

        AmountUnit(String symbol) {
            this.symbol = symbol;
        }

        public String getSymbol() {
            return symbol;
        }
    }

    private final ChemicalCompound compound;
    private final double amount;
    private final AmountUnit unit;

    /**
     * Constructs a new ChemicalQuantity instance.
     * @param compound The chemical compound. Must not be null.
     * @param amount The numerical amount of the compound. Must be non-negative.
     * @param unit The unit of the amount. Must not be null.
     * @throws IllegalArgumentException if compound or unit are null, or amount is negative.
     */
    public ChemicalQuantity(ChemicalCompound compound, double amount, AmountUnit unit) {
        if (compound == null) {
            throw new IllegalArgumentException("Compound cannot be null.");
        }
        if (unit == null) {
            throw new IllegalArgumentException("Amount unit cannot be null.");
        }
        if (amount < 0) {
            throw new IllegalArgumentException("Amount cannot be negative.");
        }

        this.compound = compound;
        this.amount = amount;
        this.unit = unit;
    }

    /**
     * Returns the chemical compound this quantity refers to.
     * @return The compound.
     */
    public ChemicalCompound getCompound() {
        return compound;
    }

    /**
     * Returns the numerical amount of the compound.
     * @return The amount.
     */
    public double getAmount() {
        return amount;
    }

    /**
     * Returns the unit of the amount.
     * @return The amount unit.
     */
    public AmountUnit getUnit() {
        return unit;
    }

    /**
     * Converts this quantity to moles.
     * @return An Optional containing the amount in moles, or empty if conversion is not possible (e.g., compound has no molecular weight).
     */
    public Optional<ChemicalQuantity> toMoles() {
        if (unit == AmountUnit.MOLES) {
            return Optional.of(this);
        }
        double molecularWeight = compound.getMolecularWeight();
        if (molecularWeight <= 0) {
            return Optional.empty(); // Cannot convert if molecular weight is unknown/zero
        }

        double moles;
        switch (unit) {
            case GRAMS:
                moles = amount / molecularWeight;
                break;
            case MILLIGRAMS:
                moles = (amount / 1000.0) / molecularWeight;
                break;
            default:
                return Optional.empty(); // Should not happen with current enum, but good practice
        }
        return Optional.of(new ChemicalQuantity(compound, moles, AmountUnit.MOLES));
    }

    /**
     * Converts this quantity to grams.
     * @return An Optional containing the amount in grams, or empty if conversion is not possible.
     */
    public Optional<ChemicalQuantity> toGrams() {
        if (unit == AmountUnit.GRAMS) {
            return Optional.of(this);
        }
        double molecularWeight = compound.getMolecularWeight();
        if (molecularWeight <= 0) {
            return Optional.empty();
        }

        double grams;
        switch (unit) {
            case MOLES:
                grams = amount * molecularWeight;
                break;
            case MILLIGRAMS:
                grams = amount / 1000.0;
                break;
            default:
                return Optional.empty();
        }
        return Optional.of(new ChemicalQuantity(compound, grams, AmountUnit.GRAMS));
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ChemicalQuantity that = (ChemicalQuantity) o;
        return Double.compare(that.amount, amount) == 0 &&
               compound.equals(that.compound) &&
               unit == that.unit;
    }

    @Override
    public int hashCode() {
        return Objects.hash(compound, amount, unit);
    }

    @Override
    public String toString() {
        return String.format("%.4f %s of %s", amount, unit.getSymbol(), compound.getName());
    }

    public static void main(String[] args) {
        ChemicalElement H = new ChemicalElement(1, "H", "Hydrogen");
        ChemicalElement O = new ChemicalElement(8, "O", "Oxygen");

        Map<ChemicalElement, Integer> waterComp = new HashMap<>();
        waterComp.put(H, 2); waterComp.put(O, 1);
        ChemicalCompound water = new ChemicalCompound("Water", waterComp);

        // 10 grams of water
        ChemicalQuantity tenGramsWater = new ChemicalQuantity(water, 10.0, AmountUnit.GRAMS);
        System.out.println(tenGramsWater);

        // Convert to moles
        tenGramsWater.toMoles().ifPresent(moles ->
            System.out.println("  -> In moles: " + moles));

        // 0.5 moles of water
        ChemicalQuantity halfMoleWater = new ChemicalQuantity(water, 0.5, AmountUnit.MOLES);
        System.out.println(halfMoleWater);

        // Convert to grams
        halfMoleWater.toGrams().ifPresent(grams ->
            System.out.println("  -> In grams: " + grams));

        // 500 milligrams of water
        ChemicalQuantity fiveHundredMilligramsWater = new ChemicalQuantity(water, 500.0, AmountUnit.MILLIGRAMS);
        System.out.println(fiveHundredMilligramsWater);

        fiveHundredMilligramsWater.toGrams().ifPresent(grams ->
            System.out.println("  -> In grams: " + grams));

        fiveHundredMilligramsWater.toMoles().ifPresent(moles ->
            System.out.println("  -> In moles: " + moles));
    }
}"
