    "text": "import java.util.Objects;

/**
 * Represents a chemical reaction condition, encapsulating temperature and pressure.
 * This class is designed to be immutable, providing a consistent set of conditions.
 */
public final class ReactionConditions {

    private final double temperatureCelsius;
    private final double pressureAtm;
    private final String notes;

    /**
     * Constructs a new ReactionConditions instance.
     * @param temperatureCelsius The temperature in Celsius.
     * @param pressureAtm The pressure in atmospheres. Must be non-negative.
     * @param notes Optional notes about the conditions. Can be null or empty.
     * @throws IllegalArgumentException if pressure is negative.
     */
    public ReactionConditions(double temperatureCelsius, double pressureAtm, String notes) {
        if (pressureAtm < 0) {
            throw new IllegalArgumentException("Pressure cannot be negative.");
        }
        this.temperatureCelsius = temperatureCelsius;
        this.pressureAtm = pressureAtm;
        this.notes = (notes != null && !notes.trim().isEmpty()) ? notes.trim() : null;
    }

    /**
     * Returns the temperature in Celsius.
     * @return The temperature.
     */
    public double getTemperatureCelsius() {
        return temperatureCelsius;
    }

    /**
     * Returns the temperature in Kelvin.
     * @return The temperature in Kelvin.
     */
    public double getTemperatureKelvin() {
        return temperatureCelsius + 273.15;
    }

    /**
     * Returns the pressure in atmospheres.
     * @return The pressure.
     */
    public double getPressureAtm() {
        return pressureAtm;
    }

    /**
     * Returns optional notes about the conditions.
     * @return The notes, or null if none were provided.
     */
    public String getNotes() {
        return notes;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ReactionConditions that = (ReactionConditions) o;
        return Double.compare(that.temperatureCelsius, temperatureCelsius) == 0 &&
               Double.compare(that.pressureAtm, pressureAtm) == 0 &&
               Objects.equals(notes, that.notes);
    }

    @Override
    public int hashCode() {
        return Objects.hash(temperatureCelsius, pressureAtm, notes);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Conditions: T = ").append(String.format("%.1f", temperatureCelsius)).append(" °C (")
          .append(String.format("%.2f", getTemperatureKelvin())).append(" K)")
          .append(", P = ").append(String.format("%.2f", pressureAtm)).append(" atm");
        if (notes != null) {
            sb.append(" (Notes: ").append(notes).append(")");
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        // Standard ambient temperature and pressure (SATP)
        ReactionConditions satp = new ReactionConditions(25.0, 1.0, "Standard Ambient Temperature and Pressure");
        System.out.println(satp);

        // Standard temperature and pressure (STP)
        ReactionConditions stp = new ReactionConditions(0.0, 1.0, "Standard Temperature and Pressure");
        System.out.println(stp);

        // High temperature, high pressure reaction
        ReactionConditions extremeConditions = new ReactionConditions(500.0, 100.0, "Industrial Synthesis");
        System.out.println(extremeConditions);

        // Vacuum conditions
        ReactionConditions vacuum = new ReactionConditions(20.0, 0.00001, "High vacuum chamber");
        System.out.println(vacuum);

        // Check equality
        ReactionConditions satpCopy = new ReactionConditions(25.0, 1.0, "Standard Ambient Temperature and Pressure");
        System.out.println("SATP equals SATP copy? " + satp.equals(satpCopy));

        ReactionConditions satpDifferentNotes = new ReactionConditions(25.0, 1.0, "Another note");
        System.out.println("SATP equals SATP with different notes? " + satp.equals(satpDifferentNotes));
    }
}"
