import java.util.Optional;

/**
 * Represents a basic ion, extending the ChemicalElement concept with a charge.
 * This class is immutable.
 */
public final class Ion extends ChemicalElement {

    private final int charge;

    /**
     * Constructs a new Ion instance.
     * @param atomicNumber The atomic number of the element.
     * @param symbol The chemical symbol of the element.
     * @param name The full name of the element.
     * @param charge The charge of the ion (e.g., -1 for anion, +1 for cation, 0 for neutral).
     * @throws IllegalArgumentException if atomic number is not positive or symbol/name are invalid.
     */
    public Ion(int atomicNumber, String symbol, String name, int charge) {
        super(atomicNumber, symbol, name);
        this.charge = charge;
    }

    /**
     * Returns the charge of the ion.
     * @return The integer charge.
     */
    public int getCharge() {
        return charge;
    }

    /**
     * Checks if the ion is a cation (positive charge).
     * @return True if charge > 0, false otherwise.
     */
    public boolean isCation() {
        return charge > 0;
    }

    /**
     * Checks if the ion is an anion (negative charge).
     * @return True if charge < 0, false otherwise.
     */
    public boolean isAnion() {
        return charge < 0;
    }

    /**
     * Checks if the ion is neutral (charge = 0).
     * @return True if charge == 0, false otherwise.
     */
    public boolean isNeutral() {
        return charge == 0;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        if (!super.equals(o)) return false; // Check superclass (ChemicalElement) equality
        Ion ion = (Ion) o;
        return charge == ion.charge;
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), charge);
    }

    @Override
    public String toString() {
        String chargeStr;
        if (charge == 0) {
            chargeStr = "";
        } else if (charge == 1) {
            chargeStr = "+";
        } else if (charge == -1) {
            chargeStr = "-";
        } else if (charge > 0) {
            chargeStr = String.valueOf(charge) + "+";
        } else {
            chargeStr = String.valueOf(Math.abs(charge)) + "-";
        }
        return String.format("%s%s (Atomic Number: %d)", getSymbol(), chargeStr, getAtomicNumber());
    }

    public static void main(String[] args) {
        Ion sodiumIon = new Ion(11, "Na", "Sodium", 1);
        System.out.println(sodiumIon);
        System.out.println("Is Sodium ion a cation? " + sodiumIon.isCation());

        Ion chlorideIon = new Ion(17, "Cl", "Chlorine", -1);
        System.out.println(chlorideIon);
        System.out.println("Is Chloride ion an anion? " + chlorideIon.isAnion());

        Ion sulfateIon = new Ion(16, "S", "Sulfur", -2); // Simplified, usually a polyatomic ion
        System.out.println(sulfateIon);

        Ion magnesiumIon = new Ion(12, "Mg", "Magnesium", 2);
        System.out.println(magnesiumIon);

        // Neutral atom as an ion
        Ion oxygenAtom = new Ion(8, "O", "Oxygen", 0);
        System.out.println(oxygenAtom);
        System.out.println("Is Oxygen atom neutral? " + oxygenAtom.isNeutral());

        // Demonstrating polymorphism
        ChemicalElement element = sodiumIon;
        System.out.println("Polymorphic element: " + element.getName() + " (Symbol: " + element.getSymbol() + ")");
    }
}"
