    "text": "import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/**
 * Represents a chemical functional group, defined by its structure and properties.
 * This is a simplified model, focusing on the name and potential atoms involved.
 * Functional groups are immutable.
 */
public final class FunctionalGroup {

    private final String name;
    private final String formula;
    private final Map<ChemicalElement, Integer> elementalComposition;
    private final String typicalReactivity;

    /**
     * Constructs a new FunctionalGroup instance.
     * @param name The common name of the functional group (e.g., "Hydroxyl"). Must not be null or empty.
     * @param formula The empirical formula of the group (e.g., "-OH"). Must not be null or empty.
     * @param elementalComposition A map detailing the elements and their counts in the group.
     *                             Must not be null or empty, and all counts must be positive.
     * @param typicalReactivity A brief description of its typical reactivity. Can be null or empty.
     * @throws IllegalArgumentException if name, formula, or elementalComposition are invalid.
     */
    public FunctionalGroup(String name, String formula,
                           Map<ChemicalElement, Integer> elementalComposition, String typicalReactivity) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Functional group name cannot be null or empty.");
        }
        if (formula == null || formula.trim().isEmpty()) {
            throw new IllegalArgumentException("Functional group formula cannot be null or empty.");
        }
        if (elementalComposition == null || elementalComposition.isEmpty()) {
            throw new IllegalArgumentException("Elemental composition map cannot be null or empty.");
        }

        this.name = name.trim();
        this.formula = formula.trim();
        this.elementalComposition = new HashMap<>();
        for (Map.Entry<ChemicalElement, Integer> entry : elementalComposition.entrySet()) {
            ChemicalElement element = entry.getKey();
            Integer count = entry.getValue();
            if (element == null || count == null || count <= 0) {
                throw new IllegalArgumentException("Invalid element or count in elemental composition.");
            }
            this.elementalComposition.put(element, count);
        }
        this.typicalReactivity = (typicalReactivity != null && !typicalReactivity.trim().isEmpty()) ? typicalReactivity.trim() : "Not specified";
    }

    /**
     * Returns the common name of the functional group.
     * @return The name.
     */
    public String getName() {
        return name;
    }

    /**
     * Returns the empirical formula of the functional group.
     * @return The formula.
     */
    public String getFormula() {
        return formula;
    }

    /**
     * Returns an unmodifiable map of the elemental composition of the functional group.
     * @return An unmodifiable map of elements and their counts.
     */
    public Map<ChemicalElement, Integer> getElementalComposition() {
        return Collections.unmodifiableMap(elementalComposition); // Defensive copy
    }

    /**
     * Returns a brief description of the functional group's typical reactivity.
     * @return The reactivity description.
     */
    public String getTypicalReactivity() {
        return typicalReactivity;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        FunctionalGroup that = (FunctionalGroup) o;
        return name.equals(that.name) &&
               formula.equals(that.formula) &&
               elementalComposition.equals(that.elementalComposition);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, formula, elementalComposition);
    }

    @Override
    public String toString() {
        return String.format("Functional Group: %s (%s) - Composition: %s - Reactivity: %s",
                             name, formula, elementalComposition, typicalReactivity);
    }

    public static void main(String[] args) {
        ChemicalElement H = new ChemicalElement(1, "H", "Hydrogen");
        ChemicalElement O = new ChemicalElement(8, "O", "Oxygen");
        ChemicalElement C = new ChemicalElement(6, "C", "Carbon");
        ChemicalElement N = new ChemicalElement(7, "N", "Nitrogen");

        // Hydroxyl group (-OH)
        Map<ChemicalElement, Integer> hydroxylComp = new HashMap<>();
        hydroxylComp.put(O, 1);
        hydroxylComp.put(H, 1);
        FunctionalGroup hydroxyl = new FunctionalGroup("Hydroxyl", "-OH", hydroxylComp,
                                                       "Polar, forms hydrogen bonds, acts as weak acid/base.");
        System.out.println(hydroxyl);

        // Carboxyl group (-COOH)
        Map<ChemicalElement, Integer> carboxylComp = new HashMap<>();
        carboxylComp.put(C, 1);
        carboxylComp.put(O, 2);
        carboxylComp.put(H, 1);
        FunctionalGroup carboxyl = new FunctionalGroup("Carboxyl", "-COOH", carboxylComp,
                                                       "Acidic, readily deprotonates.");
        System.out.println(carboxyl);

        // Amino group (-NH2)
        Map<ChemicalElement, Integer> aminoComp = new HashMap<>();
        aminoComp.put(N, 1);
        aminoComp.put(H, 2);
        FunctionalGroup amino = new FunctionalGroup("Amino", "-NH2", aminoComp,
                                                    "Basic, can be protonated, nucleophilic.");
        System.out.println(amino);

        // Carbonyl group (C=O)
        Map<ChemicalElement, Integer> carbonylComp = new HashMap<>();
        carbonylComp.put(C, 1);
        carbonylComp.put(O, 1);
        FunctionalGroup carbonyl = new FunctionalGroup("Carbonyl", "=C=O", carbonylComp,
                                                    "Polar, electrophilic carbon, participates in nucleophilic addition.");
        System.out.println(carbonyl);

        FunctionalGroup anotherHydroxyl = new FunctionalGroup("Hydroxyl", "-OH", hydroxylComp, "Different note");
        System.out.println("Hydroxyl equals anotherHydroxyl (ignoring reactivity)? " + hydroxyl.equals(anotherHydroxyl));
    }
