    "text": "import java.util.Objects;

/**
 * Represents a physical constant relevant to chemistry.
 * This class is designed to be immutable and provides common physical constants.
 */
public final class PhysicalConstant {

    private final String name;
    private final String symbol;
    private final double value;
    private final String unit;

    /**
     * Constructs a new PhysicalConstant instance.
     * @param name The full name of the constant (e.g., "Avogadro's Number"). Must not be null or empty.
     * @param symbol The symbol representation (e.g., "NA"). Must not be null or empty.
     * @param value The numerical value of the constant. Must be non-negative.
     * @param unit The unit of the constant (e.g., "mol^-1"). Must not be null or empty.
     * @throws IllegalArgumentException if name, symbol, or unit are invalid, or value is negative.
     */
    public PhysicalConstant(String name, String symbol, double value, String unit) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Constant name cannot be null or empty.");
        }
        if (symbol == null || symbol.trim().isEmpty()) {
            throw new IllegalArgumentException("Constant symbol cannot be null or empty.");
        }
        if (unit == null || unit.trim().isEmpty()) {
            throw new IllegalArgumentException("Constant unit cannot be null or empty.");
        }
        if (value < 0) {
            throw new IllegalArgumentException("Constant value cannot be negative.");
        }

        this.name = name.trim();
        this.symbol = symbol.trim();
        this.value = value;
        this.unit = unit.trim();
    }

    /**
     * Returns the full name of the constant.
     * @return The name.
     */
    public String getName() {
        return name;
    }

    /**
     * Returns the symbol of the constant.
     * @return The symbol.
     */
    public String getSymbol() {
        return symbol;
    }

    /**
     * Returns the numerical value of the constant.
     * @return The value.
     */
    public double getValue() {
        return value;
    }

    /**
     * Returns the unit of the constant.
     * @return The unit.
     */
    public String getUnit() {
        return unit;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        PhysicalConstant that = (PhysicalConstant) o;
        return Double.compare(that.value, value) == 0 &&
               name.equals(that.name) &&
               symbol.equals(that.symbol) &&
               unit.equals(that.unit);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, symbol, value, unit);
    }

    @Override
    public String toString() {
        return String.format("%s (%s) = %.6e %s", name, symbol, value, unit);
    }

    public static void main(String[] args) {
        // Avogadro's Number
        PhysicalConstant avogadro = new PhysicalConstant("Avogadro's Number", "NA", 6.02214076e23, "mol^-1");
        System.out.println(avogadro);

        // Ideal Gas Constant
        PhysicalConstant gasConstant = new PhysicalConstant("Ideal Gas Constant", "R", 8.314462618, "J/(mol·K)");
        System.out.println(gasConstant);

        // Planck's Constant
        PhysicalConstant planck = new PhysicalConstant("Planck's Constant", "h", 6.62607015e-34, "J·s");
        System.out.println(planck);

        // Speed of Light in Vacuum
        PhysicalConstant speedOfLight = new PhysicalConstant("Speed of Light in Vacuum", "c", 299792458.0, "m/s");
        System.out.println(speedOfLight);

        // Elementary Charge
        PhysicalConstant elementaryCharge = new PhysicalConstant("Elementary Charge", "e", 1.602176634e-19, "C");
        System.out.println(elementaryCharge);

        // Check equality
        PhysicalConstant avogadroCopy = new PhysicalConstant("Avogadro's Number", "NA", 6.02214076e23, "mol^-1");
        System.out.println("Avogadro equals Avogadro copy? " + avogadro.equals(avogadroCopy));

        PhysicalConstant avogadroDifferentValue = new PhysicalConstant("Avogadro's Number", "NA", 6.022e23, "mol^-1");
        System.out.println("Avogadro equals Avogadro with different value? " + avogadro.equals(avogadroDifferentValue));
    }
}"
