    "text": "import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/**
 * Represents a material sample, which can be a pure compound or a mixture.
 * This class models a sample by its name, type, and composition.
 * It is designed to be immutable.
 */
public final class MaterialSample {

    /**
     * Enum to define the type of material sample.
     */
    public enum SampleType {
        PURE_COMPOUND, MIXTURE, SOLUTION, ALLOY
    }

    private final String name;
    private final SampleType type;
    private final double totalMassGrams;
    private final Map<ChemicalCompound, Double> compositionMasses;

    /**
     * Constructs a new MaterialSample instance.
     * @param name The name of the sample (e.g., "Distilled Water", "Air Sample"). Must not be null or empty.
     * @param type The type of the sample. Must not be null.
     * @param compositionMasses A map of chemical compounds and their masses in grams. Must not be null or empty.
     *                          All masses must be positive.
     * @throws IllegalArgumentException if name, type, or compositionMasses are invalid.
     */
    public MaterialSample(String name, SampleType type, Map<ChemicalCompound, Double> compositionMasses) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Sample name cannot be null or empty.");
        }
        if (type == null) {
            throw new IllegalArgumentException("Sample type cannot be null.");
        }
        if (compositionMasses == null || compositionMasses.isEmpty()) {
            throw new IllegalArgumentException("Composition masses map cannot be null or empty.");
        }

        this.name = name.trim();
        this.type = type;

        this.compositionMasses = new HashMap<>();
        double calculatedTotalMass = 0.0;
        for (Map.Entry<ChemicalCompound, Double> entry : compositionMasses.entrySet()) {
            ChemicalCompound compound = entry.getKey();
            Double mass = entry.getValue();
            if (compound == null || mass == null || mass <= 0) {
                throw new IllegalArgumentException("Invalid compound or non-positive mass in composition.");
            }
            this.compositionMasses.put(compound, mass);
            calculatedTotalMass += mass;
        }
        this.totalMassGrams = calculatedTotalMass;

        if (type == SampleType.PURE_COMPOUND && compositionMasses.size() > 1) {
            throw new IllegalArgumentException("A PURE_COMPOUND sample cannot have more than one component.");
        }
    }

    /**
     * Returns the name of the material sample.
     * @return The sample name.
     */
    public String getName() {
        return name;
    }

    /**
     * Returns the type of the material sample.
     * @return The sample type.
     */
    public SampleType getType() {
        return type;
    }

    /**
     * Returns the total mass of the sample in grams.
     * @return The total mass.
     */
    public double getTotalMassGrams() {
        return totalMassGrams;
    }

    /**
     * Returns an unmodifiable map of the sample's composition by mass.
     * @return An unmodifiable map of compounds and their masses.
     */
    public Map<ChemicalCompound, Double> getCompositionMasses() {
        return Collections.unmodifiableMap(compositionMasses); // Defensive copy
    }

    /**
     * Calculates the mass percentage of a specific compound in the sample.
     * @param compound The compound to calculate the percentage for.
     * @return An Optional containing the mass percentage (0-100), or empty if the compound is not in the sample.
     */
    public Optional<Double> getMassPercentage(ChemicalCompound compound) {
        if (compositionMasses.containsKey(compound) && totalMassGrams > 0) {
            return Optional.of((compositionMasses.get(compound) / totalMassGrams) * 100.0);
        }
        return Optional.empty();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        MaterialSample that = (MaterialSample) o;
        return Double.compare(that.totalMassGrams, totalMassGrams) == 0 &&
               name.equals(that.name) &&
               type == that.type &&
               compositionMasses.equals(that.compositionMasses);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, type, totalMassGrams, compositionMasses);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Material Sample: ").append(name).append(" (Type: ").append(type).append(")\n");
        sb.append("  Total Mass: ").append(String.format("%.3f", totalMassGrams)).append(" g\n");
        sb.append("  Composition (Mass %):\n");
        compositionMasses.forEach((compound, mass) -> {
            getMassPercentage(compound).ifPresent(percent ->
                sb.append("    - ").append(compound.getName()).append(": ").append(String.format("%.2f", percent)).append(" %\n"));
        });
        return sb.toString();
    }

    public static void main(String[] args) {
        ChemicalElement H = new ChemicalElement(1, "H", "Hydrogen");
        ChemicalElement O = new ChemicalElement(8, "O", "Oxygen");
        ChemicalElement C = new ChemicalElement(6, "C", "Carbon");
        ChemicalElement N = new ChemicalElement(7, "N", "Nitrogen");

        Map<ChemicalElement, Integer> waterComp = new HashMap<>();
        waterComp.put(H, 2); waterComp.put(O, 1);
        ChemicalCompound water = new ChemicalCompound("Water", waterComp);

        Map<ChemicalElement, Integer> ethanolComp = new HashMap<>();
        ethanolComp.put(C, 2); ethanolComp.put(H, 6); ethanolComp.put(O, 1);
        ChemicalCompound ethanol = new ChemicalCompound("Ethanol", ethanolComp);

        Map<ChemicalElement, Integer> nitrogenGasComp = new HashMap<>();
        nitrogenGasComp.put(N, 2);
        ChemicalCompound nitrogenGas = new ChemicalCompound("Nitrogen", nitrogenGasComp);

        Map<ChemicalElement, Integer> oxygenGasComp = new HashMap<>();
        oxygenGasComp.put(O, 2);
        ChemicalCompound oxygenGas = new ChemicalCompound("Oxygen", oxygenGasComp);

        // Pure water sample
        Map<ChemicalCompound, Double> pureWaterComposition = new HashMap<>();
        pureWaterComposition.put(water, 100.0);
        MaterialSample pureWater = new MaterialSample("Distilled Water", SampleType.PURE_COMPOUND, pureWaterComposition);
        System.out.println(pureWater);

        // Ethanol-water mixture
        Map<ChemicalCompound, Double> ethanolWaterComposition = new HashMap<>();
        ethanolWaterComposition.put(water, 70.0);
        ethanolWaterComposition.put(ethanol, 30.0);
        MaterialSample ethanolWater = new MaterialSample("70% Ethanol Solution", SampleType.SOLUTION, ethanolWaterComposition);
        System.out.println(ethanolWater);

        // Air sample (simplified)
        Map<ChemicalCompound, Double> airComposition = new HashMap<>();
        airComposition.put(nitrogenGas, 78.0);
        airComposition.put(oxygenGas, 21.0);
        airComposition.put(new ChemicalCompound("Argon", Map.of(new ChemicalElement(18, "Ar", "Argon"), 1)), 1.0);
        MaterialSample air = new MaterialSample("Atmospheric Air", SampleType.MIXTURE, airComposition);
        System.out.println(air);

        ethanolWater.getMassPercentage(water).ifPresent(p -> System.out.println("Mass % of water in ethanol-water: " + String.format("%.2f", p) + "%"));
    }
}"
  }
]

public class ClimateDataAnalyzer {
    public static double calculateAverageTemperature(double[] temperatures) {
        double sum = 0;
        for (double temp : temperatures) {
            sum += temp;
        }
        return sum / temperatures.length;
    }
}

public class CarbonFootprintCalculator {
    public static double calculateCarbonFootprint(double distance, double fuelEfficiency, double carbonIntensity) {
        return distance / fuelEfficiency * carbonIntensity;
    }
}

public class TemperatureConverter {
    public static double celsiusToFahrenheit(double celsius) {
        return celsius * 9 / 5 + 32;
    }
}

public class ClimateDataValidator {
    public static boolean isValidTemperature(double temperature) {
        return temperature >= -100 && temperature <= 100;
    }
}

public class ClimateDataSmoother {
    public static double[] smoothData(double[] data, int windowSize) {
        double[] smoothedData = new double[data.length];
        for (int i = 0; i < data.length; i++) {
            int start = Math.max(0, i - windowSize / 2);
            int end = Math.min(data.length - 1, i + windowSize / 2);
            double sum = 0;
            for (int j = start; j <= end; j++) {
                sum += data[j];
            }
            smoothedData[i] = sum / (end - start + 1);
        }
        return smoothedData;
    }
}

public class ClimateDataInterpolator {
    public static double[] interpolateData(double[] data, int newLength) {
        double[] interpolatedData = new double[newLength];
        double ratio = (double) (data.length - 1) / (newLength - 1);
        for (int i = 0; i < newLength; i++) {
            double index = i * ratio;
            int lowerIndex = (int) index;
            int upperIndex = Math.min(data.length - 1, lowerIndex + 1);
            double weight = index - lowerIndex;
            interpolatedData[i] = data[lowerIndex] * (1 - weight) + data[upperIndex] * weight;
        }
        return interpolatedData;
    }
}

public class ClimateDataNormalizer {
    public static double[] normalizeData(double[] data) {
        double min = Arrays.stream(data).min().getAsDouble();
        double max = Arrays.stream(data).max().getAsDouble();
        double[] normalizedData = new double[data.length];
        for (int i = 0; i < data.length; i++) {
            normalizedData[i] = (data[i] - min) / (max - min);
        }
        return normalizedData;
    }
}

public class ClimateDataTrendAnalyzer {
    public static double calculateTrend(double[] data) {
        int n = data.length;
        double sumXY = 0, sumX = 0, sumY = 0, sumX2 = 0;
        for (int i = 0; i < n; i++) {
            sumXY += i * data[i];
            sumX += i;
            sumY += data[i];
            sumX2 += i * i;
        }
        return (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    }
}

public class ClimateDataAnomalyDetector {
    public static boolean isAnomaly(double value, double[] data) {
        double mean = Arrays.stream(data).average().getAsDouble();
        double stdDev = Math.sqrt(Arrays.stream(data).map(x -> Math.pow(x - mean, 2)).average().getAsDouble());
        return Math.abs(value - mean) > 3 * stdDev;
    }
}

public class ClimateDataCorrelator {
    public static double calculateCorrelation(double[] data1, double[] data2) {
        double mean1 = Arrays.stream(data1).average().getAsDouble();
        double mean2 = Arrays.stream(data2).average().getAsDouble();
        double sumXY = 0, sumX2 = 0, sumY2 = 0;
        for (int i = 0; i < data1.length; i++) {
            sumXY += (data1[i] - mean1) * (data2[i] - mean2);
            sumX2 += Math.pow(data1[i] - mean1, 2);
            sumY2 += Math.pow(data2[i] - mean2, 2);
        }
        return sumXY / Math.sqrt(sumX2 * sumY2);
    }
}

