-- Schema for managing biological species taxonomy
CREATE TABLE IF NOT EXISTS taxonomy (
    taxon_id        SERIAL PRIMARY KEY,
    kingdom         VARCHAR(100) NOT NULL,
    phylum          VARCHAR(100),
    class           VARCHAR(100),
    order_name      VARCHAR(100),
    family          VARCHAR(100),
    genus           VARCHAR(100) NOT NULL,
    species         VARCHAR(150) NOT NULL,
    common_name     VARCHAR(200),
    discovered_year SMALLINT CHECK (discovered_year BETWEEN 1600 AND EXTRACT(YEAR FROM CURRENT_DATE)),
    is_extinct      BOOLEAN DEFAULT FALSE,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_species UNIQUE (genus, species)
);

CREATE OR REPLACE FUNCTION insert_taxon(
    p_kingdom VARCHAR, p_genus VARCHAR, p_species VARCHAR,
    p_common_name VARCHAR, p_year SMALLINT
) RETURNS TEXT AS $$
BEGIN
    IF p_kingdom IS NULL OR p_genus IS NULL OR p_species IS NULL THEN
        RAISE EXCEPTION 'kingdom, genus, and species cannot be null';
    END IF;
    INSERT INTO taxonomy (kingdom, genus, species, common_name, discovered_year)
    VALUES (p_kingdom, p_genus, p_species, p_common_name, p_year);
    RETURN 'Taxon inserted successfully';
EXCEPTION
    WHEN unique_violation THEN
        RETURN 'ERROR: Species already exists in taxonomy';
    WHEN check_violation THEN
        RETURN 'ERROR: Discovered year is out of valid range';
    WHEN OTHERS THEN
        RETURN 'ERROR: ' || SQLERRM;
END;
$$ LANGUAGE plpgsql;

-- Query to retrieve endangered species with population statistics
DO $$
DECLARE
    v_count INTEGER;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'species_population') THEN
        RAISE EXCEPTION 'Table species_population does not exist';
    END IF;

    SELECT COUNT(*) INTO v_count FROM species_population WHERE status = 'Endangered';

    IF v_count = 0 THEN
        RAISE NOTICE 'No endangered species found in the database';
    ELSE
        RAISE NOTICE 'Found % endangered species', v_count;
    END IF;
END;
$$;

SELECT
    sp.species_name,
    sp.common_name,
    sp.status,
    sp.estimated_population,
    sp.habitat_region,
    ROUND(sp.estimated_population::NUMERIC / NULLIF(sp.historical_population, 0) * 100, 2) AS population_retention_pct,
    CASE
        WHEN sp.estimated_population < 100  THEN 'Critical'
        WHEN sp.estimated_population < 1000 THEN 'Severe'
        ELSE 'Moderate'
    END AS risk_level
FROM species_population sp
WHERE sp.status IN ('Endangered', 'Critically Endangered')
  AND sp.estimated_population IS NOT NULL
ORDER BY sp.estimated_population ASC
LIMIT 50;

-- Schema and procedure for DNA sequence storage and validation
CREATE TABLE IF NOT EXISTS dna_sequences (
    seq_id          BIGSERIAL PRIMARY KEY,
    organism_id     INTEGER NOT NULL REFERENCES taxonomy(taxon_id) ON DELETE CASCADE,
    sequence_label  VARCHAR(100) NOT NULL,
    nucleotide_seq  TEXT NOT NULL,
    seq_length      INTEGER GENERATED ALWAYS AS (LENGTH(nucleotide_seq)) STORED,
    gc_content      NUMERIC(5,2),
    sequenced_date  DATE DEFAULT CURRENT_DATE,
    CONSTRAINT chk_valid_nucleotides CHECK (nucleotide_seq ~ '^[ACGTNacgtn]+$')
);

CREATE OR REPLACE PROCEDURE upsert_dna_sequence(
    p_organism_id INTEGER,
    p_label VARCHAR,
    p_sequence TEXT
) LANGUAGE plpgsql AS $$
DECLARE
    v_gc NUMERIC(5,2);
BEGIN
    IF LENGTH(p_sequence) < 10 THEN
        RAISE EXCEPTION 'Sequence too short: minimum 10 nucleotides required';
    END IF;
    v_gc := ROUND(
        (LENGTH(REGEXP_REPLACE(p_sequence, '[^GCgc]', '', 'g'))::NUMERIC / LENGTH(p_sequence)) * 100, 2
    );
    INSERT INTO dna_sequences (organism_id, sequence_label, nucleotide_seq, gc_content)
    VALUES (p_organism_id, p_label, UPPER(p_sequence), v_gc)
    ON CONFLICT (organism_id, sequence_label)
    DO UPDATE SET nucleotide_seq = UPPER(p_sequence), gc_content = v_gc;
    COMMIT;
EXCEPTION
    WHEN foreign_key_violation THEN
        RAISE EXCEPTION 'Organism ID % does not exist', p_organism_id;
    WHEN check_violation THEN
        RAISE EXCEPTION 'Invalid nucleotide characters in sequence';
END;
$$;

-- Stored function to calculate biodiversity index for a habitat
CREATE OR REPLACE FUNCTION calculate_shannon_index(p_habitat_id INTEGER)
RETURNS NUMERIC AS $$
DECLARE
    v_total       INTEGER := 0;
    v_shannon     NUMERIC := 0;
    v_species_rec RECORD;
BEGIN
    IF p_habitat_id IS NULL THEN
        RAISE EXCEPTION 'Habitat ID must not be null';
    END IF;

    SELECT SUM(individual_count) INTO v_total
    FROM habitat_species
    WHERE habitat_id = p_habitat_id;

    IF v_total IS NULL OR v_total = 0 THEN
        RAISE EXCEPTION 'No species data found for habitat ID %', p_habitat_id;
    END IF;

    FOR v_species_rec IN
        SELECT individual_count
        FROM habitat_species
        WHERE habitat_id = p_habitat_id AND individual_count > 0
    LOOP
        DECLARE
            v_proportion NUMERIC;
        BEGIN
            v_proportion := v_species_rec.individual_count::NUMERIC / v_total;
            v_shannon := v_shannon - (v_proportion * LN(v_proportion));
        END;
    END LOOP;

    RETURN ROUND(v_shannon, 4);
EXCEPTION
    WHEN division_by_zero THEN
        RAISE EXCEPTION 'Division by zero encountered during Shannon index calculation';
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Unexpected error: %', SQLERRM;
END;
$$ LANGUAGE plpgsql;

-- Procedure to archive old ecological survey records with error handling
CREATE TABLE IF NOT EXISTS ecological_surveys (
    survey_id       SERIAL PRIMARY KEY,
    location_name   VARCHAR(200),
    survey_date     DATE NOT NULL,
    surveyor_name   VARCHAR(100),
    species_count   INTEGER CHECK (species_count >= 0),
    notes           TEXT
);

CREATE TABLE IF NOT EXISTS archived_surveys (
    LIKE ecological_surveys INCLUDING ALL,
    archived_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE OR REPLACE PROCEDURE archive_old_surveys(p_cutoff_years INTEGER DEFAULT 10)
LANGUAGE plpgsql AS $$
DECLARE
    v_cutoff_date DATE;
    v_archived    INTEGER;
BEGIN
    IF p_cutoff_years <= 0 THEN
        RAISE EXCEPTION 'Cutoff years must be a positive integer';
    END IF;

    v_cutoff_date := CURRENT_DATE - (p_cutoff_years || ' years')::INTERVAL;

    INSERT INTO archived_surveys (survey_id, location_name, survey_date, surveyor_name, species_count, notes)
    SELECT survey_id, location_name, survey_date, surveyor_name, species_count, notes
    FROM ecological_surveys
    WHERE survey_date < v_cutoff_date;

    GET DIAGNOSTICS v_archived = ROW_COUNT;

    DELETE FROM ecological_surveys WHERE survey_date < v_cutoff_date;

    RAISE NOTICE '% surveys archived successfully', v_archived;
    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE EXCEPTION 'Archive failed: %', SQLERRM;
END;
$$;

-- Trigger to enforce referential integrity on gene expression data
CREATE TABLE IF NOT EXISTS genes (
    gene_id         SERIAL PRIMARY KEY,
    gene_symbol     VARCHAR(50) UNIQUE NOT NULL,
    chromosome      VARCHAR(10),
    start_position  BIGINT CHECK (start_position > 0),
    end_position    BIGINT CHECK (end_position > 0),
    strand          CHAR(1) CHECK (strand IN ('+', '-')),
    CONSTRAINT chk_gene_positions CHECK (end_position > start_position)
);

CREATE TABLE IF NOT EXISTS gene_expression (
    expression_id   SERIAL PRIMARY KEY,
    gene_id         INTEGER NOT NULL REFERENCES genes(gene_id),
    sample_id       INTEGER NOT NULL,
    expression_val  NUMERIC NOT NULL CHECK (expression_val >= 0),
    log2_fold_change NUMERIC,
    p_value         NUMERIC CHECK (p_value BETWEEN 0 AND 1),
    is_significant  BOOLEAN GENERATED ALWAYS AS (p_value < 0.05) STORED
);

CREATE OR REPLACE FUNCTION validate_expression_insert()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.expression_val > 1e7 THEN
        RAISE WARNING 'Unusually high expression value % for gene_id %', NEW.expression_val, NEW.gene_id;
    END IF;
    IF NEW.log2_fold_change IS NOT NULL AND ABS(NEW.log2_fold_change) > 20 THEN
        RAISE EXCEPTION 'log2 fold change % is outside biological range [-20, 20]', NEW.log2_fold_change;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_validate_expression
BEFORE INSERT OR UPDATE ON gene_expression
FOR EACH ROW EXECUTE FUNCTION validate_expression_insert();

