// Compute the angular separation between two stars in degrees
export function angularSeparation(ra1: number, dec1: number, ra2: number, dec2: number): number {
  const toRad = (d: number) => d * Math.PI / 180;
  const cosD = Math.sin(toRad(dec1)) * Math.sin(toRad(dec2)) +
    Math.cos(toRad(dec1)) * Math.cos(toRad(dec2)) * Math.cos(toRad(ra1 - ra2));
  return Math.acos(Math.min(1, Math.max(-1, cosD))) * 180 / Math.PI;
}

// Convert astronomical units to kilometers
export const AU_IN_KM = 149_597_870.7;

export function auToKilometers(au: number): number {
  return au * AU_IN_KM;
}

// Estimate orbital period in years using Kepler's third law
export function orbitalPeriod(semiMajorAxisAU: number, stellarMassSolar: number): number {
  // P^2 = a^3 / M for convenient astronomical units
  const periodSquared = Math.pow(semiMajorAxisAU, 3) / stellarMassSolar;
  return Math.sqrt(periodSquared);
}

// Convert parsecs to light-years
export function parsecToLightYears(parsecs: number): number {
  const LY_PER_PARSEC = 3.26156;
  return parsecs * LY_PER_PARSEC;
}

// Compute redshift from observed and emitted wavelengths
export function redshift(observedNm: number, emittedNm: number): number {
  if (emittedNm === 0) throw new Error('Emitted wavelength must be non-zero');
  return (observedNm - emittedNm) / emittedNm;
}

// Escape velocity from a spherical body in m/s
export function escapeVelocity(massKg: number, radiusM: number): number {
  const G = 6.67430e-11;
  // v = sqrt(2GM/r)
  return Math.sqrt((2 * G * massKg) / radiusM);
}

// Convert apparent magnitude difference into brightness ratio
export function brightnessRatio(mag1: number, mag2: number): number {
  // Pogson ratio: 100^(1/5) ≈ 2.512
  return Math.pow(10, 0.4 * (mag2 - mag1));
}

// Compute the Schwarzschild radius of a mass in meters
export function schwarzschildRadius(massKg: number): number {
  const G = 6.67430e-11;
  const c = 299_792_458;
  return (2 * G * massKg) / (c * c);
}

// Convert degrees, arcminutes, arcseconds to decimal degrees
export function dmsToDecimal(deg: number, arcmin: number, arcsec: number): number {
  const sign = deg < 0 ? -1 : 1;
  const absDeg = Math.abs(deg) + arcmin / 60 + arcsec / 3600;
  return sign * absDeg;
}

// Compute luminosity from radius and temperature using Stefan-Boltzmann law
export function luminosity(radiusM: number, tempK: number): number {
  const sigma = 5.670374419e-8;
  return 4 * Math.PI * radiusM * radiusM * sigma * Math.pow(tempK, 4);
}

// cell.ts - Cell lifecycle management with error handling

class CellCycleError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'CellCycleError';
    }
}

enum CellPhase {
    G1 = 'G1',
    S = 'S',
    G2 = 'G2',
    M = 'M'
}

class Cell {
    private phase: CellPhase;
    private dnaIntegrity: number; // 0-100%

    constructor() {
        this.phase = CellPhase.G1;
        this.dnaIntegrity = 100;
    }

    transitionToNextPhase(): void {
        try {
            switch(this.phase) {
                case CellPhase.G1:
                    this.validateDNAIntegrity(75);
                    this.phase = CellPhase.S;
                    break;
                case CellPhase.S:
                    this.phase = CellPhase.G2;
                    break;
                case CellPhase.G2:
                    this.validateDNAIntegrity(90);
                    this.phase = CellPhase.M;
                    break;
                case CellPhase.M:
                    this.phase = CellPhase.G1;
                    break;
                default:
                    throw new CellCycleError(`Unknown phase: ${this.phase}`);
            }
            console.log(`Cell transitioned to ${this.phase} phase`);
        } catch (error) {
            if (error instanceof CellCycleError) {
                console.error('Cell cycle arrested:', error.message);
                this.initiateApoptosis();
            }
            throw error;
        }
    }

    private validateDNAIntegrity(minThreshold: number): void {
        if (this.dnaIntegrity < minThreshold) {
            throw new CellCycleError(
                `DNA integrity ${this.dnaIntegrity}% below required ${minThreshold}%`
            );
        }
    }

    private initiateApoptosis(): void {
        console.log('Initiating programmed cell death');
    }
}

export { Cell, CellPhase, CellCycleError };

// gene_expression.ts - Transcription and translation simulation

class ExpressionError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'ExpressionError';
    }
}

type Nucleotide = 'A' | 'T' | 'C' | 'G';
type AminoAcid = string;

class Gene {
    private sequence: Nucleotide[];
    private promoterRegion: Nucleotide[];

    constructor(dnaSequence: string) {
        if (!/^[ATCG]+$/.test(dnaSequence)) {
            throw new ExpressionError('Invalid DNA sequence');
        }
        this.sequence = dnaSequence.split('') as Nucleotide[];
        this.promoterRegion = this.sequence.slice(0, 10);
    }

    transcribe(): string {
        try {
            this.validatePromoter();
            let mrna = '';
            const transcriptionMap: Record<Nucleotide, string> = {
                'A': 'U', 'T': 'A', 'C': 'G', 'G': 'C'
            };

            for (const nucleotide of this.sequence) {
                mrna += transcriptionMap[nucleotide];
            }

            if (mrna.length % 3 !== 0) {
                throw new ExpressionError('mRNA length not divisible by 3');
            }

            return mrna;
        } catch (error) {
            console.error('Transcription failed:', error.message);
            throw error;
        }
    }

    private validatePromoter(): void {
        const promoterSeq = this.promoterRegion.join('');
        if (!promoterSeq.includes('TATA')) {
            throw new ExpressionError('Promoter region missing TATA box');
        }
    }
}

export { Gene, ExpressionError };

// enzyme.ts - Enzyme kinetics with error handling

class EnzymeError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'EnzymeError';
    }
}

interface Substrate {
    name: string;
    concentration: number; // mM
}

class Enzyme {
    private name: string;
    private km: number; // Michaelis constant
    private vmax: number; // Maximum velocity
    private activeSiteOccupied: boolean;

    constructor(name: string, km: number, vmax: number) {
        if (km <= 0 || vmax <= 0) {
            throw new EnzymeError('KM and Vmax must be positive values');
        }
        this.name = name;
        this.km = km;
        this.vmax = vmax;
        this.activeSiteOccupied = false;
    }

    calculateReactionRate(substrate: Substrate): number {
        try {
            if (substrate.concentration < 0) {
                throw new EnzymeError('Substrate concentration cannot be negative');
            }

            if (this.activeSiteOccupied) {
                throw new EnzymeError('Active site already occupied');
            }

            // Michaelis-Menten equation
            const rate = (this.vmax * substrate.concentration) / 
                        (this.km + substrate.concentration);

            this.activeSiteOccupied = true;
            setTimeout(() => {
                this.activeSiteOccupied = false;
            }, 1000);

            return rate;
        } catch (error) {
            console.error(`Enzyme ${this.name} reaction failed:`, error.message);
            throw error;
        }
    }

    getEfficiency(substrate: Substrate): number {
        const rate = this.calculateReactionRate(substrate);
        return (rate / this.vmax) * 100;
    }
}

export { Enzyme, EnzymeError, Substrate };

// organism.ts - Basic organism classification

class TaxonomyError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'TaxonomyError';
    }
}

interface OrganismData {
    scientificName: string;
    kingdom: string;
    phylum?: string;
    class?: string;
    order?: string;
    family?: string;
    genus: string;
    species: string;
}

class Organism {
    private data: OrganismData;
    private static kingdoms = ['Animalia', 'Plantae', 'Fungi', 'Protista', 'Archaea', 'Bacteria'];

    constructor(data: OrganismData) {
        this.validateData(data);
        this.data = data;
    }

    private validateData(data: OrganismData): void {
        if (!Organism.kingdoms.includes(data.kingdom)) {
            throw new TaxonomyError(`Invalid kingdom: ${data.kingdom}`);
        }

        if (!data.scientificName.includes(data.genus) || 
            !data.scientificName.includes(data.species)) {
            throw new TaxonomyError('Scientific name must include genus and species');
        }

        const nameParts = data.scientificName.split(' ');
        if (nameParts.length !== 2) {
            throw new TaxonomyError('Scientific name must be in format "Genus species"');
        }
    }

    getClassification(): string[] {
        const classification: string[] = [];

        try {
            classification.push(`Kingdom: ${this.data.kingdom}`);
            if (this.data.phylum) classification.push(`Phylum: ${this.data.phylum}`);
            if (this.data.class) classification.push(`Class: ${this.data.class}`);
            if (this.data.order) classification.push(`Order: ${this.data.order}`);
            if (this.data.family) classification.push(`Family: ${this.data.family}`);
            classification.push(`Genus: ${this.data.genus}`);
            classification.push(`Species: ${this.data.species}`);

            return classification;
        } catch (error) {
            console.error('Classification retrieval failed:', error.message);
            return ['Classification unavailable'];
        }
    }

    getBinomialName(): string {
        return this.data.scientificName;
    }
}

export { Organism, TaxonomyError, OrganismData };

// ecosystem.ts - Simple ecosystem energy flow

class EcosystemError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'EcosystemError';
    }
}

type TrophicLevel = 'producer' | 'primary_consumer' | 'secondary_consumer' | 'decomposer';

interface Organism {
    name: string;
    trophicLevel: TrophicLevel;
    energyContent: number; // kcal
}

class FoodChain {
    private organisms: Organism[];
    private energyTransferEfficiency: number = 0.1; // 10% efficiency

    constructor() {
        this.organisms = [];
    }

    addOrganism(organism: Organism): void {
        try {
            this.validateTrophicLevel(organism);
            this.organisms.push(organism);
            console.log(`Added ${organism.name} to food chain`);
        } catch (error) {
            console.error('Failed to add organism:', error.message);
            throw error;
        }
    }

    private validateTrophicLevel(organism: Organism): void {
        const validLevels: TrophicLevel[] = ['producer', 'primary_consumer', 'secondary_consumer', 'decomposer'];
        if (!validLevels.includes(organism.trophicLevel)) {
            throw new EcosystemError(`Invalid trophic level: ${organism.trophicLevel}`);
        }
    }

    calculateEnergyTransfer(): Map<string, number> {
        const energyMap = new Map<string, number>();

        try {
            for (const organism of this.organisms) {
                let transferredEnergy = organism.energyContent;

                if (organism.trophicLevel !== 'producer') {
                    transferredEnergy *= this.energyTransferEfficiency;
                }

                if (transferredEnergy < 0) {
                    throw new EcosystemError('Negative energy calculated');
                }

                energyMap.set(organism.name, transferredEnergy);
            }

            return energyMap;
        } catch (error) {
            console.error('Energy transfer calculation failed:', error.message);
            return new Map();
        }
    }

    getEnergyPyramid(): TrophicLevel[][] {
        const pyramid: TrophicLevel[][] = [[], [], [], []];

        this.organisms.forEach(organism => {
            const index = ['producer', 'primary_consumer', 'secondary_consumer', 'decomposer']
                .indexOf(organism.trophicLevel);
            if (index !== -1) {
                pyramid[index].push(organism.trophicLevel);
            }
        });

        return pyramid;
    }
}

export { FoodChain, EcosystemError, Organism };

// dna_replication.ts - DNA replication simulation

class ReplicationError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'ReplicationError';
    }
}

class DNAPolymerase {
    private fidelity: number; // Accuracy percentage
    private speed: number; // Nucleotides per second
    private isBound: boolean;

    constructor(fidelity: number = 99.9, speed: number = 50) {
        if (fidelity < 0 || fidelity > 100) {
            throw new ReplicationError('Fidelity must be between 0-100%');
        }
        this.fidelity = fidelity;
        this.speed = speed;
        this.isBound = false;
    }

    replicate(templateStrand: string): { leadingStrand: string, laggingStrand: string } {
        try {
            if (this.isBound) {
                throw new ReplicationError('Polymerase already bound to DNA');
            }

            this.validateDNAStrand(templateStrand);
            this.isBound = true;

            const complementaryBase: Record<string, string> = {
                'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'
            };

            let leadingStrand = '';
            let laggingStrand = '';

            // Simulate leading strand synthesis (continuous)
            for (const base of templateStrand) {
                if (Math.random() * 100 > this.fidelity) {
                    throw new ReplicationError('Replication error: fidelity threshold exceeded');
                }
                leadingStrand += complementaryBase[base];
            }

            // Simulate lagging strand synthesis (Okazaki fragments)
            const fragmentSize = 1000;
            for (let i = 0; i < templateStrand.length; i += fragmentSize) {
                const fragment = templateStrand.substr(i, fragmentSize);
                let fragmentStrand = '';
                for (const base of fragment) {
                    fragmentStrand = complementaryBase[base] + fragmentStrand;
                }
                laggingStrand += fragmentStrand;
            }

            this.isBound = false;
            return { leadingStrand, laggingStrand };

        } catch (error) {
            this.isBound = false;
            console.error('DNA replication failed:', error.message);
            throw error;
        }
    }

    private validateDNAStrand(strand: string): void {
        if (!/^[ATCG]+$/.test(strand)) {
            throw new ReplicationError('Invalid DNA sequence');
        }
        if (strand.length < 10) {
            throw new ReplicationError('DNA strand too short for replication');
        }
    }

    getReplicationStats(): { fidelity: number, speed: number } {
        return { fidelity: this.fidelity, speed: this.speed };
    }
}

export { DNAPolymerase, ReplicationError };

// protein_folding.ts - Protein structure prediction

class ProteinFoldingError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'ProteinFoldingError';
    }
}

type AminoAcid = 'A' | 'R' | 'N' | 'D' | 'C' | 'E' | 'Q' | 'G' | 'H' | 'I' | 'L' | 'K' | 'M' | 'F' | 'P' | 'S' | 'T' | 'W' | 'Y' | 'V';

class Protein {
    private sequence: AminoAcid[];
    private foldedStructure: string | null;
    private stabilityScore: number;

    constructor(sequence: string) {
        this.validateSequence(sequence);
        this.sequence = sequence.split('') as AminoAcid[];
        this.foldedStructure = null;
        this.stabilityScore = 0;
    }

    fold(): void {
        try {
            if (this.foldedStructure !== null) {
                throw new ProteinFoldingError('Protein already folded');
            }

            if (this.sequence.length < 20) {
                throw new ProteinFoldingError('Sequence too short for proper folding');
            }

            // Simplified folding simulation
            const hydrophobicResidues = ['A', 'I', 'L', 'M', 'F', 'W', 'V'];
            let buriedResidues = 0;

            for (let i = 0; i < this.sequence.length; i++) {
                if (hydrophobicResidues.includes(this.sequence[i])) {
                    buriedResidues++;
                }
            }

            this.stabilityScore = (buriedResidues / this.sequence.length) * 100;

            if (this.stabilityScore < 30) {
                throw new ProteinFoldingError('Protein unstable - likely to misfold');
            }

            // Generate random 3D structure representation
            this.foldedStructure = this.generateStructure();

        } catch (error) {
            console.error('Protein folding failed:', error.message);
            throw error;
        }
    }

    private validateSequence(sequence: string): void {
        if (!/^[ARNDCEQGHILKMFPSTWYV]+$/i.test(sequence)) {
            throw new ProteinFoldingError('Invalid amino acid sequence');
        }
    }

    private generateStructure(): string {
        const structures = ['α-helix', 'β-sheet', 'random coil', 'mixed structure'];
        const structure = structures[Math.floor(Math.random() * structures.length)];
        return `${structure} with ${this.sequence.length} residues`;
    }

    getStructure(): string {
        if (!this.foldedStructure) {
            throw new ProteinFoldingError('Protein not folded yet');
        }
        return this.foldedStructure;
    }

    getStability(): number {
        return this.stabilityScore;
    }
}

export { Protein, ProteinFoldingError };

// population_genetics.ts - Hardy-Weinberg equilibrium

class GeneticsError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'GeneticsError';
    }
}

interface AlleleFrequencies {
    p: number; // Dominant allele frequency
    q: number; // Recessive allele frequency
}

class Population {
    private populationSize: number;
    private frequencies: AlleleFrequencies;

    constructor(populationSize: number, p: number, q: number) {
        if (populationSize <= 0) {
            throw new GeneticsError('Population size must be positive');
        }
        if (Math.abs(p + q - 1) > 0.0001) {
            throw new GeneticsError('Allele frequencies must sum to 1');
        }

        this.populationSize = populationSize;
        this.frequencies = { p, q };
    }

    calculateGenotypeFrequencies(): {
        AA: number, Aa: number, aa: number
    } {
        try {
            const { p, q } = this.frequencies;

            // Hardy-Weinberg equilibrium: p² + 2pq + q² = 1
            const AA = p * p;
            const Aa = 2 * p * q;
            const aa = q * q;

            const total = AA + Aa + aa;
            if (Math.abs(total - 1) > 0.0001) {
                throw new GeneticsError('Hardy-Weinberg equilibrium violated');
            }

            return { AA, Aa, aa };
        } catch (error) {
            console.error('Genotype calculation failed:', error.message);
            throw error;
        }
    }

    simulateNextGeneration(): Population {
        try {
            const { AA, Aa, aa } = this.calculateGenotypeFrequencies();

            // Calculate new allele frequencies
            const newP = AA + (Aa / 2);
            const newQ = aa + (Aa / 2);

            return new Population(this.populationSize, newP, newQ);
        } catch (error) {
            console.error('Generation simulation failed:', error.message);
            throw error;
        }
    }

    isInEquilibrium(otherPopulation: Population): boolean {
        try {
            const freqs1 = this.frequencies;
            const freqs2 = otherPopulation.frequencies;

            const diffP = Math.abs(freqs1.p - freqs2.p);
            const diffQ = Math.abs(freqs1.q - freqs2.q);

            return diffP < 0.01 && diffQ < 0.01;
        } catch (error) {
            console.error('Equilibrium check failed:', error.message);
            return false;
        }
    }

    getFrequencies(): AlleleFrequencies {
        return { ...this.frequencies };
    }
}

export { Population, GeneticsError, AlleleFrequencies };

// photosynthesis.ts - Photosynthesis simulation

class PhotosynthesisError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'PhotosynthesisError';
    }
}

interface PhotosynthesisConditions {
    lightIntensity: number; // μmol photons/m²/s
    co2Concentration: number; // ppm
    temperature: number; // Celsius
    waterAvailability: number; // 0-100%
}

class Chloroplast {
    private chlorophyllContent: number; // mg/m²
    private conditions: PhotosynthesisConditions;

    constructor(chlorophyllContent: number, conditions: PhotosynthesisConditions) {
        if (chlorophyllContent <= 0) {
            throw new PhotosynthesisError('Chlorophyll content must be positive');
        }
        this.chlorophyllContent = chlorophyllContent;
        this.conditions = conditions;
    }

    calculatePhotosynthesisRate(): number {
        try {
            this.validateConditions();

            // Simplified photosynthesis model
            let rate = this.conditions.lightIntensity * 0.8;
            rate *= (this.conditions.co2Concentration / 400);
            rate *= (this.chlorophyllContent / 50);

            // Temperature effect (optimal ~25°C)
            const tempEffect = Math.exp(-Math.pow(this.conditions.temperature - 25, 2) / 200);
            rate *= tempEffect;

            // Water availability effect
            rate *= (this.conditions.waterAvailability / 100);

            if (rate < 0) {
                throw new PhotosynthesisError('Negative photosynthesis rate calculated');
            }

            return rate;
        } catch (error) {
            console.error('Photosynthesis calculation failed:', error.message);
            throw error;
        }
    }

    private validateConditions(): void {
        if (this.conditions.lightIntensity < 0) {
            throw new PhotosynthesisError('Light intensity cannot be negative');
        }
        if (this.conditions.co2Concentration < 0) {
            throw new PhotosynthesisError('CO2 concentration cannot be negative');
        }
        if (this.conditions.waterAvailability < 0 || this.conditions.waterAvailability > 100) {
            throw new PhotosynthesisError('Water availability must be between 0-100%');
        }
    }

    simulateDayCycle(hours: number): number[] {
        try {
            if (hours <= 0 || hours > 24) {
                throw new PhotosynthesisError('Invalid number of hours');
            }

            const rates: number[] = [];
            for (let hour = 0; hour < hours; hour++) {
                // Simulate diurnal light variation
                const lightIntensity = this.calculateLightIntensity(hour);
                this.conditions.lightIntensity = lightIntensity;
                rates.push(this.calculatePhotosynthesisRate());
            }

            return rates;
        } catch (error) {
            console.error('Day cycle simulation failed:', error.message);
            return [];
        }
    }

    private calculateLightIntensity(hour: number): number {
        // Simplified sinusoidal light pattern
        return Math.max(0, 1000 * Math.sin((hour * Math.PI) / 12));
    }
}

export { Chloroplast, PhotosynthesisError, PhotosynthesisConditions };

// immune_response.ts - Basic immune system simulation

class ImmuneError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'ImmuneError';
    }
}

interface Pathogen {
    type: 'virus' | 'bacteria' | 'fungus' | 'parasite';
    virulence: number; // 0-100
    antigen: string;
}

interface Antibody {
    antigenSpecificity: string;
    affinity: number; // 0-100
    concentration: number;
}

class ImmuneSystem {
    private antibodies: Antibody[];
    private memoryCells: Set<string>;
    private healthStatus: number; // 0-100

    constructor() {
        this.antibodies = [];
        this.memoryCells = new Set();
        this.healthStatus = 100;
    }

    encounterPathogen(pathogen: Pathogen): void {
        try {
            this.validatePathogen(pathogen);

            if (this.memoryCells.has(pathogen.antigen)) {
                console.log(`Memory response activated for ${pathogen.type}`);
                this.mountSecondaryResponse(pathogen);
            } else {
                console.log(`Primary response initiated for ${pathogen.type}`);
                this.mountPrimaryResponse(pathogen);
            }

            this.healthStatus -= pathogen.virulence / 10;
            if (this.healthStatus < 0) this.healthStatus = 0;

        } catch (error) {
            console.error('Immune response failed:', error.message);
            throw error;
        }
    }

    private validatePathogen(pathogen: Pathogen): void {
        if (pathogen.virulence < 0 || pathogen.virulence > 100) {
            throw new ImmuneError('Virulence must be between 0-100');
        }
        if (!['virus', 'bacteria', 'fungus', 'parasite'].includes(pathogen.type)) {
            throw new ImmuneError('Invalid pathogen type');
        }
    }

    private mountPrimaryResponse(pathogen: Pathogen): void {
        // Simulate antibody production
        const antibody: Antibody = {
            antigenSpecificity: pathogen.antigen,
            affinity: 50 + Math.random() * 30, // Initial moderate affinity
            concentration: 10
        };

        this.antibodies.push(antibody);
        this.memoryCells.add(pathogen.antigen);

        console.log(`Primary antibody produced for antigen: ${pathogen.antigen}`);
    }

    private mountSecondaryResponse(pathogen: Pathogen): void {
        const antibody = this.antibodies.find(ab => ab.antigenSpecificity === pathogen.antigen);
        if (antibody) {
            antibody.concentration *= 2; // Faster, stronger response
            antibody.affinity += 10; // Increased affinity
            console.log(`Secondary response boosted antibody concentration`);
        }
    }

    getAntibodyLevels(): Map<string, number> {
        const levels = new Map<string, number>();
        this.antibodies.forEach(ab => {
            levels.set(ab.antigenSpecificity, ab.concentration);
        });
        return levels;
    }

    getHealthStatus(): number {
        return this.healthStatus;
    }
}

export { ImmuneSystem, ImmuneError, Pathogen, Antibody };

// neural_network.ts - Simple neuron and synapse model

class NeuralError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'NeuralError';
    }
}

class Neuron {
    private membranePotential: number; // mV
    private threshold: number; // mV
    private restingPotential: number; // mV
    private synapses: Synapse[];
    private refractoryPeriod: boolean;

    constructor(threshold: number = -55, restingPotential: number = -70) {
        if (threshold >= restingPotential) {
            throw new NeuralError('Threshold must be more negative than resting potential');
        }
        this.threshold = threshold;
        this.restingPotential = restingPotential;
        this.membranePotential = restingPotential;
        this.synapses = [];
        this.refractoryPeriod = false;
    }

    addSynapse(synapse: Synapse): void {
        this.synapses.push(synapse);
    }

    receiveInput(voltage: number): void {
        try {
            if (this.refractoryPeriod) {
                throw new NeuralError('Neuron in refractory period');
            }

            this.membranePotential += voltage;

            if (this.membranePotential >= this.threshold) {
                this.fireActionPotential();
            }

            // Leakage
            this.membranePotential += (this.restingPotential - this.membranePotential) * 0.1;

        } catch (error) {
            console.error('Neuron input processing failed:', error.message);
            throw error;
        }
    }

    private fireActionPotential(): void {
        console.log('Action potential fired!');
        this.membranePotential = 30; // Peak potential

        // Refractory period
        this.refractoryPeriod = true;
        setTimeout(() => {
            this.membranePotential = this.restingPotential;
            this.refractoryPeriod = false;
        }, 2); // 2ms refractory period simulation

        // Transmit to synapses
        this.synapses.forEach(synapse => {
            synapse.transmit(50); // Standard action potential magnitude
        });
    }

    getPotential(): number {
        return this.membranePotential;
    }

    isRefractory(): boolean {
        return this.refractoryPeriod;
    }
}

class Synapse {
    private neurotransmitterAmount: number;
    private receptorSensitivity: number;

    constructor(neurotransmitterAmount: number = 10, receptorSensitivity: number = 1) {
        if (neurotransmitterAmount <= 0) {
            throw new NeuralError('Neurotransmitter amount must be positive');
        }
        this.neurotransmitterAmount = neurotransmitterAmount;
        this.receptorSensitivity = receptorSensitivity;
    }

    transmit(actionPotential: number): number {
        try {
            if (actionPotential < 0) {
                throw new NeuralError('Action potential cannot be negative');
            }

            // Simplified transmission calculation
            const transmittedVoltage = actionPotential * 
                                    this.neurotransmitterAmount * 
                                    this.receptorSensitivity * 0.01;

            return transmittedVoltage;
        } catch (error) {
            console.error('Synaptic transmission failed:', error.message);
            throw error;
        }
    }
}

export { Neuron, Synapse, NeuralError };

