export function getElement(symbol: ElementSymbol): ElementData {
  return PERIODIC_TABLE[symbol];
}

export function getAverageAtomicMass(symbols: readonly ElementSymbol[]): number {
  if (symbols.length === 0) {
    throw new Error('Expected at least one element symbol.');
  }

  const total = symbols.reduce((sum, symbol) => sum + getElement(symbol).atomicMass, 0);
  return total / symbols.length;
}

export function listByCategory(category: ElementData['category']): ElementData[] {
  return Object.values(PERIODIC_TABLE)
    .filter((element) => element.category === category)
    .sort((a, b) => a.atomicNumber - b.atomicNumber);
}

export function describeElement(symbol: ElementSymbol): string {
  const element = getElement(symbol);
  const parts = [
    `${element.name} (${element.symbol})`,
    `atomic number ${element.atomicNumber}`,
    `atomic mass ${element.atomicMass}`,
    `period ${element.period}`,
    element.group ? `group ${element.group}` : 'no standard group'
  ];

  return parts.join(', ');
}

export function isLikelyReactiveNonmetal(symbol: ElementSymbol): boolean {
  const element = getElement(symbol);
  return element.category === 'halogen' || (element.category === 'nonmetal' && element.group !== 18);
}

export function summarizeTable(): string[] {
  return Object.keys(PERIODIC_TABLE)
    .map((symbol) => describeElement(symbol as ElementSymbol));
}

export function validateAtomicNumbers(): boolean {
  const seen = new Set<number>();

  for (const element of Object.values(PERIODIC_TABLE)) {
    if (seen.has(element.atomicNumber)) {
      return false;
    }
    seen.add(element.atomicNumber);
  }

  return true;
}

