export type AtomCountMap = Readonly<Record<string, number>>;

export interface Compound {
  formula: string;
  composition: AtomCountMap;
  molarMass: number;
  commonName?: string;
}

const ATOMIC_MASSES: Readonly<Record<string, number>> = {
  H: 1.008,
  C: 12.011,
  N: 14.007,
  O: 15.999,
  Na: 22.99,
  Mg: 24.305,
  Al: 26.982,
  Si: 28.085,
  P: 30.974,
  S: 32.06,
  Cl: 35.45,
  K: 39.098,
  Ca: 40.078,
  Fe: 55.845,
  Cu: 63.546
} as const;

export function computeMolarMass(composition: AtomCountMap): number {
  let total = 0;

  for (const [symbol, count] of Object.entries(composition)) {
    const mass = ATOMIC_MASSES[symbol];
    if (mass === undefined) {
      throw new Error(`Unknown atomic mass for element: ${symbol}`);
    }
    if (!Number.isFinite(count) || count <= 0) {
      throw new Error(`Invalid atom count for ${symbol}: ${count}`);
    }
    total += mass * count;
  }

  return total;
}

export function createCompound(
  formula: string,
  composition: AtomCountMap,
  commonName?: string
): Compound {
  return {
    formula,
    composition,
    molarMass: computeMolarMass(composition),
    commonName
  };
}

export const COMMON_COMPOUNDS: readonly Compound[] = [
  createCompound('H2O', { H: 2, O: 1 }, 'water'),
  createCompound('CO2', { C: 1, O: 2 }, 'carbon dioxide'),
  createCompound('NH3', { N: 1, H: 3 }, 'ammonia'),
  createCompound('NaCl', { Na: 1, Cl: 1 }, 'sodium chloride'),
  createCompound('H2SO4', { H: 2, S: 1, O: 4 }, 'sulfuric acid'),
  createCompound('CaCO3', { Ca: 1, C: 1, O: 3 }, 'calcium carbonate')
] as const;

export function formatComposition(composition: AtomCountMap): string {
  return Object.entries(composition)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([symbol, count]) => `${symbol}:${count}`)
    .join(', ');
}

export function compareByMolarMass(a: Compound, b: Compound): number {
  return a.molarMass - b.molarMass;
}

export function findCompoundByFormula(formula: string): Compound | undefined {
  return COMMON_COMPOUNDS.find((compound) => compound.formula === formula);
}

export function compoundsContaining(elementSymbol: string): Compound[] {
  return COMMON_COMPOUNDS.filter((compound) => compound.composition[elementSymbol] !== undefined);
}

export function percentComposition(compound: Compound): Record<string, number> {
  const result: Record<string, number> = {};

  for (const [symbol, count] of Object.entries(compound.composition)) {
    const subtotal = ATOMIC_MASSES[symbol] * count;
    result[symbol] = (subtotal / compound.molarMass) * 100;
  }

  return result;
}

export function describeCompound(compound: Compound): string {
  const identity = compound.commonName ? `${compound.commonName} (${compound.formula})` : compound.formula;
  return `${identity} has molar mass ${compound.molarMass.toFixed(3)} g/mol and composition ${formatComposition(compound.composition)}.`;
}

export function rankCompounds(): Compound[] {
  return [...COMMON_COMPOUNDS].sort(compareByMolarMass);
}

export function demo(): void {
  for (const compound of rankCompounds()) {
    console.log(describeCompound(compound));
    console.log(percentComposition(compound));
  }

  const salt = findCompoundByFormula('NaCl');
  if (salt) {
    console.log(`Found compound: ${salt.commonName}`);
  }

