export interface SolutionSample {
  soluteMoles: number;
  solutionVolumeLiters: number;
  temperatureCelsius?: number;
  label?: string;
}

export interface ConcentrationResult {
  molarity: number;
  valid: boolean;
  warnings: string[];
}

export function validateSample(sample: SolutionSample): string[] {
  const warnings: string[] = [];

  if (!Number.isFinite(sample.soluteMoles) || sample.soluteMoles < 0) {
    warnings.push('Solute moles should be a finite non-negative number.');
  }

  if (!Number.isFinite(sample.solutionVolumeLiters) || sample.solutionVolumeLiters <= 0) {
    warnings.push('Solution volume must be a finite number greater than zero liters.');
  }

  if (sample.temperatureCelsius !== undefined && !Number.isFinite(sample.temperatureCelsius)) {
    warnings.push('Temperature should be finite when provided.');
  }

  return warnings;
}

export function calculateMolarity(sample: SolutionSample): ConcentrationResult {
  const warnings = validateSample(sample);
  const valid = warnings.length === 0;

  if (!valid) {
    return {
      molarity: Number.NaN,
      valid,
      warnings
    };
  }

  return {
    molarity: sample.soluteMoles / sample.solutionVolumeLiters,
    valid,
    warnings
  };
}

export function dilute(
  initialMolarity: number,
  initialVolumeLiters: number,
  finalVolumeLiters: number
): number {
  if (initialMolarity < 0 || initialVolumeLiters <= 0 || finalVolumeLiters <= 0) {
    throw new Error('Volumes must be positive and molarity must be non-negative.');
  }

  return (initialMolarity * initialVolumeLiters) / finalVolumeLiters;
}

export function requiredDilutionVolume(
  initialMolarity: number,
  targetMolarity: number,
  targetVolumeLiters: number
): number {
  if (initialMolarity <= 0 || targetMolarity <= 0 || targetVolumeLiters <= 0) {
    throw new Error('All concentration and volume inputs must be greater than zero.');
  }

  if (targetMolarity > initialMolarity) {
    throw new Error('Target molarity cannot exceed the initial molarity in a simple dilution.');
  }

  return (targetMolarity * targetVolumeLiters) / initialMolarity;
}

export function formatConcentration(result: ConcentrationResult): string {
  if (!result.valid) {
    return `Invalid concentration result: ${result.warnings.join(' | ')}`;
  }

  return `${result.molarity.toFixed(4)} mol/L`;
}

export const EXAMPLE_SAMPLES: readonly SolutionSample[] = [
  { soluteMoles: 0.5, solutionVolumeLiters: 1.0, temperatureCelsius: 25, label: 'NaCl stock' },
  { soluteMoles: 0.125, solutionVolumeLiters: 0.25, temperatureCelsius: 20, label: 'HCl standard' },
  { soluteMoles: 0.01, solutionVolumeLiters: 0.1, label: 'trace analyte' },
  { soluteMoles: -1, solutionVolumeLiters: 1, label: 'invalid sample' }
] as const;

export function summarizeSamples(samples: readonly SolutionSample[]): string[] {
  return samples.map((sample) => {
    const result = calculateMolarity(sample);
    const label = sample.label ?? 'unnamed sample';
    return `${label}: ${formatConcentration(result)}`;
  });
}

export function averageMolarity(samples: readonly SolutionSample[]): number {
  const validResults = samples
    .map(calculateMolarity)
    .filter((result) => result.valid);

  if (validResults.length === 0) {
    throw new Error('No valid samples available for averaging.');
  }

  const total = validResults.reduce((sum, result) => sum + result.molarity, 0);
  return total / validResults.length;
}

export function demo(): void {
  for (const line of summarizeSamples(EXAMPLE_SAMPLES)) {
    console.log(line);
  }

  const stockMolarity = calculateMolarity(EXAMPLE_SAMPLES[0]).molarity;
  const diluted = dilute(stockMolarity, 0.1, 0.5);
  const aliquot = requiredDilutionVolume(stockMolarity, 0.05, 1.0);

  console.log(`Diluted concentration: ${diluted.toFixed(4)} mol/L`);
  console.log(`Aliquot needed for target dilution: ${aliquot.toFixed(4)} L`);
  console.log(`Average valid molarity: ${averageMolarity(EXAMPLE_SAMPLES).toFixed(4)} mol/L`);
}

export interface GasSample {
  pressureAtm: number;
  volumeLiters: number;
  temperatureKelvin: number;
  moles?: number;
}

export const IDEAL_GAS_CONSTANT_L_ATM = 0.082057 as const;

export function validateGasSample(sample: GasSample): void {
  if (sample.pressureAtm <= 0 || !Number.isFinite(sample.pressureAtm)) {
    throw new Error('Pressure must be a positive finite value in atm.');
  }
  if (sample.volumeLiters <= 0 || !Number.isFinite(sample.volumeLiters)) {
    throw new Error('Volume must be a positive finite value in liters.');
  }
  if (sample.temperatureKelvin <= 0 || !Number.isFinite(sample.temperatureKelvin)) {
    throw new Error('Temperature must be a positive finite value in kelvin.');
  }
  if (sample.moles !== undefined && (sample.moles <= 0 || !Number.isFinite(sample.moles))) {
    throw new Error('Moles must be positive and finite when provided.');
  }
}

export function solveForMoles(sample: Omit<GasSample, 'moles'>): number {
  validateGasSample(sample);
  return (sample.pressureAtm * sample.volumeLiters) / (IDEAL_GAS_CONSTANT_L_ATM * sample.temperatureKelvin);
}

export function solveForPressure(volumeLiters: number, moles: number, temperatureKelvin: number): number {
  if (volumeLiters <= 0 || moles <= 0 || temperatureKelvin <= 0) {
    throw new Error('All values must be positive.');
  }
  return (moles * IDEAL_GAS_CONSTANT_L_ATM * temperatureKelvin) / volumeLiters;
}

export function solveForVolume(pressureAtm: number, moles: number, temperatureKelvin: number): number {
  if (pressureAtm <= 0 || moles <= 0 || temperatureKelvin <= 0) {
    throw new Error('All values must be positive.');
  }
  return (moles * IDEAL_GAS_CONSTANT_L_ATM * temperatureKelvin) / pressureAtm;
}

export function solveForTemperature(pressureAtm: number, volumeLiters: number, moles: number): number {
  if (pressureAtm <= 0 || volumeLiters <= 0 || moles <= 0) {
    throw new Error('All values must be positive.');
  }
  return (pressureAtm * volumeLiters) / (moles * IDEAL_GAS_CONSTANT_L_ATM);
}

export interface GasLawScenario {
  name: string;
  sample: Omit<GasSample, 'moles'>;
}

export const SCENARIOS: readonly GasLawScenario[] = [
  { name: 'standard sample', sample: { pressureAtm: 1, volumeLiters: 22.414, temperatureKelvin: 273.15 } },
