export function describeScenario(scenario: GasLawScenario): string {
  const moles = solveForMoles(scenario.sample);
  return `${scenario.name}: ${moles.toFixed(4)} mol at ${scenario.sample.pressureAtm} atm, ${scenario.sample.volumeLiters} L, ${scenario.sample.temperatureKelvin} K.`;
