export function comparePressures(moles: number, temperatureKelvin: number, volumes: readonly number[]): number[] {
  return volumes.map((volume) => solveForPressure(volume, moles, temperatureKelvin));
}

export function estimateExpansion(
  initialPressureAtm: number,
  initialVolumeLiters: number,
  finalPressureAtm: number
): number {
  if (initialPressureAtm <= 0 || initialVolumeLiters <= 0 || finalPressureAtm <= 0) {
    throw new Error('Pressure and volume must be positive.');
  }

  return (initialPressureAtm * initialVolumeLiters) / finalPressureAtm;
}

