export type Phase = 'solid' | 'liquid' | 'gas' | 'aqueous';

export interface SubstanceState {
  name: string;
  formula: string;
  phase: Phase;
}

export interface ReactionParticipant extends SubstanceState {
  coefficient: number;
}

export interface Reaction {
  reactants: readonly ReactionParticipant[];
  products: readonly ReactionParticipant[];
  reversible?: boolean;
  notes?: string;
}

export function formatParticipant(participant: ReactionParticipant): string {
  const coefficientPrefix = participant.coefficient === 1 ? '' : `${participant.coefficient}`;
  const phaseSuffix = `(${participant.phase.charAt(0)})`;
  return `${coefficientPrefix}${participant.formula}${phaseSuffix}`;
}

export function formatReaction(reaction: Reaction): string {
  const left = reaction.reactants.map(formatParticipant).join(' + ');
  const right = reaction.products.map(formatParticipant).join(' + ');
  const arrow = reaction.reversible ? '⇌' : '→';
  return `${left} ${arrow} ${right}`;
}

export function totalCoefficients(side: readonly ReactionParticipant[]): number {
  return side.reduce((sum, participant) => sum + participant.coefficient, 0);
}

export function countSpecies(reaction: Reaction): number {
  return reaction.reactants.length + reaction.products.length;
}

export function listPhases(reaction: Reaction): Phase[] {
  const phases = new Set<Phase>();

  for (const participant of [...reaction.reactants, ...reaction.products]) {
    phases.add(participant.phase);
  }

  return [...phases];
}

export const REACTION_LIBRARY: readonly Reaction[] = [
  {
    reactants: [
      { name: 'hydrogen', formula: 'H2', phase: 'gas', coefficient: 2 },
      { name: 'oxygen', formula: 'O2', phase: 'gas', coefficient: 1 }
