] as const;

export function describeReaction(reaction: Reaction): string {
  const formatted = formatReaction(reaction);
  const species = countSpecies(reaction);
  const phases = listPhases(reaction).join(', ');
  return `${formatted} | species: ${species} | phases: ${phases}${reaction.notes ? ` | ${reaction.notes}` : ''}`;
}

export function reactionsWithGasProduct(): Reaction[] {
  return REACTION_LIBRARY.filter((reaction) => reaction.products.some((product) => product.phase === 'gas'));
}

export function coefficientRatio(reaction: Reaction): string {
  const reactantTotal = totalCoefficients(reaction.reactants);
  const productTotal = totalCoefficients(reaction.products);
  return `${reactantTotal}:${productTotal}`;
}

export function demo(): void {
