export interface TitrationInput {
  analyteVolumeLiters: number;
  titrantMolarity: number;
  equivalenceVolumeLiters: number;
  analyteToTitrantRatio: number;
  label?: string;
}

export interface TitrationResult {
  analyteMoles: number;
  analyteMolarity: number;
}

export function validateTitrationInput(input: TitrationInput): void {
  const values = [
    input.analyteVolumeLiters,
    input.titrantMolarity,
    input.equivalenceVolumeLiters,
    input.analyteToTitrantRatio
  ];

  if (values.some((value) => !Number.isFinite(value) || value <= 0)) {
    throw new Error('All titration input values must be positive finite numbers.');
  }
}

export function analyzeTitration(input: TitrationInput): TitrationResult {
  validateTitrationInput(input);

  const titrantMoles = input.titrantMolarity * input.equivalenceVolumeLiters;
  const analyteMoles = titrantMoles * input.analyteToTitrantRatio;
  const analyteMolarity = analyteMoles / input.analyteVolumeLiters;

  return {
    analyteMoles,
    analyteMolarity
  };
}

export const TITRATION_CASES: readonly TitrationInput[] = [
  {
    label: 'HCl with NaOH',
    analyteVolumeLiters: 0.025,
    titrantMolarity: 0.1,
    equivalenceVolumeLiters: 0.020,
    analyteToTitrantRatio: 1
  },
  {
    label: 'H2SO4 with NaOH',
    analyteVolumeLiters: 0.01,
    titrantMolarity: 0.2,
    equivalenceVolumeLiters: 0.015,
    analyteToTitrantRatio: 0.5
  },
  {
    label: 'Acetic acid with NaOH',
    analyteVolumeLiters: 0.05,
    titrantMolarity: 0.1,
    equivalenceVolumeLiters: 0.018,
    analyteToTitrantRatio: 1
  }
] as const;

export function formatTitrationReport(input: TitrationInput): string {
  const result = analyzeTitration(input);
  const label = input.label ?? 'unnamed titration';
  return `${label}: analyte moles = ${result.analyteMoles.toFixed(6)} mol, analyte molarity = ${result.analyteMolarity.toFixed(4)} mol/L`;
}

export function averageAnalyteMolarity(inputs: readonly TitrationInput[]): number {
  if (inputs.length === 0) {
    throw new Error('At least one titration case is required.');
  }

  const total = inputs.reduce((sum, input) => sum + analyzeTitration(input).analyteMolarity, 0);
  return total / inputs.length;
}

export function strongestAnalyte(inputs: readonly TitrationInput[]): TitrationInput {
  if (inputs.length === 0) {
    throw new Error('At least one titration case is required.');
  }

  return [...inputs].sort(
    (a, b) => analyzeTitration(b).analyteMolarity - analyzeTitration(a).analyteMolarity
  )[0];
}

export function demo(): void {
  for (const input of TITRATION_CASES) {
    console.log(formatTitrationReport(input));
  }

  console.log(`Average analyte molarity: ${averageAnalyteMolarity(TITRATION_CASES).toFixed(4)} mol/L`);
  console.log(`Highest concentration case: ${strongestAnalyte(TITRATION_CASES).label}`);
}

export interface BufferComponent {
  name: string;
  concentration: number;
}

export interface BufferSystem {
  acid: BufferComponent;
  base: BufferComponent;
  pKa: number;
  label?: string;
}

export interface BufferReport {
  pH: number;
  ratio: number;
  classification: 'acidic' | 'basic' | 'neutral-ish';
}

export function validateBufferSystem(system: BufferSystem): void {
  if (system.acid.concentration <= 0 || system.base.concentration <= 0) {
    throw new Error('Acid and base concentrations must be positive.');
  }
  if (!Number.isFinite(system.pKa)) {
    throw new Error('pKa must be finite.');
  }
}

export function calculateBufferPH(system: BufferSystem): BufferReport {
  validateBufferSystem(system);

  const ratio = system.base.concentration / system.acid.concentration;
  const pH = system.pKa + Math.log10(ratio);

  let classification: BufferReport['classification'];
  if (pH < 6.5) {
    classification = 'acidic';
  } else if (pH > 7.5) {
    classification = 'basic';
  } else {
    classification = 'neutral-ish';
  }

  return { pH, ratio, classification };
}

export const BUFFERS: readonly BufferSystem[] = [
  {
    label: 'Acetate buffer',
    acid: { name: 'acetic acid', concentration: 0.2 },
    base: { name: 'acetate', concentration: 0.1 },
    pKa: 4.76
  },
  {
    label: 'Phosphate buffer',
    acid: { name: 'dihydrogen phosphate', concentration: 0.05 },
    base: { name: 'hydrogen phosphate', concentration: 0.08 },
    pKa: 7.21
  },
  {
    label: 'Ammonium buffer',
    acid: { name: 'ammonium', concentration: 0.15 },
    base: { name: 'ammonia', concentration: 0.3 },
    pKa: 9.25
  }
] as const;

export function describeBuffer(system: BufferSystem): string {
  const report = calculateBufferPH(system);
  return `${system.label ?? 'buffer'}: pH ${report.pH.toFixed(2)}, base/acid ratio ${report.ratio.toFixed(2)}, ${report.classification}`;
}

export function sortBuffersByPH(systems: readonly BufferSystem[]): BufferSystem[] {
  return [...systems].sort((a, b) => calculateBufferPH(a).pH - calculateBufferPH(b).pH);
}

export function nearestToNeutral(systems: readonly BufferSystem[]): BufferSystem {
  if (systems.length === 0) {
    throw new Error('Expected at least one buffer system.');
  }

  return [...systems].sort(
    (a, b) => Math.abs(calculateBufferPH(a).pH - 7) - Math.abs(calculateBufferPH(b).pH - 7)
  )[0];
}

export function adjustBaseConcentration(system: BufferSystem, multiplier: number): BufferSystem {
  if (multiplier <= 0 || !Number.isFinite(multiplier)) {
    throw new Error('Multiplier must be positive and finite.');
  }

  return {
    ...system,
    base: {
      ...system.base,
      concentration: system.base.concentration * multiplier
    }
  };
}

export function demo(): void {
  for (const buffer of sortBuffersByPH(BUFFERS)) {
    console.log(describeBuffer(buffer));
  }

  const tuned = adjustBaseConcentration(BUFFERS[0], 2);
  console.log(`Adjusted system: ${describeBuffer(tuned)}`);
  console.log(`Closest to neutral: ${nearestToNeutral(BUFFERS).label}`);
}

export interface ThermoState {
  enthalpyKJ: number;
  entropyJK: number;
  temperatureK: number;
}

export interface GibbsResult {
  deltaGkJ: number;
  spontaneous: boolean;
}

export function validateThermoState(state: ThermoState): void {
  if (!Number.isFinite(state.enthalpyKJ)) {
    throw new Error('Enthalpy must be finite.');
  }
  if (!Number.isFinite(state.entropyJK)) {
    throw new Error('Entropy must be finite.');
  }
  if (!Number.isFinite(state.temperatureK) || state.temperatureK <= 0) {
    throw new Error('Temperature must be a positive finite value in kelvin.');
  }
}

export function calculateGibbsFreeEnergy(state: ThermoState): GibbsResult {
  validateThermoState(state);

  const entropyKJK = state.entropyJK / 1000;
  const deltaGkJ = state.enthalpyKJ - state.temperatureK * entropyKJK;

  return {
    deltaGkJ,
    spontaneous: deltaGkJ < 0
  };
}

export interface ThermoCase {
  name: string;
  state: ThermoState;
}

export const THERMO_CASES: readonly ThermoCase[] = [
  { name: 'Case A', state: { enthalpyKJ: -40, entropyJK: -50, temperatureK: 298.15 } },
  { name: 'Case B', state: { enthalpyKJ: 25, entropyJK: 120, temperatureK: 350 } },
  { name: 'Case C', state: { enthalpyKJ: -10, entropyJK: 80, temperatureK: 400 } }
] as const;

export function describeThermoCase(item: ThermoCase): string {
  const result = calculateGibbsFreeEnergy(item.state);
  return `${item.name}: ΔG = ${result.deltaGkJ.toFixed(3)} kJ/mol, spontaneous = ${result.spontaneous}`;
}

export function transitionTemperature(enthalpyKJ: number, entropyJK: number): number {
  if (entropyJK === 0) {
    throw new Error('Entropy change cannot be zero when calculating transition temperature.');
  }
  return enthalpyKJ / (entropyJK / 1000);
}

export function rankBySpontaneity(cases: readonly ThermoCase[]): ThermoCase[] {
  return [...cases].sort(
    (a, b) => calculateGibbsFreeEnergy(a.state).deltaGkJ - calculateGibbsFreeEnergy(b.state).deltaGkJ
  );
}

export function countSpontaneous(cases: readonly ThermoCase[]): number {
  return cases.filter((item) => calculateGibbsFreeEnergy(item.state).spontaneous).length;
}

export function demo(): void {
  for (const item of rankBySpontaneity(THERMO_CASES)) {
    console.log(describeThermoCase(item));
  }

  console.log(`Spontaneous cases: ${countSpontaneous(THERMO_CASES)}`);
  console.log(`Transition temperature example: ${transitionTemperature(20, 100).toFixed(2)} K`);
}

export interface RateExperiment {
  reactant: string;
  concentrationM: number;
  observedRate: number;
}

export interface RateLawResult {
  rateConstant: number;
  order: number;
}

export function validateExperiment(experiment: RateExperiment): void {
  if (experiment.concentrationM <= 0 || !Number.isFinite(experiment.concentrationM)) {
    throw new Error('Concentration must be a positive finite value.');
  }
  if (experiment.observedRate <= 0 || !Number.isFinite(experiment.observedRate)) {
    throw new Error('Observed rate must be a positive finite value.');
  }
}

export function inferOrder(exp1: RateExperiment, exp2: RateExperiment): number {
  validateExperiment(exp1);
  validateExperiment(exp2);

  const concentrationRatio = exp2.concentrationM / exp1.concentrationM;
  const rateRatio = exp2.observedRate / exp1.observedRate;

  return Math.log(rateRatio) / Math.log(concentrationRatio);
}

export function calculateRateConstant(experiment: RateExperiment, order: number): number {
  validateExperiment(experiment);
  return experiment.observedRate / Math.pow(experiment.concentrationM, order);
}

export const EXPERIMENTS: readonly RateExperiment[] = [
  { reactant: 'A', concentrationM: 0.1, observedRate: 0.02 },
  { reactant: 'A', concentrationM: 0.2, observedRate: 0.08 },
  { reactant: 'A', concentrationM: 0.4, observedRate: 0.32 }
] as const;

export function analyzeRateLaw(experiments: readonly RateExperiment[]): RateLawResult {
  if (experiments.length < 2) {
    throw new Error('At least two experiments are required to infer reaction order.');
  }

  const order = inferOrder(experiments[0], experiments[1]);
  const rateConstant = calculateRateConstant(experiments[0], order);

  return { rateConstant, order };
}

export function predictedRate(concentrationM: number, result: RateLawResult): number {
  if (concentrationM <= 0 || !Number.isFinite(concentrationM)) {
    throw new Error('Concentration must be positive and finite.');
  }
  return result.rateConstant * Math.pow(concentrationM, result.order);
}

export function summarizeExperiments(experiments: readonly RateExperiment[]): string[] {
  const analysis = analyzeRateLaw(experiments);

  return experiments.map((experiment) => {
    const predicted = predictedRate(experiment.concentrationM, analysis);
    return `${experiment.reactant} at ${experiment.concentrationM.toFixed(3)} M: observed ${experiment.observedRate.toFixed(4)}, predicted ${predicted.toFixed(4)}`;
  });
}

export function demo(): void {
  const analysis = analyzeRateLaw(EXPERIMENTS);
  console.log(`Inferred order: ${analysis.order.toFixed(2)}`);
  console.log(`Rate constant: ${analysis.rateConstant.toFixed(4)}`);

  for (const line of summarizeExperiments(EXPERIMENTS)) {
    console.log(line);
  }

  console.log(`Predicted rate at 0.300 M: ${predictedRate(0.3, analysis).toFixed(4)}`);
}

