  }
] as const;

export function getRulesBySeverity(severity: LabSafetyRule['severity']): LabSafetyRule[] {
  return LAB_SAFETY_RULES.filter((rule) => rule.severity === severity);
}

export function searchRulesByTag(tag: string): LabSafetyRule[] {
  const normalized = tag.trim().toLowerCase();
  return LAB_SAFETY_RULES.filter((rule) => rule.tags.some((entry) => entry.toLowerCase() === normalized));
}

export function formatRule(rule: LabSafetyRule): string {
  return `[${rule.severity.toUpperCase()}] ${rule.id} ${rule.title}: ${rule.description}`;
}

export function summarizeSafetyPosture(): Record<LabSafetyRule['severity'], number> {
  return {
    info: getRulesBySeverity('info').length,
    warning: getRulesBySeverity('warning').length,
    critical: getRulesBySeverity('critical').length
  };
}

export function assertCriticalCoverage(requiredTags: readonly string[]): boolean {
  const criticalRules = getRulesBySeverity('critical');
  return requiredTags.every((tag) => criticalRules.some((rule) => rule.tags.includes(tag)));
}

export function demo(): void {
  for (const rule of LAB_SAFETY_RULES) {
    console.log(formatRule(rule));
  }

  console.log('Rule counts:', summarizeSafetyPosture());
  console.log('Ventilation-tagged rules:', searchRulesByTag('ventilation').map((rule) => rule.id).join(', '));
  console.log('Critical coverage ok:', assertCriticalCoverage(['ppe', 'ventilation']));
}

