"""
DNA Sequence Validator with Error Handling
Validates DNA sequences and calculates GC content
"""

import sys

def validate_dna_sequence(sequence: str) -> bool:
    """Validate if string contains only valid DNA nucleotides."""
    valid_nucleotides = {'A', 'T', 'C', 'G'}
    try:
        if not sequence:
            raise ValueError("Sequence cannot be empty")

        sequence_upper = sequence.upper().strip()

        for char in sequence_upper:
            if char not in valid_nucleotides:
                raise ValueError(f"Invalid nucleotide '{char}' found. Only A, T, C, G allowed.")

        return True
    except Exception as e:
        print(f"Validation error: {e}", file=sys.stderr)
        return False

def calculate_gc_content(sequence: str) -> float:
    """Calculate GC content percentage of DNA sequence."""
    try:
        if not validate_dna_sequence(sequence):
            raise ValueError("Invalid DNA sequence")

        sequence_upper = sequence.upper()
        gc_count = sequence_upper.count('G') + sequence_upper.count('C')

        if len(sequence_upper) == 0:
            return 0.0

        return (gc_count / len(sequence_upper)) * 100
