"""
Protein Sequence Analyzer
Validates amino acid sequences and calculates molecular weight
"""

import re
from typing import Dict, Optional

AMINO_ACID_WEIGHTS = {
    'A': 89.09, 'R': 174.20, 'N': 132.12, 'D': 133.10,
    'C': 121.16, 'E': 147.13, 'Q': 146.15, 'G': 75.07,
    'H': 155.16, 'I': 131.17, 'L': 131.17, 'K': 146.19,
    'M': 149.21, 'F': 165.19, 'P': 115.13, 'S': 105.09,
    'T': 119.12, 'W': 204.23, 'Y': 181.19, 'V': 117.15
}

def validate_protein_sequence(sequence: str) -> bool:
    """Validate protein amino acid sequence."""
    try:
        if not sequence:
            raise ValueError("Protein sequence cannot be empty")

        sequence = sequence.strip().upper()

        # Check for invalid characters
        pattern = re.compile(r'^[ARNDCQEGHILKMFPSTWYV]+$')
        if not pattern.match(sequence):
            invalid_chars = set(sequence) - set(AMINO_ACID_WEIGHTS.keys())
            raise ValueError(f"Invalid amino acids: {', '.join(invalid_chars)}")

        return True
    except Exception as e:
        print(f"Protein validation error: {e}")
        return False

def calculate_protein_weight(sequence: str) -> Optional[float]:
    """Calculate molecular weight of protein sequence."""
    try:
        if not validate_protein_sequence(sequence):
            return None

        sequence = sequence.upper()
        total_weight = 0.0

        for aa in sequence:
            if aa in AMINO_ACID_WEIGHTS:
                total_weight += AMINO_ACID_WEIGHTS[aa]
            else:
                raise ValueError(f"Unknown amino acid: {aa}")

        # Subtract weight of water molecules (n-1) * 18.02
