"""
FASTA File Parser with Error Handling
Parses FASTA format files containing biological sequences
"""

from typing import List, Tuple, Dict
import os

class FastaParserError(Exception):
    """Custom exception for FASTA parsing errors."""
    pass

def parse_fasta_file(filepath: str) -> List[Tuple[str, str]]:
    """Parse FASTA file and return list of (header, sequence) tuples."""
    sequences = []
    current_header = ""
    current_sequence = []

    try:
        if not os.path.exists(filepath):
            raise FileNotFoundError(f"FASTA file not found: {filepath}")

        with open(filepath, 'r') as fasta_file:
            line_number = 0

            for line in fasta_file:
                line_number += 1
                line = line.strip()

                if not line:
                    continue

                if line.startswith('>'):
                    # Save previous sequence if exists
                    if current_header:
                        seq_string = ''.join(current_sequence)
                        if not seq_string:
                            raise FastaParserError(
                                f"Empty sequence for header: {current_header}"
                            )
                        sequences.append((current_header, seq_string))

                    # Start new sequence
                    current_header = line[1:].strip()
                    if not current_header:
                        raise FastaParserError(
                            f"Empty header at line {line_number}"
                        )
                    current_sequence = []
                else:
                    # Sequence line
                    if not current_header:
                        raise FastaParserError(
                            f"Sequence data without header at line {line_number}"
                        )
                    current_sequence.append(line)

            # Save last sequence
            if current_header:
                seq_string = ''.join(current_sequence)
                if not seq_string:
                    raise FastaParserError(
                        f"Empty sequence for header: {current_header}"
                    )
                sequences.append((current_header, seq_string))

        if not sequences:
            raise FastaParserError("No valid sequences found in file")

        return sequences

    except UnicodeDecodeError:
        raise FastaParserError("File is not a valid text file")
    except PermissionError:
        raise FastaParserError(f"Permission denied: {filepath}")
    except Exception as e:
        if not isinstance(e, FastaParserError):
            raise FastaParserError(f"Error parsing FASTA file: {str(e)}")
        else:
            raise

def analyze_fasta_statistics(sequences: List[Tuple[str, str]]) -> Dict:
    """Calculate statistics for parsed FASTA sequences."""
    try:
        if not sequences:
            raise ValueError("No sequences provided for analysis")

        stats = {
            'total_sequences': len(sequences),
            'total_length': 0,
            'min_length': float('inf'),
            'max_length': 0,
            'avg_length': 0
        }

        total_length = 0

        for header, sequence in sequences:
            seq_len = len(sequence)
            total_length += seq_len
            stats['min_length'] = min(stats['min_length'], seq_len)
            stats['max_length'] = max(stats['max_length'], seq_len)

        stats['total_length'] = total_length
        stats['avg_length'] = total_length / len(sequences) if sequences else 0

        return stats

    except Exception as e:
        raise FastaParserError(f"Error in statistics calculation: {str(e)}")

def main():
    """Demonstrate FASTA file parsing."""
    test_fasta_content = """>seq1
