"""
Enzyme Kinetics Calculator
Calculates Michaelis-Menten kinetics parameters
"""

import numpy as np
from typing import Tuple, Optional
import warnings

class KineticsError(Exception):
    """Custom exception for enzyme kinetics errors."""
    pass

def calculate_michaelis_menten(
    substrate_concentrations: list,
    reaction_rates: list
) -> Tuple[float, float]:
    """
    Calculate Vmax and Km using Lineweaver-Burk plot.
    Returns (Vmax, Km)
    """
    try:
        # Validate inputs
        if len(substrate_concentrations) != len(reaction_rates):
            raise KineticsError(
                "Substrate concentrations and reaction rates must have same length"
            )

        if len(substrate_concentrations) < 2:
            raise KineticsError("At least 2 data points required")

        # Check for zero or negative values
        for i, (s, v) in enumerate(zip(substrate_concentrations, reaction_rates)):
            if s <= 0:
                raise KineticsError(
                    f"Substrate concentration must be positive at index {i}"
                )
            if v <= 0:
                raise KineticsError(
                    f"Reaction rate must be positive at index {i}"
                )

        # Convert to numpy arrays
        S = np.array(substrate_concentrations, dtype=float)
        V = np.array(reaction_rates, dtype=float)

        # Lineweaver-Burk transformation: 1/V vs 1/S
        with warnings.catch_warnings():
            warnings.simplefilter("error")
            try:
                inv_S = 1.0 / S
                inv_V = 1.0 / V
            except RuntimeWarning as w:
                raise KineticsError(f"Numerical error in transformation: {w}")

        # Linear regression: 1/V = (Km/Vmax)*(1/S) + 1/Vmax
        # y = mx + b where y = 1/V, x = 1/S
        # m = Km/Vmax, b = 1/Vmax

        # Calculate using numpy's polyfit
        coefficients = np.polyfit(inv_S, inv_V, 1)
        m, b = coefficients

        # Calculate Vmax and Km
        if abs(b) < 1e-10:
            raise KineticsError("Cannot calculate parameters: intercept too small")

        Vmax = 1.0 / b
        Km = m * Vmax

        # Validate results
        if Vmax <= 0 or Km <= 0:
            raise KineticsError("Calculated parameters must be positive")

        return float(Vmax), float(Km)

    except np.linalg.LinAlgError:
        raise KineticsError("Matrix singularity error in linear regression")
    except Exception as e:
        if not isinstance(e, KineticsError):
            raise KineticsError(f"Error in kinetics calculation: {str(e)}")
        else:
            raise

def predict_reaction_rate(
    substrate_concentration: float,
    Vmax: float,
    Km: float
) -> float:
    """Predict reaction rate using Michaelis-Menten equation."""
    try:
        if substrate_concentration < 0:
            raise KineticsError("Substrate concentration cannot be negative")
        if Vmax <= 0:
            raise KineticsError("Vmax must be positive")
        if Km <= 0:
            raise KineticsError("Km must be positive")

        # Michaelis-Menten equation: V = (Vmax * [S]) / (Km + [S])
        if substrate_concentration == 0:
            return 0.0

        rate = (Vmax * substrate_concentration) / (Km + substrate_concentration)

        if rate < 0:
            raise KineticsError("Calculated negative reaction rate")

        return rate

    except ZeroDivisionError:
        raise KineticsError("Division by zero in rate calculation")
    except Exception as e:
        raise KineticsError(f"Error in rate prediction: {str(e)}")

def main():
    """Demonstrate enzyme kinetics calculations."""
    # Test data: substrate concentrations (mM) and reaction rates (μM/min)
    test_data = {
        'S': [0.1, 0.2, 0.5, 1.0, 2.0, 5.0],
        'V': [0.68, 1.25, 2.50, 3.33, 4.00, 4.55]
    }

    try:
        print("Calculating Michaelis-Menten parameters...")
        Vmax, Km = calculate_michaelis_menten(test_data['S'], test_data['V'])

        print(f"\nResults:")
        print(f"Vmax = {Vmax:.3f} μM/min")
        print(f"Km = {Km:.3f} mM")

        # Test prediction
        print(f"\nPredictions:")
        test_concentrations = [0.1, 0.5, 1.0, 10.0]
        for S in test_concentrations:
            rate = predict_reaction_rate(S, Vmax, Km)
            print(f"At [S] = {S:.1f} mM: V = {rate:.3f} μM/min")

    except KineticsError as e:
        print(f"Kinetics error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()"
    },
