"""
Population Growth Simulator
Models logistic population growth with error handling
"""

from typing import List
import matplotlib.pyplot as plt
import numpy as np

class PopulationError(Exception):
    """Custom exception for population simulation errors."""
    pass

def logistic_growth(
    initial_population: float,
    growth_rate: float,
    carrying_capacity: float,
    time_steps: int
) -> List[float]:
    """
    Simulate logistic population growth.
    dN/dt = r * N * (1 - N/K)
    """
    try:
        # Validate parameters
        if initial_population <= 0:
            raise PopulationError("Initial population must be positive")
        if growth_rate <= 0:
            raise PopulationError("Growth rate must be positive")
        if carrying_capacity <= 0:
            raise PopulationError("Carrying capacity must be positive")
        if time_steps <= 0:
            raise PopulationError("Number of time steps must be positive")
        if initial_population > carrying_capacity:
            raise PopulationError(
                "Initial population cannot exceed carrying capacity"
            )

        population = [initial_population]

        for t in range(1, time_steps + 1):
            N = population[-1]

            # Logistic growth equation
            delta_N = growth_rate * N * (1 - N / carrying_capacity)

            # Prevent negative populations
            if N + delta_N < 0:
                new_N = 0.0
            else:
                new_N = N + delta_N

            # Check for numerical instability
            if new_N > carrying_capacity * 10:
                raise PopulationError(
                    f"Numerical instability at time step {t}: "
                    f"population = {new_N}"
                )

            population.append(new_N)

        return population

    except OverflowError:
        raise PopulationError("Numerical overflow in population calculation")
    except Exception as e:
        if not isinstance(e, PopulationError):
            raise PopulationError(f"Error in growth simulation: {str(e)}")
        else:
            raise

def analyze_population_trend(population_data: List[float]) -> dict:
    """Analyze population trends and stability."""
    try:
        if len(population_data) < 2:
            raise PopulationError("Insufficient data for analysis")

        analysis = {
            'final_population': population_data[-1],
            'max_population': max(population_data),
            'min_population': min(population_data),
            'stable': False,
            'growth_rate': 0.0
        }

        # Calculate average growth rate
        changes = []
        for i in range(1, len(population_data)):
            if population_data[i-1] > 0:
                change = (population_data[i] - population_data[i-1]) / population_data[i-1]
                changes.append(change)

        if changes:
            analysis['growth_rate'] = np.mean(changes)

        # Check for stability (population changes less than 1%)
        if len(population_data) > 10:
            last_values = population_data[-10:]
            relative_changes = []
            for i in range(1, len(last_values)):
                if last_values[i-1] > 0:
                    rel_change = abs(last_values[i] - last_values[i-1]) / last_values[i-1]
                    relative_changes.append(rel_change)

            if relative_changes and max(relative_changes) < 0.01:
                analysis['stable'] = True

        return analysis

    except Exception as e:
        raise PopulationError(f"Error in population analysis: {str(e)}")

def main():
    """Demonstrate population growth simulation."""
    # Test scenarios
    scenarios = [
        {"name": "Normal Growth", "N0": 10, "r": 0.5, "K": 100, "steps": 50},
        {"name": "Rapid Growth", "N0": 5, "r": 1.2, "K": 200, "steps": 30},
        {"name": "Slow Growth", "N0": 50, "r": 0.1, "K": 150, "steps": 100}
    ]

    plt.figure(figsize=(12, 8))

    for i, scenario in enumerate(scenarios, 1):
        try:
            print(f"\nScenario: {scenario['name']}")
            print(f"Parameters: N0={scenario['N0']}, r={scenario['r']}, "
                  f"K={scenario['K']}, steps={scenario['steps']}")

            population = logistic_growth(
                scenario['N0'],
                scenario['r'],
                scenario['K'],
                scenario['steps']
            )

            analysis = analyze_population_trend(population)
            print(f"Final population: {analysis['final_population']:.2f}")
            print(f"Maximum population: {analysis['max_population']:.2f}")
            print(f"Stable: {analysis['stable']}")
            print(f"Average growth rate: {analysis['growth_rate']:.4f}")

            # Plot
            plt.subplot(2, 2, i)
            plt.plot(population, 'b-', linewidth=2)
            plt.axhline(y=scenario['K'], color='r', linestyle='--', 
                       label=f"K={scenario['K']}")
            plt.xlabel('Time Steps')
            plt.ylabel('Population Size')
            plt.title(scenario['name'])
            plt.legend()
            plt.grid(True, alpha=0.3)

        except PopulationError as e:
            print(f"Simulation error: {e}")
        except Exception as e:
            print(f"Unexpected error: {e}")

    plt.tight_layout()
    plt.savefig('population_growth.png', dpi=150)
    print("\nPlot saved as 'population_growth.png'")

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"Program failed: {e}")"
