"""
Genetic Code Translator
Translates DNA sequences to amino acid sequences
"""

from typing import Dict, Optional, List
import re

class TranslationError(Exception):
    """Custom exception for translation errors."""
    pass

GENETIC_CODE = {
    'ATA':'I', 'ATC':'I', 'ATT':'I', 'ATG':'M',
    'ACA':'T', 'ACC':'T', 'ACG':'T', 'ACT':'T',
    'AAC':'N', 'AAT':'N', 'AAA':'K', 'AAG':'K',
    'AGC':'S', 'AGT':'S', 'AGA':'R', 'AGG':'R',
    'CTA':'L', 'CTC':'L', 'CTG':'L', 'CTT':'L',
    'CCA':'P', 'CCC':'P', 'CCG':'P', 'CCT':'P',
    'CAC':'H', 'CAT':'H', 'CAA':'Q', 'CAG':'Q',
    'CGA':'R', 'CGC':'R', 'CGG':'R', 'CGT':'R',
    'GTA':'V', 'GTC':'V', 'GTG':'V', 'GTT':'V',
    'GCA':'A', 'GCC':'A', 'GCG':'A', 'GCT':'A',
    'GAC':'D', 'GAT':'D', 'GAA':'E', 'GAG':'E',
    'GGA':'G', 'GGC':'G', 'GGG':'G', 'GGT':'G',
    'TCA':'S', 'TCC':'S', 'TCG':'S', 'TCT':'S',
    'TTC':'F', 'TTT':'F', 'TTA':'L', 'TTG':'L',
    'TAC':'Y', 'TAT':'Y', 'TAA':'*', 'TAG':'*',
    'TGC':'C', 'TGT':'C', 'TGA':'*', 'TGG':'W'
}

def validate_dna_for_translation(dna_sequence: str) -> bool:
    """Validate DNA sequence for translation."""
    try:
        if not dna_sequence:
            raise TranslationError("DNA sequence cannot be empty")

        dna_upper = dna_sequence.upper().strip()

        # Check for valid nucleotides
        if not re.match(r'^[ATCG]+$', dna_upper):
            invalid_chars = set(dna_upper) - set('ATCG')
            raise TranslationError(
                f"Invalid DNA characters: {', '.join(invalid_chars)}"
            )

        # Check length is multiple of 3
        if len(dna_upper) % 3 != 0:
            raise TranslationError(
                f"DNA sequence length ({len(dna_upper)}) "
                f"is not a multiple of 3"
            )

        return True

    except TranslationError:
        raise
    except Exception as e:
        raise TranslationError(f"Validation error: {str(e)}")

def translate_dna_to_protein(
    dna_sequence: str,
    reading_frame: int = 1
) -> str:
    """
    Translate DNA sequence to protein sequence.
    reading_frame: 1, 2, or 3
    """
    try:
        # Validate reading frame
        if reading_frame not in [1, 2, 3]:
            raise TranslationError("Reading frame must be 1, 2, or 3")

        dna_upper = dna_sequence.upper().strip()

        # Start from reading frame offset
        start_index = reading_frame - 1

        if start_index >= len(dna_upper):
            raise TranslationError(
                f"Reading frame {reading_frame} starts beyond sequence length"
            )

        # Extract coding sequence
        coding_sequence = dna_upper[start_index:]

        # Validate coding sequence
        validate_dna_for_translation(coding_sequence)

        # Translate codon by codon
        protein_sequence = []

        for i in range(0, len(coding_sequence), 3):
            codon = coding_sequence[i:i+3]

            if len(codon) != 3:
                raise TranslationError(
                    f"Incomplete codon at position {i}: '{codon}'"
                )

            if codon not in GENETIC_CODE:
                raise TranslationError(
                    f"Unknown codon: {codon} at position {i}"
                )

            amino_acid = GENETIC_CODE[codon]

            # Stop codon
            if amino_acid == '*':
                protein_sequence.append('*')
                break

            protein_sequence.append(amino_acid)

        return ''.join(protein_sequence)

    except TranslationError:
        raise
    except Exception as e:
        raise TranslationError(f"Translation error: {str(e)}")

def find_open_reading_frames(dna_sequence: str) -> List[dict]:
    """Find all open reading frames in DNA sequence."""
    try:
        dna_upper = dna_sequence.upper().strip()

        if not validate_dna_for_translation(dna_upper):
            return []

        orfs = []

        # Check all reading frames
        for frame in [1, 2, 3]:
            try:
                protein = translate_dna_to_protein(dna_upper, frame)

                # Find start (M) and stop (*) codons
                start_positions = []
                for i, aa in enumerate(protein):
                    if aa == 'M':
                        start_positions.append(i)
                    elif aa == '*':
                        # Check if this stop codon follows any start codon
                        for start_pos in start_positions:
                            orf_seq = protein[start_pos:i]
                            if len(orf_seq) >= 10:  # Minimum ORF length
                                orfs.append({
                                    'frame': frame,
                                    'start': start_pos * 3 + (frame - 1),
                                    'stop': i * 3 + (frame - 1) + 3,
                                    'length_aa': len(orf_seq),
                                    'sequence': orf_seq
                                })
                        start_positions = []  # Reset for next ORF
            except TranslationError:
                continue

        # Sort by length (longest first)
        orfs.sort(key=lambda x: x['length_aa'], reverse=True)
        return orfs

    except Exception as e:
        raise TranslationError(f"ORF finding error: {str(e)}")

def main():
    """Demonstrate DNA translation."""
    test_sequences = [
        "ATGGCTAGCTAA",  # Valid with start and stop
        "ATGGCTAGC",     # Valid no stop
        "ATGGCTAGCTAG",  # Valid
        "XYZATGGCT",     # Invalid characters
        "ATG",           # Too short
        "ATGGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGC"  # Long sequence
    ]

    for i, dna in enumerate(test_sequences, 1):
        print(f"\nTest {i}: {dna}")

        try:
            # Try translation in frame 1
            protein = translate_dna_to_protein(dna, 1)
            print(f"Translation: {protein}")

            # Find ORFs
            orfs = find_open_reading_frames(dna)
            print(f"Found {len(orfs)} ORF(s)")
            for orf in orfs[:3]:  # Show first 3
                print(f"  Frame {orf['frame']}: {orf['sequence']} "
                      f"(length: {orf['length_aa']} aa)")

        except TranslationError as e:
            print(f"Translation error: {e}")
        except Exception as e:
            print(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()"
    },
