"""
Phylogenetic Distance Calculator
Calculates genetic distances between sequences
"""

from typing import List, Tuple, Dict
import numpy as np
from itertools import combinations

class PhylogeneticError(Exception):
    """Custom exception for phylogenetic analysis errors."""
    pass

def calculate_p_distance(seq1: str, seq2: str) -> float:
    """
    Calculate p-distance (proportion of different sites)
    between two aligned sequences.
    """
    try:
        if len(seq1) != len(seq2):
            raise PhylogeneticError(
                f"Sequence lengths differ: {len(seq1)} vs {len(seq2)}"
            )

        if len(seq1) == 0:
            raise PhylogeneticError("Sequences cannot be empty")

        seq1_upper = seq1.upper()
        seq2_upper = seq2.upper()

        # Count differences
        differences = 0
        total_sites = 0

        for a, b in zip(seq1_upper, seq2_upper):
            # Skip gaps or ambiguous characters
            if a in 'ACGT' and b in 'ACGT':
                total_sites += 1
                if a != b:
                    differences += 1
            elif a == '-' and b == '-':
                continue  # Both gaps
            else:
                # Ambiguous character or partial gap
                continue

        if total_sites == 0:
            raise PhylogeneticError(
                "No valid nucleotide sites for comparison"
            )

        p_distance = differences / total_sites

        # Validate result
        if p_distance < 0 or p_distance > 1:
            raise PhylogeneticError(
                f"Invalid p-distance calculated: {p_distance}"
            )

        return p_distance

    except ZeroDivisionError:
        raise PhylogeneticError("Division by zero in distance calculation")
    except Exception as e:
        if not isinstance(e, PhylogeneticError):
            raise PhylogeneticError(f"Distance calculation error: {str(e)}")
        else:
            raise

def calculate_jukes_cantor_distance(p_distance: float) -> float:
    """
    Calculate Jukes-Cantor corrected distance.
    d = -(3/4) * ln(1 - (4/3)*p)
    """
    try:
        if p_distance < 0 or p_distance > 1:
            raise PhylogeneticError(
                f"p-distance must be between 0 and 1, got {p_distance}"
            )

        # Handle edge cases
        if p_distance == 0:
            return 0.0

        if p_distance >= 0.75:
            raise PhylogeneticError(
                f"p-distance ({p_distance}) too high for Jukes-Cantor correction"
            )

        # Jukes-Cantor formula
        try:
            jc_distance = -0.75 * np.log(1.0 - (4.0/3.0) * p_distance)
        except ValueError as e:
            raise PhylogeneticError(
                f"Math domain error in Jukes-Cantor: {str(e)}"
            )

        if jc_distance < 0:
            raise PhylogeneticError(
                f"Negative Jukes-Cantor distance calculated: {jc_distance}"
            )

        return jc_distance

    except Exception as e:
        if not isinstance(e, PhylogeneticError):
            raise PhylogeneticError(f"Jukes-Cantor error: {str(e)}")
        else:
            raise

def create_distance_matrix(
    sequences: List[str],
    names: List[str],
    use_jukes_cantor: bool = False
) -> Tuple[np.ndarray, List[str]]:
    """Create pairwise distance matrix for multiple sequences."""
    try:
        n = len(sequences)

        if n != len(names):
            raise PhylogeneticError(
                f"Number of sequences ({n}) doesn't match "
                f"number of names ({len(names)})"
            )

        if n < 2:
            raise PhylogeneticError("Need at least 2 sequences for distance matrix")

        # Initialize distance matrix
        distance_matrix = np.zeros((n, n))

        # Calculate pairwise distances
        for i in range(n):
            for j in range(i + 1, n):
                try:
                    p_dist = calculate_p_distance(sequences[i], sequences[j])

                    if use_jukes_cantor:
                        dist = calculate_jukes_cantor_distance(p_dist)
                    else:
                        dist = p_dist

                    distance_matrix[i, j] = dist
                    distance_matrix[j, i] = dist

                except PhylogeneticError as e:
