"""
Bioinformatics Sequence Alignment
Simple pairwise sequence alignment with scoring
"""

from typing import Tuple, List, Dict
import numpy as np

class AlignmentError(Exception):
    """Custom exception for sequence alignment errors."""
    pass

class ScoringMatrix:
    """Scoring matrix for sequence alignment."""

    def __init__(self, match_score: int = 1, mismatch_penalty: int = -1, 
                 gap_penalty: int = -2):
        try:
            if gap_penalty > 0:
                raise AlignmentError("Gap penalty should be negative")

            self.match_score = match_score
            self.mismatch_penalty = mismatch_penalty
            self.gap_penalty = gap_penalty

        except Exception as e:
            raise AlignmentError(f"Scoring matrix error: {str(e)}")

    def score(self, a: str, b: str) -> int:
        """Score for aligning two characters."""
        if a == b:
            return self.match_score
        elif a == '-' or b == '-':
            return self.gap_penalty
        else:
            return self.mismatch_penalty

def needleman_wunsch(
    seq1: str,
    seq2: str,
    scoring_matrix: ScoringMatrix
) -> Tuple[str, str, int]:
    """
    Perform Needleman-Wunsch global alignment.
    Returns (aligned_seq1, aligned_seq2, score)
    """
    try:
        if not seq1 or not seq2:
            raise AlignmentError("Sequences cannot be empty")

        n = len(seq1)
        m = len(seq2)

        # Initialize score matrix
        score_matrix = np.zeros((n + 1, m + 1), dtype=int)

        # Initialize traceback matrix
        traceback = np.zeros((n + 1, m + 1), dtype=int)

        # Initialize first row and column with gap penalties
        for i in range(1, n + 1):
            score_matrix[i, 0] = i * scoring_matrix.gap_penalty
            traceback[i, 0] = 1  # Up (gap in seq2)

        for j in range(1, m + 1):
            score_matrix[0, j] = j * scoring_matrix.gap_penalty
            traceback[0, j] = 2  # Left (gap in seq1)

        # Fill score matrix
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                # Calculate scores for three possibilities
                match_score = score_matrix[i-1, j-1] + scoring_matrix.score(seq1[i-1], seq2[j-1])
                gap_in_seq2 = score_matrix[i-1, j] + scoring_matrix.gap_penalty
                gap_in_seq1 = score_matrix[i, j-1] + scoring_matrix.gap_penalty

                # Choose maximum score
                scores = [match_score, gap_in_seq2, gap_in_seq1]
                max_score = max(scores)
                score_matrix[i, j] = max_score

                # Store traceback direction
                traceback[i, j] = scores.index(max_score)

        # Traceback to construct alignment
        aligned_seq1 = []
        aligned_seq2 = []
        i, j = n, m

        while i > 0 or j > 0:
            direction = traceback[i, j]

            if direction == 0:  # Diagonal (match/mismatch)
                aligned_seq1.append(seq1[i-1])
                aligned_seq2.append(seq2[j-1])
                i -= 1
                j -= 1
            elif direction == 1:  # Up (gap in seq2)
                aligned_seq1.append(seq1[i-1])
                aligned_seq2.append('-')
                i -= 1
            else:  # Left (gap in seq1)
                aligned_seq1.append('-')
                aligned_seq2.append(seq2[j-1])
                j -= 1

        # Reverse sequences
        aligned_seq1 = ''.join(reversed(aligned_seq1))
        aligned_seq2 = ''.join(reversed(aligned_seq2))

        final_score = score_matrix[n, m]

        # Validate alignment
        if len(aligned_seq1) != len(aligned_seq2):
            raise AlignmentError("Alignment produced sequences of different lengths")

        return aligned_seq1, aligned_seq2, final_score

    except MemoryError:
        raise AlignmentError("Memory error: sequences too long for alignment")
    except Exception as e:
        raise AlignmentError(f"Alignment error: {str(e)}")

def calculate_identity(aligned_seq1: str, aligned_seq2: str) -> float:
    """Calculate percentage identity from alignment."""
    try:
        if len(aligned_seq1) != len(aligned_seq2):
            raise AlignmentError("Aligned sequences must have same length")

        if len(aligned_seq1) == 0:
            return 0.0

        matches = 0
        total_aligned = 0

        for a, b in zip(aligned_seq1, aligned_seq2):
            if a != '-' or b != '-':  # Count aligned positions
                total_aligned += 1
                if a == b:
                    matches += 1

        if total_aligned == 0:
            return 0.0

        identity = (matches / total_aligned) * 100

        if identity < 0 or identity > 100:
            raise AlignmentError(f"Invalid identity percentage: {identity}")

        return identity

    except ZeroDivisionError:
        raise AlignmentError("Division by zero in identity calculation")
    except Exception as e:
        raise AlignmentError(f"Identity calculation error: {str(e)}")

def main():
    """Demonstrate sequence alignment."""
    # Test sequences
    test_pairs = [
        ("ACGTACGT", "ACGTACGT"),  # Identical
        ("ACGTACGT", "ACGTAAGT"),  # One mismatch
        ("ACGT", "ACGTACGT"),      # Shorter sequence
        ("ACGT", "TGCA"),          # Completely different
        ("", "ACGT")               # Empty sequence
    ]

    scoring = ScoringMatrix(match_score=2, mismatch_penalty=-1, gap_penalty=-2)

    for i, (seq1, seq2) in enumerate(test_pairs, 1):
        print(f"\nAlignment {i}:")
        print(f"Sequence 1: {seq1}")
        print(f"Sequence 2: {seq2}")

        try:
            aligned1, aligned2, score = needleman_wunsch(seq1, seq2, scoring)

            print(f"Aligned 1:  {aligned1}")
            print(f"Aligned 2:  {aligned2}")
            print(f"Score:      {score}")

            identity = calculate_identity(aligned1, aligned2)
            print(f"Identity:   {identity:.1f}%")

            # Show matches
            matches = []
            for a, b in zip(aligned1, aligned2):
                if a == b:
                    matches.append('|')
                else:
                    matches.append(' ')
            print(f"Matches:    {''.join(matches)}")

        except AlignmentError as e:
            print(f"Alignment error: {e}")
        except Exception as e:
            print(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()"
