"""
Gene Expression Normalization
Normalizes gene expression data with error handling
"""

import numpy as np
from typing import List, Tuple, Dict
import warnings

class ExpressionError(Exception):
    """Custom exception for gene expression analysis errors."""
    pass

def validate_expression_data(
    expression_matrix: np.ndarray,
    sample_names: List[str],
    gene_names: List[str]
) -> bool:
    """Validate gene expression data."""
    try:
        if expression_matrix.size == 0:
            raise ExpressionError("Expression matrix is empty")

        if expression_matrix.ndim != 2:
            raise ExpressionError(
                f"Expression matrix must be 2D, got {expression_matrix.ndim}D"
            )

        n_genes, n_samples = expression_matrix.shape

        if len(sample_names) != n_samples:
            raise ExpressionError(
                f"Number of sample names ({len(sample_names)}) "
                f"doesn't match matrix columns ({n_samples})"
            )

        if len(gene_names) != n_genes:
            raise ExpressionError(
                f"Number of gene names ({len(gene_names)}) "
                f"doesn't match matrix rows ({n_genes})"
            )

        # Check for NaN or infinite values
        if np.any(np.isnan(expression_matrix)):
            raise ExpressionError("Expression matrix contains NaN values")

        if np.any(np.isinf(expression_matrix)):
            raise ExpressionError("Expression matrix contains infinite values")

        # Check for negative values (if not allowed)
        if np.any(expression_matrix < 0):
            warnings.warn("Expression matrix contains negative values")

        return True

    except Exception as e:
        if not isinstance(e, ExpressionError):
            raise ExpressionError(f"Validation error: {str(e)}")
        else:
            raise

def normalize_rpkm(
    expression_counts: np.ndarray,
    gene_lengths: np.ndarray,
    total_reads: np.ndarray
) -> np.ndarray:
    """
    Normalize expression counts to RPKM (Reads Per Kilobase Million).
    RPKM = (10^9 * read_count) / (gene_length * total_reads)
    """
    try:
        # Validate inputs
        if expression_counts.ndim != 2:
            raise ExpressionError("Expression counts must be 2D matrix")

        n_genes, n_samples = expression_counts.shape

        if len(gene_lengths) != n_genes:
            raise ExpressionError(
                f"Gene lengths ({len(gene_lengths)}) doesn't match "
                f"number of genes ({n_genes})"
            )

        if len(total_reads) != n_samples:
            raise ExpressionError(
                f"Total reads ({len(total_reads)}) doesn't match "
                f"number of samples ({n_samples})"
            )

        # Check for zero or negative values
        if np.any(gene_lengths <= 0):
            raise ExpressionError("Gene lengths must be positive")

        if np.any(total_reads <= 0):
            raise ExpressionError("Total reads must be positive")

        if np.any(expression_counts < 0):
            raise ExpressionError("Expression counts cannot be negative")

        # Convert to float for division
        counts_float = expression_counts.astype(float)
        lengths_float = gene_lengths.astype(float).reshape(-1, 1)
        total_reads_float = total_reads.astype(float).reshape(1, -1)

        # Calculate RPKM
        with warnings.catch_warnings():
            warnings.simplefilter("error")
            try:
                # Avoid division by zero
                scaling_factor = 1e9 / (lengths_float * total_reads_float)
                rpkm_matrix = counts_float * scaling_factor
            except RuntimeWarning as w:
                raise ExpressionError(f"Numerical error in RPKM calculation: {w}")

        # Replace any NaN or Inf with 0
        rpkm_matrix = np.nan_to_num(rpkm_matrix, nan=0.0, posinf=0.0, neginf=0.0)

        return rpkm_matrix

    except ZeroDivisionError:
        raise ExpressionError("Division by zero in RPKM calculation")
    except Exception as e:
        if not isinstance(e, ExpressionError):
            raise ExpressionError(f"RPKM normalization error: {str(e)}")
        else:
            raise

def normalize_tpm(
    expression_counts: np.ndarray,
    gene_lengths: np.ndarray
) -> np.ndarray:
    """
    Normalize expression counts to TPM (Transcripts Per Million).
    """
    try:
        # Validate inputs
        if expression_counts.ndim != 2:
            raise ExpressionError("Expression counts must be 2D matrix")

        n_genes, n_samples = expression_counts.shape

        if len(gene_lengths) != n_genes:
            raise ExpressionError(
                f"Gene lengths ({len(gene_lengths)}) doesn't match "
                f"number of genes ({n_genes})"
            )

        if np.any(gene_lengths <= 0):
            raise ExpressionError("Gene lengths must be positive")

        if np.any(expression_counts < 0):
            raise ExpressionError("Expression counts cannot be negative")

        # Convert to float
        counts_float = expression_counts.astype(float)
        lengths_float = gene_lengths.astype(float).reshape(-1, 1)

        # Calculate reads per kilobase
        with warnings.catch_warnings():
            warnings.simplefilter("error")
            try:
                rpk = counts_float / (lengths_float / 1000.0)
            except RuntimeWarning as w:
                raise ExpressionError(f"Numerical error in RPK calculation: {w}")

        # Sum RPK per sample
        rpk_sum = np.sum(rpk, axis=0, keepdims=True)

        # Avoid division by zero
        rpk_sum[rpk_sum == 0] = 1.0

        # Calculate TPM
        tpm_matrix = (rpk / rpk_sum) * 1e6

        # Replace any NaN or Inf with 0
        tpm_matrix = np.nan_to_num(tpm_matrix, nan=0.0, posinf=0.0, neginf=0.0)

        return tpm_matrix

    except ZeroDivisionError:
        raise ExpressionError("Division by zero in TPM calculation")
    except Exception as e:
        if not isinstance(e, ExpressionError):
            raise ExpressionError(f"TPM normalization error: {str(e)}")
        else:
            raise

def main():
