        stop_codons = ['TAA', 'TAG', 'TGA']
        stop_index = len(coding_seq)

        for i in range(0, len(coding_seq), 3):
            codon = coding_seq[i:i+3]
            if codon in stop_codons:
                stop_index = i + 3
                break

        if stop_index == len(coding_seq):
            warnings.warn("No stop codon found, using entire sequence")

        return coding_seq[:stop_index]

    except Exception as e:
        raise CodonUsageError(f"Error extracting coding sequence: {str(e)}")

