    if not formula:
        raise ValueError("Formula cannot be empty")

    element_pattern = re.compile(r'([A-Z][a-z]?)(\d*)')
    composition: Dict[str, int] = {}

    for match in element_pattern.finditer(formula):
        element = match.group(1)
        count_str = match.group(2)
        count = int(count_str) if count_str else 1

        if element not in ATOMIC_MASSES:
            raise ValueError(f"Unknown element: {element}")

        composition[element] = composition.get(element, 0) + count

    if not composition:
        raise ValueError(f"No valid elements found in formula: {formula}")

    return composition


def calculate_molar_mass(formula: str) -> MolarMassResult:
    """
    Calculate the molar mass and percent composition of a compound.
    """
    composition = parse_formula(formula)

    molar_mass = sum(
        ATOMIC_MASSES[element] * count
        for element, count in composition.items()
    )

    percent_composition = {
        element: (ATOMIC_MASSES[element] * count / molar_mass) * 100
        for element, count in composition.items()
    }

    return MolarMassResult(
        formula=formula,
        molar_mass=molar_mass,
        composition=composition,
        percent_composition=percent_composition,
    )


def empirical_from_percent(percentages: Dict[str, float]) -> Optional[str]:
    """
    Determine empirical formula from percent composition.
    """
    if abs(sum(percentages.values()) - 100.0) > 0.5:
        raise ValueError("Percentages must sum to approximately 100%")

    moles = {
        element: pct / ATOMIC_MASSES[element]
        for element, pct in percentages.items()
    }

    min_moles = min(moles.values())
    ratios = {element: mol / min_moles for element, mol in moles.items()}

    # Round to nearest integer
    int_ratios = {element: round(ratio) for element, ratio in ratios.items()}

    formula = "".join(
        f"{element}{count if count > 1 else ''}"
        for element, count in int_ratios.items()
    )
    return formula


def main():
    """Demonstrate molar mass calculations for common compounds."""
    compounds = ['H2O', 'NaCl', 'C6H12O6', 'H2SO4', 'CaCO3']

    print("=" * 50)
    print("MOLAR MASS CALCULATOR")
    print("=" * 50)

    for formula in compounds:
        try:
            result = calculate_molar_mass(formula)
            print(f"\n{result}")
            print("-" * 40)
        except ValueError as e:
            print(f"Error processing {formula}: {e}")

    # Empirical formula example
    print("\nEmpirical Formula from Percent Composition:")
    water_pct = {'H': 11.19, 'O': 88.81}
    empirical = empirical_from_percent(water_pct)
    print(f"Water percent composition -> Empirical formula: {empirical}")


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""
Chemistry Best Practices: Stoichiometry and Reaction Balancing
Demonstrates limiting reagent, yield calculations, and reaction analysis.
"""

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple
from fractions import Fraction
import math


@dataclass
class Compound:
    """Represents a chemical compound in a reaction."""
    formula: str
    molar_mass: float  # g/mol
    name: Optional[str] = None

    def moles_from_grams(self, grams: float) -> float:
        """Convert grams to moles."""
        if grams < 0:
            raise ValueError("Mass cannot be negative")
        return grams / self.molar_mass

    def grams_from_moles(self, moles: float) -> float:
        """Convert moles to grams."""
        if moles < 0:
            raise ValueError("Moles cannot be negative")
        return moles * self.molar_mass

    def __str__(self) -> str:
        label = self.name or self.formula
        return f"{label} (M={self.molar_mass:.3f} g/mol)"


@dataclass
class ReactionComponent:
    """A compound with its stoichiometric coefficient."""
    compound: Compound
    coefficient: int
    available_grams: float = 0.0

    @property
    def available_moles(self) -> float:
        return self.compound.moles_from_grams(self.available_grams)

    @property
    def moles_per_coefficient(self) -> float:
        """Moles available divided by stoichiometric coefficient."""
        return self.available_moles / self.coefficient


@dataclass
class ChemicalReaction:
    """Represents a balanced chemical reaction."""
    reactants: List[ReactionComponent]
    products: List[ReactionComponent]
    name: str = "Chemical Reaction"

    def find_limiting_reagent(self) -> Tuple[ReactionComponent, float]:
        """
        Find the limiting reagent based on available amounts.
        Returns (limiting_reagent, moles_per_coefficient).
        """
        if not self.reactants:
            raise ValueError("No reactants defined")

        limiting = min(self.reactants, key=lambda r: r.moles_per_coefficient)
        return limiting, limiting.moles_per_coefficient

    def theoretical_yield(self, product_index: int = 0) -> Dict[str, float]:
        """
        Calculate theoretical yield for a product.
        Returns dict with moles and grams.
        """
        if product_index >= len(self.products):
            raise IndexError(f"Product index {product_index} out of range")

        _, limiting_ratio = self.find_limiting_reagent()
        product = self.products[product_index]

        moles_product = limiting_ratio * product.coefficient
        grams_product = product.compound.grams_from_moles(moles_product)

        return {
            'moles': moles_product,
            'grams': grams_product,
            'compound': product.compound.formula
        }

    def percent_yield(self, actual_grams: float, product_index: int = 0) -> float:
        """Calculate percent yield from actual yield."""
        theoretical = self.theoretical_yield(product_index)
        if theoretical['grams'] == 0:
            raise ValueError("Theoretical yield is zero")
        return (actual_grams / theoretical['grams']) * 100

    def excess_reagent_remaining(self) -> Dict[str, float]:
        """Calculate how much of each excess reagent remains."""
        limiting, limiting_ratio = self.find_limiting_reagent()
        remaining = {}

        for reactant in self.reactants:
            if reactant is limiting:
                remaining[reactant.compound.formula] = 0.0
            else:
                moles_used = limiting_ratio * reactant.coefficient
                moles_remaining = reactant.available_moles - moles_used
                grams_remaining = reactant.compound.grams_from_moles(
                    max(0, moles_remaining)
                )
                remaining[reactant.compound.formula] = grams_remaining

        return remaining


def combustion_analysis(carbon_pct: float, hydrogen_pct: float,
                        oxygen_pct: float = 0.0) -> str:
    """Determine empirical formula from combustion analysis data."""
    masses = {'C': carbon_pct, 'H': hydrogen_pct, 'O': oxygen_pct}
    atomic_masses = {'C': 12.011, 'H': 1.008, 'O': 15.999}

    moles = {elem: mass / atomic_masses[elem]
             for elem, mass in masses.items() if mass > 0}

    min_moles = min(moles.values())
    ratios = {elem: mol / min_moles for elem, mol in moles.items()}

    # Convert to integers
    int_ratios = {elem: round(ratio) for elem, ratio in ratios.items()}

    formula = "".join(
        f"{elem}{count if count > 1 else ''}"
        for elem, count in int_ratios.items()
        if count > 0
    )
    return formula


def main():
    """Demonstrate stoichiometry calculations."""
    print("STOICHIOMETRY CALCULATOR")
    print("=" * 40)

    # Reaction: 2H2 + O2 -> 2H2O
    h2 = Compound('H2', 2.016, 'Hydrogen gas')
    o2 = Compound('O2', 31.998, 'Oxygen gas')
    h2o = Compound('H2O', 18.015, 'Water')

    reaction = ChemicalReaction(
        reactants=[
            ReactionComponent(h2, coefficient=2, available_grams=10.0),
            ReactionComponent(o2, coefficient=1, available_grams=50.0),
        ],
        products=[ReactionComponent(h2o, coefficient=2)],
        name="Hydrogen Combustion: 2H2 + O2 -> 2H2O"
    )

    print(f"\nReaction: {reaction.name}")
    limiting, ratio = reaction.find_limiting_reagent()
    print(f"Limiting Reagent: {limiting.compound.formula}")

    yield_data = reaction.theoretical_yield()
    print(f"Theoretical Yield: {yield_data['grams']:.4f} g of {yield_data['compound']}")

    excess = reaction.excess_reagent_remaining()
    print("Excess Reagents Remaining:")
    for formula, grams in excess.items():
        print(f"  {formula}: {grams:.4f} g")

    actual_yield = 8.5
    pct_yield = reaction.percent_yield(actual_yield)
    print(f"\nActual yield: {actual_yield} g -> Percent yield: {pct_yield:.2f}%")

    print("\nCombustion Analysis Example:")
    formula = combustion_analysis(carbon_pct=40.0, hydrogen_pct=6.7, oxygen_pct=53.3)
    print(f"C=40%, H=6.7%, O=53.3% -> Empirical formula: {formula}")


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""
Chemistry Best Practices: Spectroscopy and Quantum Chemistry
Demonstrates Beer-Lambert law, spectral calculations, and atomic orbitals.
"""

import math
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple
from enum import Enum

# Physical constants
H_PLANCK = 6.626e-34   # J·s
C_LIGHT = 2.998e8      # m/s
K_BOLTZMANN = 1.381e-23  # J/K
AVOGADRO = 6.022e23
RYDBERG = 1.097e7      # m⁻¹
BOHR_RADIUS = 5.292e-11  # m


class SpectralRegion(Enum):
    RADIO = "Radio"
    MICROWAVE = "Microwave"
    INFRARED = "Infrared"
    VISIBLE = "Visible"
    ULTRAVIOLET = "UV"
    X_RAY = "X-ray"
    GAMMA = "Gamma"


SPECTRAL_RANGES: Dict[SpectralRegion, Tuple[float, float]] = {
    SpectralRegion.RADIO: (1e-3, 1e3),
    SpectralRegion.MICROWAVE: (1e-3, 1e-1),
    SpectralRegion.INFRARED: (7e-7, 1e-3),
    SpectralRegion.VISIBLE: (380e-9, 700e-9),
    SpectralRegion.ULTRAVIOLET: (10e-9, 380e-9),
    SpectralRegion.X_RAY: (1e-11, 10e-9),
    SpectralRegion.GAMMA: (1e-14, 1e-11),
}


@dataclass
class PhotonProperties:
    """Properties of a photon at a given wavelength."""
    wavelength_m: float

    def __post_init__(self):
        if self.wavelength_m <= 0:
            raise ValueError("Wavelength must be positive")

    @property
    def frequency_Hz(self) -> float:
        return C_LIGHT / self.wavelength_m

    @property
    def energy_J(self) -> float:
        return H_PLANCK * self.frequency_Hz

    @property
    def energy_eV(self) -> float:
        return self.energy_J / 1.602e-19

    @property
    def wavenumber_cm_inv(self) -> float:
        return 1.0 / (self.wavelength_m * 100)

    @property
    def spectral_region(self) -> SpectralRegion:
        for region, (low, high) in SPECTRAL_RANGES.items():
            if low <= self.wavelength_m <= high:
                return region
        return SpectralRegion.GAMMA

    def __str__(self) -> str:
        return (f"λ={self.wavelength_m*1e9:.2f} nm, "
                f"ν={self.frequency_Hz:.4e} Hz, "
                f"E={self.energy_eV:.4f} eV")


@dataclass
class BeerLambertData:
    """Beer-Lambert law: A = ε * c * l"""
    molar_absorptivity: float  # ε in L/(mol·cm)
    concentration: float       # c in mol/L
    path_length_cm: float      # l in cm

    @property
    def absorbance(self) -> float:
        """A = ε * c * l"""
        return self.molar_absorptivity * self.concentration * self.path_length_cm

    @property
    def transmittance(self) -> float:
        """T = 10^(-A)"""
        return 10 ** (-self.absorbance)

    @property
    def percent_transmittance(self) -> float:
        return self.transmittance * 100

    def concentration_from_absorbance(self, measured_A: float) -> float:
        """Solve for concentration given measured absorbance."""
        return measured_A / (self.molar_absorptivity * self.path_length_cm)


def hydrogen_emission_wavelength(n_upper: int, n_lower: int) -> float:
    """
    Calculate emission wavelength for hydrogen atom transitions.
    1/λ = R * (1/n1² - 1/n2²)
    """
    if n_upper <= n_lower:
        raise ValueError("Upper level must be greater than lower level")
    if n_lower < 1:
        raise ValueError("Energy levels must be positive integers")

    inv_wavelength = RYDBERG * (1/n_lower**2 - 1/n_upper**2)
    return 1.0 / inv_wavelength


def hydrogen_series_name(n_lower: int) -> str:
    """Return the name of the hydrogen spectral series."""
    series = {1: 'Lyman', 2: 'Balmer', 3: 'Paschen',
              4: 'Brackett', 5: 'Pfund'}
    return series.get(n_lower, f'n={n_lower} series')


def orbital_energy_hydrogen(n: int) -> float:
    """Energy of hydrogen orbital in eV: E_n = -13.6/n² eV"""
    if n < 1:
        raise ValueError("Principal quantum number must be >= 1")
    return -13.6 / n**2


def main():
    """Demonstrate spectroscopy calculations."""
    print("SPECTROSCOPY AND QUANTUM CHEMISTRY")
    print("=" * 40)

    # Photon properties
    print("\n--- Photon Properties ---")
    wavelengths_nm = [400, 550, 700, 1000, 254]
    for wl_nm in wavelengths_nm:
        photon = PhotonProperties(wl_nm * 1e-9)
        print(f"  {photon} [{photon.spectral_region.value}]")

    # Beer-Lambert law
    print("\n--- Beer-Lambert Law ---")
    sample = BeerLambertData(
        molar_absorptivity=1500,  # L/(mol·cm)
        concentration=1e-4,       # mol/L
        path_length_cm=1.0
    )
    print(f"  Absorbance: {sample.absorbance:.4f}")
    print(f"  Transmittance: {sample.percent_transmittance:.2f}%")
    unknown_conc = sample.concentration_from_absorbance(0.25)
    print(f"  A=0.25 corresponds to c={unknown_conc:.4e} mol/L")

    # Hydrogen emission spectrum
    print("\n--- Hydrogen Emission Spectrum ---")
    for n_lower in [1, 2, 3]:
        series = hydrogen_series_name(n_lower)
        print(f"  {series} Series (n→{n_lower}):")
        for n_upper in range(n_lower + 1, n_lower + 4):
            wl = hydrogen_emission_wavelength(n_upper, n_lower)
            photon = PhotonProperties(wl)
            print(f"    n={n_upper}→{n_lower}: {wl*1e9:.2f} nm [{photon.spectral_region.value}]")

    # Orbital energies
    print("\n--- Hydrogen Orbital Energies ---")
    for n in range(1, 6):
        e = orbital_energy_hydrogen(n)
        print(f"  n={n}: E = {e:.4f} eV")


if __name__ == '__main__':
    main()

