from typing import List, Dict

def calculate_allele_frequencies(genotypes: List[str]) -> Dict[str, float]:
    """
    Calculates allele frequencies from a list of genotypes.

    Args:
        genotypes: A list of genotype strings (e.g., ["AA", "Aa", "aa"]).

    Returns:
        A dictionary with allele names as keys and their frequencies as values.
    """
    allele_counts: Dict[str, int] = {}
    total_alleles = 0

    for genotype in genotypes:
        for allele in genotype:
            allele_counts[allele] = allele_counts.get(allele, 0) + 1
            total_alleles += 1

    if total_alleles == 0:
        return {}

    allele_frequencies: Dict[str, float] = {
        allele: count / total_alleles for allele, count in allele_counts.items()
    }
    return allele_frequencies


