// Calculate the distance between two celestial bodies using the Euclidean distance formula
fn calculate_distance(x1: f64, y1: f64, z1: f64, x2: f64, y2: f64, z2: f64) -> f64 {
    ((x2 - x1).powi(2) + (y2 - y1).powi(2) + (z2 - z1).powi(2)).sqrt()
}

// Convert degrees to radians for use in trigonometric functions
fn degrees_to_radians(degrees: f64) -> f64 {
    degrees * std::f64::consts::PI / 180.0
}

// Calculate the apparent magnitude of a star given its absolute magnitude and distance
fn calculate_apparent_magnitude(absolute_magnitude: f64, distance: f64) -> f64 {
    absolute_magnitude + 5.0 * (1.0 + distance).log10()
}

// Determine if a star is visible to the naked eye based on its apparent magnitude
fn is_star_visible(apparent_magnitude: f64) -> bool {
    apparent_magnitude <= 6.5
}

// Calculate the parallax angle of a star given its distance in parsecs
fn calculate_parallax_angle(distance: f64) -> f64 {
    1.0 / distance
}

// Convert a Julian Date to a Gregorian Date for easier readability
fn julian_to_gregorian(julian_date: f64) -> String {
    // Implementation of the algorithm to convert Julian Date to Gregorian Date
    // ...
}

// Calculate the Doppler shift of a star's light based on its radial velocity
fn calculate_doppler_shift(radial_velocity: f64, wavelength: f64) -> f64 {
    (radial_velocity / 299792458.0) * wavelength
}

// Determine if a celestial body is within the habitable zone of its star
fn is_in_habitable_zone(distance: f64, star_luminosity: f64) -> bool {
    let inner_bound = (star_luminosity / 1.1).sqrt();
    let outer_bound = (star_luminosity / 0.53).sqrt();
    distance >= inner_bound && distance <= outer_bound
}

// Calculate the orbital period of a planet around its star using Kepler's Third Law
fn calculate_orbital_period(semi_major_axis: f64, star_mass: f64) -> f64 {
    ((semi_major_axis.powi(3) / star_mass).sqrt()) * 365.25
}

// Determine the spectral type of a star based on its surface temperature
fn determine_spectral_type(temperature: f64) -> String {
    match temperature {
        t if t >= 30000.0 => "O",
        t if t >= 10000.0 => "B",
        t if t >= 7500.0 => "A",
        t if t >= 6000.0 => "F",
        t if t >= 5200.0 => "G",
        t if t >= 3700.0 => "K",
        _ => "M",
    }.to_string()
}

