// Represents a simple DNA sequence
struct DnaSequence {
    sequence: String,
}

impl DnaSequence {
    fn new(seq_str: &str) -> Result<DnaSequence, &'static str> {
        if seq_str.chars().all(|c| "ATCGatcg".contains(c)) {
            Ok(DnaSequence { sequence: seq_str.to_uppercase() })
        } else {
            Err("Invalid DNA characters found. Only A, T, C, G are allowed.")
        }
    }

    fn complement(&self) -> String {
        self.sequence.chars().map(|c| match c {
            'A' => 'T',
            'T' => 'A',
            'C' => 'G',
            'G' => 'C',
            _ => c, // Should not happen with validation
        }).collect()
    }

    fn len(&self) -> usize {
        self.sequence.len()
    }
}

fn main() {
    print!("Enter a DNA sequence: ");
    io::stdout().flush().unwrap();
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let dna_str = input.trim();

    match DnaSequence::new(dna_str) {
        Ok(dna) => {
            println!("Original DNA: {}", dna.sequence);
            println!("Complementary DNA: {}", dna.complement());
            println!("Sequence length: {}", dna.len());
        }
        Err(e) => {
            eprintln!("Error: {}", e);
        }
    }
}

use std::collections::HashMap;
use std::io::{self, Write};

// Simple codon table for mRNA to amino acid translation
fn translate_codon(codon: &str) -> Option<&'static str> {
    let codon_map: HashMap<&str, &str> = [ // Partial table for brevity
        ("AUG", "Met"), ("UUU", "Phe"), ("UUC", "Phe"),
        ("UUA", "Leu"), ("UUG", "Leu"), ("UCU", "Ser"),
        ("UCC", "Ser"), ("UCA", "Ser"), ("UCG", "Ser"),
        ("UAA", "STOP"), ("UAG", "STOP"), ("UGA", "STOP"),
    ].iter().cloned().collect();
    codon_map.get(codon).copied()
}

fn main() {
    print!("Enter an mRNA sequence (e.g., AUGUUU): ");
    io::stdout().flush().unwrap();
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let mrna_seq = input.trim().to_uppercase();

    if mrna_seq.len() % 3 != 0 {
        eprintln!("Error: mRNA sequence length must be a multiple of 3.");
        return;
    }

    let mut protein_sequence = Vec::new();
    for i in (0..mrna_seq.len()).step_by(3) {
        let codon = &mrna_seq[i..i+3];
        match translate_codon(codon) {
            Some("STOP") => break,
            Some(amino_acid) => protein_sequence.push(amino_acid),
            None => {
                eprintln!("Warning: Unknown codon '{}'. Skipping.", codon);
                // You might choose to stop or indicate an error here
            }
        }
    }
    println!("Translated protein sequence: {}", protein_sequence.join("-"));
}

use std::io::{self, Write};

// Represents a simple cell with a name and a state (alive/dead)
enum CellState {
    Alive,
    Dead,
}

struct Cell {
    name: String,
    state: CellState,
}

impl Cell {
    fn new(name: String) -> Self {
        Cell { name, state: CellState::Alive }
    }

    fn kill(&mut self) {
        self.state = CellState::Dead;
        println!("Cell '{}' has died.", self.name);
    }

    fn describe(&self) -> String {
        match self.state {
            CellState::Alive => format!("Cell '{}' is currently alive.", self.name),
            CellState::Dead => format!("Cell '{}' is no longer alive.", self.name),
        }
    }
}

fn main() {
    print!("Enter a name for the cell: ");
    io::stdout().flush().unwrap();
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let cell_name = input.trim().to_string();

    let mut my_cell = Cell::new(cell_name);
    println!("{}", my_cell.describe());

    print!("Kill the cell? (y/n): ");
    io::stdout().flush().unwrap();
    let mut choice = String::new();
    io::stdin().read_line(&mut choice).expect("Failed to read line");

    if choice.trim().to_lowercase() == "y" {
        my_cell.kill();
    } else {
        println!("Cell '{}' remains alive for now.", my_cell.name);
    }
    println!("{}", my_cell.describe());
}

