#[derive(Debug, Clone)]
struct PeriodicTable {
    elements: HashMap<u8, Element>,
}

impl PeriodicTable {
    fn new() -> Self {
        Self {
            elements: HashMap::new(),
        }
    }

    fn add_element(&mut self, element: Element) -> Result<(), Box<dyn Error>> {
        if self.elements.contains_key(&element.atomic_number) {
            return Err("Element already exists".into());
        }
        self.elements.insert(element.atomic_number, element);
        Ok(())
    }

    fn get_element(&self, atomic_number: u8) -> Option<&Element> {
        self.elements.get(&atomic_number)
    }
}

#[derive(Debug, Clone, PartialEq)]
struct Molecule {
    formula: String,
    composition: HashMap<String, u32>,
    molar_mass: f64,
}

impl Molecule {
    fn from_formula(formula: &str, periodic_table: &PeriodicTable) -> Result<Self, Box<dyn Error>> {
        let mut composition = HashMap::new();
        let mut molar_mass = 0.0;
        let mut i = 0;
        let chars: Vec<char> = formula.chars().collect();

        while i < chars.len() {
            if chars[i].is_uppercase() {
                let mut symbol = chars[i].to_string();
                i += 1;

                if i < chars.len() && chars[i].is_lowercase() {
                    symbol.push(chars[i]);
                    i += 1;
                }

                let mut count = 1;
                if i < chars.len() && chars[i].is_digit(10) {
                    let mut count_str = String::new();
                    while i < chars.len() && chars[i].is_digit(10) {
                        count_str.push(chars[i]);
                        i += 1;
                    }
                    count = count_str.parse::<u32>()?;
                }

                let element = periodic_table.elements.values()
                    .find(|e| e.symbol == symbol)
                    .ok_or_else(|| format!("Element {} not found", symbol))?;

                *composition.entry(symbol).or_insert(0) += count;
                molar_mass += element.atomic_mass * count as f64;
            } else {
                return Err("Invalid formula".into());
            }
        }

        Ok(Self {
            formula: formula.to_string(),
            composition,
            molar_mass,
        })
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut periodic_table = PeriodicTable::new();

    periodic_table.add_element(Element::new("H", 1, 1.008)?)?;
    periodic_table.add_element(Element::new("C", 6, 12.011)?)?;
