        for (formula, coefficient) in &self.reactants {
            Self::add_elements(formula, -(*coefficient), &mut element_counts);
        }

        for (formula, coefficient) in &self.products {
            Self::add_elements(formula, *coefficient, &mut element_counts);
        }

        element_counts.values().all(|&count| count.abs() < 1e-10)
    }

    fn add_elements(formula: &str, multiplier: f64, counts: &mut HashMap<String, f64>) {
