                }

                *counts.entry(symbol).or_insert(0.0) += multiplier * count;
            }
        }
    }

    fn calculate_gibbs_free_energy(&self, temperature: f64) -> Option<f64> {
        match (self.enthalpy_change, self.entropy_change) {
            (Some(Δh), Some(Δs)) => {
                Some(Δh - temperature * Δs / 1000.0)
            }
            _ => None,
        }
