#[derive(Debug, Clone)]
struct Atom {
    symbol: String,
    coordinates: (f64, f64, f64),
    bonds: Vec<Bond>,
}

#[derive(Debug, Clone)]
struct Bond {
    atom_index: usize,
    bond_type: BondType,
}

#[derive(Debug, Clone)]
struct Molecule3D {
    atoms: Vec<Atom>,
    name: String,
}

impl Molecule3D {
    fn new(name: &str) -> Self {
        Self {
            atoms: Vec::new(),
            name: name.to_string(),
        }
    }

    fn add_atom(&mut self, symbol: &str, x: f64, y: f64, z: f64) -> usize {
        let index = self.atoms.len();
        self.atoms.push(Atom {
            symbol: symbol.to_string(),
            coordinates: (x, y, z),
            bonds: Vec::new(),
        });
        index
    }

    fn add_bond(&mut self, atom1: usize, atom2: usize, bond_type: BondType) -> Result<(), Box<dyn Error>> {
        if atom1 >= self.atoms.len() || atom2 >= self.atoms.len() {
            return Err("Invalid atom index".into());
        }

        self.atoms[atom1].bonds.push(Bond {
            atom_index: atom2,
            bond_type,
        });

        self.atoms[atom2].bonds.push(Bond {
            atom_index: atom1,
            bond_type,
        });

        Ok(())
    }

    fn calculate_distance(&self, atom1: usize, atom2: usize) -> Result<f64, Box<dyn Error>> {
        if atom1 >= self.atoms.len() || atom2 >= self.atoms.len() {
            return Err("Invalid atom index".into());
        }

        let (x1, y1, z1) = self.atoms[atom1].coordinates;
        let (x2, y2, z2) = self.atoms[atom2].coordinates;

        let dx = x2 - x1;
        let dy = y2 - y1;
        let dz = z2 - z1;

        Ok((dx*dx + dy*dy + dz*dz).sqrt())
    }

    fn calculate_center_of_mass(&self) -> (f64, f64, f64) {
        let mut total_mass = 0.0;
        let mut weighted_x = 0.0;
        let mut weighted_y = 0.0;
        let mut weighted_z = 0.0;

        let atomic_masses: HashMap<&str, f64> = [
            ("H", 1.008),
            ("C", 12.011),
            ("N", 14.007),
            ("O", 15.999),
        ].iter().cloned().collect();

        for atom in &self.atoms {
            if let Some(&mass) = atomic_masses.get(atom.symbol.as_str()) {
                total_mass += mass;
                let (x, y, z) = atom.coordinates;
                weighted_x += mass * x;
                weighted_y += mass * y;
                weighted_z += mass * z;
            }
        }

        if total_mass > 0.0 {
            (weighted_x / total_mass, weighted_y / total_mass, weighted_z / total_mass)
        } else {
            (0.0, 0.0, 0.0)
        }
    }
}

struct MolecularDynamics {
    molecules: Vec<Molecule3D>,
    temperature: f64,
    time_step: f64,
}

impl MolecularDynamics {
    fn new(temperature: f64, time_step: f64) -> Self {
        Self {
            molecules: Vec::new(),
            temperature,
            time_step,
        }
    }

    fn add_molecule(&mut self, molecule: Molecule3D) {
        self.molecules.push(molecule);
    }

    fn calculate_total_energy(&self) -> f64 {
        let kb = 1.380649e-23; // Boltzmann constant
        let na = 6.02214076e23; // Avogadro's number

        // Simplified kinetic energy calculation
        let kinetic_energy = 1.5 * kb * self.temperature * na as f64;
        kinetic_energy
    }
}

