#[derive(Debug, Clone)]
struct ChemicalSolution {
    solutes: HashMap<String, f64>, // concentration in mol/L
    volume: f64,                    // liters
    temperature: f64,              // Kelvin
    ph: Option<f64>,
}

impl ChemicalSolution {
    fn new(volume: f64, temperature: f64) -> Self {
        Self {
            solutes: HashMap::new(),
            volume,
            temperature,
            ph: None,
        }
    }

    fn add_solute(&mut self, formula: &str, concentration: f64) {
        self.solutes.insert(formula.to_string(), concentration);
        self.ph = None; // Reset pH when solution changes
    }

    fn calculate_ph(&mut self) -> f64 {
        if let Some(ph) = self.ph {
            return ph;
        }

        let mut h_plus = 1e-7; // Default for pure water

        // Simplified pH calculation considering strong acids
        for (formula, &concentration) in &self.solutes {
            if formula == "HCl" || formula == "HNO3" || formula == "H2SO4" {
                // Strong acid - completely dissociates
                h_plus += concentration;
            } else if formula == "NaOH" || formula == "KOH" {
                // Strong base
                h_plus -= concentration;
            }
        }

        let ph = -h_plus.log10();
        self.ph = Some(ph);
        ph
    }

    fn calculate_ionic_strength(&self) -> f64 {
        let mut ionic_strength = 0.0;

        // Simplified ion charges
        let ion_charges: HashMap<&str, i32> = [
            ("Na+", 1), ("K+", 1), ("H+", 1),
            ("Cl-", -1), ("OH-", -1), ("NO3-", -1),
            ("SO4(2-)", -2), ("CO3(2-)", -2),
        ].iter().cloned().collect();

        for (formula, &concentration) in &self.solutes {
            if let Some(&charge) = ion_charges.get(formula.as_str()) {
                ionic_strength += 0.5 * concentration * (charge * charge) as f64;
            }
        }

        ionic_strength
    }
}

struct Titration {
    analyte: ChemicalSolution,
    titrant: ChemicalSolution,
    equivalence_point: Option<f64>, // volume at equivalence point
}

impl Titration {
    fn new(analyte: ChemicalSolution, titrant: ChemicalSolution) -> Self {
        Self {
            analyte,
            titrant,
            equivalence_point: None,
        }
    }

    fn calculate_titration_curve(&self, volume_increments: usize) -> Vec<(f64, f64)> {
        let mut curve = Vec::new();
        let total_volume = self.analyte.volume;

        for i in 0..=volume_increments {
            let volume_added = (i as f64 / volume_increments as f64) * total_volume;

            // Simplified titration calculation
            let mut mixed_solution = self.analyte.clone();
            mixed_solution.volume += volume_added;

            // Adjust concentrations
            for (formula, concentration) in &mut mixed_solution.solutes {
                *concentration *= self.analyte.volume / mixed_solution.volume;
            }

            // Add titrant contributions
            for (formula, concentration) in &self.titrant.solutes {
                let added_concentration = concentration * volume_added / mixed_solution.volume;
                *mixed_solution.solutes.entry(formula.clone()).or_insert(0.0) += added_concentration;
            }

            let ph = mixed_solution.calculate_ph();
            curve.push((volume_added, ph));
        }

        curve
    }
}

