#[derive(Debug, Clone, Copy, PartialEq)]
enum CrystalSystem {
    Cubic,
    Tetragonal,
    Orthorhombic,
    Hexagonal,
    Trigonal,
    Monoclinic,
    Triclinic,
}

#[derive(Debug, Clone)]
struct CrystalStructure {
    system: CrystalSystem,
    lattice_constants: (f64, f64, f64), // a, b, c in Ångströms
    angles: (f64, f64, f64),           // α, β, γ in degrees
    atoms: Vec<CrystalAtom>,
    space_group: String,
}

#[derive(Debug, Clone)]
struct CrystalAtom {
    element: String,
    position: (f64, f64, f64), // fractional coordinates
    occupancy: f64,
    thermal_factor: f64,
}

impl CrystalStructure {
    fn new(system: CrystalSystem, a: f64, b: f64, c: f64, 
           alpha: f64, beta: f64, gamma: f64, space_group: &str) -> Self {
        Self {
            system,
            lattice_constants: (a, b, c),
            angles: (alpha, beta, gamma),
            atoms: Vec::new(),
            space_group: space_group.to_string(),
        }
    }

    fn add_atom(&mut self, element: &str, x: f64, y: f64, z: f64, 
                occupancy: f64, thermal_factor: f64) {
        self.atoms.push(CrystalAtom {
            element: element.to_string(),
            position: (x, y, z),
            occupancy,
            thermal_factor,
        });
    }

    fn calculate_density(&self) -> f64 {
        let atomic_masses: HashMap<&str, f64> = [
            ("Na", 22.990), ("Cl", 35.453),
            ("Si", 28.086), ("O", 15.999),
            ("C", 12.011), ("H", 1.008),
        ].iter().cloned().collect();

        let (a, b, c) = self.lattice_constants;
        let (alpha, beta, gamma) = self.angles;

        // Calculate unit cell volume
        let volume = self.calculate_unit_cell_volume();

        // Calculate total mass in unit cell
        let mut total_mass = 0.0;
        for atom in &self.atoms {
            if let Some(&mass) = atomic_masses.get(atom.element.as_str()) {
                total_mass += mass * atom.occupancy;
            }
        }

        // Convert to g/cm³ (1 Å³ = 1e-24 cm³)
        let density_g_per_cm3 = total_mass / (volume * 1e-24);
        density_g_per_cm3
    }

    fn calculate_unit_cell_volume(&self) -> f64 {
        let (a, b, c) = self.lattice_constants;
        let (alpha, beta, gamma) = self.angles;

        let alpha_rad = alpha.to_radians();
        let beta_rad = beta.to_radians();
        let gamma_rad = gamma.to_radians();

        match self.system {
            CrystalSystem::Cubic => a * a * a,
            CrystalSystem::Tetragonal => a * a * c,
            CrystalSystem::Orthorhombic => a * b * c,
            _ => {
                // General triclinic formula
                let volume = a * b * c * (
                    1.0 - alpha_rad.cos().powi(2) - beta_rad.cos().powi(2) - gamma_rad.cos().powi(2)
                    + 2.0 * alpha_rad.cos() * beta_rad.cos() * gamma_rad.cos()
                ).sqrt();
                volume
            }
        }
    }

    fn calculate_interatomic_distance(&self, atom1: usize, atom2: usize) -> Option<f64> {
        if atom1 >= self.atoms.len() || atom2 >= self.atoms.len() {
            return None;
        }

        let (x1, y1, z1) = self.atoms[atom1].position;
        let (x2, y2, z2) = self.atoms[atom2].position;

        let (a, b, c) = self.lattice_constants;
        let (alpha, beta, gamma) = self.angles;

        // Convert fractional to Cartesian coordinates
        // Simplified for orthogonal systems
        let dx = (x2 - x1) * a;
        let dy = (y2 - y1) * b;
        let dz = (z2 - z1) * c;

        Some((dx*dx + dy*dy + dz*dz).sqrt())
    }
}

struct XRayDiffraction {
    wavelength: f64, // in Ångströms
    theta_range: (f64, f64), // in degrees
}

impl XRayDiffraction {
    fn new(wavelength: f64) -> Self {
        Self {
            wavelength,
            theta_range: (0.0, 90.0),
        }
    }

    fn calculate_bragg_angle(&self, d_spacing: f64, n: i32) -> Option<f64> {
        if d_spacing <= 0.0 || n <= 0 {
            return None;
        }

        let sin_theta = (n as f64 * self.wavelength) / (2.0 * d_spacing);
        if sin_theta.abs() <= 1.0 {
            Some(sin_theta.asin().to_degrees())
        } else {
            None
        }
    }
}

