use std::f64::consts::E;

#[derive(Debug, Clone, Copy, PartialEq)]
enum ReactionOrder {
    Zero,
    First,
    Second,
    Nth(f64),
}

#[derive(Debug, Clone)]
struct ChemicalKinetics {
    reactants: HashMap<String, f64>, // initial concentrations
    rate_constant: f64,
    order: ReactionOrder,
    activation_energy: f64, // kJ/mol
    pre_exponential: f64,   // Arrhenius factor
}

impl ChemicalKinetics {
    fn new(reactants: HashMap<String, f64>, rate_constant: f64, order: ReactionOrder) -> Self {
        Self {
            reactants,
            rate_constant,
            order,
            activation_energy: 0.0,
            pre_exponential: 0.0,
        }
    }

    fn calculate_rate(&self, concentrations: &HashMap<String, f64>) -> f64 {
        match self.order {
            ReactionOrder::Zero => self.rate_constant,
            ReactionOrder::First => {
                let reactant = self.reactants.keys().next().unwrap();
                self.rate_constant * concentrations.get(reactant).unwrap_or(&0.0)
            }
            ReactionOrder::Second => {
                let mut product = 1.0;
                for reactant in self.reactants.keys() {
                    product *= concentrations.get(reactant).unwrap_or(&0.0);
                }
                self.rate_constant * product
            }
            ReactionOrder::Second => {
                let mut product = 1.0;
                for reactant in self.reactants.keys() {
                    product *= concentrations.get(reactant).unwrap_or(&0.0);
                }
                self.rate_constant * product
            }
            ReactionOrder::Nth(n) => {
                let reactant = self.reactants.keys().next().unwrap();
                let concentration = concentrations.get(reactant).unwrap_or(&0.0);
                self.rate_constant * concentration.powf(n)
            }
        }
    }

    fn integrate_rate_law(&self, time: f64) -> HashMap<String, f64> {
        let mut result = HashMap::new();
        let r = 8.314462618; // J/(mol·K)

        match self.order {
            ReactionOrder::Zero => {
                for (reactant, &initial) in &self.reactants {
                    let remaining = initial - self.rate_constant * time;
                    result.insert(reactant.clone(), remaining.max(0.0));
                }
            }
            ReactionOrder::First => {
                for (reactant, &initial) in &self.reactants {
                    let remaining = initial * E.powf(-self.rate_constant * time);
                    result.insert(reactant.clone(), remaining);
                }
            }
            ReactionOrder::Second => {
                for (reactant, &initial) in &self.reactants {
                    let remaining = initial / (1.0 + self.rate_constant * initial * time);
                    result.insert(reactant.clone(), remaining);
                }
            }
            ReactionOrder::Nth(n) => {
                for (reactant, &initial) in &self.reactants {
                    if n != 1.0 {
                        let remaining = (initial.powf(1.0 - n) + (n - 1.0) * self.rate_constant * time)
                            .powf(1.0 / (1.0 - n));
                        result.insert(reactant.clone(), remaining.max(0.0));
                    }
                }
            }
        }

        result
    }

    fn calculate_half_life(&self) -> f64 {
        match self.order {
            ReactionOrder::Zero => {
                let initial = self.reactants.values().next().unwrap_or(&0.0);
                initial / (2.0 * self.rate_constant)
            }
            ReactionOrder::First => (2.0_f64.ln()) / self.rate_constant,
            ReactionOrder::Second => {
                let initial = self.reactants.values().next().unwrap_or(&0.0);
                1.0 / (self.rate_constant * initial)
            }
            ReactionOrder::Nth(n) => {
                let initial = self.reactants.values().next().unwrap_or(&0.0);
                (2.0_f64.powf(n - 1.0) - 1.0) / ((n - 1.0) * self.rate_constant * initial.powf(n - 1.0))
            }
        }
    }

    fn arrhenius_equation(&self, temperature: f64) -> f64 {
        let r = 8.314462618e-3; // kJ/(mol·K)
        self.pre_exponential * E.powf(-self.activation_energy / (r * temperature))
    }
}

struct ReactionMonitor {
    kinetics: ChemicalKinetics,
    temperature: f64,
    time_points: Vec<f64>,
}

impl ReactionMonitor {
    fn new(kinetics: ChemicalKinetics, temperature: f64) -> Self {
        Self {
            kinetics,
            temperature,
            time_points: Vec::new(),
        }
    }

    fn simulate_reaction(&mut self, end_time: f64, num_points: usize) -> Vec<HashMap<String, f64>> {
        let mut results = Vec::new();

        for i in 0..=num_points {
            let time = (i as f64 / num_points as f64) * end_time;
            self.time_points.push(time);

            let concentrations = self.kinetics.integrate_rate_law(time);
            results.push(concentrations);
        }

        results
    }

    fn calculate_reaction_rate_at_time(&self, time: f64) -> f64 {
        let concentrations = self.kinetics.integrate_rate_law(time);
        self.kinetics.calculate_rate(&concentrations)
    }
}

