#[derive(Debug, Clone, Copy, PartialEq)]
enum OrbitalType {
    S,
    P,
    D,
    F,
}

#[derive(Debug, Clone)]
struct AtomicOrbital {
    n: u8,           // principal quantum number
    l: u8,           // azimuthal quantum number
    m: i8,           // magnetic quantum number
    orbital_type: OrbitalType,
    energy: f64,     // Hartree
    nodes: u8,
}

impl AtomicOrbital {
    fn new(n: u8, l: u8, m: i8) -> Option<Self> {
        if n == 0 || l >= n || m.abs() > l as i8 {
            return None;
        }

        let orbital_type = match l {
            0 => OrbitalType::S,
            1 => OrbitalType::P,
            2 => OrbitalType::D,
            3 => OrbitalType::F,
            _ => OrbitalType::S,
        };

        let energy = -(1.0 / (n as f64).powi(2)); // Simplified hydrogen-like
        let nodes = n - l - 1;

        Some(Self {
            n,
            l,
            m,
            orbital_type,
            energy,
            nodes,
        })
    }

    fn calculate_radial_function(&self, r: f64, z: f64) -> f64 {
        let a0 = 0.52917721067; // Bohr radius in Ångströms
        let rho = 2.0 * z * r / (self.n as f64 * a0);

        // Simplified radial function for hydrogen-like atoms
        match self.orbital_type {
            OrbitalType::S => {
                let normalization = (z.powi(3) / (PI * a0.powi(3))).sqrt() / (self.n as f64).powf(1.5);
                normalization * (-rho / 2.0).exp()
            }
            OrbitalType::P => {
                let normalization = (z.powi(5) / (32.0 * PI * a0.powi(5))).sqrt() / (self.n as f64).powf(2.5);
                normalization * rho * (-rho / 2.0).exp()
            }
            _ => 0.0 // Simplified
        }
    }
}

#[derive(Debug, Clone)]
struct ElectronConfiguration {
    element: String,
    atomic_number: u8,
    orbitals: Vec<(AtomicOrbital, u8)>, // orbital and electron count
    total_energy: f64,
}

impl ElectronConfiguration {
    fn new(element: &str, atomic_number: u8) -> Self {
        let mut orbitals = Vec::new();
        let mut electrons_remaining = atomic_number as i32;
        let mut total_energy = 0.0;

        // Aufbau principle ordering
        let orbital_order = vec![
            (1, 0), // 1s
            (2, 0), // 2s
            (2, 1), // 2p
            (3, 0), // 3s
            (3, 1), // 3p
            (4, 0), // 4s
            (3, 2), // 3d
            (4, 1), // 4p
            (5, 0), // 5s
            (4, 2), // 4d
            (5, 1), // 5p
            (6, 0), // 6s
            (4, 3), // 4f
            (5, 2), // 5d
            (6, 1), // 6p
            (7, 0), // 7s
            (5, 3), // 5f
            (6, 2), // 6d
        ];

        for (n, l) in orbital_order {
            if electrons_remaining <= 0 {
                break;
            }

            let orbital = AtomicOrbital::new(n, l, 0).unwrap();
            let max_electrons = 2 * (2 * l + 1);
            let electrons = electrons_remaining.min(max_electrons as i32) as u8;

            orbitals.push((orbital, electrons));
            total_energy += orbital.energy * electrons as f64;
            electrons_remaining -= electrons as i32;
        }

        Self {
            element: element.to_string(),
            atomic_number,
            orbitals,
            total_energy,
        }
    }

    fn get_valence_electrons(&self) -> u8 {
        let mut valence = 0;

        // Simplified valence electron calculation
        for (orbital, electrons) in &self.orbitals {
            if orbital.n >= self.orbitals.last().unwrap().0.n.saturating_sub(2) {
                valence += electrons;
            }
        }

        valence
    }
}

struct QuantumChemistry {
    elements: HashMap<String, ElectronConfiguration>,
}

impl QuantumChemistry {
    fn new() -> Self {
        Self {
            elements: HashMap::new(),
        }
    }

    fn add_element(&mut self, element: ElectronConfiguration) {
        self.elements.insert(element.element.clone(), element);
    }

    fn calculate_ionization_energy(&self, element: &str) -> Option<f64> {
        self.elements.get(element).map(|config| {
            // Simplified: energy of highest occupied orbital
            config.orbitals.last().map(|(orbital, _)| -orbital.energy).unwrap_or(0.0)
        })
    }
}

