impl NMRCalculator {
    fn new(reference_frequency: f64) -> Self {
        let mut ratios = HashMap::new();
        ratios.insert("1H".to_string(), 42.577);
        ratios.insert("13C".to_string(), 10.705);
        ratios.insert("15N".to_string(), -4.316);
        ratios.insert("19F".to_string(), 40.078);
        ratios.insert("31P".to_string(), 17.235);

        Self {
            gyromagnetic_ratios,
            reference_frequency,
        }
    }

    fn calculate_chemical_shift(&self, nucleus: &str, frequency: f64) -> f64 {
        let gamma = self.gyromagnetic_ratios.get(nucleus).unwrap_or(&42.577);
        let reference_frequency = gamma * self.reference_frequency / 42.577; // Normalized to 1H

        (reference_frequency - frequency) / reference_frequency * 1e6 // ppm
    }
}

