#[derive(Debug, Clone, Copy, PartialEq)]
enum Phase {
    Solid,
    Liquid,
    Gas,
    Supercritical,
}

#[derive(Debug, Clone)]
struct ThermodynamicSystem {
    temperature: f64,      // Kelvin
    pressure: f64,         // Pa
    volume: f64,          // m³
    moles: f64,           // mol
    phase: Phase,
    heat_capacity: f64,   // J/(mol·K)
}

impl ThermodynamicSystem {
    fn new(temperature: f64, pressure: f64, volume: f64, moles: f64) -> Self {
        let phase = if temperature < 273.15 && pressure < 101325.0 {
            Phase::Solid
        } else if temperature < 373.15 && pressure >= 101325.0 {
            Phase::Liquid
        } else {
            Phase::Gas
        };

        Self {
            temperature,
            pressure,
            volume,
            moles,
            phase,
            heat_capacity: 0.0,
        }
    }

    fn calculate_internal_energy(&self) -> f64 {
        let r = 8.314462618; // J/(mol·K)
        match self.phase {
            Phase::Gas => 1.5 * self.moles * r * self.temperature,
            Phase::Liquid => 0.0, // Simplified
            Phase::Solid => 0.0,  // Simplified
            Phase::Supercritical => 2.0 * self.moles * r * self.temperature,
        }
    }

    fn calculate_enthalpy(&self) -> f64 {
        let r = 8.314462618;
        match self.phase {
            Phase::Gas => 2.5 * self.moles * r * self.temperature,
            Phase::Liquid => self.moles * self.heat_capacity * self.temperature,
            Phase::Solid => self.moles * self.heat_capacity * self.temperature,
            Phase::Supercritical => 3.0 * self.moles * r * self.temperature,
        }
    }

    fn calculate_entropy_change(&self, initial_temperature: f64) -> f64 {
        if self.heat_capacity > 0.0 {
            self.moles * self.heat_capacity * (self.temperature / initial_temperature).ln()
        } else {
            0.0
        }
    }

    fn calculate_gibbs_free_energy(&self) -> f64 {
        self.calculate_enthalpy() - self.temperature * self.calculate_entropy_change(298.15)
    }
}

