    cold_reservoir: ThermodynamicSystem,
    efficiency: f64,
}

impl HeatEngine {
    fn new(hot_temp: f64, cold_temp: f64) -> Self {
        Self {
            hot_reservoir: ThermodynamicSystem::new(hot_temp, 101325.0, 0.1, 1.0),
            cold_reservoir: ThermodynamicSystem::new(cold_temp, 101325.0, 0.1, 1.0),
            efficiency: 0.0,
        }
    }

    fn calculate_carnot_efficiency(&self) -> f64 {
        let th = self.hot_reservoir.temperature;
        let tc = self.cold_reservoir.temperature;

        if th > 0.0 && tc > 0.0 {
            1.0 - (tc / th)
        } else {
            0.0
        }
    }

    fn calculate_work_output(&self, heat_input: f64) -> f64 {
        self.calculate_carnot_efficiency() * heat_input
    }
}

