struct OrganicMolecule {
    name: String,
    formula: String,
    functional_groups: Vec<FunctionalGroup>,
    chiral_centers: Vec<ChiralCenter>,
    stereochemistry: Stereochemistry,
}

#[derive(Debug, Clone, PartialEq)]
enum FunctionalGroup {
    Alcohol,
    Aldehyde,
    Ketone,
    CarboxylicAcid,
    Amine,
    Alkene,
    Alkyne,
    Halide,
}

