enum Chirality {
    R,
    S,
    Achiral,
}

#[derive(Debug, Clone)]
struct ChiralCenter {
    atom_index: usize,
    chirality: Chirality,
    priority: [u8; 4],
}

#[derive(Debug, Clone, PartialEq)]
enum Stereochemistry {
    Racemic,
    Enantiopure(Chirality),
    Meso,
    Diastereomeric,
}

impl OrganicMolecule {
    fn new(name: &str, formula: &str) -> Self {
        Self {
            name: name.to_string(),
            formula: formula.to_string(),
            functional_groups: Vec::new(),
            chiral_centers: Vec::new(),
            stereochemistry: Stereochemistry::Racemic,
        }
    }

    fn add_functional_group(&mut self, group: FunctionalGroup) {
        self.functional_groups.push(group);
    }

    fn add_chiral_center(&mut self, atom_index: usize, priority: [u8; 4]) {
        let chirality = Self::determine_chirality(&priority);
        self.chiral_centers.push(ChiralCenter {
            atom_index,
            chirality,
            priority,
        });

        // Update stereochemistry
        if self.chiral_centers.len() == 1 {
            self.stereochemistry = Stereochemistry::Enantiopure(chirality);
        } else if self.chiral_centers.len() > 1 {
            self.stereochemistry = Stereochemistry::Diastereomeric;
        }
    }

    fn determine_chirality(priority: &[u8; 4]) -> Chirality {
        // Simplified Cahn-Ingold-Prelog rules
        let mut sorted = priority.clone();
        sorted.sort_unstable();

        if sorted[0] == sorted[3] {
            Chirality::Achiral
        } else {
            // Determine R/S based on priority order
            let sum: u8 = priority.iter().sum();
            if sum % 2 == 0 {
                Chirality::R
            } else {
                Chirality::S
            }
        }
    }

    fn predict_reactivity(&self, mechanism: ReactionMechanism) -> f64 {
        let mut reactivity_score = 1.0;

        match mechanism {
            ReactionMechanism::SN1 => {
                // SN1 favors tertiary carbocations
                reactivity_score *= 0.8;
                if self.functional_groups.contains(&FunctionalGroup::Halide) {
                    reactivity_score *= 1.5;
                }
            }
            ReactionMechanism::SN2 => {
                // SN2 favors primary substrates
                reactivity_score *= 1.2;
                if self.functional_groups.contains(&FunctionalGroup::Alcohol) {
                    reactivity_score *= 0.7;
                }
            }
            ReactionMechanism::E1 => {
                // E1 favors tertiary substrates
                reactivity_score *= 0.9;
                if self.functional_groups.contains(&FunctionalGroup::Alkene) {
                    reactivity_score *= 1.3;
                }
            }
            ReactionMechanism::E2 => {
                // E2 favors anti-periplanar elimination
                reactivity_score *= 1.1;
            }
            _ => {
                reactivity_score *= 1.0;
            }
        }

        reactivity_score
    }
}

