// Computes Shannon-Wiener and Simpson's diversity indices
use std::collections::HashMap;

fn calculate_shannon(species_counts: &HashMap<String, u32>) -> f64 {
    let total: u32 = species_counts.values().sum();
    let mut index = 0.0;

    for &count in species_counts.values() {
        if count > 0 {
            let proportion = count as f64 / total as f64;
            index -= proportion * proportion.ln();
        }
    }
    index
}

fn calculate_simpson(species_counts: &HashMap<String, u32>) -> f64 {
    let total: u32 = species_counts.values().sum();
    let mut index = 0.0;

    for &count in species_counts.values() {
        if total > 0 {
            let proportion = count as f64 / total as f64;
            index += proportion.powi(2);
        }
    }
    index
}

