    "text": "// Ocean Acidification Impact Model
// Simulates pH changes and calcification impacts
struct OceanModel {
    current_ph: f64,
    co2_emissions: f64, // in GtCO2/year
    buffer_capacity: f64,
}

impl OceanModel {
    fn new(initial_ph: f64) -> Self {
        OceanModel {
            current_ph: initial_ph,
            co2_emissions: 36.0, // Current global average
            buffer_capacity: 0.1,
        }
    }

    fn update_ph(&mut self, years: u32) {
        for year in 1..=years {
            let ph_change = -self.buffer_capacity * 
                          (self.co2_emissions / 1000.0).ln();
            self.current_ph += ph_change;
            println!("Year {}: Projected pH = {:.2}", year, self.current_ph);

            // Calcification impact calculation
            let calcification = 100.0 * (10.0_f64.powf(self.current_ph - 8.1));
            println!("Calcification rate: {:.1}% of pre-industrial", calcification);
        }
    }
}

fn main() {
    let mut pacific = OceanModel::new(8.1);
    pacific.update_ph(5);
}"
