    "text": "// Marine Genetic Diversity Simulator
// Models genetic drift in isolated populations
use rand::distributions::{Distribution, Uniform};

struct Population {
    size: u32,
    allele_frequency: f64,
    mutation_rate: f64,
}

impl Population {
    fn new(initial_freq: f64) -> Self {
        Population {
            size: 1000,
            allele_frequency: initial_freq,
            mutation_rate: 0.001,
        }
    }

    fn evolve(&mut self, generations: u32) {
        let mut rng = rand::thread_rng();
        let dist = Uniform::new(0.0, 1.0);

        for gen in 1..=generations {
            // Genetic drift simulation
            let mut new_freq = self.allele_frequency;
            for _ in 0..self.size {
                if dist.sample(&mut rng) < self.mutation_rate {
                    new_freq += if dist.sample(&mut rng) < 0.5 { 0.01 } else { -0.01 };
                }
            }
            self.allele_frequency = new_freq.max(0.0).min(1.0);
            println!("Generation {}: Allele frequency = {:.4}", 
                     gen, self.allele_frequency);
        }
    }
}

fn main() {
    let mut coral_pop = Population::new(0.5);
    coral_pop.evolve(10);
}"
