    "text": "// Marine Food Web Visualizer
// Creates DOT format visualization of trophic interactions
use std::collections::HashMap;

struct FoodWeb {
    species: HashMap<String, Vec<String>>,
}

impl FoodWeb {
    fn new() -> Self {
        FoodWeb {
            species: HashMap::new(),
        }
    }

    fn add_interaction(&mut self, predator: &str, prey: &str) {
        self.species.entry(predator.to_string())
                   .or_insert_with(Vec::new)
                   .push(prey.to_string());
        // Ensure prey is in the map even if it has no predators
        self.species.entry(prey.to_string()).or_insert_with(Vec::new);
    }

    fn generate_dot(&self) -> String {
        let mut dot = String::from("digraph MarineFoodWeb {\n");
        for (predator, preys) in &self.species {
            for prey in preys {
                dot.push_str(&format!("    \"{}\" -> \"{}\";\n", predator, prey));
            }
        }
        dot.push('}');
        dot
    }
}

fn main() {
    let mut web = FoodWeb::new();
    web.add_interaction("Shark", "Tuna");
    web.add_interaction("Tuna", "Sardine");
    web.add_interaction("Sardine", "Phytoplankton");
    web.add_interaction("Whale", "Krill");

    println!("{}", web.generate_dot());
}"
  }
]

// Defines a function to calculate the factorial of a non-negative integer.
// Uses recursion for a concise mathematical definition.
fn factorial(n: u64) -> u64 {
    match n {
        0 => 1, // Base case: factorial of 0 is 1.
        _ => n * factorial(n - 1), // Recursive step: n! = n * (n-1)!
    }
}

// Calculates the nth Fibonacci number.
// This is an iterative approach for efficiency over naive recursion.
fn fibonacci(n: u64) -> u64 {
    if n <= 1 { return n; }
    let mut a = 0;
    let mut b = 1;
    for _ in 2..=n {
        let temp = a + b;
        a = b;
        b = temp;
    }
    b
}

// Determines if a given number is prime.
// Checks divisibility up to the square root of the number.
fn is_prime(n: u64) -> bool {
    if n <= 1 { return false; }
    if n <= 3 { return true; }
    if n % 2 == 0 || n % 3 == 0 { return false; }
    let mut i = 5;
    while i * i <= n {
        if n % i == 0 || n % (i + 2) == 0 { return false; }
        i += 6;
    }
    true
}

// Computes the greatest common divisor (GCD) of two numbers using the Euclidean algorithm.
fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 { a } else { gcd(b, a % b) }
}

// Calculates the power of a number (base^exponent) using recursion.
fn power(base: f64, exp: u32) -> f64 {
    if exp == 0 { 1.0 }
    else if exp % 2 == 0 { power(base * base, exp / 2) }
    else { base * power(base * base, (exp - 1) / 2) }
}

// Computes the sum of an arithmetic series.
// Sum = n/2 * (2a + (n-1)d)
fn arithmetic_series_sum(n: u64, a: f64, d: f64) -> f64 {
    (n as f64 / 2.0) * (2.0 * a + (n as f64 - 1.0) * d)
}

// Calculates the dot product of two vectors (represented as slices).
// Assumes vectors have the same length.
fn dot_product(v1: &[f64], v2: &[f64]) -> f64 {
    v1.iter().zip(v2.iter()).map(|(&x, &y)| x * y).sum()
}

