:root {
    /* Atomic color palette */
    --proton-red: #ff6b6b;
    --neutron-gray: #8395a7;
    --electron-blue: #54a0ff;
    --orbital-purple: #5f27cd;
    --reaction-green: #1dd1a1;
    --hazard-yellow: #feca57;
    --lab-white: #f5f6fa;

    /* Periodic table spacing system */
    --atomic-unit: 8px;
    --molecular-unit: calc(var(--atomic-unit) * 2);
    --compound-unit: calc(var(--atomic-unit) * 3);
    --reaction-unit: calc(var(--atomic-unit) * 5);

    /* Bond angles for transforms */
    --bond-angle-109: 109.5deg;
    --bond-angle-120: 120deg;
    --bond-angle-180: 180deg;
}

/* Base atomic reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Courier New', monospace;
}

body {
    background-color: var(--lab-white);
    color: #2d3436;
    line-height: 1.6;
    padding: var(--reaction-unit);
}

/* Periodic table grid system */
.periodic-table {
    display: grid;
    grid-template-columns: repeat(18, 1fr);
    grid-gap: var(--atomic-unit);
    max-width: 1200px;
    margin: 0 auto;
}

.element-cell {
    background: linear-gradient(145deg, #ffffff, #f0f0f0);
    border-radius: 4px;
    padding: var(--atomic-unit);
    text-align: center;
    transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    border: 2px solid transparent;
    position: relative;
    overflow: hidden;
}

.element-cell:hover {
    transform: translateY(-4px) scale(1.05);
    box-shadow: 0 10px 20px rgba(0,0,0,0.1);
    border-color: var(--electron-blue);
}

.element-symbol {
    font-size: 1.5rem;
    font-weight: bold;
    color: var(--proton-red);
    margin-bottom: calc(var(--atomic-unit) / 2);
}

.element-number {
    font-size: 0.8rem;
    color: var(--neutron-gray);
    position: absolute;
    top: 4px;
    left: 4px;
}

.element-name {
    font-size: 0.7rem;
    color: #636e72;
    margin-top: calc(var(--atomic-unit) / 2);
}

/* Chemical bond styling */
.chemical-bond {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: var(--molecular-unit) 0;
}

.bond-line {
    height: 3px;
