.reaction-arrow {
    font-size: 2rem;
    color: var(--reaction-green);
    margin: 0 var(--compound-unit);
    animation: pulse 2s infinite;
}

@keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
}

