/* Glassware components */
.glassware {
    background: rgba(52, 152, 219, 0.1);
    border-radius: 12px;
    padding: var(--lab-bench);
    border: var(--glass-border);
    backdrop-filter: var(--glass-blur);
    position: relative;
    transition: transform 0.3s ease;
}

.glassware:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);
}

.beaker {
    border-top: 3px solid var(--beaker-blue);
}

.flask {
    border-top: 3px solid var(--flask-green);
}

.pipette {
    border-top: 3px solid var(--pipette-purple);
}

/* Liquid levels */
.liquid-level {
    height: 40px;
    width: 100%;
    background: linear-gradient(to bottom, var(--beaker-blue), #2980b9);
    border-radius: 0 0 8px 8px;
    margin-top: var(--lab-bench);
    position: relative;
    overflow: hidden;
}

.liquid-level::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 4px;
    background: rgba(255, 255, 255, 0.3);
    animation: wave 2s infinite linear;
}

@keyframes wave {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(100%); }
}

/* Bunsen burner flame */
.bunsen-burner {
    width: 60px;
    height: 100px;
    margin: var(--safety-gap) auto;
    position: relative;
}

.flame {
    width: 40px;
    height: 80px;
    background: linear-gradient(to top, #ff9a00, #ff5500, #ff0000);
    border-radius: 50% 50% 20% 20%;
    margin: 0 auto;
    position: relative;
    animation: flicker 0.5s infinite alternate;
}

@keyframes flicker {
    0% { transform: scaleY(1); opacity: 0.9; }
    100% { transform: scaleY(1.1); opacity: 1; }
}

.flame::before,
.flame::after {
    content: '';
    position: absolute;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 50%;
}

.flame::before {
    width: 20px;
    height: 20px;
    top: 10px;
    left: 10px;
}

.flame::after {
    width: 10px;
    height: 10px;
    top: 30px;
    left: 15px;
}

/* Centrifuge animation */
.centrifuge {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    background: var(--centrifuge-silver);
    margin: var(--safety-gap) auto;
    position: relative;
    overflow: hidden;
}

.centrifuge-spinner {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: conic-gradient(
        #3498db,
        #2ecc71,
        #e74c3c,
        #f39c12,
        #9b59b6,
        #3498db
    );
    position: absolute;
    top: 10px;
    left: 10px;
    animation: spin 2s linear infinite;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

/* Fume hood ventilation */
.fume-hood {
    grid-column: 3;
    grid-row: 2;
    background: linear-gradient(to bottom, #34495e, #2c3e50);
    padding: var(--equipment-padding);
    border-left: 3px solid var(--bunsen-orange);
}

.ventilation-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px;
    margin-top: var(--lab-bench);
}

.vent {
    background: rgba(255, 255, 255, 0.1);
    height: 20px;
    border-radius: 2px;
    animation: ventFlow 3s infinite alternate;
}

@keyframes ventFlow {
    0% { opacity: 0.3; }
    100% { opacity: 0.8; }
}

/* Laboratory controls */
.lab-controls {
    display: flex;
    gap: var(--lab-bench);
    margin-top: var(--cabinet-margin);
}

.control-knob {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, #95a5a6, #7f8c8d);
    border: 3px solid #636e72;
    position: relative;
    cursor: pointer;
}

.control-knob::after {
    content: '';
    position: absolute;
    top: 5px;
    left: 50%;
    transform: translateX(-50%);
    width: 3px;
    height: 20px;
    background: #2c3e50;
}

/* Measurement indicators */
.measurement-scale {
    height: 200px;
    width: 20px;
    background: linear-gradient(to bottom, #27ae60, #e74c3c);
    margin: var(--safety-gap) auto;
    position: relative;
    border-radius: 10px;
}

.measurement-marker {
    position: absolute;
    left: 0;
    right: 0;
    height: 2px;
    background: white;
}

.marker-label {
    position: absolute;
    right: -30px;
    transform: translateY(-50%);
    font-size: 0.8rem;
    color: #2c3e50;
}

/* Safety equipment */
.safety-gear {
    background: rgba(231, 76, 60, 0.1);
    padding: var(--lab-bench);
    border-radius: 8px;
    margin-top: var(--safety-gap);
    border-left: 4px solid #e74c3c;
}

/* Emergency stop button */
.emergency-stop {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, #e74c3c, #c0392b);
    margin: var(--safety-gap) auto;
    border: 8px solid #2c3e50;
    cursor: pointer;
    position: relative;
    animation: pulseEmergency 2s infinite;
}

@keyframes pulseEmergency {
    0%, 100% { box-shadow: 0 0 0 0 rgba(231, 76, 60, 0.7); }
    50% { box-shadow: 0 0 0 20px rgba(231, 76, 60, 0); }
}

.emergency-stop::before {
    content: 'STOP';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: white;
    font-weight: bold;
    font-size: 1.2rem;
}

/* Data display panel */
.data-panel {
    background: rgba(0, 0, 0, 0.8);
    color: #00ff00;
    padding: var(--lab-bench);
    border-radius: 8px;
    font-family: 'Courier New', monospace;
    margin-top: var(--safety-gap);
    overflow: hidden;
}

.data-stream {
    height: 200px;
    overflow-y: auto;
    padding: var(--lab-bench);
    background: rgba(0, 0, 0, 0.5);
    border-radius: 4px;
}

.data-point {
    padding: 4px 0;
    border-bottom: 1px solid rgba(0, 255, 0, 0.2);
}

/* Laboratory lighting */
.lab-lighting {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
    background: radial-gradient(
        circle at 20% 80%,
        rgba(255, 255, 255, 0.1) 0%,
        transparent 50%
    );
    z-index: 1000;
}

/* Mobile laboratory layout */
@media (max-width: 1024px) {
    .lab-container {
        grid-template-columns: 200px 1fr;
        grid-template-rows: 60px 1fr 50px;
    }

    .fume-hood {
        grid-column: 1 / -1;
        grid-row: 3;
    }
}

@media (max-width: 768px) {
    .lab-container {
        grid-template-columns: 1fr;
        grid-template-rows: 50px auto auto auto;
    }

    .safety-cabinet,
    .workbench,
    .fume-hood {
        grid-column: 1;
    }
