        "text": "/* PERIODIC TABLE VISUALIZATION SYSTEM */

:root {
    /* Element category colors */
    --alkali-metal: #ff6b6b;
    --alkaline-earth: #ff9f43;
    --transition-metal: #54a0ff;
    --post-transition: #48dbfb;
    --metalloid: #1dd1a1;
    --nonmetal: #f368e0;
    --halogen: #a29bfe;
    --noble-gas: #6c5ce7;
    --lanthanide: #00d2d3;
    --actinide: #ff9ff3;

    /* Table dimensions */
    --cell-size: 60px;
    --cell-gap: 4px;
    --table-width: calc((var(--cell-size) + var(--cell-gap)) * 18);

    /* Element states */
    --solid: #636e72;
    --liquid: #0984e3;
    --gas: #00cec9;
    --unknown: #dfe6e9;
}

.periodic-table-container {
    width: var(--table-width);
    margin: 0 auto;
    padding: 20px;
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    border-radius: 20px;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
}

.table-grid {
    display: grid;
    grid-template-columns: repeat(18, var(--cell-size));
    grid-auto-rows: var(--cell-size);
    gap: var(--cell-gap);
    position: relative;
}

/* Base element cell */
.element {
    width: var(--cell-size);
    height: var(--cell-size);
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    position: relative;
    cursor: pointer;
    transition: all 0.3s ease;
    overflow: hidden;
    font-family: 'Arial', sans-serif;
}

.element:hover {
    transform: scale(1.2);
    z-index: 10;
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2);
}

/* Element category coloring */
.element.alkali-metal { background: linear-gradient(135deg, var(--alkali-metal), #ff4757); }
.element.alkaline-earth { background: linear-gradient(135deg, var(--alkaline-earth), #ffa502); }
.element.transition-metal { background: linear-gradient(135deg, var(--transition-metal), #2e86de); }
.element.post-transition { background: linear-gradient(135deg, var(--post-transition), #0abde3); }
.element.metalloid { background: linear-gradient(135deg, var(--metalloid), #10ac84); }
.element.nonmetal { background: linear-gradient(135deg, var(--nonmetal), #e056fd); }
.element.halogen { background: linear-gradient(135deg, var(--halogen), #5f27cd); }
.element.noble-gas { background: linear-gradient(135deg, var(--noble-gas), #341f97); }
.element.lanthanide { background: linear-gradient(135deg, var(--lanthanide), #01a3a4); }
.element.actinide { background: linear-gradient(135deg, var(--actinide), #e84393); }

/* Element content */
.element-symbol {
    font-size: 1.2rem;
    font-weight: bold;
    color: white;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.3);
    margin-bottom: 2px;
}

.element-number {
    font-size: 0.7rem;
    color: rgba(255, 255, 255, 0.8);
    position: absolute;
    top: 4px;
    left: 4px;
}

.element-name {
    font-size: 0.6rem;
    color: rgba(255, 255, 255, 0.9);
    text-align: center;
    padding: 0 2px;
}

.element-mass {
    font-size: 0.5rem;
    color: rgba(255, 255, 255, 0.7);
    position: absolute;
    bottom: 2px;
    right: 4px;
}

/* State indicators */
.element-state {
    position: absolute;
    top: 4px;
    right: 4px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
}

.element-state.solid { background-color: var(--solid); }
.element-state.liquid { background-color: var(--liquid); }
.element-state.gas { background-color: var(--gas); }
.element-state.unknown { background-color: var(--unknown); }

/* Electron configuration visualization */
.electron-shells {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
}

.electron-shell {
    position: absolute;
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 50%;
    animation: orbit 10s linear infinite;
}

.electron {
    position: absolute;
    width: 4px;
    height: 4px;
    background: white;
    border-radius: 50%;
    box-shadow: 0 0 4px #54a0ff;
}

@keyframes orbit {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

/* Group and period labels */
.group-label {
    position: absolute;
    top: -30px;
    text-align: center;
    width: var(--cell-size);
    font-weight: bold;
    color: #2d3436;
}

.period-label {
    position: absolute;
    left: -40px;
    height: var(--cell-size);
    display: flex;
    align-items: center;
    font-weight: bold;
    color: #2d3436;
}

/* Legend system */
.table-legend {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 10px;
    margin-top: 30px;
    padding: 20px;
    background: rgba(255, 255, 255, 0.9);
    border-radius: 10px;
}

.legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
}

.legend-color {
    width: 20px;
    height: 20px;
    border-radius: 4px;
}

.legend-label {
    font-size: 0.9rem;
    color: #2d3436;
}

/* Element detail modal */
.element-detail {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 400px;
    background: white;
    border-radius: 20px;
    padding: 30px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    z-index: 1000;
    display: none;
}

.element-detail.active {
    display: block;
    animation: elementReveal 0.5s ease;
}

@keyframes elementReveal {
    from {
        opacity: 0;
        transform: translate(-50%, -50%) scale(0.8);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}

.detail-header {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 20px;
}

.detail-symbol {
    font-size: 3rem;
    font-weight: bold;
    width: 80px;
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    color: white;
}

.detail-info {
    flex: 1;
}

.detail-name {
    font-size: 1.5rem;
    font-weight: bold;
    margin-bottom: 5px;
}

.detail-number {
    font-size: 1rem;
    color: #636e72;
}

/* Property grid */
.property-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 15px;
    margin-top: 20px;
}

.property-item {
    background: #f8f9fa;
    padding: 15px;
    border-radius: 10px;
    border-left: 4px solid #54a0ff;
}

.property-label {
    font-size: 0.8rem;
    color: #636e72;
    margin-bottom: 5px;
}

.property-value {
    font-size: 1.1rem;
    font-weight: bold;
    color: #2d3436;
}

/* Atomic radius visualization */
.atomic-radius-chart {
    height: 100px;
    margin: 20px 0;
    position: relative;
}

.radius-circle {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border: 2px solid #54a0ff;
    border-radius: 50%;
    animation: pulseRadius 2s infinite;
}

@keyframes pulseRadius {
    0%, 100% { opacity: 0.5; }
    50% { opacity: 1; }
}

/* Trend arrows */
.trend-arrow {
    display: inline-block;
    margin: 0 5px;
    font-size: 1.2rem;
}

.trend-up { color: #ff6b6b; }
.trend-down { color: #1dd1a1; }
.trend-neutral { color: #636e72; }

/* Search and filter */
.table-controls {
    margin-bottom: 20px;
    display: flex;
    gap: 10px;
}

.search-input {
    flex: 1;
    padding: 12px 20px;
    border: 2px solid #dfe6e9;
    border-radius: 25px;
    font-size: 1rem;
    transition: border-color 0.3s ease;
}

.search-input:focus {
    outline: none;
    border-color: #54a0ff;
}

.filter-select {
    padding: 12px 20px;
    border: 2px solid #dfe6e9;
    border-radius: 25px;
    background: white;
    font-size: 1rem;
    cursor: pointer;
}

/* Responsive table */
@media (max-width: 1200px) {
    :root {
        --cell-size: 50px;
    }
}

@media (max-width: 992px) {
    :root {
        --cell-size: 40px;
    }

    .element-symbol {
        font-size: 1rem;
    }

    .element-name {
        font-size: 0.5rem;
    }
}

@media (max-width: 768px) {
    .periodic-table-container {
        width: 100%;
        padding: 10px;
    }

    .table-grid {
        grid-template-columns: repeat(9, 1fr);
        grid-auto-rows: minmax(50px, auto);
    }

    .element-detail {
        width: 90%;
        max-width: 400px;
    }
}

/* Print styles */
@media print {
    .periodic-table-container {
        box-shadow: none;
        background: white;
    }

    .element:hover {
        transform: none;
        box-shadow: none;
    }

    .element-detail {
        position: static;
        transform: none;
        width: auto;
        box-shadow: none;
        page-break-inside: avoid;
    }
