        "text": "/* CHEMICAL REACTION VISUALIZER */

:root {
    /* Reaction state colors */
    --reactant-color: #3498db;
    --product-color: #2ecc71;
    --catalyst-color: #f39c12;
    --transition-color: #9b59b6;
    --energy-color: #e74c3c;

    /* Animation timings */
    --reaction-duration: 2s;
    --bond-formation: 0.5s;
    --molecule-rotation: 1s;

    /* Molecular spacing */
    --molecule-gap: 100px;
    --atom-radius: 30px;
    --bond-length: 80px;
}

.reaction-container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 40px;
    background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
    border-radius: 20px;
    position: relative;
    overflow: hidden;
}

.reaction-stages {
    display: flex;
    justify-content: space-between;
    align-items: center;
    min-height: 300px;
    position: relative;
}

/* Reactants section */
.reactants {
    flex: 1;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: var(--molecule-gap);
    padding: 20px;
    background: rgba(52, 152, 219, 0.1);
    border-radius: 15px;
    border: 2px dashed var(--reactant-color);
}

/* Products section */
.products {
    flex: 1;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: var(--molecule-gap);
    padding: 20px;
    background: rgba(46, 204, 113, 0.1);
    border-radius: 15px;
    border: 2px dashed var(--product-color);
}

/* Reaction arrow */
.reaction-arrow-container {
    width: 200px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
}

.reaction-arrow {
    width: 100px;
    height: 10px;
    background: linear-gradient(90deg, var(--reactant-color), var(--product-color));
    position: relative;
    animation: arrowFlow 3s infinite;
}

.reaction-arrow::before {
    content: '';
    position: absolute;
    right: -10px;
    top: 50%;
    transform: translateY(-50%);
    width: 0;
    height: 0;
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
    border-left: 20px solid var(--product-color);
}

@keyframes arrowFlow {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
}

/* Energy diagram */
.energy-diagram {
    position: absolute;
    top: 0;
    right: 0;
    width: 300px;
    height: 100%;
    pointer-events: none;
}

.energy-barrier {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 10px;
    height: 150px;
    background: linear-gradient(to bottom, var(--energy-color), #c0392b);
    transform: translate(-50%, -50%);
    border-radius: 5px;
}

.energy-activation {
    position: absolute;
    top: 30%;
    left: 50%;
    width: 200px;
    height: 4px;
    background: var(--energy-color);
    transform: translateX(-50%);
}

.energy-activation::before {
    content: 'Activation Energy';
    position: absolute;
    top: -25px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 0.8rem;
    color: var(--energy-color);
}

/* Molecule visualization */
.molecule {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 20px;
    padding: 20px;
    background: white;
    border-radius: 15px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
    transition: transform 0.3s ease;
}

.molecule:hover {
    transform: translateY(-5px);
}

.molecule-structure {
    position: relative;
    width: 200px;
    height: 200px;
}

/* Atom styling */
.atom {
    position: absolute;
    width: var(--atom-radius);
    height: var(--atom-radius);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: bold;
    font-size: 1.2rem;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.3);
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
    z-index: 2;
}

.atom.hydrogen {
    background: radial-gradient(circle at 30% 30%, #3498db, #2980b9);
}

.atom.oxygen {
    background: radial-gradient(circle at 30% 30%, #e74c3c, #c0392b);
}

.atom.carbon {
    background: radial-gradient(circle at 30% 30%, #2c3e50, #000000);
}

.atom.nitrogen {
    background: radial-gradient(circle at 30% 30%, #9b59b6, #8e44ad);
}

/* Bond styling */
.bond {
    position: absolute;
    height: 4px;
    background: linear-gradient(90deg, #636e72, #b2bec3);
    transform-origin: 0 50%;
    z-index: 1;
}

.bond.single {
    height: 4px;
}

.bond.double {
    height: 8px;
    background: linear-gradient(90deg, #636e72, #b2bec3, #636e72);
}

.bond.triple {
    height: 12px;
    background: linear-gradient(90deg, #636e72, #b2bec3, #636e72, #b2bec3);
}

/* Reaction animation */
.reaction-animation {
    position: absolute;
    top: 50%;
    left: 0;
    right: 0;
    height: 4px;
    background: linear-gradient(90deg, transparent, var(--transition-color), transparent);
    animation: reactionProgress var(--reaction-duration) infinite;
}

@keyframes reactionProgress {
    0% { left: 0; right: 100%; }
    50% { left: 0; right: 0; }
    100% { left: 100%; right: 0; }
}

/* Catalyst indicator */
.catalyst {
    position: absolute;
    bottom: -30px;
    left: 50%;
    transform: translateX(-50%);
    padding: 10px 20px;
    background: var(--catalyst-color);
    color: white;
    border-radius: 20px;
    font-size: 0.9rem;
    animation: catalystPulse 2s infinite;
}

@keyframes catalystPulse {
    0%, 100% { transform: translateX(-50%) scale(1); }
    50% { transform: translateX(-50%) scale(1.1); }
}

/* Reaction conditions */
.reaction-conditions {
    display: flex;
    justify-content: center;
    gap: 30px;
    margin-top: 40px;
    padding: 20px;
    background: rgba(243, 156, 18, 0.1);
    border-radius: 15px;
}

.condition {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
}

.condition-icon {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: white;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.condition-label {
    font-size: 0.9rem;
    color: #2c3e50;
    font-weight: bold;
}

.condition-value {
    font-size: 1.1rem;
    color: #e74c3c;
    font-weight: bold;
}

/* Stoichiometry display */
.stoichiometry {
    display: flex;
    align-items: center;
    gap: 5px;
    margin-bottom: 10px;
}

.coefficient {
    font-size: 1.5rem;
    font-weight: bold;
    color: var(--reactant-color);
    padding: 0 10px;
}

.plus-sign {
    font-size: 1.2rem;
    color: #636e72;
    margin: 0 10px;
}

/* Reaction rate indicator */
.reaction-rate {
    height: 20px;
    background: linear-gradient(90deg, #2ecc71, #f39c12, #e74c3c);
    border-radius: 10px;
    margin-top: 20px;
    position: relative;
    overflow: hidden;
}

.rate-indicator {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 4px;
    background: white;
    animation: rateMovement 3s infinite linear;
}

@keyframes rateMovement {
    0% { left: 0; }
    100% { left: 100%; }
}

/* Equilibrium indicator */
.equilibrium {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 20px;
    margin-top: 30px;
}

.equilibrium-arrow {
    font-size: 2rem;
    color: #9b59b6;
    animation: equilibriumShift 4s infinite alternate;
}

@keyframes equilibriumShift {
    0% { transform: translateX(-20px); }
    100% { transform: translateX(20px); }
}

/* Reaction progress bar */
.reaction-progress {
    height: 10px;
    background: #dfe6e9;
    border-radius: 5px;
    margin-top: 30px;
    overflow: hidden;
}

.progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--reactant-color), var(--product-color));
    width: 0%;
    animation: progressFill 5s infinite;
}

@keyframes progressFill {
    0% { width: 0%; }
    50% { width: 100%; }
    100% { width: 0%; }
}

/* Mobile responsiveness */
@media (max-width: 768px) {
    .reaction-stages {
        flex-direction: column;
        gap: 40px;
    }

    .reaction-arrow-container {
        width: 100%;
        height: 100px;
    }

    .reaction-arrow {
        transform: rotate(90deg);
    }

    .molecule-structure {
        width: 150px;
        height: 150px;
    }

    :root {
        --atom-radius: 25px;
        --bond-length: 60px;
    }
}

/* Print styles */
@media print {
    .reaction-container {
        background: white;
        box-shadow: none;
    }

    .reaction-animation,
    .rate-indicator,
    .progress-fill {
        animation: none;
        opacity: 0.5;
    }
