        "text": "/* MOLECULAR STRUCTURE BUILDER */

:root {
    /* Molecular visualization colors */
    --atom-carbon: #2d3436;
    --atom-hydrogen: #3498db;
    --atom-oxygen: #e74c3c;
    --atom-nitrogen: #9b59b6;
    --atom-sulfur: #f1c40f;
    --atom-phosphorus: #e67e22;
    --atom-halogen: #1abc9c;

    /* Bond types */
    --bond-single: #636e72;
    --bond-double: #2c3e50;
    --bond-triple: #000000;
    --bond-aromatic: #8e44ad;

    /* 3D perspective */
    --perspective: 1000px;
    --rotation-x: 20deg;
    --rotation-y: 30deg;
}

.molecule-builder {
    width: 100%;
    height: 600px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    border-radius: 20px;
    position: relative;
    overflow: hidden;
    perspective: var(--perspective);
}

.builder-canvas {
    width: 100%;
    height: 100%;
    position: relative;
    transform-style: preserve-3d;
    transform: rotateX(var(--rotation-x)) rotateY(var(--rotation-y));
    transition: transform 0.5s ease;
}

/* Atom sphere styling */
.atom-sphere {
    position: absolute;
    width: 60px;
    height: 60px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: bold;
    font-size: 1.2rem;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
    cursor: grab;
    user-select: none;
    transform-style: preserve-3d;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.atom-sphere:active {
    cursor: grabbing;
}

.atom-sphere:hover {
    transform: scale(1.1) translateZ(20px);
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3);
}

/* Atom type colors */
.atom-sphere.carbon {
    background: radial-gradient(circle at 30% 30%, var(--atom-carbon), #000000);
    box-shadow: 0 8px 16px rgba(45, 52, 54, 0.4);
}

.atom-sphere.hydrogen {
    background: radial-gradient(circle at 30% 30%, var(--atom-hydrogen), #2980b9);
    box-shadow: 0 8px 16px rgba(52, 152, 219, 0.4);
}

.atom-sphere.oxygen {
    background: radial-gradient(circle at 30% 30%, var(--atom-oxygen), #c0392b);
    box-shadow: 0 8px 16px rgba(231, 76, 60, 0.4);
}

.atom-sphere.nitrogen {
    background: radial-gradient(circle at 30% 30%, var(--atom-nitrogen), #8e44ad);
    box-shadow: 0 8px 16px rgba(155, 89, 182, 0.4);
}

.atom-sphere.sulfur {
    background: radial-gradient(circle at 30% 30%, var(--atom-sulfur), #f39c12);
    box-shadow: 0 8px 16px rgba(241, 196, 15, 0.4);
}

.atom-sphere.phoshorus {
    background: radial-gradient(circle at 30% 30%, var(--atom-phosphorus), #d35400);
    box-shadow: 0 8px 16px rgba(230, 126, 34, 0.4);
}

/* Bond visualization */
.bond-cylinder {
    position: absolute;
    background: linear-gradient(to right, var(--bond-single), #95a5a6);
    transform-origin: 0 50%;
    height: 8px;
    border-radius: 4px;
    transform-style: preserve-3d;
    z-index: 1;
}

.bond-cylinder.double {
    background: linear-gradient(to right, var(--bond-double), #7f8c8d);
    height: 12px;
}

.bond-cylinder.triple {
    background: linear-gradient(to right, var(--bond-triple), #636e72);
    height: 16px;
}

.bond-cylinder.aromatic {
    background: linear-gradient(to right, var(--bond-aromatic), #8e44ad);
    height: 8px;
    animation: aromaticPulse 2s infinite;
}

@keyframes aromaticPulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.7; }
}

/* Bond formation animation */
.bond-formation {
    position: absolute;
    height: 4px;
    background: linear-gradient(90deg, transparent, #54a0ff, transparent);
    animation: bondForm 1s ease-out;
}

@keyframes bondForm {
    0% { width: 0; opacity: 0; }
    50% { width: 100%; opacity: 1; }
    100% { width: 0; opacity: 0; }
}

/* Molecular orbital visualization */
.orbital {
    position: absolute;
    border: 2px solid rgba(84, 160, 255, 0.3);
    border-radius: 50%;
    animation: orbitalRotation 10s linear infinite;
    transform-style: preserve-3d;
}

.orbital.s {
    border-color: rgba(46, 204, 113, 0.5);
}

.orbital.p {
    border-color: rgba(155, 89, 182, 0.5);
    animation: orbitalRotation 8s linear infinite reverse;
}

.orbital.d {
    border-color: rgba(241, 196, 15, 0.5);
    animation: orbitalRotation 12s linear infinite;
}

@keyframes orbitalRotation {
    from { transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg); }
    to { transform: rotateX(360deg) rotateY(360deg) rotateZ(360deg); }
}

/* Electron cloud */
.electron-cloud {
    position: absolute;
    width: 100px;
    height: 100px;
    background: radial-gradient(circle, rgba(84, 160, 255, 0.1) 0%, transparent 70%);
    border-radius: 50%;
    animation: cloudPulse 3s infinite alternate;
}

@keyframes cloudPulse {
    0% { transform: scale(1); opacity: 0.3; }
    100% { transform: scale(1.2); opacity: 0.6; }
}

/* Builder controls */
.builder-controls {
    position: absolute;
    bottom: 20px;
    left: 20px;
    right: 20px;
    display: flex;
    gap: 15px;
    padding: 20px;
    background: rgba(255, 255, 255, 0.9);
    border-radius: 15px;
    backdrop-filter: blur(10px);
}

.atom-palette {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}

.palette-atom {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: bold;
    cursor: pointer;
    transition: transform 0.2s ease;
}

.palette-atom:hover {
    transform: scale(1.1);
}

.bond-controls {
    display: flex;
    gap: 10px;
    align-items: center;
}

.bond-type {
    padding: 8px 16px;
    background: #3498db;
    color: white;
    border: none;
    border-radius: 20px;
    cursor: pointer;
