}

.bond-type:hover {
    background: #2980b9;
}

.bond-type.active {
    background: #2c3e50;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}

/* Measurement tools */
.measurement-tool {
    position: absolute;
    top: 20px;
    right: 20px;
    background: rgba(255, 255, 255, 0.9);
    padding: 15px;
    border-radius: 10px;
    backdrop-filter: blur(10px);
}

.bond-length {
    font-size: 0.9rem;
    color: #2c3e50;
    margin-bottom: 5px;
}

.bond-angle {
    font-size: 0.9rem;
    color: #2c3e50;
}

/* 3D rotation controls */
.rotation-controls {
    position: absolute;
    top: 20px;
    left: 20px;
    display: flex;
    gap: 10px;
}

.rotation-button {
    width: 40px;
    height: 40px;
    background: rgba(255, 255, 255, 0.9);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 1.2rem;
    color: #2c3e50;
    transition: all 0.3s ease;
}

.rotation-button:hover {
    background: white;
    transform: scale(1.1);
}

/* Molecular properties panel */
.properties-panel {
    position: absolute;
    top: 80px;
    right: 20px;
    width: 250px;
    background: rgba(255, 255, 255, 0.9);
    padding: 20px;
    border-radius: 15px;
    backdrop-filter: blur(10px);
}

.property-item {
    margin-bottom: 15px;
    padding-bottom: 15px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.1);
}

.property-label {
    font-size: 0.8rem;
    color: #636e72;
    margin-bottom: 5px;
}

.property-value {
    font-size: 1.1rem;
    font-weight: bold;
    color: #2c3e50;
}

/* Molecular formula display */
.molecular-formula {
    position: absolute;
    bottom: 100px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(255, 255, 255, 0.9);
    padding: 15px 30px;
    border-radius: 25px;
    font-size: 1.5rem;
    font-weight: bold;
    color: #2c3e50;
    backdrop-filter: blur(10px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
}

.formula-part {
    margin: 0 5px;
}

.formula-subscript {
    font-size: 0.8em;
    vertical-align: sub;
}

/* Grid system for atom placement */
.builder-grid {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-image: 
        linear-gradient(rgba(0, 0, 0, 0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0, 0, 0, 0.05) 1px, transparent 1px);
    background-size: 50px 50px;
    pointer-events: none;
}

/* Snap-to-grid indicator */
.snap-indicator {
    position: absolute;
    width: 10px;
    height: 10px;
    background: #e74c3c;
    border-radius: 50%;
    transform: translate(-50%, -50%);
    animation: snapPulse 1s infinite;
}

@keyframes snapPulse {
    0%, 100% { transform: translate(-50%, -50%) scale(1); }
    50% { transform: translate(-50%, -50%) scale(1.5); }
}

/* Undo/Redo controls */
.history-controls {
    position: absolute;
    bottom: 20px;
    right: 20px;
    display: flex;
    gap: 10px;
}

.history-button {
    padding: 10px 20px;
    background: rgba(255, 255, 255, 0.9);
    border: none;
    border-radius: 20px;
    cursor: pointer;
    font-weight: bold;
    color: #2c3e50;
    transition: all 0.3s ease;
}

.history-button:hover {
    background: white;
    transform: translateY(-2px);
}

/* Responsive design */
@media (max-width: 768px) {
    .molecule-builder {
        height: 400px;
    }

    .builder-controls {
        flex-direction: column;
    }

    .properties-panel {
        position: relative;
        width: auto;
        margin: 20px;
        top: auto;
        right: auto;
    }
