class Neuron {
  constructor() {
    this.Vm = -70; // Resting potential (mV)
    this.spikeHistory = []; // Timestamps of past spikes (ms)
    this.synapses = []; // Incoming synaptic connections
  }

  // Hodgkin-Huxley-inspired update rule
  update(dt, inputCurrent) {
    const gNa = 120, gK = 36, gL = 0.3; // Conductances (mS/cm²)
    const ENa = 50, EK = -77, EL = -54.4; // Reversal potentials (mV)

    const alpha_n = 0.01 * (this.Vm + 55) / (1 - Math.exp(-(this.Vm + 55) / 10));
    const beta_n = 0.125 * Math.exp(-(this.Vm + 65) / 80);
    const n_inf = alpha_n / (alpha_n + beta_n);

    this.Vm += dt * (gNa * Math.pow(m_inf(this.Vm), 3) * h_inf(this.Vm) * (ENa - this.Vm)
                   + gK * Math.pow(n_inf, 4) * (EK - this.Vm)
                   + gL * (EL - this.Vm)
