      this.Vm = -65; // Reset potential
    }
  }
}

// Helper functions for gating variables
function m_inf(V) {
  return 1 / (1 + Math.exp(-(V + 40) / 9));
}

function h_inf(V) {
  return 1 / (1 + Math.exp((V + 65) / 7));
}

// Synaptic plasticity rule (STDP)
function updateWeights(preNeuron, postNeuron, dt) {
  const tau_plus = 20, tau_minus = 20; // Time constants (ms)
  const A_plus = 0.1, A_minus = 0.1; // Learning rates

