    double g_AMPA;     // AMPA conductance
    double g_GABA;     // GABA conductance
    double g_DA;       // Dopamine modulation
    double eligibility; // Synaptic eligibility trace

    MSN() : V(-80), g_AMPA(0), g_GABA(0), g_DA(1), eligibility(0) {}

    void update(double dt, double input) {
        // Conductance-based dynamics
        const double E_AMPA = 0, E_GABA = -70;
        V += dt * (g_AMPA * (E_AMPA - V) + g_GABA * (E_GABA - V) + 0.1 * (input - V));

        // Spike generation
        if (V > -50) {
            V = -60;
            eligibility = 1.0;  // Mark synapse as eligible
        }

        // Decay conductances
        g_AMPA *= exp(-dt/5);
        g_GABA *= exp(-dt/10);
        eligibility *= exp(-dt/100);
    }
};

