// Hippocampal Place Cell Model
/*
 * This JavaScript implementation models place cell activity in the
 * hippocampus using a continuous attractor network.
 *
 * Key features:
 *   - 2D sheet of place cells
 *   - Recurrent connections with Mexican hat profile
 *   - Path integration via grid cell input
 *   - Theta phase precession
 *
 * References:
 * O'Keefe & Dostrovsky (1971) "The hippocampus as a spatial map"
 * Hafting et al. (2005) "Microstructure of a spatial map in the entorhinal cortex"
 */

// Network parameters
const params = {
    size: 50,            // Number of cells along one dimension
    tau: 10,             // Time constant (ms)
    v_th: -50,           // Spike threshold (mV)
    v_reset: -70,        // Reset potential (mV)
    dt: 0.1,             // Time step (ms)
    sim_time: 10000,     // Total simulation time (ms)
    speed: 0.05,         // Animal speed (m/ms)
    theta_freq: 8        // Theta oscillation frequency (Hz)
};

// Initialize place cells
const place_cells = Array(params.size).fill().map(() =>
    Array(params.size).fill().map(() => ({
        v: -60,              // Membrane potential
        x: Math.random(),    // Place field center x
        y: Math.random(),    // Place field center y
        phase: Math.random() * 2 * Math.PI  // Theta phase
    }))
);

// Mexican hat connectivity
function mexican_hat(dx, dy) {
    const sigma_exc = 0.1;
    const sigma_inh = 0.3;
    const d = Math.sqrt(dx*dx + dy*dy);
    return Math.exp(-d*d/(2*sigma_exc*sigma_exc)) - 0.3*Math.exp(-d*d/(2*sigma_inh*sigma_inh));
}

// Grid cell input (simplified)
function grid_cell_input(x, y, t) {
    const scale = 0.2;
    const angle = t * params.speed * 0.1;
    return 0.5 * (
        Math.cos(2*Math.PI*(x*Math.cos(angle) + y*Math.sin(angle))/scale) +
        Math.cos(2*Math.PI*(x*Math.cos(angle+2*Math.PI/3) + y*Math.sin(angle+2*Math.PI/3))/scale) +
        Math.cos(2*Math.PI*(x*Math.cos(angle+4*Math.PI/3) + y*Math.sin(angle+4*Math.PI/3))/scale)
    ) + 0.5;
}

// Animal trajectory (random walk)
function get_position(t) {
    return {
        x: 0.5 + 0.3 * Math.sin(t * params.speed * 0.001),
        y: 0.5 + 0.3 * Math.cos(t * params.speed * 0.001)
    };
}

// Simulation loop
for (let t = 0; t < params.sim_time; t += params.dt) {
    const pos = get_position(t);
    const theta_phase = 2 * Math.PI * params.theta_freq * t / 1000;

    // Update all place cells
    for (let i = 0; i < params.size; i++) {
        for (let j = 0; j < params.size; j++) {
            const cell = place_cells[i][j];

            // Distance from current position to place field center
            const dx = pos.x - cell.x;
            const dy = pos.y - cell.y;
            const d = Math.sqrt(dx*dx + dy*dy);

            // Input from grid cells
            const grid_input = grid_cell_input(cell.x, cell.y, t);

            // Recurrent input
            let recurrent_input = 0;
            for (let ii = 0; ii < params.size; ii++) {
                for (let jj = 0; jj < params.size; jj++) {
                    const dxx = (ii - i) / params.size;
                    const dyy = (jj - j) / params.size;
                    recurrent_input += mexican_hat(dxx, dyy) * (place_cells[ii][jj].v > params.v_th ? 1 : 0);
                }
            }

            // Theta modulation
            const theta_input = 0.5 * Math.cos(theta_phase - cell.phase);

            // Total input
            const input = 5 * Math.exp(-d*d/(2*0.05*0.05)) + 0.3 * grid_input + recurrent_input + theta_input;

            // Leaky integration
            cell.v += params.dt * (-cell.v + input) / params.tau;

            // Spike generation and reset
            if (cell.v > params.v_th) {
                cell.v = params.v_reset;
                // Phase precession
                cell.phase = (cell.phase + 0.1) % (2 * Math.PI);
            }
        }
    }
}

