// Cerebellar Motor Learning Model
/*
 * This C++ implementation models cerebellar learning using
 * the Marr-Albus-Ito theory of motor adaptation.
 *
 * Key components:
 *   - Granule cells (expansion recoding)
 *   - Purkinje cells (plasticity)
 *   - Climbing fiber input (error signal)
 *   - Mossy fiber input (sensory/motor context)
 *
 * Biological references:
 * Marr (1969) "A theory of cerebellar cortex"
 * Albus (1971) "A theory of cerebellar function"
 */

#include <vector>
#include <cmath>
#include <random>

// Network parameters
struct Params {
    int n_mf = 100;        // Number of mossy fibers
    int n_gc = 1000;       // Number of granule cells
    int n_pc = 10;         // Number of Purkinje cells
    int n_cf = 1;          // Number of climbing fibers
    double tau = 10;       // Time constant (ms)
    double eta = 0.01;     // Learning rate
    double dt = 0.1;       // Time step (ms)
    int sim_time = 5000;   // Total simulation time (ms)
};

// Neuron models
class GranuleCell {
public:
    double v;              // Membrane potential
    std::vector<double> weights;  // MF->GC weights

    GranuleCell(int n_mf) : v(-65), weights(n_mf) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<> dis(0, 0.1);
        for (auto& w : weights) w = dis(gen);
    }

    void update(const std::vector<double>& mf_input) {
        double input = 0;
        for (size_t i = 0; i < weights.size(); ++i) {
            input += weights[i] * mf_input[i];
        }
        v += Params().dt * (-v + input) / Params().tau;
    }
};

class PurkinjeCell {
public:
    double v;
    std::vector<double> weights;  // GC->PC weights
    double cf_input;

    PurkinjeCell(int n_gc) : v(-65), weights(n_gc, 0.1), cf_input(0) {}

    void update(const std::vector<double>& gc_input) {
        double input = 0;
        for (size_t i = 0; i < weights.size(); ++i) {
            input += weights[i] * gc_input[i];
        }

        // Climbing fiber modulation
        input *= (1 - 0.5 * cf_input);

        v += Params().dt * (-v + input) / Params().tau;

        // Plasticity (LTD)
        if (cf_input > 0.5) {
            for (auto& w : weights) {
                w -= Params().eta * cf_input * w;
            }
        }
    }
};

// Motor command generation
class MotorSystem {
public:
    double desired_angle;
    double actual_angle;
    double error;

    MotorSystem() : desired_angle(0), actual_angle(0), error(0) {}

    void update(double pc_output) {
        // Simple motor plant
        actual_angle += 0.1 * (desired_angle - actual_angle) + 0.01 * pc_output;
        error = desired_angle - actual_angle;
    }
};

int main() {
    Params params;
    std::vector<GranuleCell> granule_cells;
    std::vector<PurkinjeCell> purkinje_cells;
    MotorSystem motor_system;

    // Initialize network
    for (int i = 0; i < params.n_gc; ++i) {
        granule_cells.emplace_back(params.n_mf);
    }
    for (int i = 0; i < params.n_pc; ++i) {
        purkinje_cells.emplace_back(params.n_gc);
    }

    // Simulation loop
    for (int t = 0; t < params.sim_time; t += params.dt) {
        // Generate mossy fiber input (sensory context)
        std::vector<double> mf_input(params.n_mf);
        for (auto& input : mf_input) {
            input = 0.5 + 0.5 * sin(t/100.0 + 2*M_PI*rand()/RAND_MAX);
        }

        // Update granule cells
        std::vector<double> gc_output(params.n_gc);
        for (int i = 0; i < params.n_gc; ++i) {
            granule_cells[i].update(mf_input);
            gc_output[i] = granule_cells[i].v > -55 ? 1 : 0;
        }

        // Generate climbing fiber input (error signal)
        double cf_input = fabs(motor_system.error) > 0.1 ? 1 : 0;

        // Update Purkinje cells
        std::vector<double> pc_output(params.n_pc);
        for (int i = 0; i < params.n_pc; ++i) {
            purkinje_cells[i].cf_input = cf_input;
            purkinje_cells[i].update(gc_output);
            pc_output[i] = purkinje_cells[i].v > -50 ? 1 : 0;
        }

        // Update motor system
        double pc_avg = 0;
        for (auto output : pc_output) pc_avg += output;
        pc_avg /= params.n_pc;

        // Desired movement pattern
        motor_system.desired_angle = sin(t/200.0);
        motor_system.update(pc_avg);

        // Print progress
        if (t % 500 == 0) {
            printf("Time %dms, Error: %.3f, PC activity: %.3f\n", 
                   t, motor_system.error, pc_avg);
        }
    }

    /*
     * Expected results:
     * 1. Motor error should decrease over time
     * 2. Purkinje cell activity should become anti-correlated with error
     * 3. Granule cell representations should become sparse
     *
     * Validation:
     * - Compare with eye blink conditioning data
     * - Test with different movement patterns
     * - Measure timing of Purkinje cell responses
     */

    return 0;
}

