/* C++ function to compute wind-driven current velocity */
#include <vector>
#include <cmath>

const double EARTH_ROTATION_RATE = 7.2921e-5; // rad/sec

std::vector<double> computeEkmanSpiral(double windStress, double latitude, int depthSteps) {
    std::vector<double> velocities;
    double coriolis = 2 * EARTH_ROTATION_RATE * sin(latitude * M_PI / 180);
    double friction = 0.001; // Arbitrary eddy viscosity coefficient

    // 1. Calculate reference velocity magnitude
    double u0 = windStress / (std::sqrt(2) * 1025 * friction);

    // 2. Compute velocity components at each depth level
    for(int z=0; z<depthSteps; z++) {
        double depth = z * 10; // meters
        double decay = exp(-depth * coriolis / friction);
        double angle = (M_PI/4) - (depth * coriolis / friction);

        velocities.push_back(u0 * decay * cos(angle)); // East-West component
        velocities.push_back(u0 * decay * sin(angle)); // North-South component
    }

    return velocities;
}

