// MATLAB script for tidal harmonic analysis
// Using Doodson's harmonic constants

% Load 30-day tidal record
load('brest_tide_data.mat');
tide = brest_tide; % msl units

% Define harmonic constituents
constituents = {'M2', 'S2', 'N2', 'K1', 'O1', 'P1'};
frequencies = [1.932; 2.0; 1.895; 1.003; 0.929; 1.006]; % cycles/day

% Initialize parameter matrix
A = zeros(length(tide), 2*numel(constituents)+1);

% Create design matrix
for i = 1:numel(constituents)
    A(:,2*i-1) = cos(2*pi*frequencies(i)*hours); % Cosine terms
    A(:,2*i) = sin(2*pi*frequencies(i)*hours);   % Sine terms
end
A(:,end) = 1; % Bias term

% Solve for coefficients
coeffs = A \ tide';

% Extract constituents
for i = 1:numel(constituents)
    amp(i) = sqrt(coeffs(2*i-1)^2 + coeffs(2*i)^2);
    phase(i) = atan2(coeffs(2*i), coeffs(2*i-1));
end

