 * Cmax: Maximum concentration
 * CL: Clearance (volume of plasma cleared of drug per unit time)
 * CYP: Cytochrome P450 enzymes
 * DDI: Drug-Drug Interaction
 * P-gp: P-glycoprotein (drug transporter)
 * RF: Renal Function adjustment factor
 * Tmax: Time to maximum concentration
 * V_d: Volume of distribution
 */

// PHARMACODYNAMIC MODEL DOCUMENTATION
// Drug: Angiomax (bivalirudin)
// Model Type: Mechanism-based PK/PD
// Last Reviewed: 2023-10-05

/*
 * This document describes the pharmacodynamic model for bivalirudin,
 * a direct thrombin inhibitor used in percutaneous coronary intervention.
 *
 * The model integrates:
 * 1. Pharmacokinetics (PK) of bivalirudin
 * 2. Thrombin generation dynamics
 * 3. Clotting time measurements (ACT)
 * 4. Clinical outcomes (bleeding, thrombosis)
 */

// ======================
// SECTION 1: MODEL STRUCTURE
// ======================

// Model compartments
const compartments = {
    plasma: {
        description: "Central compartment for drug distribution",
        volume: 5.0  // L
    },
    effectSite: {
        description: "Biophase where drug exerts its effect",
        volume: 0.2  // L
    },
    thrombin: {
        description: "Thrombin generation and inhibition dynamics",
        baseline: 100  // nM
    }
};

// ======================
// SECTION 2: PARAMETER ESTIMATES
// ======================

// Pharmacokinetic parameters
const pkParams = {
    CL: 3.6,      // L/h (clearance)
    V1: 5.0,      // L (central volume)
    Q: 2.4,       // L/h (intercompartmental clearance)
    V2: 4.8,      // L (peripheral volume)
    k_a: 0.8      // 1/h (absorption rate constant)
};

// Pharmacodynamic parameters
const pdParams = {
    k_e0: 0.45,   // 1/h (effect site equilibration rate)
    IC50: 0.25,   // µM (concentration for 50% inhibition)
    gamma: 1.8,   // Hill coefficient
    E_max: 100,   // % inhibition
    baseline_ACT: 120  // sec (baseline activated clotting time)
};

/*
 * SECTION 3: MATHEMATICAL MODEL
 *
 * The model consists of:
 *
 * 1. PK model (2-compartment):
 *    dC1/dt = (k_a * Dose/V1) - (CL/V1 * C1) - (Q/V1 * C1) + (Q/V2 * C2)
 *    dC2/dt = (Q/V1 * C1) - (Q/V2 * C2)
 *
 * 2. Effect site model:
 *    dCe/dt = k_e0 * (C1 - Ce)
 *
 * 3. PD model (sigmoidal Emax):
 *    E = E0 + (E_max - E0) * (Ce^gamma) / (Ce^gamma + IC50^gamma)
 *    where E = % inhibition of thrombin
 *
 * 4. ACT relationship:
 *    ACT = baseline_ACT / (1 - E/100)
 */

// Model implementation (pseudocode)
function simulateBivalirudin(patient, dosingRegimen) {
    // Initialize state variables
    let state = {
        C1: 0,  // Central compartment concentration
        C2: 0,  // Peripheral compartment concentration
        Ce: 0,  // Effect site concentration
        thrombin: compartments.thrombin.baseline,
        ACT: pdParams.baseline_ACT
    };

    // Apply patient-specific adjustments
    const adjustedParams = adjustForCovariates(patient, pkParams, pdParams);

    // Simulation loop
    for (let t = 0; t < simulationTime; t += timeStep) {
        // Update PK
        const dC1 = (adjustedParams.k_a * dosingRegimen.dose/adjustedParams.V1) 
                  - (adjustedParams.CL/adjustedParams.V1 * state.C1) 
                  - (adjustedParams.Q/adjustedParams.V1 * state.C1) 
                  + (adjustedParams.Q/adjustedParams.V2 * state.C2);

        const dC2 = (adjustedParams.Q/adjustedParams.V1 * state.C1) 
                  - (adjustedParams.Q/adjustedParams.V2 * state.C2);

        // Update effect site
        const dCe = adjustedParams.k_e0 * (state.C1 - state.Ce);

        // Update PD
        const E = (adjustedParams.E_max * Math.pow(state.Ce, adjustedParams.gamma)) 
                / (Math.pow(state.Ce, adjustedParams.gamma) + Math.pow(adjustedParams.IC50, adjustedParams.gamma));

        // Update thrombin and ACT
        state.thrombin = compartments.thrombin.baseline * (1 - E/100);
        state.ACT = adjustedParams.baseline_ACT / (1 - E/100);

        // Update state
        state.C1 += dC1 * timeStep;
        state.C2 += dC2 * timeStep;
        state.Ce += dCe * timeStep;

        // Store results
        results.push({
            time: t,
            C1: state.C1,
            Ce: state.Ce,
            thrombin: state.thrombin,
            ACT: state.ACT
        });
    }

    return results;
}

/*
 * SECTION 4: COVARIATE ADJUSTMENTS
 *
 * The following patient factors are known to affect bivalirudin PK/PD:
 *
 * 1. Renal function:
 *    - CL = CL_pop * (1 - 0.3 * (1 - RF))
 *    - RF = renal function (1.0 = normal, 0.0 = dialysis)
 *
 * 2. Body weight:
 *    - V1 = V1_pop * (WT/70)
 *    - CL = CL_pop * (WT/70)^0.75
 *
 * 3. Age:
 *    - CL = CL_pop * (1 - 0.005 * (age - 50)) for age > 50
 *
 * 4. Sex:
 *    - V1 = V1_pop * 0.9 for females
 */

function adjustForCovariates(patient, pkParams, pdParams) {
    const adjusted = {...pkParams};

    // Renal function adjustment
    const RF = calculateRenalFunction(patient.creatinineClearance);
    adjusted.CL = pkParams.CL * (1 - 0.3 * (1 - RF));

    // Weight adjustment
    adjusted.V1 = pkParams.V1 * (patient.weight / 70);
    adjusted.CL = adjusted.CL * Math.pow(patient.weight / 70, 0.75);

    // Age adjustment
    if (patient.age > 50) {
        adjusted.CL = adjusted.CL * (1 - 0.005 * (patient.age - 50));
    }

    // Sex adjustment
    if (patient.sex === "female") {
        adjusted.V1 = adjusted.V1 * 0.9;
    }

    return adjusted;
}

/*
 * SECTION 5: CLINICAL VALIDATION
