  ; Individual parameters
  KIN = KIN * EXP(ETA(1))
  KOUT = KOUT * EXP(ETA(2))

  ; Secondary parameters
  BASE = KIN/KOUT
  S1 = BASE

$DES
  ; PK
  DADT(1) = -KA * A(1)
  DADT(2) = KA * A(1) - (CL/V2) * A(2)

  ; Calculate concentrations
  CS = A(2)/V2  ; S-warfarin concentration
  CR = A(2)/V2  ; R-warfarin concentration (simplified)

  ; PD - indirect response model
  INH = (CS**GAMMA)/(CS**GAMMA + IC50_S**GAMMA) + (CR**GAMMA)/(CR**GAMMA + IC50_R**GAMMA)
  DADT(3) = KIN * (1 - INH) - KOUT * A(3)

  ; INR relationship
  DADT(4) = ALPHA * (A(3) - BASE)

$ERROR
  IPRED = A(4) + INR0
  W = THETA(11)
  IRES = DV - IPRED
  IWRES = IRES/(W*IPRED)
  Y = IPRED + W*IPRED*EPS(1)

$THETA
  (0, 1)    ; 1 - KIN
  (0, 0.05) ; 2 - KOUT
  (0, 0.5)  ; 3 - IC50_S
  (0, 2)    ; 4 - IC50_R
  (0, 1.2)  ; 5 - GAMMA
  (0.9, 1.1) ; 6 - INR0
  (0, 3)    ; 7 - ALPHA
  (0.8, 1)  ; 8 - VKORC1 GG
  (0.6, 0.9) ; 9 - VKORC1 GA
  (0.4, 0.7) ; 10 - VKORC1 AA
  (0, 0.1)  ; 11 - proportional error

$OMEGA
  0.2 ; IIV KIN
  0.1 ; IIV KOUT

$SIGMA
  1 FIX

$ESTIMATION METHOD=1 INTERACTION MAXEVAL=9999`;

