// ======================
// SECTION 2: BASE MODEL DEVELOPMENT
// ======================

/*
 * Structural model:
 * - Two-compartment model with first-order elimination
 * - Zero-order input (infusion)
 *
 * Parameters:
 * - CL: Clearance (L/h)
 * - V1: Central volume (L)
 * - Q: Intercompartmental clearance (L/h)
 * - V2: Peripheral volume (L)
 *
 * Statistical model:
 * - Exponential inter-individual variability (IIV)
 * - Combined additive and proportional residual error
 */

// Base model code (NONMEM)
const baseModelCode = `$PROBLEM VANCOMYCIN POPULATION PK
$INPUT ID TIME AMT DV EVID CMT MDV RATE DUR AGE WT SEX SCR CRCL ALBUMIN
$DATA vancomycin_data.csv IGNORE=@
$SUBROUTINES ADVAN3 TRANS3

$PK
  ; Typical values
  TVCL = THETA(1)
  TVV1 = THETA(2)
  TVQ = THETA(3)
  TVV2 = THETA(4)

  ; Individual parameters
  CL = TVCL * EXP(ETA(1))
  V1 = TVV1 * EXP(ETA(2))
  Q = TVQ * EXP(ETA(3))
  V2 = TVV2 * EXP(ETA(4))

  ; Secondary parameters
  K12 = Q/V1
  K21 = Q/V2
  K10 = CL/V1
  S1 = V1

$ERROR
  IPRED = F
  W = SQRT(THETA(5)**2 + (THETA(6)*IPRED)**2)
  IRES = DV - IPRED
  IWRES = IRES/W
  Y = IPRED + W*EPS(1)

$THETA
  (0, 4)    ; 1 - CL (L/h)
  (0, 50)   ; 2 - V1 (L)
  (0, 10)   ; 3 - Q (L/h)
  (0, 100)  ; 4 - V2 (L)
  (0, 2)    ; 5 - additive error (mg/L)
  (0, 0.2)  ; 6 - proportional error

$OMEGA
  0.3 ; IIV CL
  0.2 ; IIV V1
  0.4 ; IIV Q
  0.3 ; IIV V2

$SIGMA
  1 FIX

$ESTIMATION METHOD=1 INTERACTION MAXEVAL=9999
$COVARIANCE PRINT=E`;

