// Covariate model code (NONMEM)
const covariateModelCode = `$PK
  ; Base clearance
  TVCL = THETA(1) * (WT/70)**0.75

  ; Renal function
  TVCL = TVCL * (CRCL/80)**THETA(5)
  IF (CRCL.GT.160) TVCL = TVCL * (160/80)**THETA(5)  ; cap effect

  ; Age
  TVCL = TVCL * (AGE/50)**THETA(6)
  IF (AGE.LT.35) TVCL = TVCL * (35/50)**THETA(6)  ; floor effect

  ; Albumin
  TVCL = TVCL * (ALBUMIN/3.5)**THETA(7)
  IF (ALBUMIN.GT.4.5) TVCL = TVCL * (4.5/3.5)**THETA(7)  ; cap effect

  ; Central volume
  TVV1 = THETA(2) * (WT/70)
  IF (SEX.EQ.0) TVV1 = TVV1 * THETA(8)  ; female

  ; Individual parameters
  CL = TVCL * EXP(ETA(1))
  V1 = TVV1 * EXP(ETA(2))
  Q = THETA(3) * EXP(ETA(3))
  V2 = THETA(4) * EXP(ETA(4))
`;

