/*
 * Structural model:
 * - Two-compartment model with first-order elimination
 * - Zero-order input (infusion)
 *
 * Parameters:
 * - CL: Clearance (L/day)
 * - V1: Central volume (L)
 * - Q: Intercompartmental clearance (L/day)
 * - V2: Peripheral volume (L)
 *
 * Statistical model:
 * - Exponential inter-individual variability (IIV)
 * - Additive residual error (log scale)
 */

// Base model code (NONMEM)
const baseModelCode = `$PROBLEM PEMBROLIZUMAB POPULATION PK
$INPUT ID TIME AMT DV EVID CMT MDV DOSE WT BSA ALBUMIN CRP ECOG TUMORBURDEN
$DATA pembrolizumab_data.csv IGNORE=@
$SUBROUTINES ADVAN3 TRANS3

$PK
  ; Typical values
  TVCL = THETA(1)
  TVV1 = THETA(2)
  TVQ = THETA(3)
  TVV2 = THETA(4)

  ; Individual parameters
  CL = TVCL * EXP(ETA(1))
  V1 = TVV1 * EXP(ETA(2))
  Q = TVQ * EXP(ETA(3))
  V2 = TVV2 * EXP(ETA(4))

  ; Secondary parameters
  K12 = Q/V1
  K21 = Q/V2
  K10 = CL/V1
  S1 = V1

$ERROR
  IPRED = LOG(F)  ; log-transformed data
  W = THETA(5)
  IRES = DV - IPRED
  IWRES = IRES/W
  Y = IPRED + W*EPS(1)

$THETA
  (0, 0.2)  ; 1 - CL (L/day)
  (0, 3)    ; 2 - V1 (L)
  (0, 0.5)  ; 3 - Q (L/day)
  (0, 4)    ; 4 - V2 (L)
  (0, 0.3)  ; 5 - additive error (log scale)

$OMEGA
  0.2 ; IIV CL
  0.1 ; IIV V1
  0.3 ; IIV Q
  0.2 ; IIV V2

$SIGMA
  1 FIX

$ESTIMATION METHOD=1 INTERACTION MAXEVAL=9999
$COVARIANCE PRINT=E`;

