// ======================
// SECTION 2: PK MODEL DEVELOPMENT
// ======================

/*
 * Structural PK model:
 * - Two-compartment model with first-order absorption and elimination
 * - Lag time for absorption
 * - Transit compartments for absorption delay
 *
 * Parameters:
 * - CL/F: Apparent clearance (L/h)
 * - V2/F: Apparent central volume (L)
 * - Q/F: Apparent intercompartmental clearance (L/h)
 * - V3/F: Apparent peripheral volume (L)
 * - ka: Absorption rate constant (1/h)
 * - tlag: Lag time (h)
 * - MTT: Mean transit time (h)
 * - N: Number of transit compartments
 *
 * Statistical model:
 * - Exponential inter-individual variability (IIV)
 * - Proportional residual error
 */

// Base PK model code (NONMEM)
const basePkModelCode = `$PROBLEM APIXABAN POPULATION PK
$INPUT ID TIME AMT DV EVID CMT MDV DOSE WT AGE SEX RACE CRCL ALBUMIN
$DATA apixaban_pk_data.csv IGNORE=@
$SUBROUTINES ADVAN6 TOL=5
$MODEL COMP=(DEPOT) COMP=(TRANS1) COMP=(CENTRAL) COMP=(PERIPHERAL)

$PK
  ; Structural parameters
  TVCL = THETA(1)
  TVV2 = THETA(2)
  TVQ = THETA(3)
  TVV3 = THETA(4)
  TVKA = THETA(5)
  TVTLAG = THETA(6)
  TVMTT = THETA(7)
  TVN = THETA(8)

  ; Individual parameters
  CL = TVCL * EXP(ETA(1))
  V2 = TVV2 * EXP(ETA(2))
  Q = TVQ * EXP(ETA(3))
  V3 = TVV3 * EXP(ETA(4))
  KA = TVKA * EXP(ETA(5))
  TLAG = TVTLAG
  MTT = TVMTT * EXP(ETA(6))
  N = TVN

  ; Secondary parameters
  K = CL/V2
  K23 = Q/V2
  K32 = Q/V3
  KTR = (N+1)/MTT
  S2 = V2

$DES
  ; Depot compartment
  DADT(1) = -KA * A(1)

  ; Transit compartments
  DADT(2) = KA * A(1) - KTR * A(2)
  DADT(3) = KTR * A(2) - KTR * A(3)
  ; ... up to N transit compartments

  ; Central compartment
  DADT(N+3) = KTR * A(N+2) - (K + K23) * A(N+3) + K32 * A(N+4)

  ; Peripheral compartment
  DADT(N+4) = K23 * A(N+3) - K32 * A(N+4)

$ERROR
  IPRED = F
  W = THETA(9)
  IRES = DV - IPRED
  IWRES = IRES/(W*IPRED)
  Y = IPRED + W*IPRED*EPS(1)

$THETA
  (0, 3)    ; 1 - CL/F (L/h)
  (0, 20)   ; 2 - V2/F (L)
  (0, 5)    ; 3 - Q/F (L/h)
  (0, 50)   ; 4 - V3/F (L)
  (0, 1.5)  ; 5 - ka (1/h)
  (0, 0.5)  ; 6 - tlag (h)
