/*
 * Structural PD model:
 * - Indirect response model with inhibition of factor Xa production
 * - Apixaban inhibits the production of factor Xa
 * - Delayed effect modeled with effect compartment
 *
 * Parameters:
 * - k_in: Zero-order rate constant for factor Xa production
 * - k_out: First-order rate constant for factor Xa degradation
 * - IC50: Concentration producing 50% inhibition of production
 * - k_e0: Effect compartment equilibration rate constant
 * - E_max: Maximum effect
 * - gamma: Hill coefficient
 * - baseline: Baseline anti-Xa activity
 */

// Base PD model code (NONMEM)
const basePdModelCode = `$PROBLEM APIXABAN PK/PD MODEL
$INPUT ID TIME AMT DV EVID CMT MDV DOSE ANTIXA
$DATA apixaban_pd_data.csv IGNORE=@
$SUBROUTINES ADVAN6 TOL=5
$MODEL COMP=(DEPOT) COMP=(CENTRAL) COMP=(PERIPHERAL) COMP=(EFFECT) COMP=(ANTIXA)

$PK
  ; PK parameters (from final PK model)
  TVCL = THETA(1) * (WT/70)**0.75 * (CRCL/80)**THETA(9) * (AGE/60)**THETA(10)
  IF (INHIBITOR.EQ.1) TVCL = TVCL * THETA(11)
  IF (INDUCER.EQ.1) TVCL = TVCL * THETA(12)
  TVV2 = THETA(2) * (WT/70)
  IF (SEX.EQ.0) TVV2 = TVV2 * THETA(13)
  TVQ = THETA(3)
  TVV3 = THETA(4)
  TVKA = THETA(5)
  TVTLAG = THETA(6)
  TVMTT = THETA(7)
  TVN = THETA(8)

  ; Individual PK parameters
  CL = TVCL * EXP(ETA(1))
  V2 = TVV2 * EXP(ETA(2))
  Q = TVQ * EXP(ETA(3))
  V3 = TVV3 * EXP(ETA(4))
  KA = TVKA * EXP(ETA(5))
  TLAG = TVTLAG
  MTT = TVMTT * EXP(ETA(6))
  N = TVN

  ; PD parameters
  TVKIN = THETA(14)
  TVKOUT = THETA(15)
  TVIC50 = THETA(16)
  TVKE0 = THETA(17)
  TVEMAX = THETA(18)
  TVGAMMA = THETA(19)
  TVBASE = THETA(20)

  ; Individual PD parameters
  KIN = TVKIN * EXP(ETA(7))
  KOUT = TVKOUT * EXP(ETA(8))
  IC50 = TVIC50 * EXP(ETA(9))
  KE0 = TVKE0
  EMAX = TVEMAX
  GAMMA = TVGAMMA
  BASE = TVBASE

  ; Secondary parameters
  K = CL/V2
  K23 = Q/V2
  K32 = Q/V3
  KTR = (N+1)/MTT
  S2 = V2

$DES
  ; PK - same as PK model
  DADT(1) = -KA * A(1)
  DADT(2) = KA * A(1) - KTR * A(2)
  DADT(3) = KTR * A(2) - KTR * A(3)
  DADT(4) = KTR * A(3) - (K + K23) * A(4) + K32 * A(5)
  DADT(5) = K23 * A(4) - K32 * A(5)

  ; Effect compartment
  DADT(6) = KE0 * (A(4)/V2 - A(6))

  ; PD - indirect response model
  INH = (EMAX * A(6)**GAMMA) / (A(6)**GAMMA + IC50**GAMMA)
  DADT(7) = KIN * (1 - INH) - KOUT * A(7)

$ERROR
  ; PK error
  IF (CMT.EQ.4) THEN
    IPRED = A(4)/V2
    W = THETA(21)
    IRES = DV - IPRED
    IWRES = IRES/(W*IPRED)
    Y = IPRED + W*IPRED*EPS(1)
  ENDIF

  ; PD error
  IF (CMT.EQ.7) THEN
    IPRED = BASE + A(7)
    W = THETA(22)
    IRES = DV - IPRED
    IWRES = IRES/W
    Y = IPRED + W*EPS(2)
  ENDIF

$THETA
  ; PK parameters
