  (-0.5, -0.2) ; 10 - age effect
  (0.5, 0.8) ; 11 - inhibitor effect
  (1.2, 2)   ; 12 - inducer effect
  (0.7, 1)   ; 13 - sex effect on V2
  (0, 0.2)   ; 21 - PK proportional error

  ; PD parameters
  (0, 1)     ; 14 - KIN
  (0, 0.5)   ; 15 - KOUT
  (0, 0.1)   ; 16 - IC50 (mg/L)
  (0, 0.2)   ; 17 - k_e0 (1/h)
