// Population genetics simulator
// Model: Wright-Fisher with selection
// Parameters: population size, mutation rate, selection coefficient

class Population {
    private:
        vector<vector<int>> genotypes;
        int populationSize;
        double mutationRate;
        double selectionCoeff;
        mt19937 rng;

    public:
        Population(int size, double mu, double s) : 
            populationSize(size), mutationRate(mu), selectionCoeff(s) {
            rng.seed(random_device()());

            // Initialize population with random genotypes
            genotypes.resize(size, vector<int>(2, 0));
            for (auto& individual : genotypes) {
                individual[0] = uniform_int_distribution<int>(0, 1)(rng);
                individual[1] = uniform_int_distribution<int>(0, 1)(rng);
            }
        }

        // Calculate fitness for a genotype
        double fitness(const vector<int>& genotype) {
            int alleleCount = genotype[0] + genotype[1];
            return 1.0 + selectionCoeff * alleleCount;
        }

        // Simulate one generation
        void nextGeneration() {
            vector<vector<int>> newGenotypes;

            // Calculate total fitness
            double totalFitness = 0.0;
            for (const auto& individual : genotypes) {
                totalFitness += fitness(individual);
            }

            // Create next generation
            while (newGenotypes.size() < populationSize) {
                // Select parents based on fitness
                uniform_real_distribution<double> dist(0.0, totalFitness);
                double randVal = dist(rng);
                double cumulative = 0.0;

                int parent1 = -1, parent2 = -1;
                for (size_t i = 0; i < genotypes.size(); ++i) {
                    cumulative += fitness(genotypes[i]);
                    if (cumulative >= randVal && parent1 == -1) {
                        parent1 = i;
                    } else if (cumulative >= randVal) {
                        parent2 = i;
                        break;
                    }
                }

                // Recombination
                vector<int> offspring(2);
                uniform_int_distribution<int> alleleDist(0, 1);
                offspring[0] = genotypes[parent1][alleleDist(rng)];
                offspring[1] = genotypes[parent2][alleleDist(rng)];

                // Mutation
                uniform_real_distribution<double> mutDist(0.0, 1.0);
                if (mutDist(rng) < mutationRate) {
                    offspring[0] = 1 - offspring[0];
                }
                if (mutDist(rng) < mutationRate) {
                    offspring[1] = 1 - offspring[1];
                }

                newGenotypes.push_back(offspring);
            }

            genotypes = newGenotypes;
        }

        // Calculate allele frequency
        double alleleFrequency() const {
            int alleleCount = 0;
            for (const auto& individual : genotypes) {
                alleleCount += individual[0] + individual[1];
            }
            return static_cast<double>(alleleCount) / (2 * populationSize);
        }
};

int main() {
    // Simulation parameters
    const int POP_SIZE = 1000;
    const double MUT_RATE = 0.0001;
    const double SELECTION = 0.01;
    const int GENERATIONS = 1000;

    Population pop(POP_SIZE, MUT_RATE, SELECTION);

    // Run simulation
    cout << "Generation,AlleleFrequency" << endl;
    for (int gen = 0; gen <= GENERATIONS; ++gen) {
        if (gen % 100 == 0) {
            cout << gen << "," << pop.alleleFrequency() << endl;
        }
        pop.nextGeneration();
    }

    return 0;
}

// Protein structure alignment
// Algorithm: TM-align
// Input: Two protein structures in PDB format
// Output: TM-score and aligned structure

#include <iostream>
