using namespace std;

struct Atom {
    string name;
    double x, y, z;
};

struct Protein {
    vector<Atom> atoms;
    string sequence;
};

// Read PDB file
Protein readPDB(const string& filename) {
    Protein protein;
    ifstream file(filename);
    string line;

    while (getline(file, line)) {
        if (line.substr(0, 4) == "ATOM") {
            Atom atom;
            atom.name = line.substr(12, 4);
            atom.x = stod(line.substr(30, 8));
            atom.y = stod(line.substr(38, 8));
            atom.z = stod(line.substr(46, 8));
            protein.atoms.push_back(atom);
        }
    }

    return protein;
}

// Calculate distance matrix
vector<vector<double>> distanceMatrix(const Protein& protein) {
    size_t n = protein.atoms.size();
    vector<vector<double>> dist(n, vector<double>(n, 0.0));

    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i+1; j < n; ++j) {
            double dx = protein.atoms[i].x - protein.atoms[j].x;
            double dy = protein.atoms[i].y - protein.atoms[j].y;
            double dz = protein.atoms[i].z - protein.atoms[j].z;
            dist[i][j] = dist[j][i] = sqrt(dx*dx + dy*dy + dz*dz);
        }
    }

    return dist;
}

// Kabsch algorithm for optimal rotation
vector<vector<double>> kabsch(const vector<vector<double>>& coords1,
                              const vector<vector<double>>& coords2) {
    // Center the coordinates
    vector<vector<double>> centered1 = coords1;
    vector<vector<double>> centered2 = coords2;

    // Calculate covariance matrix
    vector<vector<double>> cov(3, vector<double>(3, 0.0));
    for (size_t i = 0; i < coords1.size(); ++i) {
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < 3; ++k) {
                cov[j][k] += centered1[i][j] * centered2[i][k];
            }
        }
    }

    // SVD
    // (In practice, use a proper SVD implementation)
    vector<vector<double>> U = cov;  // Placeholder
    vector<vector<double>> V = cov;  // Placeholder
    vector<vector<double>> S = {{1,0,0}, {0,1,0}, {0,0,1}};  // Placeholder

    // Calculate rotation matrix
    vector<vector<double>> rotation(3, vector<double>(3, 0.0));
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < 3; ++k) {
                rotation[i][j] += V[i][k] * U[j][k];
            }
        }
    }

    return rotation;
}

// Calculate TM-score
double tmScore(const Protein& protein1, const Protein& protein2,
                const vector<int>& alignment) {
    vector<vector<double>> coords1, coords2;

    // Get aligned coordinates
    for (size_t i = 0; i < alignment.size(); ++i) {
        if (alignment[i] != -1) {
            coords1.push_back({protein1.atoms[i].x, protein1.atoms[i].y, protein1.atoms[i].z});
            coords2.push_back({protein2.atoms[alignment[i]].x, 
                              protein2.atoms[alignment[i]].y, 
                              protein2.atoms[alignment[i]].z});
        }
    }

    // Optimal rotation
    vector<vector<double>> rotation = kabsch(coords1, coords2);

    // Calculate TM-score
    double score = 0.0;
    double L = protein1.atoms.size();
    double d0 = 1.24 * pow(L - 15, 1.0/3) - 1.8;

    for (size_t i = 0; i < coords1.size(); ++i) {
        // Apply rotation
        vector<double> rotated(3);
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < 3; ++k) {
                rotated[j] += rotation[j][k] * coords1[i][k];
            }
        }

        // Calculate distance
        double dx = rotated[0] - coords2[i][0];
        double dy = rotated[1] - coords2[i][1];
        double dz = rotated[2] - coords2[i][2];
        double d = sqrt(dx*dx + dy*dy + dz*dz);

        score += 1.0 / (1.0 + pow(d/d0, 2));
    }

    return score / L;
}

