        while idx < len(intensities) - 1 and intensities[idx] > intensities[idx+1] * 0.8:
            idx += 1
        return idx

    def integrate_peaks(self):
        """Integrate area under each peak"""
        retention_times = self.sample['retention_times']
        intensities = self.sample['intensities']

        for i, peak in enumerate(self.peaks):
            start_idx = peak['start_idx']
            end_idx = peak['end_idx']

            area = 0
            for j in range(start_idx, end_idx):
                dt = retention_times[j+1] - retention_times[j]
                avg_intensity = (intensities[j] + intensities[j+1]) / 2
                area += dt * avg_intensity

            self.integrations[f'peak_{i+1}'] = {
                'retention_time': peak['retention_time'],
                'area': area,
                'height': peak['intensity'],
                'width': peak['width'],
                'start_time': retention_times[start_idx],
                'end_time': retention_times[end_idx]
            }

        return self.integrations

    def calculate_concentrations(self, calibration_data):
        """Calculate concentrations from peak areas using calibration"""
        concentrations = {}
        total_area = sum([peak['area'] for peak in self.integrations.values()])

        for peak_id, peak_data in self.integrations.items():
            # Linear calibration: concentration = slope * area + intercept
            slope = calibration_data.get('slope', 1.0)
            intercept = calibration_data.get('intercept', 0.0)

            concentration = slope * peak_data['area'] + intercept
            relative_abundance = (peak_data['area'] / total_area) * 100 if total_area > 0 else 0

            concentrations[peak_id] = {
                'concentration': concentration,
                'relative_abundance': relative_abundance,
                'retention_time': peak_data['retention_time'],
                'peak_area': peak_data['area']
            }

        return concentrations

    def identify_compounds(self, library):
        """Identify compounds based on retention times"""
        identifications = {}
        tolerance = 0.1  # Retention time tolerance in minutes

        for peak_id, peak_data in self.integrations.items():
            rt = peak_data['retention_time']
            best_match = None
            best_score = float('inf')

            for compound, compound_data in library.items():
                expected_rt = compound_data['retention_time']
                score = abs(rt - expected_rt)

                if score < tolerance and score < best_score:
                    best_match = compound
                    best_score = score

            identifications[peak_id] = {
                'compound': best_match,
                'match_score': best_score,
                'retention_time': rt,
                'confidence': 'high' if best_score < tolerance/2 else 'medium' if best_score < tolerance else 'low'
            }

        return identifications

    def generate_report(self):
        """Generate comprehensive analysis report"""
        report = {
            'sample_info': {
                'name': self.sample.get('name', 'Unknown'),
                'injection_volume': self.sample.get('injection_volume', 1.0),
                'run_time': self.sample['retention_times'][-1] if self.sample['retention_times'] else 0
            },
            'peak_detection': {
                'num_peaks': len(self.peaks),
                'peaks': self.peaks,
                'detection_threshold': 0.05
            },
            'integration_results': self.integrations,
            'quality_metrics': {
                'baseline_noise': self.calculate_baseline_noise(),
                'resolution': self.calculate_resolution(),
                'peak_symmetry': self.calculate_peak_symmetry()
            }
        }

        return report

    def calculate_baseline_noise(self):
        """Calculate baseline noise level"""
        if len(self.sample['intensities']) < 10:
            return 0

        # Use first 10 points as baseline
        baseline_points = self.sample['intensities'][:10]
        noise = np.std(baseline_points) if hasattr(np, 'std') else \
               (max(baseline_points) - min(baseline_points)) / 2
        return noise

    def calculate_resolution(self):
        """Calculate resolution between adjacent peaks"""
        resolutions = []
        sorted_peaks = sorted(self.peaks, key=lambda x: x['retention_time'])

        for i in range(len(sorted_peaks) - 1):
            rt1 = sorted_peaks[i]['retention_time']
            rt2 = sorted_peaks[i+1]['retention_time']
            w1 = sorted_peaks[i]['width']
            w2 = sorted_peaks[i+1]['width']

            if w1 > 0 and w2 > 0:
                resolution = 2 * (rt2 - rt1) / (w1 + w2)
                resolutions.append({
                    'peaks': (i+1, i+2),
                    'resolution': resolution
                })

        return resolutions

    def calculate_peak_symmetry(self):
        """Calculate peak symmetry factor"""
        symmetries = {}

        for i, peak in enumerate(self.peaks):
            peak_idx = peak['index']
            start_idx = peak['start_idx']
            end_idx = peak['end_idx']
            intensities = self.sample['intensities']

            # Calculate front and back half widths
            front_half = peak_idx - start_idx
            back_half = end_idx - peak_idx

            if front_half > 0 and back_half > 0:
                symmetry = back_half / front_half
                symmetries[f'peak_{i+1}'] = symmetry

        return symmetries

