        "text": "# Molecular Dynamics Simulation Framework

import numpy as np
from typing import Dict, List, Tuple
import math

class MolecularSystem:
    def __init__(self, atoms: List[Dict], box_size: Tuple[float, float, float], 
                 temperature: float = 300.0):
        """
        Initialize molecular system for MD simulation
        """
        self.atoms = atoms
        self.num_atoms = len(atoms)
        self.box_size = np.array(box_size)
        self.temperature = temperature
        self.positions = self._extract_positions()
        self.velocities = self._initialize_velocities()
        self.forces = np.zeros((self.num_atoms, 3))
        self.potential_energy = 0.0
        self.kinetic_energy = 0.0
        self.total_energy = 0.0

        # Simulation parameters
        self.time_step = 0.001  # ps
        self.simulation_time = 0.0
        self.step_counter = 0

        # Force field parameters
        self.force_field = {
            'lj_sigma': 3.4,      # Angstrom
            'lj_epsilon': 0.238,  # kcal/mol
            'coulomb_const': 332.1,  # kcal·mol⁻¹·Å·e⁻²
            'cutoff_distance': 10.0  # Angstrom
        }

        # Trajectory storage
        self.trajectory = []
        self.energy_history = []

    def _extract_positions(self):
        """Extract atomic positions from atom list"""
        positions = np.zeros((self.num_atoms, 3))
        for i, atom in enumerate(self.atoms):
            positions[i] = atom['position']
        return positions

    def _initialize_velocities(self):
        """Initialize velocities according to Maxwell-Boltzmann distribution"""
        velocities = np.random.normal(0, 1, (self.num_atoms, 3))

        # Scale to desired temperature
        kb = 0.0019872041  # Boltzmann constant in kcal/mol·K
        target_ke = 1.5 * kb * self.temperature * self.num_atoms

        current_ke = 0.5 * np.sum(self._get_masses()[:, np.newaxis] * 
                                 velocities**2)
        scale_factor = math.sqrt(target_ke / current_ke)

        velocities *= scale_factor

        # Remove center of mass motion
        total_mass = np.sum(self._get_masses())
        com_velocity = np.sum(self._get_masses()[:, np.newaxis] * velocities, 
                            axis=0) / total_mass
        velocities -= com_velocity

        return velocities

    def _get_masses(self):
        """Get atomic masses"""
        masses = np.zeros(self.num_atoms)
        for i, atom in enumerate(self.atoms):
            masses[i] = atom['mass']
        return masses

    def _get_charges(self):
        """Get atomic charges"""
        charges = np.zeros(self.num_atoms)
        for i, atom in enumerate(self.atoms):
            charges[i] = atom.get('charge', 0.0)
        return charges

    def calculate_forces(self):
        """Calculate forces on all atoms"""
        self.forces.fill(0.0)
        self.potential_energy = 0.0

        masses = self._get_masses()
        charges = self._get_charges()

        # Calculate all pairwise interactions
        for i in range(self.num_atoms):
            for j in range(i + 1, self.num_atoms):
                # Minimum image convention
                rij = self.positions[j] - self.positions[i]
                rij -= self.box_size * np.round(rij / self.box_size)

                distance = np.linalg.norm(rij)

                if distance < self.force_field['cutoff_distance']:
                    # Lennard-Jones potential
                    sigma = self.force_field['lj_sigma']
                    epsilon = self.force_field['lj_epsilon']

                    sr6 = (sigma / distance) ** 6
                    lj_energy = 4.0 * epsilon * (sr6**2 - sr6)
                    lj_force = 24.0 * epsilon * (2 * sr6**2 - sr6) / distance

                    # Coulomb potential
                    coulomb_const = self.force_field['coulomb_const']
                    qij = charges[i] * charges[j]
                    coulomb_energy = coulomb_const * qij / distance
                    coulomb_force = coulomb_const * qij / (distance**2)

                    # Total force
                    total_force = (lj_force + coulomb_force) * (rij / distance)

                    self.forces[i] += total_force
                    self.forces[j] -= total_force

                    self.potential_energy += lj_energy + coulomb_energy

    def calculate_kinetic_energy(self):
        """Calculate kinetic energy"""
        masses = self._get_masses()
        self.kinetic_energy = 0.5 * np.sum(masses[:, np.newaxis] * 
                                          self.velocities**2)
        return self.kinetic_energy

    def calculate_temperature(self):
        """Calculate instantaneous temperature"""
        kb = 0.0019872041  # Boltzmann constant in kcal/mol·K
        dof = 3 * self.num_atoms - 3  # Subtract 3 for COM motion
        self.calculate_kinetic_energy()
        return (2.0 * self.kinetic_energy) / (dof * kb)

    def apply_periodic_boundary(self):
        """Apply periodic boundary conditions"""
        self.positions = self.positions % self.box_size

    def velocity_verlet_step(self):
        """Perform one Velocity Verlet integration step"""
        masses = self._get_masses()
        dt = self.time_step

        # Update positions
        self.positions += self.velocities * dt + \
                         0.5 * self.forces / masses[:, np.newaxis] * dt**2

        # Apply periodic boundary conditions
        self.apply_periodic_boundary()

        # Save old forces
        old_forces = self.forces.copy()

        # Calculate new forces
        self.calculate_forces()

        # Update velocities
        self.velocities += 0.5 * (old_forces + self.forces) / \
                          masses[:, np.newaxis] * dt

        # Update energies
        self.calculate_kinetic_energy()
        self.total_energy = self.potential_energy + self.kinetic_energy

        # Update simulation time
        self.simulation_time += dt
        self.step_counter += 1

    def run_simulation(self, num_steps: int, save_frequency: int = 100):
        """Run MD simulation for specified number of steps"""
        print(f"Starting MD simulation for {num_steps} steps")
        print(f"Time step: {self.time_step} ps")
        print(f"Box size: {self.box_size} Å")
        print(f"Temperature: {self.temperature} K")
        print("=" * 50)

        for step in range(num_steps):
            self.velocity_verlet_step()

            # Save trajectory and energy
            if step % save_frequency == 0:
                self.trajectory.append(self.positions.copy())

                current_temp = self.calculate_temperature()
                self.energy_history.append({
                    'step': step,
                    'time': self.simulation_time,
                    'potential': self.potential_energy,
                    'kinetic': self.kinetic_energy,
                    'total': self.total_energy,
                    'temperature': current_temp
                })

            # Print progress
            if step % 1000 == 0:
                print(f"Step {step}: Time = {self.simulation_time:.3f} ps, " +
                      f"Temp = {self.calculate_temperature():.2f} K, " +
                      f"E_total = {self.total_energy:.4f} kcal/mol")

        print("=" * 50)
        print(f"Simulation completed after {num_steps} steps")
        print(f"Final temperature: {self.calculate_temperature():.2f} K")
        print(f"Final total energy: {self.total_energy:.4f} kcal/mol")

        return {
            'trajectory': np.array(self.trajectory),
            'energy_history': self.energy_history,
            'final_positions': self.positions,
            'final_velocities': self.velocities,
            'final_forces': self.forces
        }

    def calculate_rdf(self, num_bins: int = 100):
        """Calculate radial distribution function"""
        max_distance = min(self.box_size) / 2
        bin_width = max_distance / num_bins

        g_r = np.zeros(num_bins)
        norm_factor = np.zeros(num_bins)

        for frame in self.trajectory:
            for i in range(self.num_atoms):
                for j in range(i + 1, self.num_atoms):
                    rij = frame[j] - frame[i]
                    rij -= self.box_size * np.round(rij / self.box_size)
                    distance = np.linalg.norm(rij)

                    if distance < max_distance:
                        bin_idx = int(distance / bin_width)
                        if bin_idx < num_bins:
                            g_r[bin_idx] += 2  # Count i-j and j-i

            # Normalization
            volume = np.prod(self.box_size)
            density = self.num_atoms / volume

            for bin_idx in range(num_bins):
                r_inner = bin_idx * bin_width
                r_outer = (bin_idx + 1) * bin_width
                shell_volume = (4/3) * np.pi * (r_outer**3 - r_inner**3)
                norm_factor[bin_idx] = density * shell_volume * \
                                     len(self.trajectory) * self.num_atoms

        g_r = g_r / norm_factor

        r_values = [(i + 0.5) * bin_width for i in range(num_bins)]

        return {
            'r': r_values,
            'g_r': g_r,
            'bin_width': bin_width,
            'max_distance': max_distance
        }

    def calculate_msd(self):
        """Calculate mean squared displacement"""
        if len(self.trajectory) < 2:
            return None

        num_frames = len(self.trajectory)
        msd = np.zeros(num_frames)

        initial_positions = self.trajectory[0]

        for t in range(num_frames):
            displacement = self.trajectory[t] - initial_positions
            displacement -= self.box_size * np.round(displacement / self.box_size)

            msd[t] = np.mean(np.sum(displacement**2, axis=1))

        times = [i * self.time_step * 100 for i in range(num_frames)]

        return {
            'time': times,
            'msd': msd,
            'diffusion_coefficient': np.polyfit(times[10:], msd[10:], 1)[0] / 6
        }

