        "text": "function reactionKineticsSolver() {
    // Define reaction mechanism
    const mechanism = {
        reactions: [
            {
                id: 'R1',
                equation: 'A + B → C',
                rateLaw: 'k1 * [A] * [B]',
                rateConstant: {
                    value: 0.05,
                    units: 'L·mol⁻¹·s⁻¹',
                    activationEnergy: 45000, // J/mol
                    preExponential: 1e10
                }
            },
            {
                id: 'R2',
                equation: 'C → D + E',
                rateLaw: 'k2 * [C]',
                rateConstant: {
                    value: 0.02,
                    units: 's⁻¹',
                    activationEnergy: 55000,
                    preExponential: 1e12
                }
            },
            {
                id: 'R3',
                equation: 'D + E → F',
                rateLaw: 'k3 * [D] * [E]',
                rateConstant: {
                    value: 0.01,
                    units: 'L·mol⁻¹·s⁻¹',
                    activationEnergy: 40000,
                    preExponential: 1e9
                }
            }
        ],
        species: {
            'A': {initialConc: 1.0, color: 'red', molecularWeight: 100},
            'B': {initialConc: 1.5, color: 'blue', molecularWeight: 150},
            'C': {initialConc: 0.0, color: 'green', molecularWeight: 250},
            'D': {initialConc: 0.0, color: 'orange', molecularWeight: 120},
            'E': {initialConc: 0.0, color: 'purple', molecularWeight: 130},
            'F': {initialConc: 0.0, color: 'brown', molecularWeight: 250}
        }
    };

    // Initialize concentrations
    let concentrations = {};
    for (const [species, data] of Object.entries(mechanism.species)) {
        concentrations[species] = data.initialConc;
    }

    // Simulation parameters
    const simulationParams = {
        timeSpan: [0, 1000], // seconds
        timeStep: 0.1,
        temperature: 298.15, // Kelvin
        pressure: 101.325, // kPa
        volume: 1.0 // liters
    };

    // Results storage
    const results = {
        time: [],
        concentrations: {},
        rates: [],
        conversions: {},
        yields: {}
    };

    // Initialize concentration arrays
    for (const species of Object.keys(mechanism.species)) {
        results.concentrations[species] = [];
    }

    // Calculate temperature-dependent rate constants
    function calculateRateConstants(T) {
        const R = 8.314462618; // J/mol·K
        const rateConstants = {};

        for (const reaction of mechanism.reactions) {
            const k0 = reaction.rateConstant.preExponential;
            const Ea = reaction.rateConstant.activationEnergy;

            // Arrhenius equation: k = A * exp(-Ea/(R*T))
            const k = k0 * Math.exp(-Ea / (R * T));
            rateConstants[reaction.id] = k;
        }

        return rateConstants;
    }

    // Calculate reaction rates
    function calculateRates(currentConcentrations, rateConstants) {
        const rates = {};

        // Reaction 1: A + B → C
        rates.R1 = rateConstants.R1 * 
                   currentConcentrations.A * 
                   currentConcentrations.B;

        // Reaction 2: C → D + E
        rates.R2 = rateConstants.R2 * 
                   currentConcentrations.C;

        // Reaction 3: D + E → F
        rates.R3 = rateConstants.R3 * 
                   currentConcentrations.D * 
                   currentConcentrations.E;

        return rates;
    }

    // Calculate concentration derivatives
    function calculateDerivatives(currentConcentrations, rates) {
        const derivatives = {};

        // d[A]/dt = -rate_R1
        derivatives.A = -rates.R1;

        // d[B]/dt = -rate_R1
        derivatives.B = -rates.R1;

        // d[C]/dt = rate_R1 - rate_R2
        derivatives.C = rates.R1 - rates.R2;

        // d[D]/dt = rate_R2 - rate_R3
        derivatives.D = rates.R2 - rates.R3;

        // d[E]/dt = rate_R2 - rate_R3
        derivatives.E = rates.R2 - rates.R3;

        // d[F]/dt = rate_R3
        derivatives.F = rates.R3;

        return derivatives;
    }

    // Runge-Kutta 4th order integration
    function rk4Step(currentConcentrations, rateConstants, dt) {
        // Calculate k1
        const rates1 = calculateRates(currentConcentrations, rateConstants);
        const deriv1 = calculateDerivatives(currentConcentrations, rates1);

        // Calculate k2
        const conc2 = {};
        for (const species of Object.keys(currentConcentrations)) {
            conc2[species] = currentConcentrations[species] + 
                           0.5 * dt * deriv1[species];
        }
        const rates2 = calculateRates(conc2, rateConstants);
        const deriv2 = calculateDerivatives(conc2, rates2);

        // Calculate k3
        const conc3 = {};
        for (const species of Object.keys(currentConcentrations)) {
            conc3[species] = currentConcentrations[species] + 
                           0.5 * dt * deriv2[species];
        }
        const rates3 = calculateRates(conc3, rateConstants);
        const deriv3 = calculateDerivatives(conc3, rates3);

        // Calculate k4
        const conc4 = {};
        for (const species of Object.keys(currentConcentrations)) {
            conc4[species] = currentConcentrations[species] + 
                           dt * deriv3[species];
        }
        const rates4 = calculateRates(conc4, rateConstants);
        const deriv4 = calculateDerivatives(conc4, rates4);

        // Combine to get final derivatives
        const newConcentrations = {};
        for (const species of Object.keys(currentConcentrations)) {
            newConcentrations[species] = currentConcentrations[species] + 
                                       (dt / 6) * (deriv1[species] + 
                                                   2 * deriv2[species] + 
                                                   2 * deriv3[species] + 
                                                   deriv4[species]);
        }

        return newConcentrations;
    }

    // Main simulation loop
    function runSimulation() {
        const [tStart, tEnd] = simulationParams.timeSpan;
        const dt = simulationParams.timeStep;
        let t = tStart;

        // Initialize rate constants
        const rateConstants = calculateRateConstants(simulationParams.temperature);

        // Store initial conditions
        results.time.push(t);
        for (const [species, conc] of Object.entries(concentrations)) {
            results.concentrations[species].push(conc);
        }

        // Time stepping
        while (t < tEnd) {
            // Calculate new concentrations
            concentrations = rk4Step(concentrations, rateConstants, dt);

            // Update time
            t += dt;

            // Store results
            results.time.push(t);
            for (const [species, conc] of Object.entries(concentrations)) {
                results.concentrations[species].push(conc);
            }

            // Calculate current rates
            const currentRates = calculateRates(concentrations, rateConstants);
            results.rates.push({
                time: t,
                R1: currentRates.R1,
                R2: currentRates.R2,
                R3: currentRates.R3
            });

            // Calculate conversions
            const initialA = mechanism.species.A.initialConc;
            const initialB = mechanism.species.B.initialConc;

            results.conversions[t] = {
                A: ((initialA - concentrations.A) / initialA) * 100,
                B: ((initialB - concentrations.B) / initialB) * 100
            };

            // Calculate yields
            const theoreticalF = Math.min(initialA, initialB);
            results.yields[t] = {
                C: (concentrations.C / theoreticalF) * 100,
                D: (concentrations.D / theoreticalF) * 100,
                E: (concentrations.E / theoreticalF) * 100,
                F: (concentrations.F / theoreticalF) * 100
            };
        }

        return results;
    }

    // Run simulation
    const simulationResults = runSimulation();

    // Analysis functions
    function findMaximumConversion() {
        let maxConversion = 0;
        let maxTime = 0;
        let maxSpecies = '';

        for (const [time, conversions] of Object.entries(simulationResults.conversions)) {
            for (const [species, conversion] of Object.entries(conversions)) {
                if (conversion > maxConversion) {
                    maxConversion = conversion;
                    maxTime = parseFloat(time);
                    maxSpecies = species;
                }
            }
        }

        return {
            species: maxSpecies,
            conversion: maxConversion,
            time: maxTime
        };
    }

    function findMaximumYield() {
        let maxYield = 0;
        let maxTime = 0;
        let maxSpecies = '';

        for (const [time, yields] of Object.entries(simulationResults.yields)) {
            for (const [species, yield_] of Object.entries(yields)) {
                if (yield_ > maxYield) {
                    maxYield = yield_;
                    maxTime = parseFloat(time);
                    maxSpecies = species;
                }
            }
        }

        return {
            species: maxSpecies,
            yield: maxYield,
            time: maxTime
        };
    }

    function calculateSelectivity() {
        const finalTime = simulationResults.time[simulationResults.time.length - 1];
        const finalYields = simulationResults.yields[finalTime];

        // Selectivity of F relative to other products
        const totalProducts = finalYields.C + finalYields.D + finalYields.E + finalYields.F;
        const selectivityF = (finalYields.F / totalProducts) * 100;

        return {
            F: selectivityF,
            C: (finalYields.C / totalProducts) * 100,
            D: (finalYields.D / totalProducts) * 100,
            E: (finalYields.E / totalProducts) * 100
        };
    }

    // Generate report
    const report = {
        simulationParameters: simulationParams,
        mechanism: mechanism,
        results: {
            timePoints: simulationResults.time.length,
            finalTime: simulationResults.time[simulationResults.time.length - 1],
            finalConcentrations: {},
            maximumConversion: findMaximumConversion(),
            maximumYield: findMaximumYield(),
            selectivity: calculateSelectivity()
        }
    };

    // Add final concentrations
    for (const species of Object.keys(mechanism.species)) {
        report.results.finalConcentrations[species] = 
            simulationResults.concentrations[species][simulationResults.concentrations[species].length - 1];
    }

    // Print summary
    console.log('Reaction Kinetics Simulation Results');
    console.log('='.repeat(50));
    console.log(`Temperature: ${simulationParams.temperature} K`);
    console.log(`Pressure: ${simulationParams.pressure} kPa`);
    console.log(`Volume: ${simulationParams.volume} L`);
    console.log(`Time span: ${simulationParams.timeSpan[0]} to ${simulationParams.timeSpan[1]} s`);
    console.log(`Time step: ${simulationParams.timeStep} s`);
    console.log('\nFinal Concentrations (mol/L):');
    for (const [species, conc] of Object.entries(report.results.finalConcentrations)) {
        console.log(`  ${species}: ${conc.toFixed(4)}`);
    }
    console.log('\nMaximum Conversion:');
    console.log(`  Species: ${report.results.maximumConversion.species}`);
    console.log(`  Value: ${report.results.maximumConversion.conversion.toFixed(2)}%`);
    console.log(`  Time: ${report.results.maximumConversion.time.toFixed(1)} s`);
    console.log('\nMaximum Yield:');
    console.log(`  Species: ${report.results.maximumYield.species}`);
    console.log(`  Value: ${report.results.maximumYield.yield.toFixed(2)}%`);
    console.log(`  Time: ${report.results.maximumYield.time.toFixed(1)} s`);
    console.log('\nProduct Selectivity (%):');
