                          String.join(",", ENV_VARIABLES.stream()
                              .map(v -> v + "_correlation")
                              .collect(Collectors.toList())));

            for (SpeciesStats stats : speciesStats.values()) {
                writer.printf("%s,%s,%d,%.1f,%.1f,%.1f,%.1f,%.1f,%.1f,%.1f,%.1f,%.1f",
                             stats.species, 
                             observations.stream()
                                 .filter(o -> o.species.equals(stats.species))
                                 .findFirst()
                                 .map(o -> o.speciesGroup)
                                 .orElse("Unknown"),
                             stats.observationCount,
                             stats.minDepth, stats.maxDepth, stats.avgDepth,
                             stats.minTemp, stats.maxTemp, stats.avgTemp,
                             stats.minSalinity, stats.maxSalinity, stats.avgSalinity);

                for (String var : ENV_VARIABLES) {
                    writer.printf(",%.3f", stats.envCorrelations.getOrDefault(var, Double.NaN));
                }
                writer.println();
            }
        } catch (FileNotFoundException e) {
            System.err.println("Error writing species report: " + e.getMessage());
        }
    }

    private void generateRegionReport() {
        try (PrintWriter writer = new PrintWriter(OUTPUT_DIR + "/region_report.csv")) {
            writer.println("region,observations," +
                          String.join(",", SPECIES_GROUPS.stream()
                              .map(g -> g + "_species_count")
                              .collect(Collectors.toList())) + "," +
                          String.join(",", ENV_VARIABLES.stream()
                              .map(v -> v + "_avg")
                              .collect(Collectors.toList())));

            for (RegionStats region : regions) {
                writer.printf("%s,%d", region.regionName, region.observationCount);

                // Species group counts
                for (String group : SPECIES_GROUPS) {
                    long count = region.speciesCounts.entrySet().stream()
                        .filter(e -> observations.stream()
                            .filter(o -> o.species.equals(e.getKey()))
                            .findFirst()
                            .map(o -> o.speciesGroup.equals(group))
                            .orElse(false))
                        .mapToInt(Map.Entry::getValue)
                        .sum();
                    writer.printf(",%d", count);
                }

                // Environmental averages
                for (String var : ENV_VARIABLES) {
                    writer.printf(",%.2f", region.envAverages.get(var));
                }

                writer.println();
            }
        } catch (FileNotFoundException e) {
            System.err.println("Error writing region report: " + e.getMessage());
        }
    }

    private void generateSummaryReport() {
        try (PrintWriter writer = new PrintWriter(OUTPUT_DIR + "/summary_report.txt")) {
            writer.println("Marine Biology Data Processing Summary");
            writer.println("=====================================");
            writer.println();
            writer.println("Processing Date: " + LocalDateTime.now());
            writer.println();

            writer.println("Data Overview:");
            writer.println("--------------");
            writer.println("Total observations: " + observations.size());
            writer.println("Unique species: " + speciesStats.size());
            writer.println("Date range: " +
                          observations.stream()
                              .map(Observation::getDate)
                              .min(LocalDate::compareTo)
                              .orElse(LocalDate.MIN) +
                          " to " +
                          observations.stream()
                              .map(Observation::getDate)
                              .max(LocalDate::compareTo)
                              .orElse(LocalDate.MAX));
            writer.println();

            writer.println("Species Groups:");
            writer.println("--------------");
            for (String group : SPECIES_GROUPS) {
                long count = observations.stream()
                    .filter(o -> o.speciesGroup.equals(group))
                    .count();
                writer.printf("%s: %d observations (%.1f%%)%n", 
                             group, count, 100.0 * count / observations.size());
            }
            writer.println();

            writer.println("Environmental Statistics:");
            writer.println("------------------------");
            for (String var : ENV_VARIABLES) {
                DescriptiveStatistics stats = new DescriptiveStatistics();
                observations.stream()
                    .mapToDouble(o -> o.getEnvVariable(var))
                    .filter(d -> !Double.isNaN(d))
                    .forEach(stats::addValue);

                writer.printf("%s: mean=%.2f, std=%.2f, min=%.2f, max=%.2f%n", 
                             var, stats.getMean(), stats.getStandardDeviation(), 
                             stats.getMin(), stats.getMax());
            }
            writer.println();

            writer.println("Top 10 Most Observed Species:");
            writer.println("----------------------------");
            speciesStats.entrySet().stream()
                .sorted((e1, e2) -> Integer.compare(e2.getValue().observationCount, 
                                                   e1.getValue().observationCount))
                .limit(10)
                .forEach(e -> writer.printf("%s: %d observations%n", 
                                          e.getKey(), e.getValue().observationCount));

        } catch (FileNotFoundException e) {
            System.err.println("Error writing summary report: " + e.getMessage());
        }
    }

    // Main processing method
    public void process() {
        try {
            // Load configuration
            loadConfig();

            // Setup directories
            setupDirectories();

            // Connect to database
            connectToDatabase();

            // Load data
            loadDataFromDatabase();
            loadDataFromFiles();

            // Filter data
            filterData();

            // Calculate statistics
            calculateStatistics();

            // Perform analyses
            detectAnomalies();
            analyzeTemporalPatterns();
            analyzeSpatialPatterns();
            buildSpeciesDistributionModels();

            // Generate reports
            generateReports();

            System.out.println("Processing completed successfully!");
        } catch (Exception e) {
            System.err.println("Error during processing: " + e.getMessage());
            e.printStackTrace();
        } finally {
            // Close database connection
            if (dbConnection != null) {
                try {
                    dbConnection.close();
                } catch (SQLException e) {
                    System.err.println("Error closing database connection: " + e.getMessage());
                }
            }
        }
    }

    // Main method
    public static void main(String[] args) {
        MarineBioDataProcessor processor = new MarineBioDataProcessor();
        processor.process();
    }
}

