const fs = require('fs');
const path = require('path');
const csv = require('csv-parser');
const { createObjectCsvWriter } = require('csv-writer');
const { parse } = require('json2csv');
const math = require('mathjs');
const Plotly = require('plotly.js-dist');
const turf = require('@turf/turf');
const { DateTime } = require('luxon');

// Configuration
const CONFIG = {
    inputDir: 'data/raw',
    outputDir: 'data/processed',
    tempDir: 'data/temp',
    logDir: 'logs',
    minDepth: 0,
    maxDepth: 11000,
    minTemp: -2,
    maxTemp: 40,
    minSalinity: 10,
    maxSalinity: 40,
    gridSize: 1, // degrees for spatial analysis
    timeBin: 'month', // 'day', 'week', 'month', 'year'
    speciesGroups: {
        'Fish': ['tuna', 'cod', 'salmon', 'shark', 'sardine', 'anchovy', 'mackerel'],
        'Mammals': ['whale', 'dolphin', 'seal', 'walrus', 'porpoise'],
        'Invertebrates': ['crab', 'lobster', 'shrimp', 'squid', 'octopus', 'jellyfish', 'starfish', 'urchin'],
        'Plankton': ['plankton', 'copepod', 'krill', 'diatom'],
        'Algae': ['algae', 'kelp', 'seaweed'],
        'Corals': ['coral', 'anemone']
    }
};

// Create directories if they don't exist
function setupDirectories() {
    [CONFIG.inputDir, CONFIG.outputDir, CONFIG.tempDir, CONFIG.logDir].forEach(dir => {
        if (!fs.existsSync(dir)) {
            fs.mkdirSync(dir, { recursive: true });
        }
    });
}

// Data structures
class Observation {
    constructor(data) {
        this.timestamp = data.timestamp;
        this.latitude = parseFloat(data.latitude);
        this.longitude = parseFloat(data.longitude);
        this.depth = parseFloat(data.depth);
        this.species = data.species;
        this.quantity = parseFloat(data.quantity) || 0;
        this.quantityType = data.quantity_type || 'individuals';
        this.lifeStage = data.life_stage;
        this.behavior = data.behavior;

        // Environmental data
        this.environment = {};
        ['temperature', 'salinity', 'oxygen', 'ph', 'turbidity', 'chlorophyll'].forEach(param => {
            if (data[param] !== undefined) {
                this.environment[param] = parseFloat(data[param]);
            }
        });

        // Derived properties
        this.date = DateTime.fromISO(this.timestamp);
        this.speciesGroup = this.determineSpeciesGroup();
        this.valid = this.validate();
    }

    determineSpeciesGroup() {
        if (!this.species) return 'Unknown';

        const speciesLower = this.species.toLowerCase();

        for (const [group, keywords] of Object.entries(CONFIG.speciesGroups)) {
            if (keywords.some(keyword => speciesLower.includes(keyword))) {
                return group;
            }
        }

        return 'Other';
    }

    validate() {
        // Validate coordinates
        if (this.latitude < -90 || this.latitude > 90 || 
            this.longitude < -180 || this.longitude > 180) {
            return false;
        }

        // Validate depth
        if (this.depth < CONFIG.minDepth || this.depth > CONFIG.maxDepth) {
            return false;
        }

        // Validate environmental parameters
        if (this.environment.temperature !== undefined &&
            (this.environment.temperature < CONFIG.minTemp || 
             this.environment.temperature > CONFIG.maxTemp)) {
            return false;
        }

        if (this.environment.salinity !== undefined &&
            (this.environment.salinity < CONFIG.minSalinity || 
             this.environment.salinity > CONFIG.maxSalinity)) {
            return false;
        }

        return true;
    }

    getTimeBin() {
        switch (CONFIG.timeBin) {
            case 'day':
                return this.date.toISODate();
            case 'week':
                return this.date.startOf('week').toISODate();
            case 'month':
                return this.date.toFormat('yyyy-MM');
            case 'year':
                return this.date.toFormat('yyyy');
            default:
                return this.date.toISODate();
        }
    }
}

class SpeciesStats {
    constructor(species) {
        this.species = species;
        this.observationCount = 0;
        this.minDepth = Infinity;
        this.maxDepth = -Infinity;
        this.sumDepth = 0;
        this.minTemp = Infinity;
        this.maxTemp = -Infinity;
        this.sumTemp = 0;
        this.minSalinity = Infinity;
        this.maxSalinity = -Infinity;
        this.sumSalinity = 0;
        this.quantityStats = {
            sum: 0,
            sumSq: 0,
            min: Infinity,
            max: -Infinity
        };
        this.envCorrelations = {};
        this.timeDistribution = {};
        this.spatialDistribution = {};
    }

    addObservation(obs) {
        this.observationCount++;

        // Update depth stats
        this.minDepth = Math.min(this.minDepth, obs.depth);
        this.maxDepth = Math.max(this.maxDepth, obs.depth);
        this.sumDepth += obs.depth;

        // Update temperature stats
        if (obs.environment.temperature !== undefined) {
            this.minTemp = Math.min(this.minTemp, obs.environment.temperature);
            this.maxTemp = Math.max(this.maxTemp, obs.environment.temperature);
            this.sumTemp += obs.environment.temperature;
        }

        // Update salinity stats
        if (obs.environment.salinity !== undefined) {
            this.minSalinity = Math.min(this.minSalinity, obs.environment.salinity);
            this.maxSalinity = Math.max(this.maxSalinity, obs.environment.salinity);
            this.sumSalinity += obs.environment.salinity;
        }

        // Update quantity stats
        this.quantityStats.sum += obs.quantity;
        this.quantityStats.sumSq += obs.quantity * obs.quantity;
        this.quantityStats.min = Math.min(this.quantityStats.min, obs.quantity);
        this.quantityStats.max = Math.max(this.quantityStats.max, obs.quantity);

        // Update time distribution
        const timeBin = obs.getTimeBin();
        this.timeDistribution[timeBin] = (this.timeDistribution[timeBin] || 0) + obs.quantity;

        // Update spatial distribution
        const latBin = Math.floor(obs.latitude / CONFIG.gridSize) * CONFIG.gridSize;
        const lonBin = Math.floor(obs.longitude / CONFIG.gridSize) * CONFIG.gridSize;
        const gridKey = `${latBin},${lonBin}`;

        if (!this.spatialDistribution[gridKey]) {
            this.spatialDistribution[gridKey] = {
                latitude: latBin + CONFIG.gridSize/2,
                longitude: lonBin + CONFIG.gridSize/2,
                count: 0,
                quantity: 0
            };
        }

        this.spatialDistribution[gridKey].count++;
        this.spatialDistribution[gridKey].quantity += obs.quantity;
    }

    calculateStats() {
        // Calculate averages
        this.avgDepth = this.sumDepth / this.observationCount;
        this.avgTemp = this.sumTemp / this.observationCount;
        this.avgSalinity = this.sumSalinity / this.observationCount;
        this.avgQuantity = this.quantityStats.sum / this.observationCount;

        // Calculate standard deviation for quantity
        const variance = (this.quantityStats.sumSq - 
                         (this.quantityStats.sum * this.quantityStats.sum) / this.observationCount) /
                        (this.observationCount - 1);
        this.stdQuantity = Math.sqrt(variance);
    }
}

class RegionStats {
    constructor(name, minLat, maxLat, minLon, maxLon) {
        this.name = name;
        this.minLat = minLat;
        this.maxLat = maxLat;
        this.minLon = minLon;
        this.maxLon = maxLon;
        this.observationCount = 0;
        this.speciesCounts = {};
        this.envStats = {
            temperature: { sum: 0, count: 0 },
            salinity: { sum: 0, count: 0 },
            oxygen: { sum: 0, count: 0 }
        };
    }

    contains(lat, lon) {
        return lat >= this.minLat && lat <= this.maxLat && 
               lon >= this.minLon && lon <= this.maxLon;
    }

    addObservation(obs) {
        this.observationCount++;

        // Update species counts
        this.speciesCounts[obs.species] = (this.speciesCounts[obs.species] || 0) + 1;

        // Update environmental stats
        if (obs.environment.temperature !== undefined) {
            this.envStats.temperature.sum += obs.environment.temperature;
            this.envStats.temperature.count++;
        }

        if (obs.environment.salinity !== undefined) {
            this.envStats.salinity.sum += obs.environment.salinity;
            this.envStats.salinity.count++;
        }

        if (obs.environment.oxygen !== undefined) {
            this.envStats.oxygen.sum += obs.environment.oxygen;
            this.envStats.oxygen.count++;
        }
    }

    calculateStats() {
        // Calculate environmental averages
        for (const param in this.envStats) {
            if (this.envStats[param].count > 0) {
                this.envStats[param].avg = this.envStats[param].sum / this.envStats[param].count;
            }
        }
    }
}

// Main analysis class
class MarineBioDataAnalysis {
    constructor() {
