        // Define ocean regions
        this.defineRegions();
    }

    defineRegions() {
        this.regionStats = [
            new RegionStats('Tropical Pacific', -30, 30, 120, 280),
            new RegionStats('North Pacific', 30, 66.5, 120, 240),
            new RegionStats('South Pacific', -66.5, -30, 150, 280),
            new RegionStats('Tropical Atlantic', -30, 30, -80, 20),
            new RegionStats('North Atlantic', 30, 66.5, -80, 0),
            new RegionStats('South Atlantic', -66.5, -30, -60, 20),
            new RegionStats('Indian Ocean', -66.5, 30, 20, 120),
            new RegionStats('Southern Ocean', -90, -60, -180, 180),
            new RegionStats('Arctic Ocean', 66.5, 90, -180, 180)
        ];
    }

    loadData() {
        return new Promise((resolve, reject) => {
            const files = fs.readdirSync(CONFIG.inputDir).filter(f => f.endsWith('.csv'));

            if (files.length === 0) {
                reject(new Error('No CSV files found in input directory'));
                return;
            }

            let processedFiles = 0;

            files.forEach(file => {
                const filePath = path.join(CONFIG.inputDir, file);
                const results = [];

                fs.createReadStream(filePath)
                    .pipe(csv())
                    .on('data', (data) => results.push(data))
                    .on('end', () => {
                        // Process the data
                        results.forEach(row => {
                            const obs = new Observation(row);
                            if (obs.valid) {
                                this.observations.push(obs);
                            }
                        });

                        processedFiles++;
                        if (processedFiles === files.length) {
                            console.log(`Loaded ${this.observations.length} observations from ${files.length} files`);
                            resolve();
                        }
                    })
                    .on('error', (err) => {
                        console.error(`Error processing file ${file}:`, err);
                        processedFiles++;
                        if (processedFiles === files.length) {
                            resolve(); // Continue with available data
                        }
                    });
            });
        });
    }

    calculateStatistics() {
        console.log('Calculating statistics...');

        // Initialize species stats
        this.observations.forEach(obs => {
            if (!this.speciesStats[obs.species]) {
                this.speciesStats[obs.species] = new SpeciesStats(obs.species);
            }
            this.speciesStats[obs.species].addObservation(obs);
        });

        // Calculate stats for each species
        for (const species in this.speciesStats) {
            this.speciesStats[species].calculateStats();
        }

        // Calculate region stats
        this.observations.forEach(obs => {
            this.regionStats.forEach(region => {
                if (region.contains(obs.latitude, obs.longitude)) {
                    region.addObservation(obs);
                }
            });
        });

        // Calculate region stats
        this.regionStats.forEach(region => {
            region.calculateStats();
        });

        // Calculate time series
        this.calculateTimeSeries();

        // Calculate spatial data
        this.calculateSpatialData();

        console.log(`Calculated statistics for ${Object.keys(this.speciesStats).length} species`);
    }

    calculateTimeSeries() {
        console.log('Calculating time series...');

        // Initialize time series structure
        this.timeSeries = {
            total: {},
            bySpecies: {},
            byGroup: {},
            environmental: {
                temperature: {},
                salinity: {},
                oxygen: {}
            }
        };

        // Initialize species and group time series
        Object.keys(this.speciesStats).forEach(species => {
            this.timeSeries.bySpecies[species] = {};
        });

        Object.keys(CONFIG.speciesGroups).forEach(group => {
            this.timeSeries.byGroup[group] = {};
        });

        // Process each observation
        this.observations.forEach(obs => {
            const timeBin = obs.getTimeBin();

            // Total observations
            this.timeSeries.total[timeBin] = (this.timeSeries.total[timeBin] || 0) + 1;

            // By species
            this.timeSeries.bySpecies[obs.species][timeBin] = 
                (this.timeSeries.bySpecies[obs.species][timeBin] || 0) + obs.quantity;

            // By group
            this.timeSeries.byGroup[obs.speciesGroup][timeBin] = 
                (this.timeSeries.byGroup[obs.speciesGroup][timeBin] || 0) + obs.quantity;

            // Environmental data
            if (obs.environment.temperature !== undefined) {
                this.timeSeries.environmental.temperature[timeBin] = 
                    (this.timeSeries.environmental.temperature[timeBin] || 0) + obs.environment.temperature;
                this.timeSeries.environmental.temperature[`${timeBin}_count`] = 
                    (this.timeSeries.environmental.temperature[`${timeBin}_count`] || 0) + 1;
            }

            if (obs.environment.salinity !== undefined) {
                this.timeSeries.environmental.salinity[timeBin] = 
                    (this.timeSeries.environmental.salinity[timeBin] || 0) + obs.environment.salinity;
                this.timeSeries.environmental.salinity[`${timeBin}_count`] = 
                    (this.timeSeries.environmental.salinity[`${timeBin}_count`] || 0) + 1;
            }

            if (obs.environment.oxygen !== undefined) {
                this.timeSeries.environmental.oxygen[timeBin] = 
                    (this.timeSeries.environmental.oxygen[timeBin] || 0) + obs.environment.oxygen;
                this.timeSeries.environmental.oxygen[`${timeBin}_count`] = 
                    (this.timeSeries.environmental.oxygen[`${timeBin}_count`] || 0) + 1;
            }
        });

        // Calculate averages for environmental data
        ['temperature', 'salinity', 'oxygen'].forEach(param => {
            for (const timeBin in this.timeSeries.environmental[param]) {
                if (!timeBin.endsWith('_count')) {
                    const countKey = `${timeBin}_count`;
                    if (this.timeSeries.environmental[param][countKey] > 0) {
                        this.timeSeries.environmental[param][timeBin] /= 
                            this.timeSeries.environmental[param][countKey];
                    }
                }
            }
        });
    }

    calculateSpatialData() {
        console.log('Calculating spatial data...');

        this.spatialData = {
            speciesDistribution: {},
            environmental: {
                temperature: {},
                salinity: {},
                oxygen: {}
            }
        };

        // Initialize grid
        const latBins = Math.ceil(180 / CONFIG.gridSize);
        const lonBins = Math.ceil(360 / CONFIG.gridSize);

        // Process each observation
        this.observations.forEach(obs => {
            const latBin = Math.floor((obs.latitude + 90) / CONFIG.gridSize);
            const lonBin = Math.floor((obs.longitude + 180) / CONFIG.gridSize);
            const gridKey = `${latBin},${lonBin}`;

            // Species distribution
            if (!this.spatialData.speciesDistribution[gridKey]) {
                this.spatialData.speciesDistribution[gridKey] = {
                    latitude: latBin * CONFIG.gridSize - 90 + CONFIG.gridSize/2,
                    longitude: lonBin * CONFIG.gridSize - 180 + CONFIG.gridSize/2,
                    species: {}
                };
            }

            this.spatialData.speciesDistribution[gridKey].species[obs.species] = 
                (this.spatialData.speciesDistribution[gridKey].species[obs.species] || 0) + obs.quantity;

            // Environmental data
            ['temperature', 'salinity', 'oxygen'].forEach(param => {
                if (obs.environment[param] !== undefined) {
                    if (!this.spatialData.environmental[param][gridKey]) {
                        this.spatialData.environmental[param][gridKey] = {
                            latitude: latBin * CONFIG.gridSize - 90 + CONFIG.gridSize/2,
                            longitude: lonBin * CONFIG.gridSize - 180 + CONFIG.gridSize/2,
                            sum: 0,
                            count: 0
                        };
                    }

                    this.spatialData.environmental[param][gridKey].sum += obs.environment[param];
                    this.spatialData.environmental[param][gridKey].count++;
                }
            });
        });

        // Calculate averages for environmental data
        ['temperature', 'salinity', 'oxygen'].forEach(param => {
            for (const gridKey in this.spatialData.environmental[param]) {
                const gridCell = this.spatialData.environmental[param][gridKey];
                if (gridCell.count > 0) {
                    gridCell.avg = gridCell.sum / gridCell.count;
                }
            }
        });
    }

    detectAnomalies() {
        console.log('Detecting anomalies...');

        // Calculate global statistics for each environmental variable
        const globalStats = {};
        ['temperature', 'salinity', 'oxygen'].forEach(param => {
            const values = this.observations
                .filter(obs => obs.environment[param] !== undefined)
                .map(obs => obs.environment[param]);

            globalStats[param] = {
                mean: math.mean(values),
                std: math.std(values)
            };
        });

        // Detect anomalies (values outside 3 standard deviations)
        const anomalies = [];

        this.observations.forEach(obs => {
            ['temperature', 'salinity', 'oxygen'].forEach(param => {
                if (obs.environment[param] !== undefined) {
                    const zScore = Math.abs(
                        (obs.environment[param] - globalStats[param].mean) / globalStats[param].std
                    );

                    if (zScore > 3) {
                        anomalies.push({
                            timestamp: obs.timestamp,
                            latitude: obs.latitude,
                            longitude: obs.longitude,
                            depth: obs.depth,
                            species: obs.species,
                            parameter: param,
                            value: obs.environment[param],
                            zScore: zScore
                        });
                    }
                }
            });
        });

        // Save anomalies to file
        if (anomalies.length > 0) {
            const csvWriter = createObjectCsvWriter({
                path: path.join(CONFIG.outputDir, 'anomalies.csv'),
                header: [
                    {id: 'timestamp', title: 'timestamp'},
                    {id: 'latitude', title: 'latitude'},
                    {id: 'longitude', title: 'longitude'},
                    {id: 'depth', title: 'depth'},
                    {id: 'species', title: 'species'},
                    {id: 'parameter', title: 'parameter'},
                    {id: 'value', title: 'value'},
                    {id: 'zScore', title: 'z_score'}
                ]
            });

            csvWriter.writeRecords(anomalies)
                .then(() => console.log(`Detected ${anomalies.length} anomalies`))
                .catch(err => console.error('Error writing anomalies file:', err));
        } else {
            console.log('No anomalies detected');
        }

        return anomalies;
    }

    analyzeSpeciesAssociations() {
        console.log('Analyzing species associations...');

        // Get list of species
        const speciesList = Object.keys(this.speciesStats);
        const nSpecies = speciesList.length;

        // Create co-occurrence matrix
        const coOccurrence = math.zeros([nSpecies, nSpecies]);

        // Create grid cells
        const gridCells = {};
        this.observations.forEach(obs => {
            const latBin = Math.floor(obs.latitude / CONFIG.gridSize) * CONFIG.gridSize;
            const lonBin = Math.floor(obs.longitude / CONFIG.gridSize) * CONFIG.gridSize;
            const gridKey = `${latBin},${lonBin}`;

            if (!gridCells[gridKey]) {
                gridCells[gridKey] = new Set();
            }

            gridCells[gridKey].add(obs.species);
        });

        // Count co-occurrences
        for (const gridKey in gridCells) {
            const speciesInCell = Array.from(gridCells[gridKey]);

            for (let i = 0; i < speciesInCell.length; i++) {
                for (let j = i; j < speciesInCell.length; j++) {
                    const idx1 = speciesList.indexOf(speciesInCell[i]);
                    const idx2 = speciesList.indexOf(speciesInCell[j]);

                    if (idx1 !== -1 && idx2 !== -1) {
                        coOccurrence.subset(math.index(idx1, idx2), 
                                           coOccurrence.subset(math.index(idx1, idx2)) + 1);
                        if (i !== j) {
                            coOccurrence.subset(math.index(idx2, idx1), 
                                               coOccurrence.subset(math.index(idx2, idx1)) + 1);
                        }
                    }
                }
            }
        }

        // Calculate association indices (Jaccard similarity)
        const associationMatrix = math.zeros([nSpecies, nSpecies]);
        const speciesCounts = speciesList.map(s => this.speciesStats[s].observationCount);

        for (let i = 0; i < nSpecies; i++) {
            for (let j = 0; j < nSpecies; j++) {
                const coOccur = coOccurrence.subset(math.index(i, j));
                const totalOccur = speciesCounts[i] + speciesCounts[j] - coOccur;

                if (totalOccur > 0) {
                    associationMatrix.subset(math.index(i, j), coOccur / totalOccur);
                }
            }
        }

        // Save association matrix
        const associationData = {
            species: speciesList,
            matrix: associationMatrix.toArray()
        };

        fs.writeFileSync(
            path.join(CONFIG.outputDir, 'species_associations.json'),
            JSON.stringify(associationData, null, 2)
        );

        console.log('Species association analysis completed');

        return associationData;
    }

    analyzeEnvironmentalRelationships() {
        console.log('Analyzing environmental relationships...');

        // Prepare data for correlation analysis
        const speciesList = Object.keys(this.speciesStats);
        const envParams = ['temperature', 'salinity', 'oxygen'];
        const correlations = {};

        speciesList.forEach(species => {
            correlations[species] = {};

            envParams.forEach(param => {
                // Get all observations for this species
                const speciesObs = this.observations.filter(o => o.species === species);

                if (speciesObs.length < 10) {
                    correlations[species][param] = NaN;
                    return;
                }

                // Get quantity and environmental values
                const quantities = speciesObs.map(o => o.quantity);
                const envValues = speciesObs.map(o => o.environment[param] || NaN);

                // Filter out NaN values
                const validPairs = quantities.map((q, i) => [q, envValues[i]])
                    .filter(pair => !isNaN(pair[0]) && !isNaN(pair[1]));

                if (validPairs.length < 10) {
                    correlations[species][param] = NaN;
                    return;
                }

                // Calculate correlation
                const q = validPairs.map(p => p[0]);
                const e = validPairs.map(p => p[1]);

                correlations[species][param] = this.calculateCorrelation(q, e);
            });
        });

        // Save correlations
        fs.writeFileSync(
            path.join(CONFIG.outputDir, 'environmental_correlations.json'),
            JSON.stringify(correlations, null, 2)
        );

        console.log('Environmental relationship analysis completed');

        return correlations;
    }

    calculateCorrelation(x, y) {
        const n = x.length;
        if (n !== y.length || n === 0) return NaN;

        const sumX = math.sum(x);
        const sumY = math.sum(y);
        const sumXY = math.sum(x.map((val, i) => val * y[i]));
        const sumX2 = math.sum(x.map(val => val * val));
        const sumY2 = math.sum(y.map(val => val * val));

        const numerator = sumXY - (sumX * sumY) / n;
        const denominatorX = Math.sqrt(sumX2 - (sumX * sumX) / n);
        const denominatorY = Math.sqrt(sumY2 - (sumY * sumY) / n);

        if (denominatorX === 0 || denominatorY === 0) return NaN;

        return numerator / (denominatorX * denominatorY);
    }

