    createSpeciesAssociationPlot(plotDir) {
        // Load association data
        const associationData = JSON.parse(
            fs.readFileSync(path.join(CONFIG.outputDir, 'species_associations.json'))
        );

        const speciesList = associationData.species;
        const matrix = associationData.matrix;

        // Create nodes and links for network graph
        const nodes = speciesList.map((species, i) => ({
            id: species,
            name: species,
            group: this.observations.find(o => o.species === species)?.speciesGroup || 'Other',
            value: this.speciesStats[species]?.observationCount || 1
        }));

        const links = [];
        for (let i = 0; i < speciesList.length; i++) {
            for (let j = i + 1; j < speciesList.length; j++) {
                const association = matrix[i][j];
                if (association > 0.1) { // Only show significant associations
                    links.push({
                        source: i,
                        target: j,
                        value: association
                    });
                }
            }
        }

        // Create plot data
        const plotData = [{
            type: 'sankey',
            orientation: 'h',
            node: {
                pad: 15,
                thickness: 20,
                line: {
                    color: 'black',
                    width: 0.5
                },
                label: nodes.map(n => n.name),
                color: nodes.map(n => this.getGroupColor(n.group))
            },
            link: {
                source: links.map(l => l.source),
                target: links.map(l => l.target),
                value: links.map(l => l.value),
                color: 'rgba(0,0,0,0.1)'
            }
        }];

        const layout = {
            title: 'Species Association Network',
            font: {
                size: 10
            },
            height: 800
        };

        Plotly.newPlot(
            path.join(plotDir, 'species_association.html'),
            plotData,
            layout
        );
    }

    getSpeciesColor(species) {
        const group = this.observations.find(o => o.species === species)?.speciesGroup || 'Other';
        return this.getGroupColor(group);
    }

    getGroupColor(group) {
        const colors = {
            'Fish': '#1f77b4',
            'Mammals': '#ff7f0e',
            'Invertebrates': '#2ca02c',
            'Plankton': '#d62728',
            'Algae': '#9467bd',
            'Corals': '#8c564b',
            'Other': '#7f7f7f'
        };

        return colors[group] || '#7f7f7f';
    }

    getEnvColor(param) {
        const colors = {
            'temperature': '#d62728',
            'salinity': '#2ca02c',
            'oxygen': '#1f77b4'
        };

        return colors[param] || '#7f7f7f';
    }

    getEnvColorscale(param) {
        const colorscales = {
            'temperature': 'Hot',
            'salinity': 'Greens',
            'oxygen': 'Blues'
        };

        return colorscales[param] || 'Viridis';
    }

    getRegionColor(index) {
        const colors = [
            '#1f77b4', '#ff7f0e', '#2ca02c', '#d62728', 
            '#9467bd', '#8c564b', '#e377c2', '#7f7f7f', 
            '#bcbd22', '#17becf'
        ];

        return colors[index % colors.length];
    }

    saveResults() {
        console.log('Saving results...');

        // Save species statistics
        const speciesStatsArray = Object.values(this.speciesStats).map(stats => ({
            species: stats.species,
            observation_count: stats.observationCount,
            min_depth: stats.minDepth,
            max_depth: stats.maxDepth,
            avg_depth: stats.avgDepth,
            min_temp: stats.minTemp,
            max_temp: stats.maxTemp,
            avg_temp: stats.avgTemp,
            min_salinity: stats.minSalinity,
            max_salinity: stats.maxSalinity,
            avg_salinity: stats.avgSalinity,
            min_quantity: stats.quantityStats.min,
            max_quantity: stats.quantityStats.max,
            avg_quantity: stats.avgQuantity,
            std_quantity: stats.stdQuantity
        }));

        const speciesStatsCsv = parse(speciesStatsArray);
        fs.writeFileSync(path.join(CONFIG.outputDir, 'species_statistics.csv'), speciesStatsCsv);

        // Save region statistics
        const regionStatsArray = this.regionStats.map(region => ({
            region: region.name,
            observation_count: region.observationCount,
            species_count: Object.keys(region.speciesCounts).length,
            avg_temperature: region.envStats.temperature.avg,
            avg_salinity: region.envStats.salinity.avg,
            avg_oxygen: region.envStats.oxygen.avg,
            top_species: Object.entries(region.speciesCounts)
                .sort((a, b) => b[1] - a[1])
                .slice(0, 5)
                .map(s => s[0])
                .join('; ')
        }));

        const regionStatsCsv = parse(regionStatsArray);
        fs.writeFileSync(path.join(CONFIG.outputDir, 'region_statistics.csv'), regionStatsCsv);

        // Save time series
        const timeSeriesArray = [];

        // Total observations
        for (const [time, count] of Object.entries(this.timeSeries.total)) {
            timeSeriesArray.push({
                time: time,
                type: 'total_observations',
                value: count
            });
        }

        // Species groups
        for (const [group, values] of Object.entries(this.timeSeries.byGroup)) {
            for (const [time, quantity] of Object.entries(values)) {
                timeSeriesArray.push({
                    time: time,
                    type: `group_${group}`,
                    value: quantity
                });
            }
        }

        // Environmental parameters
        for (const [param, values] of Object.entries(this.timeSeries.environmental)) {
            for (const [time, value] of Object.entries(values)) {
                if (!time.endsWith('_count')) {
                    timeSeriesArray.push({
                        time: time,
                        type: `env_${param}`,
                        value: value
                    });
                }
            }
        }

        const timeSeriesCsv = parse(timeSeriesArray);
        fs.writeFileSync(path.join(CONFIG.outputDir, 'time_series.csv'), timeSeriesCsv);

        // Save spatial data
        const spatialDataArray = [];

        // Species distribution
        for (const [gridKey, cell] of Object.entries(this.spatialData.speciesDistribution)) {
            for (const [species, quantity] of Object.entries(cell.species)) {
                spatialDataArray.push({
                    type: 'species_distribution',
                    latitude: cell.latitude,
                    longitude: cell.longitude,
                    species: species,
                    quantity: quantity
                });
            }
        }

        // Environmental data
        for (const param of ['temperature', 'salinity', 'oxygen']) {
            for (const [gridKey, cell] of Object.entries(this.spatialData.environmental[param])) {
                spatialDataArray.push({
                    type: `env_${param}`,
                    latitude: cell.latitude,
                    longitude: cell.longitude,
                    value: cell.avg,
                    count: cell.count
                });
            }
        }

        const spatialDataCsv = parse(spatialDataArray);
        fs.writeFileSync(path.join(CONFIG.outputDir, 'spatial_data.csv'), spatialDataCsv);

        console.log('Results saved');
    }

    generateReport() {
        console.log('Generating report...');

        const report = {
            metadata: {
                generated_at: new Date().toISOString(),
                observation_count: this.observations.length,
                species_count: Object.keys(this.speciesStats).length,
                time_range: {
                    start: this.observations.length > 0 ? 
                        math.min(this.observations.map(o => o.date.toMillis())) : null,
                    end: this.observations.length > 0 ? 
                        math.max(this.observations.map(o => o.date.toMillis())) : null
                },
                config: CONFIG
            },
            summary: {
                species_groups: {},
                environmental_stats: {}
            },
            top_species: [],
            region_stats: this.regionStats.map(region => ({
                name: region.name,
                observation_count: region.observationCount,
                species_count: Object.keys(region.speciesCounts).length,
                avg_temperature: region.envStats.temperature.avg,
                avg_salinity: region.envStats.salinity.avg,
                avg_oxygen: region.envStats.oxygen.avg
            })),
            environmental_correlations: JSON.parse(
                fs.readFileSync(path.join(CONFIG.outputDir, 'environmental_correlations.json'))
            )
        };

        // Calculate species group summary
        for (const group of Object.keys(CONFIG.speciesGroups)) {
            const groupObs = this.observations.filter(o => o.speciesGroup === group);
            report.summary.species_groups[group] = {
                observation_count: groupObs.length,
                species_count: Object.values(this.speciesStats)
                    .filter(s => this.observations.find(o => o.species === s.species)?.speciesGroup === group)
                    .length
            };
        }

        // Calculate environmental stats
        ['temperature', 'salinity', 'oxygen'].forEach(param => {
            const values = this.observations
                .filter(o => o.environment[param] !== undefined)
                .map(o => o.environment[param]);

            report.summary.environmental_stats[param] = {
                mean: math.mean(values),
                std: math.std(values),
                min: math.min(values),
                max: math.max(values)
            };
        });

        // Get top 10 species
        const topSpecies = Object.entries(this.speciesStats)
            .sort((a, b) => b[1].observationCount - a[1].observationCount)
            .slice(0, 10)
            .map(([species, stats]) => ({
                species: species,
                observation_count: stats.observationCount,
                avg_quantity: stats.avgQuantity,
                min_depth: stats.minDepth,
                max_depth: stats.maxDepth,
                avg_depth: stats.avgDepth,
                min_temp: stats.minTemp,
                max_temp: stats.maxTemp,
                avg_temp: stats.avgTemp
            }));

        report.top_species = topSpecies;

        // Save report
        fs.writeFileSync(
            path.join(CONFIG.outputDir, 'analysis_report.json'),
            JSON.stringify(report, null, 2)
        );

        console.log('Report generated');
    }

    async run() {
        try {
            setupDirectories();

            console.log('Loading data...');
            await this.loadData();

            console.log('Calculating statistics...');
            this.calculateStatistics();

            console.log('Detecting anomalies...');
            this.detectAnomalies();

            console.log('Analyzing species associations...');
            this.analyzeSpeciesAssociations();

            console.log('Analyzing environmental relationships...');
            this.analyzeEnvironmentalRelationships();

            console.log('Creating visualizations...');
            this.createVisualizations();

            console.log('Saving results...');
            this.saveResults();

            console.log('Generating report...');
            this.generateReport();

            console.log('Analysis completed successfully!');
        } catch (error) {
            console.error('Error during analysis:', error);
        }
    }
}

